  dbUser      String
  passwordEnc String? // encrypted; CLEARED once the create job applies it
  status      String   @default("PENDING") // PENDING | ACTIVE | FAILED | DELETING
  error       String?
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  @@unique([serverId, engine, name])
  @@index([userId])
  @@index([serverId])
}

/// A one-click application install (WordPress, Ghost, Nextcloud, …). Reuses the
/// Website + VpsDatabase primitives; admin credentials are shown once via the
/// returned row / notification. `adminPassEnc` is cleared after the install job.
model AppInstall {
  id           String   @id @default(cuid())
  userId       String
  serverId     String
  server       Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  appSlug      String // wordpress | ghost | nextcloud | ...
  domain       String
  websiteId    String? // the Website row provisioned for it
  databaseId   String? // the VpsDatabase row provisioned for it
  url          String? // final site URL
  adminUser    String?
  adminPassEnc String? // encrypted admin password; CLEARED after install
  status       String   @default("PENDING") // PENDING | INSTALLING | ACTIVE | FAILED
  error        String?
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  @@index([userId])
  @@index([serverId])
}

/// A crontab entry managed for the customer's VPS. All enabled entries for a
/// server are rendered into a single Nxeon-owned crontab block on CRON_SYNC.
model CronJob {
  id        String   @id @default(cuid())
  userId    String
  serverId  String
  server    Server   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  schedule  String // 5-field cron expression
  command   String
  comment   String?
  enabled   Boolean  @default(true)
  status    String   @default("PENDING") // PENDING | ACTIVE | FAILED | DELETING
  error     String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@index([userId])
  @@index([serverId])
}

/// Periodic in-guest disk-usage samples collected from the QEMU guest agent
/// (get-fsinfo) by the worker monitor sweep. Powers the customer "Disk usage
/// over time" chart, which Proxmox RRD can't feed for QEMU VMs (disk=0).
/// Pruned on a rolling ~35-day retention window by the sampler.
model ServerDiskSample {
  id         String   @id @default(cuid())
  serverId   String
  ts         DateTime @default(now())
  usedBytes  BigInt
  totalBytes BigInt

  @@index([serverId, ts])
}

/// Raw live-telemetry events shipped by the nxeon-shipper agent (per-server on
/// VPS/game boxes; centralized — one shipper per node — for shared HOSTING and
/// MAIL). This is a SHORT ROLLING WINDOW table, not a permanent log: worker's
/// telemetrySweep (worker/telemetry.ts) prunes rows past TELEMETRY_RETENTION_HOURS
/// on the same cadence it processes new batches, exactly like ServerDiskSample's
/// prune-then-sample pattern, so it never grows unbounded. `serverId` is a plain
/// column (no `@relation`) deliberately, matching ServerDiskSample — a high-write
/// table should never take a lock tied to the parent row, and events must survive
/// briefly even if the server row is deleted moments later.
model TelemetryEvent {
  id       String   @id @default(cuid())
  // One of these two identifies the source; VPS/GAME events set serverId,
  // HOSTING/MAIL events (centralized shippers) set nodeId + nodeKind instead.
  serverId String?
  server   Server?  @relation(fields: [serverId], references: [id], onDelete: Cascade)
  nodeId   String? // HostingNode.id for HOSTING; a fixed constant for MAIL (see lib/telemetry.ts)
  nodeKind String // VPS | GAME | HOSTING | MAIL
  type     String // SSH_LOGIN | SSH_LOGOUT | SSH_FAILED | VISITOR | MAIL_AUTH
  ts       DateTime @default(now()) // event time as reported by the shipper
  ip       String?
  user     String?
  path     String? // VISITOR request path
  site     String? // which vhost/customer site, on a centralized HOSTING shipper
  status   String?
  meta     String?
  label    String? // hostname/display label the shipper reported, for the UI
  createdAt DateTime @default(now()) // ingest time — what the prune sweep keys off

  @@index([createdAt])
  @@index([serverId, createdAt])
  @@index([nodeKind, createdAt])
}

import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import { EmptyState } from "@/components/ui/primitives";
import { PortalHero } from "@/components/portal/PortalHero";
import { DeployButton } from "@/components/customer/DeployButton";
import { ServersList, type ServerRow } from "@/components/customer/ServersList";
import { effectiveDiskGB } from "@/lib/extra-disk";

export const dynamic = "force-dynamic";

export default async function ServersPage() {
  const user = await requireUser();
  const servers = await db.server.findMany({
    // NxCloud instances are backed by a Server but surfaced as their own product
    // under /dashboard/nxcloud, so they're hidden from the raw VPS list here.
    where: { userId: user.id, nxcloudInstance: { is: null } },
    include: { plan: true, osTemplate: true, project: true },
    orderBy: { createdAt: "desc" },
  });

  const transitional = servers.some((s) =>
    ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)
  );

  const rows: ServerRow[] = servers.map((s) => ({
    id: s.id,
    hostname: s.hostname,
    status: s.status,
    isFree: s.isFree,
    // Effective disk = plan allowance + any separately-purchased extra disk.
    planLine: `${s.plan.name} · ${s.plan.cpuCores} vCPU · ${s.plan.ramMB / 1024} GB · ${effectiveDiskGB(s.plan.diskGB, s.extraDiskGB)} GB`,
    osName: s.osTemplate.name,
    project: s.project ? { name: s.project.name, color: s.project.color } : null,
    endpoint: s.sshPort ? `${process.env.PUBLIC_IP}:${s.sshPort}` : null,
    created: s.createdAt.toISOString().slice(0, 10),
  }));

  return (
    <div className="space-y-6">
      {transitional && <AutoRefresh />}
      <PortalHero variant="servers" title="Servers" sub="All virtual machines on your account.">
        <DeployButton href="/dashboard/deploy">Deploy server</DeployButton>
      </PortalHero>

      {servers.length === 0 ? (
        <EmptyState
          title="No servers yet"
          sub="Deploy your first NVMe-backed VPS — it takes under two minutes from click to SSH."
          action={
            <DeployButton href="/dashboard/deploy">Deploy your first server</DeployButton>
          }
        />
      ) : (
        <ServersList servers={rows} />
      )}
    </div>
  );
}
"use client";

import { useState, type ReactNode } from "react";

// Base tab order. "Manage" (the game control panel) is injected right after
// Overview for game servers only — see `tabs` below.
const BASE_TABS = [
  "Overview",
  "Control panel",
  "Metrics",
  "Console",
  "Files",
  "Snapshots",
  "Backups",
  "Networking",
  "Resize",
  "Activity",
] as const;

// Customer-facing label overrides. The internal tab key stays "resize" so the
// ?tab=resize deep-links, the panels map and every internal reference keep
// working untouched — only the text the customer reads changes to "Upgrade".
const TAB_LABELS: Record<string, string> = {
  resize: "Upgrade",
};

export function ServerTabs({
  initialTab,
  overview,
  manage,
  mods,
  controlPanel,
  metrics,
  console: consolePanel,
  files,
  snapshots,
  backups,
  networking,
  resize,
  activity,
}: {
  initialTab?: string;
  overview: ReactNode;
  /** Game control panel — present (and shown as "Manage") for game servers only. */
  manage?: ReactNode;
  /** Mod/plugin manager — present ("Mods") for game servers only. */
  mods?: ReactNode;
  controlPanel: ReactNode;
  metrics: ReactNode;
  console: ReactNode;
  files: ReactNode;
  snapshots: ReactNode;
  backups: ReactNode;
  networking: ReactNode;
  resize: ReactNode;
  activity: ReactNode;
}) {
  // Game-only tabs are injected right after Overview, in order.
  const extra: string[] = [];
  if (manage) extra.push("Manage");
  if (mods) extra.push("Mods");
  const TABS: readonly string[] = extra.length ? ["Overview", ...extra, ...BASE_TABS.slice(1)] : BASE_TABS;
  const keys = TABS.map((t) => t.toLowerCase());
  const [tab, setTab] = useState<string>(
    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview"
  );

  const panels: Record<string, ReactNode> = {
    overview,
    manage,
    mods,
    "control panel": controlPanel,
    metrics,
    console: consolePanel,
    files,
    snapshots,
    backups,
    networking,
    resize,
    activity,
  };

  return (
    <div>
      <div className="mb-6 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md">
        {TABS.map((t) => {
          const k = t.toLowerCase();
          const active = tab === k;
          return (
            <button
              key={k}
              type="button"
              onClick={() => {
                setTab(k);
                window.history.replaceState(null, "", `?tab=${k}`);
              }}
              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
                active
                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              {TAB_LABELS[k] ?? t}
            </button>
          );
        })}
      </div>
      <div className="animate-fade-up">{panels[tab]}</div>
    </div>
  );
}
