##### lib/actions-server-lifecycle.ts
"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
// Re-exporting a const from a "use server" file is illegal (Next throws
// "found object"), so the choices live in a plain module.
import { BACKUP_INTERVAL_CHOICES } from "./backup-intervals";
import { prorateDowngradeCreditCents, remainingMonths, terminationRefundCents } from "./proration";
import { annualDiscountPct, frozenAnnualDiscountPct } from "./annual-discount";
import { invoiceCreateData } from "./invoices";

/**
 * Server lifecycle "extras" — scheduled backups, reinstall-to-a-different-OS and
 * resize-down. These complement the primary flows in `lib/actions-server.ts`
 * (create backup, resize-up, reinstall-same-OS). Every op is ownership-checked
 * and respects the "one in-flight job per server" invariant.
 */

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    include: { plan: true, osTemplate: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function hasInflightJob(serverId: string): Promise<boolean> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  return pending > 0;
}

// ---------- 1. Scheduled backups ----------

/**
 * Enable/disable recurring backups and set the cadence. When enabling we do NOT
 * touch `lastAutoBackup` — a null/stale value simply lets the sweep run the
 * first backup on its next pass.
 */
export async function setBackupSchedule(
  serverId: string,
  enabled: boolean,
  intervalHours: number
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  if (enabled && !BACKUP_INTERVAL_CHOICES.includes(intervalHours as any)) {
    return { error: "Choose a valid backup interval." };
  }

  await db.server.update({
    where: { id: server.id },
    data: {
      autoBackup: enabled,
      backupIntervalHours: enabled ? intervalHours : null,
    },
  });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.backup_schedule",
      detail: enabled ? `${serverId} every ${intervalHours}h` : `${serverId} disabled`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- 1b. Retry a failed provision ----------

/**
 * Re-enqueue provisioning for a server that failed to build (status ERROR).
 *
 * A terminal PROVISION failure strands the server in ERROR with a red banner and
 * no way forward; this is the customer's self-service retry. It re-uses the exact
 * same job/worker machinery as the original order — the provision handler keeps
 * any vmid already persisted on the row, so a retry resumes rather than leaking a
 * second VM. Ownership-checked, guarded to ERROR only, and respects the one
 * in-flight job invariant. Moving the row to PROVISIONING immediately makes the
 * detail page show the transitional "being set up" state (and auto-refresh)
 * rather than the stale ERROR banner while the worker picks the job up.
 */
export async function retryProvision(serverId: string): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  if (server.status !== "ERROR") {
    return { error: "This server isn't in a failed state." };
  }
  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  await db.$transaction([
    db.server.update({
      where: { id: server.id },
      data: { status: "PROVISIONING", provisionError: null },
    }),
    db.job.create({ data: { type: "PROVISION", serverId } }),
  ]);
  await db.auditLog.create({
    data: { userId: user.id, action: "server.retry_provision", detail: serverId },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- 2. Reinstall to a different OS ----------

/**
 * Switch the server to a different OS image and reinstall. This ERASES all data:
 * the worker's REINSTALL handler destroys the VM and re-provisions it from
 * `Server.osTemplateId`, so we persist the new template BEFORE enqueuing.
 */
export async function reinstallToOs(
  serverId: string,
  osTemplateId: string
): Promise<{ error?: string }> {
  const { user, server } = await ownedServer(serverId);

  if (!["RUNNING", "STOPPED"].includes(server.status)) {
    return { error: "Server must be running or stopped to reinstall." };
  }

  const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
  if (!os?.active) return { error: "That operating system isn't available." };
  if (os.id === server.osTemplateId) {
    return { error: "This server is already running that operating system." };
  }
  if (server.plan.ramMB < os.minRamMB) {
    return { error: `${os.name} needs at least ${os.minRamMB / 1024} GB RAM — your plan has ${server.plan.ramMB / 1024} GB.` };
  }
  if (server.plan.diskGB < os.minDiskGB) {
    return { error: `${os.name} needs at least ${os.minDiskGB} GB disk — your plan has ${server.plan.diskGB} GB.` };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  // A reinstall destroys and re-clones the VM (same vmid). Its disks — including
  // any block-storage volume disk (vm-<vmid>-disk-N) — are purged with it. A
  // *detached* volume still keeps its disk under this vmid (Proxmox "unused"), so
  // purge wipes it too. Refuse while ANY volume is pinned to this server so the
  // customer must delete it (which cleanly destroys just that disk) first.
  const pinnedVolumes = await db.volume.count({ where: { serverId } });
  if (pinnedVolumes > 0) {
    const n = pinnedVolumes === 1 ? "volume" : `${pinnedVolumes} volumes`;
    return {
      error:
        `This server still has ${pinnedVolumes === 1 ? "a" : pinnedVolumes} block-storage ${n}. ` +
        `Detaching isn't enough — the disk stays on this server, so a reinstall would erase it too. ` +
        `To KEEP the data, attach the ${pinnedVolumes === 1 ? "volume" : "volumes"} to a different server first; ` +
        `to discard it, delete the ${pinnedVolumes === 1 ? "volume" : "volumes"} from the Volumes page. Then reinstall.`,
    };
  }

  // Persist the target OS and enqueue the rebuild ATOMICALLY.
  //
  // The REINSTALL handler re-provisions from `Server.osTemplateId`, so the write
  // has to land before the job — but as two separate statements a failure between
  // them left the row claiming an operating system the VM is not running, with no
  // job to make it true. Every page, every support view and the next reinstall
  // would then read that row and believe it. One transaction: either the server
  // is recorded as the new image AND a rebuild is queued, or neither happened.
  await db.$transaction([
    db.server.update({ where: { id: server.id }, data: { osTemplateId: os.id } }),
    db.job.create({ data: { type: "REINSTALL", serverId } }),
  ]);
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "server.reinstall_os",
      detail: `${serverId} -> ${os.slug} (was ${server.osTemplate.slug})`,
    },
  });
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- 3. Resize-down ----------

/**
 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
 * otherwise). A prorated credit for the price difference over the remaining term
 * is returned to the wallet.
 */
export async function resizeServerDown(
  serverId: string,
  newPlanId: string
): Promise<{ error?: string }> {
  // Money path: this MOVES money (a prorated credit into the wallet) and it
  // permanently gives up capacity the customer paid for. `cancelTransferIn`
  // guards its credit the same way; this one did not, so an admin impersonating
  // a customer could downgrade their server and cash the remaining term out into
  // a balance the customer never asked to convert.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);

  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
  if (!newPlan?.active) return { error: "Plan not available." };
  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
  // A GAME server cannot be prorated against its base VPS plan — and THIS is the
  // credit path, so this is the dangerous half.
  //
  // A game tier carries BOTH a `planId` and a `gamePlanId`, and is sold at
  // `gamePlan.priceCents`: a FLAT all-in price, typically LOWER than the base plan
  // it runs on. `orderGameServer` correctly records `termPromoPercent: 0`, because
  // a flat price is not a discounted one. So the credit below is computed from the
  // BASE plan's full monthly rate for every remaining month.
  //
  // lib/proration.ts rests on exactly one invariant — a prorated credit is
  // strictly less than the cash actually collected for those months — and this
  // breaks it. A $9.99/mo flat tier on a $20.99 base plan pays out $20.99-worth
  // per remaining month: real wallet money the customer never paid, self-service,
  // repeatable.
  //
  // Until now it was blocked ONLY by the disk-monotonic guard below, because in a
  // catalogue where price and disk both rise there is no cheaper plan with
  // equal-or-larger disk. That is a coincidence of the price list, not a
  // protection — one cheap high-disk plan opens it. Refusing outright matches how
  // `renewalCharge` already treats a game plan: all-in, no add-on lines.
  if (server.gamePlanId) {
    return {
      error:
        "Game server plans are fixed bundles — switch tiers from the game server's own settings, or contact support.",
    };
  }
  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };

  // This action is downgrades only — upgrades go through resizeServer().
  if (newPlan.priceCents >= server.plan.priceCents) {
    return { error: "This is not a smaller plan — use the upgrade flow instead." };
  }
  // Disk can't shrink destructively; block the move rather than lose data.
  // Compares PLAN disks on purpose: any purchased `extraDiskGB` is additive to
  // both the old and the new plan and is preserved verbatim across the resize, so
  // "new plan disk >= old plan disk" is exactly the condition for "effective disk
  // does not shrink". Nothing here ever writes extraDiskGB.
  if (newPlan.diskGB < server.plan.diskGB) {
    return {
      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
    };
  }

  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  // Credit at the SAME effective rate the upgrade path charges at (term discount
  // plus `server.termPromoPercent`, the rate THIS term was actually sold at) over
  // the SAME remaining duration — every month left on `expiresAt`, uncapped,
  // exactly as lib/resize.ts charges for. Both directions read that one persisted
  // scalar off the same row, which is what makes a round trip net to zero no matter
  // what dates the two halves happen on. Until 2026-07-26 the rate came from
  // `currentPromo(now)` instead, so a customer could upgrade under the 45% Cyber
  // Monday basis and downgrade under the 15% Launch Sale basis and keep the spread
  // on every remaining month, once per promo cycle, forever.
  //
  // The old maths credited the raw LIST-price delta, so it refunded more than the
  // customer had ever paid (they bought at the term-discounted, promo-reduced
  // price). Pricing both directions through lib/proration.ts fixed the RATE, but
  // this line then capped the DURATION at one term while the upgrade side did not,
  // which broke the round trip the other way: a customer whose stacked "Renew now"
  // had pushed `expiresAt` 36 months out on a 12-month term paid $544.32 to
  // upgrade Starter -> Max and got only $181.44 back coming straight down, so the
  // platform pocketed $362.88 of months they had genuinely paid for. `expiresAt`
  // never advances without payment, so all of those months are owed back. The cap
  // argument has been removed from `remainingMonths` outright — the two directions
  // now cannot express different durations.
  let creditCents = 0;
  if (!server.isFree && server.expiresAt) {
    creditCents = prorateDowngradeCreditCents({
      fromMonthlyCents: server.plan.priceCents,
      toMonthlyCents: newPlan.priceCents,
      termMonths: server.termMonths,
      termPromoPercent: server.termPromoPercent,
      // Mirror the upgrade charge (lib/resize.ts): credit at the annual rate the server
      // was FROZEN at (falling back to live only for legacy rows), so the round trip
      // cannot mint or lose money even if the admin retunes the setting between the two
      // (Finding 2). Both directions read `frozenAnnualDiscountPct(server)`.
      annualDiscountPct: frozenAnnualDiscountPct(server) ?? (await annualDiscountPct()),
      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
    });
  }

  await db.$transaction([
    ...(creditCents > 0
      ? [
          db.user.update({
            where: { id: server.userId },
            data: { balanceCents: { increment: creditCents } },
          }),
          db.walletTransaction.create({
            data: {
              userId: server.userId,
              amountCents: creditCents,
              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
            },
          }),
        ]
      : []),
    // Record the amount credited on the job so the worker's RESIZE handler can
    // REVERSE it (re-debit `payload.prorateCents` from the wallet) if the resize
    // terminally fails — the credit is committed here, before the job runs.
    //
    // DONE, not pending: `reconcileFailedJob` (worker/index.ts) reads both fields
    // and claws the credit back on `direction: "down"`, guarded by `debitWallet`
    // so it can never drive the balance negative, and idempotent on an audit row
    // keyed to this job id. It is called from both terminal-failure paths.
    //
    // This carried an "INTEGRATION NEEDED" note long after the integration
    // landed, and on 2026-07-26 an audit read the note rather than the code and
    // reported a live double-credit money bug that does not exist. A stale
    // comment claiming work is undone costs real investigation time and, worse,
    // invites someone to "fix" a path that is already correct.
    db.job.create({
      data: {
        type: "RESIZE",
        serverId,
        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
      },
    }),
    db.auditLog.create({
      data: {
        userId: user.id,
        action: "server.resize_down",
        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
      },
    }),
  ]);

  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

// ---------- 4. Self-serve cancel / terminate (+ prorated refund) ----------

/**
 * Customer-initiated cancellation of a VPS / game server. Two modes:
 *
 *   • "period_end"  — stop auto-renew and keep the server running until `expiresAt`.
 *                     No money moves; the paid term is honoured to its end. Default
 *                     and always-safe choice.
 *   • "immediate"   — terminate NOW: enqueue the SAME audited DELETE job the manual
 *                     delete uses (worker destroys the VM), and — for a standard VPS
 *                     with unused paid time — credit the prorated refund to the WALLET
 *                     (never a Stripe refund; safer and reversible) in the same
 *                     transaction, with a ledger line and a credit-note invoice.
 *
 * Ownership-guarded and `assertNotImpersonating` (this both destroys a resource and
 * can move money — an admin must not do either on a customer's behalf). Respects the
 * one-in-flight-job invariant. The confirm dialog in the UI carries the data-retention
 * warning and the refund figure.
 */
export async function cancelService(
  serverId: string,
  mode: "immediate" | "period_end",
): Promise<{ error?: string; ok?: boolean; refundCents?: number; message?: string }> {
  // Moves money and destroys a resource — never while impersonating.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);

  if (server.status === "DELETING") return { error: "This server is already being cancelled." };

  // ---- Cancel at period end: just stop auto-renew, keep the server to expiry. ----
  if (mode === "period_end") {
    if (server.isFree || !server.expiresAt) {
      return { error: "This server has no billing term to cancel — use immediate termination to remove it." };
    }
    if (!server.autoRenew) {
      return { ok: true, message: `Auto-renew is already off. This server stays active until ${server.expiresAt.toISOString().slice(0, 10)}, then stops.` };
    }
    await db.server.update({ where: { id: server.id }, data: { autoRenew: false } });
    await db.auditLog.create({
      data: { userId: user.id, action: "server.cancel_period_end", detail: serverId },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    return {
      ok: true,
      message: `Auto-renew turned off. This server keeps running until ${server.expiresAt.toISOString().slice(0, 10)}, then stops automatically. You can turn auto-renew back on any time before then.`,
    };
  }

  // ---- Immediate termination (+ prorated wallet refund). ----
  if (await hasInflightJob(serverId)) {
    return { error: "Another operation is already in progress on this server. Wait for it to finish, then try again." };
  }

  const refundCents = terminationRefundCents({
    isFree: server.isFree,
    expiresAt: server.expiresAt,
    isGame: !!server.gamePlanId,
    planMonthlyCents: server.plan.priceCents,
    termMonths: server.termMonths,
    termPromoPercent: server.termPromoPercent,
    // Authoritative refund basis: the real plan cash collected for the term, net of
    // promo AND coupon. Null on legacy rows → the helper falls back to the (safe,
    // never-over-refunding) termPromoPercent formula.
    refundableTermCents: server.refundableTermCents,
    annualDiscountPct: frozenAnnualDiscountPct(server) ?? (await annualDiscountPct()),
  });

  // One INTERACTIVE transaction whose FIRST act is a compare-and-swap on status: flip
  // to DELETING only if it is not already DELETING. A double-click / retry that loses
  // the race (`adv.count === 0`) does NOTHING — no second refund, no second DELETE job.
  // Only the winner issues the refund credit + ledger line + credit-note + DELETE job,
  // so refund and termination commit together and can never both run twice. (The old
  // array form flipped status unconditionally, so N concurrent calls all refunded.)
  const won = await db.$transaction(async (tx) => {
    const adv = await tx.server.updateMany({
      where: { id: server.id, status: { not: "DELETING" } },
      data: { status: "DELETING", autoRenew: false },
    });
    if (adv.count !== 1) return false; // lost the race — another call already claimed it

    if (refundCents > 0) {
      await tx.user.update({
        where: { id: server.userId },
        data: { balanceCents: { increment: refundCents } },
      });
      await tx.walletTransaction.create({
        data: {
          userId: server.userId,
          amountCents: refundCents,
          description: `Cancellation refund (unused term) — ${server.hostname}`,
        },
      });
      // A credit-note invoice for the refund, so the ledger line has a matching
      // billing document the customer can download. Marked REFUNDED.
      await tx.invoice.create({
        data: invoiceCreateData({
          userId: server.userId,
          description: `Cancellation refund — ${server.hostname}`,
          status: "REFUNDED",
          lineItems: [
            {
              description: `Prorated refund for unused term — ${server.hostname}`,
              qty: 1,
              unitCents: refundCents,
              amountCents: refundCents,
            },
          ],
        }),
      });
    }
    await tx.job.create({ data: { type: "DELETE", serverId } });
    await tx.auditLog.create({
      data: {
        userId: user.id,
        action: "server.cancel_immediate",
        detail: `${serverId} refund=${refundCents}`,
      },
    });
    return true;
  });

  if (!won) {
    return { error: "This server is already being cancelled." };
  }

  if (refundCents > 0) {
    await db.notification
      .create({
        data: {
          userId: server.userId,
          title: `Refund of $${(refundCents / 100).toFixed(2)} credited to your wallet`,
          body: `We refunded the unused portion of ${server.hostname}'s term as wallet credit. Your data on this server is being erased and cannot be recovered.`,
          href: "/dashboard/billing",
        },
      })
      .catch(() => {});
  }

  revalidatePath(`/dashboard/servers/${serverId}`);
  return {
    ok: true,
    refundCents,
    message:
      refundCents > 0
        ? `Server termination started. $${(refundCents / 100).toFixed(2)} for the unused part of your term has been credited to your wallet. All data on this server is being permanently erased.`
        : `Server termination started. All data on this server is being permanently erased.`,
  };
}

