              </button>
              <button
                type="button"
                className="btn-primary px-3 py-1.5 text-sm"
                onClick={saveEditor}
                disabled={editorSaving || editorLoading || !editor.dirty}
              >
                {editorSaving ? "Saving…" : "Save"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

