"use client";

import { useEffect, useRef, useState, useTransition } from "react";
import { submitBuild, approveBuild, rejectBuild } from "@/lib/actions-claude";

type ServerOption = { id: string; hostname: string };
type BuildState = { status: string; steps: number; log: string; plan?: string | null };
type PlanStep = { cmd: string; intent?: string };

const EXAMPLES = [
  "Install and configure nginx serving a simple landing page over HTTP.",
  "Set up Node.js LTS, PM2, and a UFW firewall allowing only SSH and HTTP/HTTPS.",
  "Install Docker and run a Postgres 16 container with a persistent volume.",
];

const TERMINAL = new Set(["DONE", "FAILED"]);

function parsePlan(raw?: string | null): PlanStep[] {
  if (!raw) return [];
  try {
    const p = JSON.parse(raw);
    if (Array.isArray(p)) {
      return p
        .map((s) => (typeof s === "string" ? { cmd: s } : { cmd: String(s?.cmd ?? ""), intent: s?.intent }))
        .filter((s) => s.cmd);
    }
  } catch {
    /* ignore */
  }
  return [];
}

export function ClaudeBuilder({ servers }: { servers: ServerOption[] }) {
  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
  const [prompt, setPrompt] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [buildId, setBuildId] = useState<string | null>(null);
  const [state, setState] = useState<BuildState | null>(null);
  const [pending, startTransition] = useTransition();
  const logRef = useRef<HTMLPreElement>(null);

  // Poll the build status while a build is active (until it reaches DONE/FAILED).
  useEffect(() => {
    if (!buildId) return;
    let alive = true;
    let timer: ReturnType<typeof setTimeout>;

    const tick = async () => {
      try {
        const res = await fetch(`/api/claude/${buildId}`, { cache: "no-store" });
        if (res.ok) {
          const data = (await res.json()) as BuildState;
          if (alive) setState(data);
          if (data.status && TERMINAL.has(data.status)) return; // stop polling
        }
      } catch {
        /* transient — keep polling */
      }
      if (alive) timer = setTimeout(tick, 2000);
    };
    void tick();
    return () => {
      alive = false;
      clearTimeout(timer);
    };
  }, [buildId]);

  // Keep the log scrolled to the bottom as it streams.
  useEffect(() => {
    if (logRef.current) logRef.current.scrollTop = logRef.current.scrollHeight;
  }, [state?.log]);

  const status = state?.status ?? null;
  const inProgress = Boolean(buildId) && !(status && TERMINAL.has(status));
  const awaitingApproval = status === "AWAITING_APPROVAL";
  const planning = status === "QUEUED" || status === "PLANNING";
  const executing = status === "RUNNING";
  const plan = parsePlan(state?.plan);

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    startTransition(async () => {
      const res = await submitBuild(serverId, prompt);
      if (res.error) {
        setError(res.error);
        return;
      }
      if (res.buildId) {
        setBuildId(res.buildId);
        setState({ status: "QUEUED", steps: 0, log: "", plan: null });
      }
    });
  };

  const onApprove = () => {
    if (!buildId) return;
    setError(null);
    startTransition(async () => {
      const res = await approveBuild(buildId);
      if (res.error) {
        setError(res.error);
        return;
      }
      // Optimistically flip to QUEUED; polling will pick up RUNNING → DONE.
      setState((s) => (s ? { ...s, status: "QUEUED" } : s));
    });
  };

  const onReject = () => {
    if (!buildId) return;
    setError(null);
    startTransition(async () => {
      const res = await rejectBuild(buildId);
      if (res.error) {
        setError(res.error);
        return;
      }
      setState((s) => (s ? { ...s, status: "FAILED" } : s));
    });
  };

  const reset = () => {
    setBuildId(null);
    setState(null);
    setPrompt("");
    setError(null);
  };

  const statusTone =
    status === "DONE"
      ? "border-emerald-500/40 bg-emerald-500/10 text-emerald-300"
      : status === "FAILED"
      ? "border-red-500/40 bg-red-500/10 text-red-300"
      : status === "AWAITING_APPROVAL"
      ? "border-sky-500/40 bg-sky-500/10 text-sky-300"
      : "border-amber-500/40 bg-amber-500/10 text-amber-300";

  return (
    <div className="space-y-6">
      <form onSubmit={onSubmit} className="card space-y-4 p-5">
        <div>
          <label className="mb-1.5 block text-sm font-medium text-slate-300">Server</label>
          <select
            className="input"
            value={serverId}
            onChange={(e) => setServerId(e.target.value)}
            disabled={inProgress || pending}
          >
            {servers.map((s) => (
              <option key={s.id} value={s.id}>
                {s.hostname}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="mb-1.5 block text-sm font-medium text-slate-300">
            What should Claude build?
          </label>
          <textarea
            className="input min-h-[110px] resize-y font-normal"
            placeholder="e.g. Install and configure a Node.js app served behind nginx with a firewall."
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            maxLength={2000}
            disabled={inProgress || pending}
          />
          <div className="mt-2 flex flex-wrap gap-2">
            {EXAMPLES.map((ex) => (
              <button
                key={ex}
                type="button"
                onClick={() => setPrompt(ex)}
                disabled={inProgress || pending}
                className="rounded-full border border-white/10 bg-white/[0.04] px-3 py-1 text-xs text-slate-400 hover:text-slate-200 disabled:opacity-50"
              >
                {ex.length > 46 ? ex.slice(0, 46) + "…" : ex}
              </button>
            ))}
          </div>
        </div>

        {error && <p className="text-sm text-red-300">{error}</p>}

        <div className="flex items-center gap-3">
          <button
            type="submit"
            className="btn-primary"
            disabled={inProgress || pending || !serverId || prompt.trim().length < 8}
          >
            {pending && !buildId ? "Starting…" : inProgress ? "In progress…" : "Plan with Claude"}
          </button>
          {buildId && !inProgress && (
            <button type="button" onClick={reset} className="btn-secondary">
              New build
            </button>
          )}
        </div>
        <p className="text-xs text-slate-500">
          Claude first proposes an ordered list of shell commands. Nothing runs on your server until you
          review and <span className="font-medium text-slate-400">Approve</span> the plan. Up to 20
          commands then run over SSH; you are responsible for the changes made to your server.
        </p>
      </form>

      {state && (
        <div className="card space-y-4 p-5">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="flex items-center gap-3">
              <span
                className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-medium ${statusTone}`}
              >
                {inProgress && !awaitingApproval && (
                  <span className="mr-2 h-1.5 w-1.5 animate-pulse rounded-full bg-current" />
                )}
                {status ? status.toLowerCase().replace(/_/g, " ") : "…"}
              </span>
              {executing && <span className="text-xs text-slate-500">step {state.steps}</span>}
            </div>
          </div>

          {planning && (
            <p className="text-sm text-slate-400">
              Claude is drafting a plan of commands for this goal…
            </p>
          )}

          {awaitingApproval && plan.length > 0 && (
            <div className="space-y-4">
              <div>
                <h3 className="text-sm font-semibold text-slate-200">Proposed plan</h3>
                <p className="mt-1 text-xs text-slate-500">
                  Review these {plan.length} command(s). They only run if you approve.
                </p>
              </div>
              <ol className="space-y-2">
                {plan.map((step, i) => (
                  <li
                    key={i}
                    className="rounded-xl border border-white/[0.08] bg-navy-950/60 p-3"
                  >
                    <code className="block whitespace-pre-wrap break-words font-mono text-xs text-slate-200">
                      $ {step.cmd}
                    </code>
                    {step.intent && (
                      <p className="mt-1.5 text-xs text-slate-500">{step.intent}</p>
                    )}
                  </li>
                ))}
              </ol>
              <div className="flex items-center gap-3">
                <button type="button" onClick={onApprove} disabled={pending} className="btn-primary">
                  {pending ? "Working…" : "Approve & run"}
                </button>
                <button type="button" onClick={onReject} disabled={pending} className="btn-danger">
                  Reject
                </button>
              </div>
            </div>
          )}

          {(executing || (status && TERMINAL.has(status))) && (
            <pre
              ref={logRef}
              className="max-h-[440px] overflow-auto whitespace-pre-wrap break-words rounded-xl border border-white/[0.08] bg-navy-950/80 p-4 font-mono text-xs leading-relaxed text-slate-300"
            >
              {state.log || (executing ? "Waiting for the worker to pick up the job…" : "No output.")}
            </pre>
          )}
        </div>
      )}
    </div>
  );
}
