16	async function ownedServer(serverId: string) {
17	  const user = await requireUser();
18	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
19	  if (!server) throw new Error("Not found");
20	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
21	  return { user, server };
