24	async function queueJob(
25	  serverId: string,
26	  type:
27	    | "SNAPSHOT_CREATE"
28	    | "SNAPSHOT_DELETE"
29	    | "SNAPSHOT_ROLLBACK"
30	    | "BACKUP_CREATE"
31	    | "RESIZE"
32	    | "PASSWORD_RESET",
33	  payload?: Record<string, unknown>
34	): Promise<{ error?: string }> {
35	  const pending = await db.job.count({
36	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
37	  });
38	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
39	  await db.job.create({ data: { type, serverId, payload: payload as any } });
40	  return {};
41	}
