45	/**
46	 * The ONE snapshot-name normalisation, applied identically on every path.
47	 *
48	 * `worker/index.ts` snapshotOp re-applies exactly this (`[^a-zA-Z0-9_]` stripped,
49	 * 40 chars) and throws "snapshot: invalid name" on an empty result — so a name
50	 * this module accepts but the worker rejects is a job that reports QUEUED to the
51	 * customer and then dies in the worker with a message they never see. Delete and
52	 * rollback used to pass the raw argument straight through: a TypeScript parameter
53	 * type is not validation, and these are reachable with any string at all.
54	 */
55	function cleanSnapshotName(name: unknown): string {
56	  return String(name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
57	}
58	
59	const SNAPSHOT_NAME_ERROR =
60	  "Snapshot name must be 2–40 characters of letters, digits or underscores. " +
61	  "Pick the snapshot from the list on the server page rather than typing its name.";
62	
63	export async function createSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
64	  const { user, server } = await ownedServer(serverId);
65	  const clean = cleanSnapshotName(name);
66	  if (clean.length < 2) return { error: "Snapshot name: letters, digits, underscores (min 2)." };
67	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
68	    return { error: "Server must be running or stopped." };
69	  }
70	  const res = await queueJob(serverId, "SNAPSHOT_CREATE", { name: clean });
71	  if (!res.error) {
72	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_create", detail: `${serverId} ${clean}` } });
73	    revalidatePath(`/dashboard/servers/${serverId}`);
74	  }
75	  return res;
76	}
