78	export async function deleteSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
79	  const { user } = await ownedServer(serverId);
80	  const clean = cleanSnapshotName(name);
81	  if (clean.length < 2) return { error: SNAPSHOT_NAME_ERROR };
82	  const res = await queueJob(serverId, "SNAPSHOT_DELETE", { name: clean });
83	  if (!res.error) {
84	    await db.auditLog.create({ data: { userId: user.id, action: "server.snapshot_delete", detail: `${serverId} ${clean}` } });
85	    revalidatePath(`/dashboard/servers/${serverId}`);
