90	export async function rollbackSnapshot(serverId: string, name: string): Promise<{ error?: string }> {
91	  const { user, server } = await ownedServer(serverId);
92	  const clean = cleanSnapshotName(name);
93	  if (clean.length < 2) return { error: SNAPSHOT_NAME_ERROR };
94	  // A rollback rewinds the VM's disk. The worker can only do that against a real
95	  // VM in a steady state — the same precondition createSnapshot already enforced.
96	  // Without it we accepted the request, said nothing, and let the job fail in the
97	  // worker while the customer believed their server was being restored.
98	  if (!server.vmid || !["RUNNING", "STOPPED"].includes(server.status)) {
99	    return { error: "Server must be running or stopped to roll back to a snapshot." };
100	  }
