160	
161	export async function resizeServer(
162	  serverId: string,
163	  planId: string,
164	  useWallet: boolean = true,
165	): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
166	  // Spend path: an upgrade debits the wallet (and can open a Stripe Checkout in
167	  // the customer's name), so it carries the same impersonation guard as every
168	  // other money movement — lib/actions-disk.ts expandServerDisk, lib/actions.ts
169	  // payAndDeploy/topUp/renewNow, and the domain transfer actions.
170	  // This one was missed, which made "upgrade the plan" the one charge an admin
171	  // impersonating a customer could still put on that customer's balance.
172	  await assertNotImpersonating();
173	  const { user, server } = await ownedServer(serverId);
174	  // Purchase gate: an upgrade is a charge (wallet or card). Downgrades live in
175	  // resizeServerDown and are deliberately NOT gated — that path REFUNDS, and
176	  // stopping a customer from spending LESS would be a gate with no one to
177	  // protect. See lib/email-verification.ts.
178	  const unverified = await emailVerificationError(user);
179	  if (unverified) return { error: unverified };
180	
181	  // Validate + price the upgrade (ownership already checked above). resizeQuote
182	  // recomputes the exact prorated charge over the remaining term.
183	  let quote;
184	  try {
185	    quote = await resizeQuote(serverId, planId);
186	  } catch (e) {
187	    if (e instanceof ResizeError) return { error: e.message };
188	    throw e;
189	  }
190	  const { newPlan, prorateCents } = quote;
191	
192	  // Wallet-aware split — identical logic to the deploy flow. ResizePicker computes
193	  // the same split (lib/wallet-split.ts) so displayed === charged.
194	  const { cardCents } = walletSplit({
195	    dueCents: prorateCents,
196	    balanceCents: user.balanceCents,
197	    useWallet,
198	  });
199	
200	  // Card portion > 0 → charge ONLY the remainder on the card (not the full
201	  // proration). The confirm route credits the card amount to the wallet and then
202	  // debits the FULL proration (encoded as chargeCents), so the wallet absorbs its
203	  // share and the card the rest — wallet never touched before the card clears.
204	  if (cardCents > 0) {
205	    const checkout = await createResizeCheckout(user, cardCents, {
206	      serverId,
207	      planId,
208	      planName: newPlan.name,
209	      prorateCents,
210	    });
211	    if (!checkout) {
212	      return {
213	        error: `Upgrading costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
214	      };
215	    }
216	    return { checkout };
217	  }
218	
219	  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
220	  // servers) → apply instantly, debiting the full proration from the wallet.
221	  try {
222	    await applyResize({ serverId, planId, actorUserId: user.id });
223	  } catch (e) {
224	    if (e instanceof ResizeError) return { error: e.message };
225	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
226	    throw e;
227	  }
228	  revalidatePath(`/dashboard/servers/${serverId}`);
229	  return {};
230	}
