250	// ---------- Port forwarding (firewall/networking) ----------
251	
252	import { SSH_PORT_START as PF_MIN, SSH_PORT_END as PF_MAX } from "./ipam";
253	const MAX_FORWARDS_PER_SERVER = 10;
254	
255	export async function addPortForward(prev: any, formData: FormData): Promise<{ error?: string }> {
256	  const serverId = String(formData.get("serverId") ?? "");
257	  const { user, server } = await ownedServer(serverId);
258	  const parsed = z
259	    .object({
260	      guestPort: z.coerce.number().int().min(1).max(65535),
261	      protocol: z.enum(["tcp", "udp"]),
262	    })
263	    .safeParse({ guestPort: formData.get("guestPort"), protocol: formData.get("protocol") ?? "tcp" });
264	  if (!parsed.success) return { error: "Invalid port." };
265	
266	  const count = await db.portForward.count({ where: { serverId } });
267	  if (count >= MAX_FORWARDS_PER_SERVER) return { error: `Limit of ${MAX_FORWARDS_PER_SERVER} forwards reached.` };
268	
269	  // Allocate the public port with the DB as the arbiter, not this read.
270	  //
271	  // `PortForward.publicPort` is UNIQUE (prisma/schema.prisma). Choosing a port
272	  // from a snapshot read and inserting it unguarded meant two requests that
273	  // overlapped — a double-click, or two customers adding a forward at the same
274	  // moment — both picked the same lowest free port and the loser's insert threw
275	  // a raw Prisma P2002. That exception escaped this action, so the customer got
276	  // a server-error page instead of a message, and (in production, where Next
277	  // redacts action errors) no clue what happened or that simply retrying works.
278	  //
279	  // Retry across the next few free candidates so an ordinary collision resolves
280	  // itself silently, and turn a genuine exhaustion into an honest, actionable
281	  // message rather than a crash.
282	  const used = new Set([
283	    ...(await db.portForward.findMany({ select: { publicPort: true } })).map((p) => p.publicPort),
284	    ...(await db.server.findMany({ where: { sshPort: { not: null } }, select: { sshPort: true } })).map((s) => s.sshPort!),
285	  ]);
286	  const candidates: number[] = [];
287	  for (let p = PF_MIN; p <= PF_MAX && candidates.length < 8; p++) {
288	    if (!used.has(p)) candidates.push(p);
289	  }
290	  if (candidates.length === 0) {
291	    return {
292	      error:
293	        "Every public port in the forwarding pool is in use, so we can't allocate one for this rule. " +
294	        "Delete a forward you no longer need, or contact support to have the pool widened.",
295	    };
296	  }
297	
298	  let publicPort = 0;
299	  for (const candidate of candidates) {
300	    try {
301	      await db.portForward.create({
302	        data: { serverId, publicPort: candidate, guestPort: parsed.data.guestPort, protocol: parsed.data.protocol },
303	      });
304	      publicPort = candidate;
305	      break;
306	    } catch (e: any) {
307	      // P2002 = another request took this port between our read and this insert.
308	      // Anything else is a real failure and must not be swallowed.
309	      if (e?.code !== "P2002") throw e;
310	    }
311	  }
312	  if (!publicPort) {
313	    return {
314	      error:
315	        "Another request took the public port we picked, several times in a row. " +
316	        "Nothing was created — please try adding the forward again.",
317	    };
318	  }
319	
320	  await db.job.create({ data: { type: "SYNC_FORWARDS", serverId } });
321	  // A NAT Minecraft server's game port isn't forwarded until this moment (see
322	  // worker/index.ts's provision() comment) — this may be the first time its
323	  // subdomain DNS has anything valid to point at.
324	  await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId } });
325	  await db.auditLog.create({
326	    data: { userId: user.id, action: "server.portforward_add", detail: `${serverId} :${publicPort}->${parsed.data.guestPort}/${parsed.data.protocol}` },
327	  });
328	  revalidatePath(`/dashboard/servers/${serverId}`);
329	  return {};
330	}
