471	export type ServerBackup = { volid: string; ctime?: number; size?: number };
472	
473	/**
474	 * List the vzdump backups on the `backup` storage that belong to this server's
475	 * VMID. Read-only Proxmox call, ownership-checked.
476	 */
477	export async function listServerBackups(
478	  serverId: string
479	): Promise<{ error?: string; backups?: ServerBackup[] }> {
480	  const { server } = await ownedServer(serverId);
481	  if (!server.vmid) return { backups: [] };
482	  try {
483	    const backups = (await listBackups(server.vmid)) as ServerBackup[];
484	    backups.sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
485	    return { backups };
486	  } catch {
487	    return { error: "Could not reach the hypervisor — try again in a moment." };
488	  }
