491	/**
492	 * Enqueue a BACKUP_RESTORE job for the selected vzdump archive. This OVERWRITES
493	 * the server's current disk. The volid is validated against the server's own
494	 * backups so a customer can only restore their own VM's archives.
495	 */
496	export async function requestRestore(
497	  serverId: string,
498	  volid: string
499	): Promise<{ error?: string }> {
500	  const { user, server } = await ownedServer(serverId);
501	  if (!server.vmid) return { error: "Server has no VM yet." };
502	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
503	    return { error: "Server must be running or stopped to restore a backup." };
504	  }
505	
506	  // Validate the archive actually belongs to this server's VMID (prevents
507	  // restoring another customer's backup by guessing a volid).
508	  let owned: ServerBackup[];
509	  try {
510	    owned = (await listBackups(server.vmid)) as ServerBackup[];
511	  } catch {
512	    return { error: "Could not verify the backup — the hypervisor is briefly unavailable." };
513	  }
514	  if (!owned.some((b) => b.volid === volid)) {
515	    return { error: "That backup was not found for this server." };
516	  }
517	
518	  // DATA SAFETY (critical): `qmrestore --force` over an existing VM calls PVE's
519	  // destroy_vm first ("avoid zombie disks when restoring over an existing VM"),
520	  // and destroy_vm frees EVERY volume the vmid owns, `unusedN` entries included.
521	  // Restoring a backup taken before a volume was attached therefore destroys that
522	  // volume's data silently, while `Volume.diskName` keeps pointing at the dead
523	  // volid and billing carries on.
524	  //
525	  // Reinstall already refuses for exactly this reason. Restore does the same thing
526	  // to the same vmid and had no guard at all — same rule, both layers.
527	  const pinnedVolumes = await db.volume.count({ where: { serverId } });
528	  if (pinnedVolumes > 0) {
529	    return {
530	      error:
531	        `Restoring replaces this server's disks, which would also destroy the ` +
532	        `${pinnedVolumes} data volume${pinnedVolumes === 1 ? "" : "s"} assigned to it — ` +
533	        `including any you have detached. Move or delete them first, then restore.`,
534	    };
535	  }
536	
537	  const idle = await ensureIdle(serverId);
538	  if (idle.error) return idle;
539	
540	  await db.job.create({ data: { type: "BACKUP_RESTORE", serverId, payload: { volid } } });
541	  await db.auditLog.create({
542	    data: { userId: user.id, action: "server.backup_restore", detail: `${serverId} ${volid}` },
543	  });
544	  revalidatePath(`/dashboard/servers/${serverId}`);
545	  return {};
546	}
