680	/**
681	 * Inbound firewall (security-group) rules for a customer's VPS.
682	 *
683	 * Ownership is enforced exactly like the port-forward actions: `ownedServer`
684	 * throws unless the caller owns the server (or is an admin). Every mutable field
685	 * is validated + normalised by lib/firewall-rules.ts BEFORE it is persisted, and
686	 * again in the worker before it reaches a shell. Each change enqueues a
687	 * SYNC_FIREWALL job that re-applies the FULL rule set idempotently on the guest.
688	 */
689	
690	const MAX_RULES_PER_SERVER = 50;
691	
692	async function ownedServer(serverId: string) {
693	  const user = await requireUser();
694	  const server = await db.server.findUnique({ where: { id: serverId } });
695	  if (!server) throw new Error("Not found");
696	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
697	  return { user, server };
698	}
699	
700	async function enqueueSync(serverId: string) {
701	  await db.job.create({ data: { type: "SYNC_FIREWALL", serverId } });
702	}
