704	export async function listFirewallRules(serverId: string) {
705	  await ownedServer(serverId);
706	  return db.firewallRule.findMany({
707	    where: { serverId },
708	    orderBy: [{ position: "asc" }, { createdAt: "asc" }],
709	  });
710	}
