712	export async function addFirewallRule(prev: any, formData: FormData): Promise<{ error?: string }> {
713	  const serverId = String(formData.get("serverId") ?? "");
714	  const { user } = await ownedServer(serverId);
715	
716	  // VALIDATE everything before it is persisted. `validateRule` is the same gate
717	  // the worker uses, so a rule this action accepts is guaranteed buildable.
718	  const result = validateRule({
719	    action: formData.get("action"),
720	    protocol: formData.get("protocol"),
721	    portFrom: formData.get("portFrom"),
722	    portTo: formData.get("portTo"),
723	    sourceCidr: formData.get("sourceCidr"),
724	  });
725	  if (!result.ok) return { error: result.error };
726	
727	  // `comment` is customer free text — persisted + shown, NEVER shell-bound.
728	  const comment = String(formData.get("comment") ?? "").trim().slice(0, 200) || null;
729	
730	  const count = await db.firewallRule.count({ where: { serverId } });
731	  if (count >= MAX_RULES_PER_SERVER) {
732	    return { error: `Limit of ${MAX_RULES_PER_SERVER} firewall rules reached. Delete one first.` };
733	  }
734	
735	  const last = await db.firewallRule.findFirst({
736	    where: { serverId },
737	    orderBy: { position: "desc" },
738	    select: { position: true },
739	  });
740	  const position = (last?.position ?? -1) + 1;
741	
742	  const { action, protocol, portFrom, portTo, sourceCidr } = result.rule;
743	  await db.firewallRule.create({
744	    data: {
745	      serverId,
746	      direction: "INBOUND",
747	      action: action as FirewallAction,
748	      protocol: protocol as FirewallProtocol,
749	      portFrom,
750	      portTo,
751	      sourceCidr,
752	      comment,
753	      enabled: true,
754	      position,
755	    },
756	  });
757	
758	  await enqueueSync(serverId);
759	  await db.auditLog.create({
760	    data: {
761	      userId: user.id,
762	      action: "server.firewall_add",
763	      detail: `${serverId} ${action} ${protocol} ${portFrom ?? "*"}-${portTo ?? "*"} from ${sourceCidr}`,
764	    },
765	  });
766	  revalidatePath(`/dashboard/servers/${serverId}`);
767	  return {};
768	}
