794	/**
795	 * Reorder rules by an explicit list of rule ids (new first-match order). Only
796	 * ids that actually belong to the server are moved; anything else is ignored, so
797	 * a caller cannot reposition another tenant's rule.
798	 */
799	export async function reorderFirewallRules(serverId: string, orderedIds: string[]): Promise<{ error?: string }> {
800	  const { user } = await ownedServer(serverId);
801	  if (!Array.isArray(orderedIds) || orderedIds.length === 0) return { error: "Nothing to reorder." };
802	
803	  const owned = await db.firewallRule.findMany({ where: { serverId }, select: { id: true } });
804	  const ownedIds = new Set(owned.map((r) => r.id));
805	  const ids = orderedIds.filter((id) => ownedIds.has(id));
806	  if (ids.length === 0) return { error: "No matching rules to reorder." };
807	
808	  await db.$transaction(
809	    ids.map((id, index) =>
810	      db.firewallRule.update({ where: { id }, data: { position: index } })
811	    )
812	  );
813	
814	  await enqueueSync(serverId);
815	  await db.auditLog.create({
816	    data: { userId: user.id, action: "server.firewall_reorder", detail: `${serverId} ${ids.length} rules` },
817	  });
818	  revalidatePath(`/dashboard/servers/${serverId}`);
819	  return {};
820	}
