845	"use server";
846	
847	import { revalidatePath } from "next/cache";
848	import { db } from "./db";
849	import { requireUser, assertNotImpersonating } from "./auth";
850	import { InsufficientBalanceError } from "./wallet";
851	import { diskExpandQuote, applyDiskExpand, DiskExpandError } from "./disk-expand";
852	import { createDiskExpandCheckout, type EmbeddedCheckout } from "./stripe";
853	import { walletSplit } from "./wallet-split";
854	import { normalizeExtraDiskGB } from "./extra-disk";
855	import { emailVerificationError } from "./email-verification";
856	
857	/**
858	 * Post-deploy "Add storage": grow ONE server's own root disk by N GB without
859	 * changing its plan (CPU/RAM/plan price are untouched).
860	 *
861	 * Money path is a carbon copy of lib/actions-server.ts resizeServer:
862	 *   quote -> walletSplit -> (card remainder ? Stripe checkout : apply now).
863	 * The wallet is only ever debited by applyDiskExpand, and only after the card
864	 * portion has cleared, so displayed === charged and nothing is charged twice.
865	 *
866	 * GROWTH IS ONE-WAY. There is deliberately no companion "shrink" action.
867	 */
868	
869	/** Max expansions a single customer may start in RATE_WINDOW_MS. */
870	const MAX_EXPANDS_PER_WINDOW = 5;
871	const RATE_WINDOW_MS = 10 * 60_000;
872	
873	async function ownedServer(serverId: string) {
874	  const user = await requireUser();
875	  const server = await db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
876	  if (!server) throw new Error("Not found");
877	  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
878	  return { user, server };
879	}
880	
881	export async function expandServerDisk(
882	  serverId: string,
883	  addGB: number,
884	  useWallet: boolean = true,
885	): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
886	  // Spend path: block wallet debits while an admin is impersonating.
887	  await assertNotImpersonating();
888	  const { user, server } = await ownedServer(serverId);
889	  // Purchase gate: a disk expansion is an irreversible charge.
890	  // See lib/email-verification.ts.
891	  const unverified = await emailVerificationError(user);
892	  if (unverified) return { error: unverified };
893	
894	  // Round DOWN to a purchasable amount — a malformed value can only ever cost
895	  // the customer less, never more (see normalizeExtraDiskGB).
896	  const gb = normalizeExtraDiskGB(addGB);
897	  if (gb <= 0) return { error: "Choose an amount of storage to add." };
898	
899	  // Rate limit: expansions are irreversible and each one queues real hypervisor
900	  // work, so cap how fast a single account can fire them off.
901	  const recent = await db.job.count({
902	    where: {
903	      type: "DISK_EXPAND",
904	      createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) },
905	      server: { userId: user.id },
906	    },
907	  });
908	  if (recent >= MAX_EXPANDS_PER_WINDOW) {
909	    return { error: "Too many storage expansions just now — please wait a few minutes and try again." };
910	  }
911	
912	  // Reject while another job is in flight, and only from a steady run state.
913	  // (applyDiskExpand re-checks both; this returns the friendlier message first.)
914	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
915	    return { error: "Server must be running or stopped to add storage." };
916	  }
917	  const pending = await db.job.count({
918	    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
919	  });
920	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
921	
922	  // Validate + price the expansion (ownership already checked above).
923	  let quote;
924	  try {
925	    quote = await diskExpandQuote(serverId, gb);
926	  } catch (e) {
927	    if (e instanceof DiskExpandError) return { error: e.message };
928	    throw e;
929	  }
930	  const { prorateCents } = quote;
931	
932	  // Wallet-aware split — identical logic to the deploy/resize flows. AddStorage
933	  // computes the same split (lib/wallet-split.ts) so displayed === charged.
934	  const { cardCents } = walletSplit({
935	    dueCents: prorateCents,
936	    balanceCents: user.balanceCents,
937	    useWallet,
938	  });
939	
940	  // Card portion > 0 → charge ONLY the remainder on the card. The confirm route
941	  // credits the card amount to the wallet and then debits the FULL proration
942	  // (encoded as chargeCents), so the wallet absorbs its share and the card the
943	  // rest — the wallet is never touched before the card clears.
944	  if (cardCents > 0) {
945	    const checkout = await createDiskExpandCheckout(user, cardCents, {
946	      serverId,
947	      addGB: gb,
948	      hostname: server.hostname,
949	      prorateCents,
950	    });
951	    if (!checkout) {
952	      return {
953	        error: `Adding ${gb} GB costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
954	      };
955	    }
956	    return { checkout };
957	  }
958	
959	  // Card portion is $0 (wallet fully covers it, or the charge is $0 for free/admin
960	  // servers) → apply instantly, debiting the full proration from the wallet.
961	  try {
962	    await applyDiskExpand({ serverId, addGB: gb, actorUserId: user.id });
963	  } catch (e) {
964	    if (e instanceof DiskExpandError) return { error: e.message };
965	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
966	    throw e;
967	  }
968	  revalidatePath(`/dashboard/servers/${serverId}`);
969	  return {};
970	}
