20	// of the static ESM asset under /public/novnc — Turbopack/Webpack must not try
21	// to resolve or bundle it.
22	const importESM: (u: string) => Promise<any> =
23	  typeof window !== "undefined"
24	    ? (new Function("u", "return import(u)") as (u: string) => Promise<any>)
25	    : async () => ({});
