27	const RFB_URL = "/novnc/core/rfb.js";
28	
29	export function Console({ serverId }: { serverId: string }) {
30	  const containerRef = useRef<HTMLDivElement>(null);
31	  const rfbRef = useRef<any>(null);
32	  const [phase, setPhase] = useState<Phase>("idle");
33	  const [message, setMessage] = useState<string | null>(null);
34	
35	  const cleanup = useCallback(() => {
36	    if (rfbRef.current) {
37	      try {
38	        rfbRef.current.disconnect();
39	      } catch {
40	        /* ignore */
41	      }
42	      rfbRef.current = null;
43	    }
44	  }, []);
45	
