269	/**
270	 * In-portal web terminal — a slide-in panel with an xterm.js terminal wired to
271	 * a real root shell on one of the customer's running servers.
272	 *
273	 * Security: the websocket is authorized by a short-lived token minted by
274	 * POST /api/terminal/token (which checks the session + ownership). This
275	 * component never sees any server credential — only the opaque token.
276	 *
277	 * Wire protocol (matches terminal-server/index.ts):
278	 *   client → server : JSON  {type:"data",data} | {type:"resize",cols,rows}
279	 *   server → client : raw shell output (text or binary) → written to xterm
280	 */
281	
282	export type TerminalServer = { id: string; hostname: string };
283	
284	type Status = "idle" | "connecting" | "connected" | "closed" | "error";
285	
286	/**
287	 * Imperative handle exposed to parents (e.g. the Matrix console's rich input
288	 * bar). `sendInput` injects text straight into the live PTY exactly as if the
289	 * user had typed it, so the parent's send box can drive the `claude` CLI.
290	 */
291	export type WebTerminalHandle = {
292	  /** Type `text` into the live PTY. No-op if the socket is not open. */
293	  sendInput: (text: string) => void;
294	  /** Whether the PTY websocket is currently open. */
295	  isConnected: () => boolean;
296	};
297	
298	type WebTerminalProps = {
299	  servers: TerminalServer[];
300	  /** Overlay mode only. Optional in embedded mode (no chrome to close). */
301	  onClose?: () => void;
302	  /**
303	   * When true, render inline (fills its parent) instead of as a full-screen
304	   * slide-in portal. Used to give each Matrix console its own terminal.
305	   */
306	  embedded?: boolean;
307	  /** Optional one-line idle hint shown before the first connect. */
308	  hint?: string;
309	};
310	
311	export const WebTerminal = forwardRef<WebTerminalHandle, WebTerminalProps>(function WebTerminal(
312	  { servers, onClose, embedded = false, hint },
313	  ref
314	) {
315	  const [mounted, setMounted] = useState(false);
316	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
317	  const [status, setStatus] = useState<Status>("idle");
318	  const [error, setError] = useState<string | null>(null);
319	  const [hintDismissed, setHintDismissed] = useState(false);
320	
