662	const TIMEFRAMES = [
663	  { key: "hour", label: "1h" },
664	  { key: "day", label: "24h" },
665	  { key: "week", label: "7d" },
666	  { key: "month", label: "30d" },
667	] as const;
668	
669	function xLabelsFor(rows: Row[], tf: string): string[] {
670	  if (rows.length < 2) return [];
671	  const n = 6;
672	  const labels: string[] = [];
673	  for (let i = 0; i < n; i++) {
674	    const idx = Math.round((i / (n - 1)) * (rows.length - 1));
675	    const d = new Date(rows[idx].time * 1000);
676	    labels.push(
677	      tf === "hour" || tf === "day"
678	        ? `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`
679	        : `${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")}`
680	    );
681	  }
682	  return labels;
683	}
