689	
690	  const load = useCallback(async (timeframe: string, quiet: boolean) => {
691	    if (!quiet) setRows(null);
692	    setError(null);
693	    try {
694	      const res = await fetch(`/api/metrics?serverId=${serverId}&tf=${timeframe}`, {
695	        cache: "no-store",
696	      });
697	      if (!res.ok) throw new Error("metrics unavailable");
698	      const json: { data?: Row[] } = await res.json();
699	      setRows(
700	        (json.data ?? []).filter(
701	          (r) => r && typeof r.time === "number" && (r.cpu !== null || r.mem !== null)
702	        )
703	      );
704	    } catch {
705	      setError("Metrics are temporarily unavailable — the hypervisor may be busy.");
706	      setRows([]);
707	    }
708	  }, [serverId]);
709	
710	  useEffect(() => {
711	    void load(tf, false);
712	    const t = setInterval(() => void load(tf, true), 30_000);
713	    return () => clearInterval(t);
714	  }, [tf, load]);
715	
716	  const loading = rows === null;
717	  const data = rows ?? [];
718	  const xLabels = xLabelsFor(data, tf);
719	  const maxMemGB = Math.max(...data.map((r) => (r.maxmem ?? 0) / 1e9), 1);
