734	                  : "text-slate-400 hover:text-white"
735	              }`}
736	            >
737	              {t.label}
738	            </button>
739	          ))}
740	        </div>
741	      </div>
742	
743	      {error && (
744	        <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
745	          {error}
746	        </div>
747	      )}
748	
749	      {loading ? (
750	        <div className="space-y-6">
751	          <div className="skeleton h-56 w-full" />
752	          <div className="skeleton h-56 w-full" />
753	          <div className="skeleton h-56 w-full" />
754	        </div>
755	      ) : data.length === 0 ? (
