926	/**
927	 * Create-backup button + LIVE progress bar. Owns polling of the current
928	 * backup/restore job (`getBackupJob`) so it renders a themed bar with the live
929	 * percentage + step while a job is QUEUED/RUNNING, shows a "Backup failed —
930	 * server unaffected" note on failure, and refreshes the backups list on success.
931	 * Restores (enqueued elsewhere) surface here too since the poll covers both types.
932	 */
933	export function CreateBackupButton({
934	  serverId,
935	  disabled,
936	  initialJob = null,
937	}: {
938	  serverId: string;
939	  disabled?: boolean;
940	  initialJob?: BackupJobStatus | null;
941	}) {
942	  const router = useRouter();
943	  const [job, setJob] = useState<BackupJobStatus | null>(initialJob);
944	  const [error, setError] = useState<string | null>(null);
945	  const [queueing, setQueueing] = useState(false);
946	  const [dismissed, setDismissed] = useState<string | null>(null);
947	
948	  // Ids we've observed in-flight this mount + the last status per id, so we can
949	  // detect an in-flight → DONE transition and refresh the list exactly once.
950	  const watched = useRef<Set<string>>(new Set());
951	  const lastStatus = useRef<Record<string, string>>({});
952	
953	  const fetchJob = useCallback(async () => {
954	    try {
955	      const j = await getBackupJob(serverId);
956	      if (isInFlight(j)) watched.current.add(j.id);
957	      if (j) {
958	        const prev = lastStatus.current[j.id];
959	        // In-flight → DONE: the archive now exists, reload the backups table.
960	        if (prev && prev !== j.status && j.status === "DONE" && watched.current.has(j.id)) {
