1164	function xLabelsFor(rows: Pt[], tf: string): string[] {
1165	  if (rows.length < 2) return [];
1166	  const n = 6;
1167	  const labels: string[] = [];
1168	  for (let i = 0; i < n; i++) {
1169	    const idx = Math.round((i / (n - 1)) * (rows.length - 1));
1170	    const d = new Date(rows[idx].time * 1000);
1171	    labels.push(
1172	      tf === "day"
1173	        ? `${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`
1174	        : `${String(d.getMonth() + 1).padStart(2, "0")}/${String(d.getDate()).padStart(2, "0")}`
1175	    );
1176	  }
1177	  return labels;
1178	}
