1195	    async (timeframe: string, quiet: boolean) => {
1196	      if (!quiet) setRows(null);
1197	      setError(null);
1198	      try {
1199	        const res = await fetch(`/api/servers/${serverId}/disk?tf=${timeframe}`, {
1200	          cache: "no-store",
1201	        });
1202	        if (!res.ok) throw new Error("unavailable");
1203	        const json: { data?: Pt[]; planTotalBytes?: number } = await res.json();
1204	        const data = (json.data ?? []).filter((r) => r && typeof r.time === "number");
1205	        setRows(data);
1206	        setTotal(json.planTotalBytes ?? planTotalGB * GB);
1207	      } catch {
1208	        setError("Disk metrics are temporarily unavailable — the hypervisor may be busy.");
1209	        setRows([]);
