4	import { useEffect, useRef, useState } from "react";
5	import { createPortal } from "react-dom";
6	import { RevealPassword, CopyText } from "@/components/customer/ServerAccess";
7	
8	/**
9	 * The Hostinger-style "your order is being set up" interstitial — shown full
10	 * screen right after a customer pays/deploys, while the VM is still
11	 * PENDING/PROVISIONING, then a one-time success card once it flips to
12	 * RUNNING. Deliberately built as a pure overlay on TOP of the existing
13	 * server-detail page rather than a new route: the page underneath keeps
14	 * rendering (and keeps refreshing via the existing `<AutoRefresh />`) exactly
15	 * as it always has, so this component only ever needs to react to props that
16	 * are already being recomputed every 5s — no new polling loop, no new server
17	 * action.
18	 *
19	 * Visibility rules (see the effect below for the full state machine):
20	 *   - Shows the "provisioning" phase whenever the server is in a transitional
21	 *     status. Sets a sessionStorage flag so a REFRESH mid-provision still
22	 *     shows it (not just the initial mount).
23	 *   - Shows "success" the moment that flag is set AND the status flips to
24	 *     RUNNING — OR, for the case where the server was ALREADY done by the
25	 *     time this page first loaded (real orders provision in under two
26	 *     minutes, but this platform's SANDBOX mode completes instantly), when
27	 *     the URL carries the `purchase=1` marker `reportPurchase` already stamps
28	 *     onto every real paid-order redirect.
29	 *   - Never shown for a customer just casually revisiting an old, already-
30	 *     running server — that's the whole reason for the two gates above
31	 *     instead of "status === RUNNING".
32	 *   - Once dismissed, stays dismissed for this server (sessionStorage),
33	 *     surviving a refresh.
34	 */
35	export function ProvisioningOverlay({
36	  serverId,
37	  status,
38	  transitional,
39	  justPaid,
40	  provisionError,
41	  productLabel,
42	  hostname,
43	  connectAddress,
44	  planName,
45	  osName,
46	  rootPassword,
47	  rootPasswordLabel,
48	  extraInfo,
49	  readyStatus = "RUNNING",
50	  liveStep = null,
51	  liveStepActive = false,
52	  dashboardHref,
53	}: {
54	  serverId: string;
55	  status: string;
56	  transitional: boolean;
57	  /**
58	   * True only when THIS request's URL carried `?purchase=1` — read server-side
59	   * from `searchParams` and passed down as a plain prop, not re-derived from
60	   * `window.location.search` on the client. `app/dashboard/layout.tsx`'s
61	   * PurchaseTracker also reads `?purchase=1` (to fire the conversion pixel)
62	   * and then strips it via `router.replace()`; a client-side read here loses
