71	  productLabel: string;
72	  hostname: string;
73	  /** The connect string to show, e.g. "ssh root@1.2.3.4" or "1.2.3.4:25565" — null while not yet assigned. */
74	  connectAddress: string | null;
75	  planName: string;
76	  osName: string | null;
77	  rootPassword: string | null;
78	  /** Label for the `rootPassword` row — defaults to "Root password" (VPS/game). Shared
