85	  extraInfo?: { label: string; value: string; href?: string }[];
86	  /** The status value that means "done, show the success card" — "RUNNING" for a
87	   *  VPS/game server, "ACTIVE" for a Shared Hosting account. */
88	  readyStatus?: string;
89	  /** Real (never fake/invented) current-step label, e.g. "Cloning your server…" or
