101	  /** Where "Go to your server" sends them — normally just this same page. */
102	  dashboardHref: string;
103	}) {
104	  const storageKey = `nxeon:overlay:${serverId}`;
105	  const [phase, setPhase] = useState<"hidden" | "provisioning" | "success">("hidden");
106	  const mountedAtRef = useRef<number | null>(null);
107	  // Real infra provisions in well under this — it's purely a perceived-progress
108	  // floor so the animation never flashes by unreadably fast (e.g. SANDBOX mode,
109	  // which completes instantly), not a claim about how long the real work takes.
110	  const MIN_PROVISIONING_MS = 3200;
111	
112	  useEffect(() => {
113	    let watching = false;
114	    try {
115	      watching = sessionStorage.getItem(storageKey) === "watching";
116	    } catch {
117	      /* storage disabled — degrade to "never show" rather than guess */
118	    }
119	
120	    if (transitional) {
121	      if (mountedAtRef.current == null) mountedAtRef.current = Date.now();
122	      setPhase("provisioning");
123	      try {
124	        sessionStorage.setItem(storageKey, "watching");
125	      } catch {
126	        /* ignore */
127	      }
128	      return;
129	    }
130	
131	    // Not transitional anymore (by the base status alone). Before deciding this is
132	    // done, check for a real, product-specific follow-on step still running — e.g.
133	    // Shared Hosting's account just flipped ACTIVE but a WordPress install queued
134	    // at order time is still processing. Gated on watching/justPaid, same as the
135	    // block above: this must never resurrect the full-screen takeover for a LATER,
136	    // casual action (installing an app months after purchase) — only for a follow-
137	    // on step that belongs to the SAME order this session was already watching.
138	    if (liveStepActive && (watching || justPaid) && sessionStorage.getItem(storageKey) !== "dismissed") {
