140	      return;
141	    }
142	
143	    // Only earn a success screen if we were either actively watching this order
144	    // provision, or just landed here from a real paid checkout (the
145	    // sandbox-instant-complete case).
146	    if (status === readyStatus && (watching || justPaid) && sessionStorage.getItem(storageKey) !== "dismissed") {
147	      const elapsed = mountedAtRef.current ? Date.now() - mountedAtRef.current : MIN_PROVISIONING_MS;
148	      const wait = Math.max(0, MIN_PROVISIONING_MS - elapsed);
149	      const t = setTimeout(() => setPhase("success"), wait);
150	      return () => clearTimeout(t);
151	    }
152	    // ERROR or anything else while we were watching: hand off to the page's
153	    // own ProvisionErrorBanner rather than duplicating retry UI here.
154	    setPhase("hidden");
155	    // eslint-disable-next-line react-hooks/exhaustive-deps
156	  }, [transitional, status, liveStepActive, readyStatus]);
