849	export function CancelService({
850	  serverId,
851	  hostname,
852	  expiresAt,
853	  autoRenew,
854	  refundEstimateCents,
855	}: {
856	  serverId: string;
857	  hostname: string;
858	  /** ISO date; null for a free/no-term server (period-end is not offered then). */
859	  expiresAt: string | null;
860	  autoRenew: boolean;
861	  /** Prorated refund the customer would get on IMMEDIATE termination, in cents. */
862	  refundEstimateCents: number;
863	}) {
864	  const [open, setOpen] = useState(false);
865	  const [pending, startTransition] = useTransition();
866	  const [error, setError] = useState<string | null>(null);
867	  const [done, setDone] = useState<string | null>(null);
868	
869	  const money = (c: number) => `$${(c / 100).toFixed(2)}`;
870	  const expiryLabel = expiresAt ? new Date(expiresAt).toISOString().slice(0, 10) : null;
871	
872	  const run = (mode: "immediate" | "period_end") => {
873	    if (mode === "immediate") {
874	      const msg =
875	        `Immediately terminate ${hostname}? This destroys the server and PERMANENTLY erases all its data — this cannot be undone.` +
876	        (refundEstimateCents > 0
877	          ? `\n\n${money(refundEstimateCents)} for the unused part of your term will be credited to your wallet.`
878	          : "\n\nNo refund applies (nothing left on the paid term).");
879	      if (!window.confirm(msg)) return;
880	    }
881	    setError(null);
882	    setDone(null);
