2	import { NextRequest, NextResponse } from "next/server";
3	import { createHash, randomUUID } from "node:crypto";
4	import { EncryptJWT } from "jose";
5	import { db } from "@/lib/db";
6	import { currentUser } from "@/lib/auth";
7	import { checkRateLimit } from "@/lib/rate-limit";
8	import { pve, node as primaryNode } from "@/lib/proxmox";
9	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
10	
11	export const dynamic = "force-dynamic";
12	
13	/**
14	 * In-browser VNC console — ticket issuer.
15	 *
16	 * GET /api/console/[serverId]
17	 *
18	 * Flow:
19	 *  1. Authenticate the caller (owner or admin).
20	 *  2. Ask Proxmox for a websocket VNC proxy ticket for the server's VM
21	 *     (POST .../vncproxy?websocket=1). This returns a short-lived VNC ticket +
22	 *     an ephemeral port on the Proxmox node.
23	 *  3. Package the connection target — Proxmox API base, node, vmid, port, the
24	 *     VNC ticket, and the API token needed to authenticate the websocket
25	 *     upgrade — into an ENCRYPTED (JWE / A256GCM) token, valid 60s, with a
26	 *     unique jti so the relay can enforce single use.
27	 *  4. Return only { wsPath, ticketId } to the browser. The browser NEVER sees
28	 *     the Proxmox API token or the raw VNC ticket — those live inside the JWE,
29	 *     which only the relay (sharing AUTH_SECRET) can decrypt.
30	 *
31	 * The relay (scripts/console-proxy.mjs) receives sid=<JWE> on the browser
32	 * websocket, decrypts it, opens a TLS websocket to Proxmox with the real
33	 * credentials, and pipes bytes both ways.
34	 */
35	
36	// 256-bit symmetric key for JWE, derived from the app's AUTH_SECRET.
37	// The relay derives the identical key the same way — no extra shared secret.
38	function consoleKey(): Uint8Array {
39	  const secret = process.env.AUTH_SECRET;
40	  if (!secret) throw new Error("AUTH_SECRET is not set");
41	  return new Uint8Array(createHash("sha256").update(`nxeon-console:${secret}`).digest());
42	}
43	
44	export async function GET(
45	  _req: NextRequest,
46	  { params }: { params: Promise<{ serverId: string }> }
47	) {
48	  const { serverId } = await params;
49	
50	  const user = await currentUser();
51	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
52	
53	  // Throttle ticket minting per user (falling back to IP) BEFORE we ask
54	  // Proxmox for a vncproxy ticket — each grant spawns an ephemeral vncproxy
55	  // process, so an unthrottled loop could orphan thousands of them.
56	  // Keyed on the authenticated user id, which is always present here (the 401
57	  // above already returned for anonymous callers) — the old `user.id || ip`
58	  // fallback was dead code whose `ip` half read the first, caller-supplied hop
59	  // of X-Forwarded-For.
60	  const rl = checkRateLimit(`console:${user.id}`, { max: 10, windowMs: 60_000 });
61	  if (!rl.ok) {
62	    return NextResponse.json(
63	      { error: "too many console requests — slow down", retryAfterSec: rl.retryAfterSec },
64	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
65	    );
66	  }
67	
68	  const server = await db.server.findUnique({
69	    where: { id: serverId },
70	    include: { node: true },
71	  });
72	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
73	    return NextResponse.json({ error: "not found" }, { status: 404 });
74	  }
75	  if (!server.vmid) {
76	    return NextResponse.json({ error: "no VM provisioned" }, { status: 409 });
77	  }
78	  if (server.status !== "RUNNING") {
79	    return NextResponse.json(
80	      { error: "server must be running to open the console" },
81	      { status: 409 }
82	    );
83	  }
84	
85	  // Resolve which Proxmox node + credentials to use. Multi-node servers carry a
86	  // Node row; otherwise fall back to the primary node from the environment.
87	  const apiBase = server.node?.apiUrl ?? process.env.PROXMOX_API_URL ?? "https://127.0.0.1:8006";
88	  const pveNode = server.node?.pveNode ?? primaryNode;
89	  const tokenId = server.node?.tokenId ?? process.env.PROXMOX_TOKEN_ID ?? "";
90	  const tokenSecret = server.node?.tokenSecret ?? process.env.PROXMOX_TOKEN_SECRET ?? "";
91	
92	  if (!pveNode || !tokenId || !tokenSecret) {
93	    return NextResponse.json({ error: "console not configured" }, { status: 500 });
94	  }
95	
96	  // Request a websocket VNC proxy ticket from Proxmox.
97	  let vnc: { ticket: string; port: string | number };
98	  try {
99	    // Use the node-scoped client for non-primary nodes so the ticket is valid
100	    // for the right host; the primary node uses the shared `pve` client.
101	    if (server.node) {
102	      const { pveFor } = await import("@/lib/proxmox");
103	      const client = pveFor({
104	        apiUrl: server.node.apiUrl,
105	        pveNode: server.node.pveNode,
106	        tokenId: server.node.tokenId,
107	        tokenSecret: server.node.tokenSecret,
108	      });
109	      vnc = await client.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
110	        websocket: 1,
111	      });
112	    } else {
113	      vnc = await pve.post(`/nodes/${pveNode}/qemu/${server.vmid}/vncproxy`, {
114	        websocket: 1,
115	      });
116	    }
117	  } catch {
118	    return NextResponse.json(
119	      { error: "hypervisor did not grant a console ticket — try again shortly" },
120	      { status: 502 }
121	    );
122	  }
123	
124	  if (!vnc?.ticket || vnc.port === undefined) {
125	    return NextResponse.json({ error: "invalid console ticket from hypervisor" }, { status: 502 });
126	  }
127	
128	  const ticketId = randomUUID();
129	
130	  // Encrypt the full connection target. Only the relay can read this.
131	  const sid = await new EncryptJWT({
132	    apiBase,
133	    node: pveNode,
134	    vmid: server.vmid,
135	    port: Number(vnc.port),
136	    vncticket: vnc.ticket,
137	    tokenId,
138	    tokenSecret,
139	  })
140	    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
141	    .setJti(ticketId)
142	    .setIssuedAt()
143	    .setExpirationTime("60s")
144	    .encrypt(consoleKey());
145	
146	  // Public websocket URL of the relay. In production behind HTTPS, set
147	  // CONSOLE_PUBLIC_WS_URL to a wss:// endpoint (e.g. proxied by nginx) so the
148	  // browser isn't blocked by mixed-content. Otherwise we hand out a bare
149	  // ws://PUBLIC_IP:PORT/console URL for the standalone relay.
150	  const base =
151	    process.env.CONSOLE_PUBLIC_WS_URL?.replace(/\/+$/, "") ??
152	    `ws://${process.env.PUBLIC_IP ?? "127.0.0.1"}:${process.env.CONSOLE_PROXY_PORT ?? "8899"}/console`;
153	
154	  const wsPath = `${base}?sid=${encodeURIComponent(sid)}`;
155	
156	  // `wsPath` embeds the JWE that authorizes a VNC session on this customer's
157	  // VM. It is a GET response and carried no cache directive at all, so a shared
158	  // proxy could store it and hand a working console ticket for someone else's
159	  // server to the next caller of this URL. Never cache it anywhere.
160	  return NextResponse.json({ wsPath, ticketId }, { headers: NO_STORE_HEADERS });
161	}
