192	async function ownedServer(
193	  serverId: string,
194	  userId: string,
195	  isAdmin: boolean
196	): Promise<SftpServer | null> {
197	  const server = await db.server.findUnique({
198	    where: { id: serverId },
199	    select: {
200	      id: true,
201	      userId: true,
202	      rootPassword: true,
203	      // The encrypted-at-rest password is the authoritative one for any server
204	      // provisioned after credential encryption shipped; the plaintext column is
205	      // null for those. serverRootPassword() prefers Enc and falls back to
206	      // plaintext, so BOTH must be selected — omitting Enc made every
207	      // encrypted-password server fail with "Server has no root password set."
208	      rootPasswordEnc: true,
209	      sshPort: true,
210	      dedicatedIp: { select: { address: true } },
211	    },
