365	/**
366	 * Secure customer backup download.
367	 *
368	 *   GET /api/servers/[serverId]/backups/download?volid=backup:backup/vzdump-...zst
369	 *     -> streams the vzdump archive as an attachment.
370	 *
371	 * SECURITY (the whole point of the card): a customer must only ever be able to
372	 * download a backup of a server THEY own. Two independent guards:
373	 *   1. Ownership — the server row must belong to the session user (or an admin).
374	 *   2. Tenancy of the archive — the requested volid must appear in this server's
375	 *      OWN backup listing (listBackups(vmid) is filtered by the server's vmid).
376	 *      This is the identical guard requestRestore() uses, so a guessed/forged
377	 *      volid for another tenant's vmid is rejected before any disk access.
378	 * Only after both pass do we touch the filesystem, and even then the resolved
379	 * path is confined to the backup dump dir (basename only, no traversal).
380	 *
381	 * Proxmox exposes no HTTP endpoint that streams a .vma.zst archive, so the file
382	 * is read off the host filesystem (the web app runs on the Proxmox host, same as
383	 * the platform-backups status reads).
384	 */
385	export const dynamic = "force-dynamic";
386	
387	// Only ever serve real vzdump archives — never anything else in the dump dir.
388	const ARCHIVE_RE = /^vzdump-[A-Za-z0-9._-]+\.(vma|tar)(\.(zst|gz|lzo))?$/;
389	
390	export async function GET(
391	  req: NextRequest,
392	  { params }: { params: Promise<{ id: string }> }
393	) {
394	  const { id: serverId } = await params;
395	
396	  const user = await currentUser();
397	  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
398	
399	  const rl = checkRateLimit(`backups:download:${user.id}`, { max: 20, windowMs: 60_000 });
400	  if (!rl.ok) {
401	    return NextResponse.json(
402	      { error: "too many downloads — slow down", retryAfterSec: rl.retryAfterSec },
403	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
404	    );
405	  }
406	
407	  // 1. Ownership.
408	  const server = await db.server.findUnique({
409	    where: { id: serverId },
410	    select: { id: true, userId: true, vmid: true },
411	  });
412	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
413	    return NextResponse.json({ error: "not found" }, { status: 404 });
414	  }
415	  if (!server.vmid) {
416	    return NextResponse.json({ error: "server has no VM yet" }, { status: 400 });
417	  }
418	
419	  const volid = req.nextUrl.searchParams.get("volid");
420	  if (!volid) return NextResponse.json({ error: "missing volid" }, { status: 400 });
421	
422	  // 2. Tenancy of the archive — must belong to THIS server's vmid.
423	  let owned: Array<{ volid: string }>;
424	  try {
425	    owned = (await listBackups(server.vmid)) as Array<{ volid: string }>;
426	  } catch {
427	    return NextResponse.json(
428	      { error: "could not verify the backup — the hypervisor is briefly unavailable" },
429	      { status: 502 }
430	    );
431	  }
432	  if (!owned.some((b) => b.volid === volid)) {
433	    return NextResponse.json({ error: "that backup was not found for this server" }, { status: 404 });
434	  }
435	
436	  // Resolve volid -> on-disk file. The basename is the only part we trust; it
437	  // must be a real vzdump archive name and cannot escape the dump dir.
438	  const filename = volid.split("/").pop() ?? "";
439	  if (!ARCHIVE_RE.test(filename)) {
440	    return NextResponse.json({ error: "unsupported backup format" }, { status: 400 });
441	  }
442	  const dumpDir = await backupDumpDir();
443	  const filePath = path.join(dumpDir, filename);
444	  if (path.dirname(path.resolve(filePath)) !== path.resolve(dumpDir)) {
445	    // Defence in depth — basename regex already forbids separators.
446	    return NextResponse.json({ error: "invalid backup path" }, { status: 400 });
447	  }
448	
449	  let size: number;
450	  try {
451	    const st = await stat(filePath);
452	    if (!st.isFile()) throw new Error("not a file");
453	    size = st.size;
454	  } catch {
455	    return NextResponse.json(
456	      { error: "backup archive is not available on the host for download" },
457	      { status: 502 }
458	    );
459	  }
460	
461	  // Stream the file rather than buffering — archives are multi-GB.
462	  const nodeStream = createReadStream(filePath);
463	  const webStream = Readable.toWeb(nodeStream) as unknown as ReadableStream<Uint8Array>;
464	
465	  return new NextResponse(webStream, {
466	    status: 200,
467	    headers: {
468	      "Content-Type": "application/octet-stream",
469	      "Content-Length": String(size),
470	      "Content-Disposition": `attachment; filename="${filename.replace(/["\\]/g, "_")}"`,
471	      "Cache-Control": "private, no-store",
472	    },
473	  });
474	}
