476	import { NextRequest, NextResponse } from "next/server";
477	import { db } from "@/lib/db";
478	import { currentUser } from "@/lib/auth";
479	import { getGuestDiskUsage, pve, node as defaultNode, pveFor } from "@/lib/proxmox";
480	import { effectiveDiskGB } from "@/lib/extra-disk";
481	import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
