483	export const dynamic = "force-dynamic";
484	
485	type Pt = { time: number; disk: number | null; maxdisk: number | null };
486	
487	// Chart timeframe → lookback window (ms). Matches DiskUsageChart's 24h/7d/30d.
488	const WINDOW_MS: Record<string, number> = {
489	  day: 24 * 60 * 60_000,
490	  week: 7 * 24 * 60 * 60_000,
491	  month: 30 * 24 * 60 * 60_000,
492	};
493	
494	/**
495	 * Real in-guest disk usage for a server the current user owns.
496	 *
497	 * Data comes from ServerDiskSample (collected by the worker via the QEMU guest
498	 * agent, since Proxmox RRD reports disk=0 for QEMU VMs) for the requested
499	 * window, plus a fresh live get-fsinfo reading appended as the current point.
500	 * Falls back to the latest stored sample when the live call isn't ready, and to
501	 * an empty series (chart shows the "not reporting" note) only when neither the
502	 * agent nor any sample yields anything.
503	 */
504	export async function GET(req: NextRequest, ctx: { params: Promise<{ id: string }> }) {
505	  const { id } = await ctx.params;
506	  const user = await currentUser();
507	  if (!user) {
508	    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
509	  }
510	
511	  const tf = req.nextUrl.searchParams.get("tf") ?? "day";
512	
513	  const server = await db.server.findUnique({
514	    where: { id },
515	    include: { node: true, plan: true },
516	  });
517	  if (!server || (server.userId !== user.id && user.role !== "ADMIN") || !server.vmid) {
518	    return NextResponse.json({ error: "not found" }, { status: 404, headers: NO_STORE_HEADERS });
519	  }
520	
521	  // Effective disk (plan + purchased extra) — a server that bought extra storage
522	  // must not be charted against its plan's smaller allowance.
523	  const planTotalBytes = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB) * 1024 ** 3;
524	  const since = new Date(Date.now() - (WINDOW_MS[tf] ?? WINDOW_MS.day));
525	
526	  // 1. Stored history for the window.
527	  let samples: { ts: Date; usedBytes: bigint; totalBytes: bigint }[] = [];
528	  try {
529	    samples = await db.serverDiskSample.findMany({
530	      where: { serverId: id, ts: { gte: since } },
531	      orderBy: { ts: "asc" },
532	      select: { ts: true, usedBytes: true, totalBytes: true },
533	    });
534	  } catch {
535	    samples = [];
536	  }
537	
538	  const data: Pt[] = samples.map((s) => ({
539	    time: Math.floor(s.ts.getTime() / 1000),
540	    disk: Number(s.usedBytes),
541	    maxdisk: Number(s.totalBytes),
542	  }));
543	
544	  // 2. Fresh live reading for the current point (best-effort).
545	  let current: { usedBytes: number; totalBytes: number } | null = null;
546	  try {
547	    const client = server.node
548	      ? pveFor({
549	          apiUrl: server.node.apiUrl,
550	          pveNode: server.node.pveNode,
551	          tokenId: server.node.tokenId,
552	          tokenSecret: server.node.tokenSecret,
553	        })
554	      : pve;
555	    const pnode = server.node?.pveNode ?? defaultNode;
556	    current = await getGuestDiskUsage(client, pnode, server.vmid, planTotalBytes);
557	  } catch {
558	    current = null;
559	  }
560	
561	  // Fall back to the newest stored sample when the live call isn't ready.
562	  if (!current && samples.length > 0) {
563	    const last = samples[samples.length - 1];
564	    current = { usedBytes: Number(last.usedBytes), totalBytes: Number(last.totalBytes) };
565	  }
566	
567	  // Append the current reading so the chart always shows the freshest value
568	  // (and isn't empty when there are no samples yet but the agent responds).
569	  if (current) {
570	    data.push({
571	      time: Math.floor(Date.now() / 1000),
572	      disk: current.usedBytes,
573	      maxdisk: current.totalBytes,
574	    });
575	  }
576	
577	  return NextResponse.json({ data, planTotalBytes }, { headers: NO_STORE_HEADERS });
578	}
