696	 * Web-terminal authorization ticket issuer.
697	 *
698	 *   POST /api/terminal/token   { serverId }
699	 *
700	 * Flow:
701	 *  1. Authenticate the caller (reuses lib/auth `requireUser`).
702	 *  2. Verify the caller OWNS the target server (userId match — or an admin) and
703	 *     that it is RUNNING. This is the ONLY place the session cookie is checked;
704	 *     the websocket itself is authorized purely by the token minted here.
705	 *  3. Mint a 60-second encrypted token encoding { userId, serverId } and return
706	 *     it. The browser hands this token to the terminal websocket, which
707	 *     re-verifies it and re-checks ownership before SSHing to the VM.
708	 *
709	 * The token is short-lived and single-purpose: it authorizes opening ONE shell
710	 * on ONE server for the user it names. It carries no credentials — the VM's
711	 * root password never leaves the server side.
712	 */
713	export const dynamic = "force-dynamic";
714	
715	export async function POST(req: NextRequest) {
716	  let user;
717	  try {
718	    user = await requireUser();
719	  } catch {
720	    return NextResponse.json({ error: "unauthorized" }, { status: 401 });
721	  }
722	
723	  // Throttle minting per user so a stolen session can't spin up shells in a loop.
724	  const rl = checkRateLimit(`terminal:token:${user.id}`, { max: 20, windowMs: 60_000 });
725	  if (!rl.ok) {
726	    return NextResponse.json(
727	      { error: "too many terminal requests — slow down", retryAfterSec: rl.retryAfterSec },
728	      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
729	    );
730	  }
731	
732	  let serverId: unknown;
733	  try {
734	    const body = await req.json();
735	    serverId = body?.serverId;
736	  } catch {
737	    return NextResponse.json({ error: "expected a JSON body" }, { status: 400 });
738	  }
739	  if (typeof serverId !== "string" || !serverId) {
740	    return NextResponse.json({ error: "serverId is required" }, { status: 400 });
741	  }
742	
743	  // Ownership check — same pattern as lib/actions-server-ops.ts / app/api/files:
744	  // the server must exist and belong to the caller (admins may open any).
745	  const server = await db.server.findUnique({
746	    where: { id: serverId },
747	    select: { id: true, userId: true, status: true },
