772	
773	/**
774	 * POST /api/telemetry/ingest — receives a batched-events payload from the
775	 * nxeon-shipper agent (see agent/nxeon-shipper/main.go `sender()`), running
776	 * either per-server on a VPS/game box or once centrally on a shared-hosting
777	 * or mail node.
778	 *
779	 * AUTH: `Authorization: Bearer <token>` — a persistent, hash-at-rest token
780	 * minted at provision time (lib/telemetry-token.ts), NOT the session-cookie
781	 * auth every other API route in this app uses. This endpoint is reachable
782	 * from customer VMs on the public internet, not just the admin's browser.
783	 *
784	 * This intentionally does the least amount of work possible per request:
785	 * validate the token, clamp + insert the batch, return. No fan-out, no
786	 * websocket push here — the admin monitor page reads back via its existing
787	 * poll (see lib/telemetry.ts header comment for why that's the right call
788	 * on a single-node deployment).
789	 */
790	export async function POST(req: NextRequest) {
791	  const auth = req.headers.get("authorization") ?? "";
792	  const token = auth.startsWith("Bearer ") ? auth.slice(7).trim() : "";
793	  if (!token) {
794	    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
795	  }
796	
797	  // Throttle per-token rather than per-IP: a shipper on a NATted VM shares an
798	  // IP with the platform's own NAT gateway, but always presents its own
799	  // token, so this is the correct dedup key. Generous ceiling — a legitimate
800	  // shipper posts ~1 batch/3s; this allows bursts (e.g. reconnect after an
801	  // outage flushing several catch-up batches) without false-positiving.
802	  const rl = checkRateLimit(`telemetry:ingest:${token}`, { max: 40, windowMs: 60_000 });
803	  if (!rl.ok) {
804	    return NextResponse.json({ error: "rate limited" }, { status: 429, headers: NO_STORE_HEADERS });
805	  }
806	
807	  let body: BatchIn;
808	  try {
809	    body = await req.json();
810	  } catch {
811	    return NextResponse.json({ error: "invalid json" }, { status: 400, headers: NO_STORE_HEADERS });
812	  }
813	
814	  try {
815	    const result = await ingestTelemetryBatch(token, body);
816	    if (!result.ok) {
817	      return NextResponse.json({ error: result.reason }, { status: 401, headers: NO_STORE_HEADERS });
818	    }
819	    return NextResponse.json({ ok: true, stored: result.stored }, { headers: NO_STORE_HEADERS });
820	  } catch (e) {
821	    console.error("[telemetry/ingest] route error", e);
822	    return NextResponse.json({ error: "ingest failed" }, { status: 500, headers: NO_STORE_HEADERS });
823	  }
824	}
