17	async function pveRequestTo(
18	  base: string,
19	  token: string,
20	  method: "GET" | "POST" | "PUT" | "DELETE",
21	  path: string,
22	  params?: Record<string, string | number | undefined>
23	): Promise<any> {
24	  const url = new URL(`${base}/api2/json${path}`);
25	  let body: string | undefined;
26	  const headers: Record<string, string> = { Authorization: token };
