28	  const clean = Object.fromEntries(
29	    Object.entries(params ?? {}).filter(([, v]) => v !== undefined)
30	  ) as Record<string, string>;
31	
32	  if (method === "GET" || method === "DELETE") {
33	    for (const [k, v] of Object.entries(clean)) url.searchParams.set(k, String(v));
34	  } else {
35	    body = new URLSearchParams(clean as Record<string, string>).toString();
36	    headers["Content-Type"] = "application/x-www-form-urlencoded";
37	  }
