39	  const res = await undiciFetch(url, { method, headers, body, dispatcher: insecureAgent });
40	  const text = await res.text();
41	  if (!res.ok) {
42	    throw new ProxmoxError(`PVE ${method} ${path} -> ${res.status}`, res.status, text);
43	  }
44	  try {
45	    return JSON.parse(text).data;
46	  } catch {
47	    return text;
48	  }
49	}
