136	// Live task progress (vzdump backup / qmrestore restore)
137	// ---------------------------------------------------------------------------
138	
139	/** Minimal shape any progress poller needs — satisfied by `pve` and `pveFor`. */
140	export type TaskClient = {
141	  get: (path: string, params?: Record<string, any>) => Promise<any>;
142	  node: string;
143	};
144	
145	export type TaskPhase = "backup" | "restore";
146	
147	/**
148	 * Parse the latest completion percentage and a human step out of Proxmox task
149	 * log lines. vzdump/qmrestore emit lines such as:
150	 *   "INFO:  42% (4.6 GiB of 11.0 GiB) in 12s, read: ..."
151	 *   "INFO: status: 42%"
152	 *   "progress 42% (read 4.6 GiB, ...)"
153	 *   "INFO: creating vzdump archive '/mnt/backup/...'"
154	 * Returns the last percentage seen (or null) plus a coarse step label.
155	 */
156	export function parseTaskProgress(
157	  lines: string[],
158	  phase: TaskPhase
159	): { pct: number | null; step: string | null } {
160	  let pct: number | null = null;
161	  let step: string | null = null;
162	  const verb = phase === "restore" ? "Restoring archive" : "Creating archive";
163	
164	  for (const raw of lines) {
165	    const line = String(raw ?? "");
166	    const m = line.match(/(\d{1,3})\s*%/);
167	    if (m) {
168	      const v = Number(m[1]);
169	      if (v >= 0 && v <= 100) pct = v;
170	    }
171	    const l = line.toLowerCase();
172	    if (l.includes("creating vzdump archive") || l.includes("starting new backup")) step = "Creating archive";
173	    else if (l.includes("restore") && (l.includes("start") || l.includes("archive"))) step = "Restoring archive";
174	    else if (l.includes("uploading") || l.includes("upload")) step = "Uploading backup";
175	    else if (l.includes("transferred") || l.includes("read:")) step = verb;
176	    else if (l.includes("finished") || l.includes("finalize") || l.includes("closing")) step = "Finalizing";
177	  }
178	  if (pct !== null && step) step = `${step}… ${pct}%`;
179	  return { pct, step: step ?? (pct !== null ? `${verb}… ${pct}%` : null) };
180	}
181	
182	/**
183	 * Wait for a Proxmox task while streaming live progress. Polls `/status` (to
184	 * detect completion) and `/tasks/<upid>/log` (for the percentage) every ~2s and
185	 * invokes `onProgress(progress, step)` on each tick.
186	 *
187	 * Progress is monotonic and never regresses. The parsed task percentage (0..100)
188	 * is mapped into the caller's [base, base+span] window so multi-phase callers
189	 * (e.g. restore = stop→restore→start) can reserve sub-ranges. When no % has been
190	 * parsed yet, a coarse time-based creep keeps the bar moving up to a cap.
191	 */
192	export async function waitForTaskProgress(
193	  client: TaskClient,
194	  upid: string,
195	  onProgress: (progress: number, step: string) => void | Promise<void>,
196	  opts: { timeoutMs?: number; phase?: TaskPhase; base?: number; span?: number } = {}
197	): Promise<void> {
198	  const timeoutMs = opts.timeoutMs ?? 3_600_000;
199	  const phase = opts.phase ?? "backup";
200	  const base = opts.base ?? 0;
201	  const span = opts.span ?? 100;
202	  const enc = encodeURIComponent(upid);
203	
204	  const start = Date.now();
205	  let reported = base; // last value handed to onProgress (monotonic)
206	  let creep = 0; // coarse fallback estimate while no % is available
207	
208	  while (Date.now() - start < timeoutMs) {
209	    let stopped = false;
210	    let exitOk = true;
211	
212	    try {
213	      const status = await client.get(`/nodes/${client.node}/tasks/${enc}/status`);
214	      if (status?.status === "stopped") {
215	        stopped = true;
216	        exitOk = status.exitstatus === "OK";
217	      }
218	    } catch {
219	      /* transient — try again next tick */
220	    }
221	
222	    // Read the log tail and parse the newest percentage/step. Cheap enough for a
223	    // single VM backup; failures are non-fatal.
224	    let step: string | null = null;
225	    let pct: number | null = null;
226	    try {
227	      const log = await client.get(`/nodes/${client.node}/tasks/${enc}/log`, { start: 0, limit: 400 });
228	      const lines: string[] = Array.isArray(log) ? log.map((e: any) => e?.t ?? "") : [];
229	      const parsed = parseTaskProgress(lines, phase);
230	      pct = parsed.pct;
231	      step = parsed.step;
232	    } catch {
233	      /* ignore */
234	    }
235	
236	    // Compute the target within [base, base+span].
237	    let target: number;
238	    if (pct !== null) {
239	      target = base + (span * pct) / 100;
240	    } else {
241	      // Coarse creep: advance slowly toward 85% of the window until a % appears.
242	      creep = Math.min(creep + 4, 85);
243	      target = base + (span * creep) / 100;
244	    }
245	    if (target > reported) reported = target;
246	
247	    if (!stopped) {
248	      await onProgress(Math.round(Math.min(reported, base + span)), step ?? (phase === "restore" ? "Restoring…" : "Creating archive…"));
249	    }
250	
251	    if (stopped) {
252	      if (!exitOk) {
253	        // Surface the real failure reason from the log tail when available.
254	        throw new Error(`Proxmox task failed: ${upid}`);
255	      }
256	      return;
257	    }
258	
259	    await new Promise((r) => setTimeout(r, 2000));
260	  }
261	  throw new Error(`Proxmox task timed out: ${upid}`);
262	}
