273	/**
274	 * Is this Proxmox error specifically "vmid <n> is not on this node"?
275	 *
276	 * PVE answers a GET/DELETE for an unknown vmid with HTTP 500 and the body
277	 *   Configuration file 'nodes/<node>/qemu-server/<vmid>.conf' does not exist
278	 * (verified by running `qm config 999123` on this host, 2026-07-27).
279	 *
280	 * The match is deliberately ANCHORED ON THE VMID rather than on the bare phrase
281	 * "does not exist". `remove()` in worker/index.ts used to swallow anything whose
282	 * message contained that phrase, which also matches errors that mean the exact
283	 * opposite of "the VM is gone" — `storage 'vmdata' does not exist`, `volume ...
284	 * does not exist`, `snapshot 'x' does not exist`. Any of those would have let the
285	 * DELETE handler decide the VM had been destroyed, drop the Server row and every
286	 * Volume row pinned to it, and leave a live VM running on the hypervisor with no
287	 * database record: unbilled, unmanageable and still holding customer data.
288	 */
289	export function isVmAbsentError(e: unknown, vmid: number): boolean {
290	  const err = e as { body?: unknown; message?: unknown } | null | undefined;
291	  const msg = `${err?.body ?? ""} ${err?.message ?? (typeof e === "string" ? e : "")}`;
292	  if (!Number.isInteger(vmid)) return false;
293	  return (
294	    new RegExp(`qemu-server[/\\\\]${vmid}\\.conf'?\\s+does not exist`, "i").test(msg) ||
295	    new RegExp(`\\bVM\\s+${vmid}\\s+does not exist\\b`, "i").test(msg) ||
296	    new RegExp(`\\bno such vm\\b.*\\b${vmid}\\b`, "i").test(msg)
297	  );
298	}
