300	/**
301	 * The side-effectful half of a VM teardown, behind a seam so the decision ladder
302	 * in `destroyVmIdempotent` can be exercised without a hypervisor.
303	 * `test/vm-lifecycle.test.ts` drives it with an in-memory fake.
304	 */
305	export type VmDestroyHost = {
306	  /** Ground truth from the hypervisor. "unknown" when it could not be read — never a guess. */
307	  probe: (vmid: number) => Promise<"present" | "absent" | "unknown">;
308	  /** Best-effort stop; may reject if the VM is already stopped or gone. */
309	  stop: (vmid: number) => Promise<void>;
310	  /** The destructive call. */
311	  destroy: (vmid: number) => Promise<void>;
312	};
313	
314	export type DestroyOutcome = {
315	  /** True when THIS call issued the destroy and the VM is verified gone afterwards. */
316	  destroyed: boolean;
317	  /** True when the VM was already absent, so no destructive call was issued. */
318	  alreadyAbsent: boolean;
319	  detail: string;
320	};
321	
322	/**
323	 * Destroy a VM in a way that is SAFE TO RUN TWICE, and that never claims a
324	 * teardown it did not observe.
325	 *
326	 * INCIDENT (found in audit, 2026-07-27 — worker/index.ts `reinstall`): REINSTALL
327	 * is destroy-then-provision, and the worker retries a failed job up to
328	 * MAX_ATTEMPTS times. `destroyVm` issued `DELETE /qemu/<vmid>` unconditionally
329	 * and did not tolerate the VM already being gone. So when attempt 1 destroyed the
330	 * VM and then failed anywhere in the re-provision that follows (a snippet write,
331	 * a clone timeout, a config POST), attempts 2 and 3 both died on the very first
332	 * step — `Configuration file '…/<vmid>.conf' does not exist` — and never reached
333	 * the provision that was supposed to rebuild the machine. The job ended FAILED,
334	 * REINSTALL is in VM_STATE_FAILURE_JOBS so the server was flipped to ERROR, and
335	 * the customer was left with no VM at all: the retry mechanism itself converted a
336	 * recoverable mid-reinstall failure into permanent destruction. `remove()` in the
337	 * same file already tolerated the absent case, which is what made the omission
338	 * here an oversight rather than a policy.
339	 *
340	 * The ladder:
341	 *   1. PROBE FIRST. An absent VM means there is nothing to destroy — return
342	 *      without issuing any destructive call at all.
343	 *   2. "unknown" does NOT block the destroy (the caller has already decided this
344	 *      vmid is to be torn down, and the vmid is not in question), but it is
345	 *      carried into the detail so nothing downstream reads it as a clean run.
346	 *   3. TOLERATE a vmid-anchored absent error from the destroy itself — that is
347	 *      the retry racing a previous attempt that actually succeeded.
348	 *   4. VERIFY AFTER. Re-probe; if the VM is still present the destroy did not
349	 *      happen and we throw, rather than let a caller delete the database rows
350	 *      that are the only remaining handle on a live machine.
351	 */
352	export async function destroyVmIdempotent(
353	  host: VmDestroyHost,
354	  vmid: number
355	): Promise<DestroyOutcome> {
356	  const beforeState = await host.probe(vmid);
357	  if (beforeState === "absent") {
358	    return {
359	      destroyed: false,
360	      alreadyAbsent: true,
361	      detail: `VM ${vmid} was already absent — no destroy was issued`,
362	    };
363	  }
364	
365	  // Stop first. A stop failure is not fatal: the VM may already be stopped, and a
366	  // real blocker (a config lock, a running backup) will surface on the destroy.
367	  try {
368	    await host.stop(vmid);
369	  } catch {
370	    /* already stopped, or gone — the destroy below is the authority */
371	  }
372	
373	  try {
374	    await host.destroy(vmid);
375	  } catch (e) {
376	    if (!isVmAbsentError(e, vmid)) throw e;
377	    return {
378	      destroyed: false,
379	      alreadyAbsent: true,
380	      detail: `VM ${vmid} disappeared before the destroy landed — treating as already torn down`,
381	    };
382	  }
383	
384	  // Never report a teardown we did not observe.
385	  const afterState = await host.probe(vmid);
386	  if (afterState === "present") {
387	    throw new Error(
388	      `destroy of VM ${vmid} reported success but the VM is still present on the hypervisor — ` +
389	        `refusing to continue, because the caller would delete the only records that still point at it.`
390	    );
391	  }
392	  return {
393	    destroyed: true,
394	    alreadyAbsent: false,
395	    detail:
396	      afterState === "absent"
397	        ? `VM ${vmid} destroyed and verified gone`
398	        : `VM ${vmid} destroy completed, but its post-destroy state could not be read back`,
399	  };
400	}
