402	// ---------------------------------------------------------------------------
403	// VMID reuse: the previous tenant's backups
404	// ---------------------------------------------------------------------------
405	
406	/**
407	 * Choose a vmid for a NEW server, skipping any id whose backup archives are
408	 * still sitting in the shared `backup` storage.
409	 *
410	 * INCIDENT (found in audit, 2026-07-27): nothing ever removed a destroyed
411	 * server's vzdump archives. `remove()` purges the VM and deletes the Server row,
412	 * but `backup:backup/vzdump-qemu-<vmid>-*.vma.zst` survives indefinitely. PVE's
413	 * `/cluster/nextid` hands out the LOWEST free id, so the next server deployed
414	 * after a deletion lands on the freed vmid — and every surface that reasons about
415	 * backups keys on the vmid alone:
416	 *
417	 *   - `listBackups(vmid)` (this file) filters on `b.vmid === vmid`, so the new
418	 *     owner's Backups tab lists the previous tenant's archives as their own;
419	 *   - `requestRestore` in lib/actions-server-ops.ts validates the requested volid
420	 *     against that same listing, so it ACCEPTS them — one click restores a
421	 *     stranger's entire root filesystem onto the new customer's VM, handing them
422	 *     that tenant's databases, application secrets, SSH keys and /etc/shadow;
423	 *   - `pruneBackups` (this file) then counts those archives as the new owner's
424	 *     and DELETES the previous tenant's data to enforce keep-last-2.
425	 *
426	 * Live on this host today (read-only `pvesm list backup`, 2026-07-27): vmids
427	 * 100–104 and 8000 all hold archives while `/cluster/nextid` answers 105 — so a
428	 * single delete followed by a single deploy is all it takes.
429	 *
430	 * This is the NON-DESTRUCTIVE half of the fix: skip the id, delete nothing.
431	 * Deciding whether a terminated customer's archives should be reaped (and after
432	 * how long) is a data-retention policy call, not an audit call.
433	 *
434	 * Pure and total: no I/O, no clock. `candidate` is the hypervisor's suggestion,
435	 * `takenVmids` the ids already in use, `archivedVmids` the ids that still own
436	 * archives. Returns the first id at or above `candidate` that is in neither set.
437	 */
438	export function pickProvisionVmid(opts: {
439	  candidate: number;
440	  takenVmids: ReadonlySet<number>;
441	  archivedVmids: ReadonlySet<number>;
442	  maxProbe?: number;
443	}): { vmid: number; skipped: number[] } {
444	  const { candidate, takenVmids, archivedVmids } = opts;
445	  const maxProbe = opts.maxProbe ?? 512;
446	  if (!Number.isInteger(candidate) || candidate <= 0) {
447	    throw new Error(`pickProvisionVmid: '${candidate}' is not a usable vmid`);
448	  }
449	  const skipped: number[] = [];
450	  for (let id = candidate; id < candidate + maxProbe; id++) {
451	    if (takenVmids.has(id) || archivedVmids.has(id)) {
452	      skipped.push(id);
453	      continue;
454	    }
455	    return { vmid: id, skipped };
456	  }
457	  throw new Error(
458	    `no vmid free of stale backup archives in [${candidate}, ${candidate + maxProbe}). ` +
459	      `Reap the orphaned archives in the "backup" storage (pvesm list backup) before deploying — ` +
460	      `reusing one of these ids would show the new customer the previous tenant's backups.`
461	  );
462	}
