464	/** Every vmid that still owns an archive in the `backup` storage, via a node-scoped client. */
465	export async function archivedVmids(client: TaskClient): Promise<Set<number>> {
466	  const content: StorageBackupEntry[] = await client.get(
467	    `/nodes/${client.node}/storage/backup/content`,
468	    { content: "backup" }
469	  );
470	  const out = new Set<number>();
471	  for (const b of content ?? []) {
472	    if (typeof b?.vmid === "number" && Number.isInteger(b.vmid)) out.add(b.vmid);
473	  }
474	  return out;
475	}
