506	/** Real filesystem usage as reported from *inside* the guest. */
507	export type GuestDiskUsage = { usedBytes: number; totalBytes: number };
508	
509	/** Any client exposing `get` (satisfied by `pve` and `pveFor(...)`). */
510	export type GuestAgentClient = {
511	  get: (path: string, params?: Record<string, any>) => Promise<any>;
512	};
513	
514	// Pseudo / virtual filesystems that don't represent real on-disk usage and must
515	// never be picked as the root filesystem. Matched against the fsinfo `type`.
516	const PSEUDO_FS_TYPES = new Set([
517	  "squashfs", "tmpfs", "devtmpfs", "overlay", "overlayfs", "vfat", "msdos",
518	  "proc", "sysfs", "cgroup", "cgroup2", "debugfs", "mqueue", "hugetlbfs",
519	  "fusectl", "pstore", "autofs", "binfmt_misc", "tracefs", "configfs",
520	  "securityfs", "ramfs", "nsfs", "efivarfs", "fuse.snapfuse", "iso9660",
521	]);
522	
523	/** Is this mountpoint one we should ignore even if the type looks real? */
524	function isIgnorableMount(mountpoint: string): boolean {
525	  const mp = String(mountpoint ?? "");
526	  return (
527	    mp === "/boot" ||
528	    mp.startsWith("/boot/") ||
529	    mp.startsWith("/snap") ||
530	    mp.startsWith("/var/lib/docker") ||
531	    mp.startsWith("/run") ||
532	    mp.startsWith("/dev") ||
533	    mp.startsWith("/sys") ||
534	    mp.startsWith("/proc")
535	  );
536	}
