538	/**
539	 * Query the QEMU guest agent's `get-fsinfo` and return the REAL root filesystem
540	 * usage (the entry mounted at "/", excluding pseudo/boot/loop filesystems).
541	 *
542	 * Proxmox RRD's `disk` field is 0 for QEMU VMs — the hypervisor can't see
543	 * in-guest usage — so this agent call is the only source of real used/total
544	 * bytes. Best-effort: returns null on any error or when the agent isn't ready
545	 * (never throws), so a missing agent degrades cleanly to the provisioned-size
546	 * fallback. In SANDBOX returns a synthetic, gently-varying realistic value.
547	 *
548	 * @param sandboxTotalBytes only used to size the synthetic sandbox value.
549	 */
550	export async function getGuestDiskUsage(
551	  client: GuestAgentClient,
552	  node: string,
553	  vmid: number,
554	  sandboxTotalBytes?: number
555	): Promise<GuestDiskUsage | null> {
556	  if (SANDBOX) {
557	    const total = sandboxTotalBytes && sandboxTotalBytes > 0 ? sandboxTotalBytes : 40 * 1024 ** 3;
558	    const base = 0.3 + (Math.abs(vmid) % 35) / 100; // 0.30..0.64
559	    const drift = 0.03 * Math.sin(Date.now() / (6 * 3600_000) + vmid); // slow ±3%
560	    const frac = Math.min(0.95, Math.max(0.05, base + drift));
561	    return { usedBytes: Math.round(total * frac), totalBytes: total };
562	  }
563	
564	  try {
565	    const res = await client.get(`/nodes/${node}/qemu/${vmid}/agent/get-fsinfo`);
566	    // The agent wraps the array in { result: [...] }; tolerate a bare array too.
567	    const list: any[] = Array.isArray(res?.result)
568	      ? res.result
569	      : Array.isArray(res)
570	        ? res
571	        : [];
572	    if (list.length === 0) return null;
573	
574	    const real = list.filter((fs) => {
575	      const type = String(fs?.type ?? "").toLowerCase();
576	      const mp = String(fs?.mountpoint ?? "");
577	      if (PSEUDO_FS_TYPES.has(type)) return false;
578	      if (isIgnorableMount(mp)) return false;
579	      const total = Number(fs?.["total-bytes"]);
580	      return Number.isFinite(total) && total > 0;
581	    });
582	    if (real.length === 0) return null;
583	
584	    // Prefer the real root filesystem; otherwise the largest real mount.
585	    const root =
586	      real.find((fs) => String(fs?.mountpoint) === "/") ??
587	      real.sort((a, b) => Number(b?.["total-bytes"]) - Number(a?.["total-bytes"]))[0];
588	
589	    const usedBytes = Number(root?.["used-bytes"]);
590	    const totalBytes = Number(root?.["total-bytes"]);
591	    if (!Number.isFinite(usedBytes) || !Number.isFinite(totalBytes) || totalBytes <= 0) {
592	      return null;
593	    }
594	    return { usedBytes, totalBytes };
595	  } catch {
596	    // Agent not installed / not ready / VM stopped / transient PVE error.
597	    return null;
598	  }
599	}
