601	/**
602	 * Wait until the QEMU guest agent answers, i.e. until the guest has genuinely
603	 * booted far enough to run software.
604	 *
605	 * WHY: `waitForTask(startUpid)` proves only that Proxmox ACCEPTED the start —
606	 * not that the guest booted, that cloud-init ran, or that sshd is listening. The
607	 * provision path used to write RUNNING and hand the customer a copy-pasteable
608	 * `ssh root@…` line on the strength of that task alone (M7 #10), which is why a
609	 * RUNNING server eight minutes old could still show "SSH command: provisioning…".
610	 *
611	 * Returns true only on a real reply. On timeout it returns FALSE rather than
612	 * throwing, so the caller can degrade its message honestly instead of failing a
613	 * server that is merely slow — a guest with no agent installed is a normal state
614	 * for some images, and calling that a provisioning failure would be its own lie.
615	 */
616	export async function waitForGuestAgent(
617	  client: GuestAgentClient,
618	  node: string,
619	  vmid: number,
620	  timeoutMs = 180_000,
621	  pollMs = 5_000
622	): Promise<boolean> {
623	  const deadline = Date.now() + timeoutMs;
624	  for (;;) {
625	    try {
626	      await client.get(`/nodes/${node}/qemu/${vmid}/agent/ping`);
627	      return true;
628	    } catch {
629	      /* agent not up yet */
630	    }
631	    if (Date.now() >= deadline) return false;
632	    await new Promise((r) => setTimeout(r, pollMs));
633	  }
634	}
