636	/**
637	 * Force the CURRENT (DB) root password onto a running guest via the QEMU guest
638	 * agent — no reboot, no dependence on cloud-init. Same primitive `passwordReset`
639	 * (worker/index.ts) uses to change a password live; pulled out here so any other
640	 * caller whose action replaces or reverts the VM's actual disk content can reuse
641	 * it, rather than re-deriving the QGA call.
642	 *
643	 * WHY THIS EXISTS BEYOND passwordReset: `SNAPSHOT_ROLLBACK` and `BACKUP_RESTORE`
644	 * both put an OLDER copy of the guest's real disk back — including whatever
645	 * `/etc/shadow` existed at snapshot/backup time — while `Server.rootPasswordEnc`
646	 * in the DB keeps whatever the CURRENT password is. If a `PASSWORD_RESET` (or
647	 * any other password change) happened between that snapshot/backup being taken
648	 * and it being rolled back to / restored from, the guest reverts to the OLDER
649	 * password while the DB still holds the NEWER one — every later SSH from the
650	 * platform (control panel, GAME_POWER, mods, backups) then authenticates with
651	 * the DB's password against a guest that has a different one, failing with "All
652	 * configured authentication methods failed". This is the identical divergence
653	 * class documented on `provision()`'s password-reuse fix, just reached by
654	 * reverting old disk state instead of a retried clone — see that comment for the
655	 * full incident. Callers must invoke this after the VM is confirmed running and
656	 * its guest agent has answered (e.g. via `waitForGuestAgent`).
657	 *
658	 * Best-effort: never throws. Returns whether the QGA call was accepted — false
659	 * means the guest's password could not be confirmed resynced, which callers
660	 * should log loudly rather than silently swallow (the rollback/restore itself
661	 * still genuinely succeeded, so this must not fail that job).
662	 */
663	export async function applyPasswordToGuest(conn: PveClient, vmid: number, password: string): Promise<boolean> {
664	  try {
665	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/agent/set-user-password`, {
666	      username: "root",
667	      password,
668	    });
669	    if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
670	    return true;
671	  } catch (e) {
672	    console.error(`[proxmox] applyPasswordToGuest failed for vmid ${vmid}`, e);
673	    return false;
674	  }
675	}
