707	// ---------------------------------------------------------------------------
708	// Platform backups vs customer backups
709	// ---------------------------------------------------------------------------
710	//
711	// DATA LOSS PREVENTED (real, on this host, 2026-07-26): `scripts/backup-vms.sh`
712	// used to write the platform's own host-level disaster-recovery archives into the
713	// SAME Proxmox storage (`backup` -> /tank/backup/dump) that customers' on-demand
714	// backups land in, and `pruneBackups` below selected victims with nothing but
715	// `b.vmid === vmid`. So vmid 102 ended the 04:31 platform run holding two
716	// archives — the customer's own manual one from 2026-07-25 12:22 and the
717	// platform's 10 GB DR copy from 2026-07-26 04:31 — and the customer's very next
718	// click on "Create backup" (keep = CUSTOMER_BACKUP_KEEP = 2) would have deleted
719	// the platform's copy of their VM. Repeated across the fleet that silently
720	// destroys the entire bare-metal recovery set, one customer click at a time.
721	//
722	// The fix is three independent layers, in order of strength:
723	//
724	//  1. STRUCTURAL. `scripts/backup-vms.sh` now writes with `vzdump --dumpdir
725	//     /tank/backup/platform`, a directory that is NOT the `dump/` subdirectory of
726	//     any configured PVE storage. Proxmox only indexes `<storage-path>/dump`, so
727	//     platform archives have no `volid` at all: they cannot appear in the
728	//     `/storage/backup/content` listing this function iterates, and there is no
729	//     volid string that `DELETE /storage/backup/content/<volid>` could resolve to
730	//     them. Not "filtered out" — not addressable.
731	//  2. CHOKEPOINT. `deleteBackup` is the only function in the repo that issues a
732	//     storage-content DELETE (whole-repo grep: this file plus its single caller in
733	//     worker/index.ts). It re-derives protection for every volid immediately
734	//     before deleting and refuses on any of: the PVE `protected` attribute, the
735	//     platform notes marker, or the protection registry — and it fails CLOSED if
736	//     it cannot determine the answer.
737	//  3. MARKER + REGISTRY. If the platform job is ever pointed back at a shared PVE
738	//     storage (`NXEON_VM_BACKUP_STORAGE=backup`), it stamps each archive with
739	//     `--notes-template` carrying PLATFORM_BACKUP_MARKER and appends the volid to
740	//     PROTECTED_REGISTRY. Both are honoured below, which also covers the archives
741	//     already sitting in /tank/backup/dump from the 2026-07-26 04:31 run, written
742	//     before layer 1 existed.
743	
744	/** Where the platform's own whole-system vzdump archives live — outside every PVE storage. */
745	export const PLATFORM_BACKUP_DIR = process.env.NXEON_PLATFORM_BACKUP_DIR ?? "/tank/backup/platform";
746	
747	/**
748	 * Stamped into the vzdump notes of platform archives (see `--notes-template` in
749	 * scripts/backup-vms.sh). Customer retention must never delete an archive whose
750	 * notes contain this string.
751	 */
752	export const PLATFORM_BACKUP_MARKER = "NXEON-PLATFORM-BACKUP";
753	
754	/**
755	 * One volid per line. Maintained by scripts/backup-vms.sh; also seeded with any
756	 * pre-existing platform archives that were written into the shared storage before
757	 * the dumpdir split. Anything listed here is undeletable through this module.
758	 */
759	const PROTECTED_REGISTRY = `${PLATFORM_BACKUP_DIR}/PROTECTED-VOLIDS`;
760	
761	/**
762	 * Read the protection registry.
763	 *
764	 * Returns `null` when the registry exists but could not be read. Callers MUST
765	 * treat `null` as "protection state unknown" and refuse to delete: a transient
766	 * EIO on this file must not be the thing that lets a customer's prune wipe the
767	 * platform's recovery set. A registry that simply does not exist yet (fresh
768	 * install, platform job has never run) is a legitimate empty set — layer 1 means
769	 * there is nothing in the shared storage to protect in that case anyway.
770	 */
771	async function protectedVolids(): Promise<Set<string> | null> {
772	  const { readFile } = await import("node:fs/promises");
773	  try {
774	    const raw = await readFile(PROTECTED_REGISTRY, "utf8");
775	    return new Set(
776	      raw.split("\n").map((l) => l.trim()).filter((l) => l.length > 0 && !l.startsWith("#"))
777	    );
778	  } catch (e: any) {
779	    if (e?.code === "ENOENT") return new Set();
780	    console.error(`[proxmox] protection registry ${PROTECTED_REGISTRY} unreadable — refusing to prune`, e);
781	    return null;
782	  }
783	}
784	
785	/** Shape of one entry in `/nodes/<node>/storage/<sid>/content`. */
786	/**
787	 * Every backup archive the `backup` storage holds for one VMID, read through a
788	 * node-scoped client. This is the READ-BACK that `backupCreate` uses to prove an
789	 * archive actually exists: the vzdump task's exit status says the task ran, not
790	 * that a file landed. See worker/backup-schedule.ts (`freshBackupProof`) and
791	 * incident H4.
792	 */
793	export async function listBackupsOn(client: any, vmid: number): Promise<StorageBackupEntry[]> {
794	  const content: StorageBackupEntry[] = await client.get(
795	    `/nodes/${client.node}/storage/backup/content`,
796	    { content: "backup" }
797	  );
798	  return content.filter((b) => b.vmid === vmid && typeof b.volid === "string");
799	}
