801	export type StorageBackupEntry = {
802	  volid?: string;
803	  vmid?: number;
804	  ctime?: number;
805	  size?: number;
806	  notes?: string;
807	  protected?: boolean | number;
808	};
809	
810	/**
811	 * Is this archive one of the platform's own (i.e. never customer-prunable)?
812	 * Any single signal is enough — they are deliberately redundant.
813	 */
814	export function isPlatformArchive(b: StorageBackupEntry, registry: Set<string>): boolean {
815	  if (b.protected) return true;
816	  if (typeof b.notes === "string" && b.notes.includes(PLATFORM_BACKUP_MARKER)) return true;
817	  if (typeof b.volid === "string" && registry.has(b.volid)) return true;
818	  return false;
819	}
820	
821	/**
822	 * Delete one backup archive by its Proxmox volume id. `client` = the node's pve client.
823	 *
824	 * This is the ONLY storage-content DELETE in the codebase, so it is where the
825	 * "a customer can never delete a platform archive" invariant is enforced rather
826	 * than merely intended. It re-checks protection against the live hypervisor for
827	 * the exact volid being deleted — a caller that passed a stale or hand-crafted
828	 * volid cannot slip past it. Every uncertain outcome throws.
829	 */
830	export async function deleteBackup(client: any, volid: string): Promise<void> {
831	  // Only `<storage>:backup/<basename>` volids are deletable here. Rejecting
832	  // anything else keeps a malformed or path-traversing volid from ever reaching
833	  // the API, and keeps this function honest about what it operates on.
834	  const m = /^([A-Za-z0-9._-]+):backup\/([^/]+)$/.exec(volid);
835	  if (!m) throw new Error(`refusing to delete: '${volid}' is not a <storage>:backup/<file> volid`);
836	
837	  const registry = await protectedVolids();
838	  if (registry === null) {
839	    throw new Error(`refusing to delete ${volid}: platform protection registry unreadable`);
840	  }
841	  if (registry.has(volid)) {
842	    throw new Error(`refusing to delete ${volid}: listed in the platform protection registry`);
843	  }
844	
845	  // Ask the hypervisor about this exact volume. `notes` and `protected` are both
846	  // returned by the content-info endpoint (PVE::API2::Storage::Content). A failure
847	  // here means we do not know whether this is a platform archive, so we stop.
848	  let info: any;
849	  try {
850	    info = await client.get(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
851	  } catch (e) {
852	    throw new Error(`refusing to delete ${volid}: could not read its attributes (${e})`);
853	  }
854	  if (isPlatformArchive({ volid, notes: info?.notes, protected: info?.protected }, registry)) {
855	    throw new Error(`refusing to delete ${volid}: it is a platform (host-level) backup`);
856	  }
857	
858	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
859	}
860	
861	/**
862	 * Retention for ONE CUSTOMER SERVER: keep only the newest `keep` archives that
863	 * belong to that customer, deleting the older ones (best-effort per file, oldest
864	 * first). Runs after every successful customer backup, and from the standalone
865	 * sweep in worker/backup-schedule.ts. Returns how many were deleted.
866	 *
867	 * Platform archives are excluded from the delete set AND from the retention
868	 * count. Counting them would be its own bug: with keep = 2, three platform
869	 * archives of a vmid would make every customer archive "older than the newest
870	 * two" and delete all of the customer's backups instead.
871	 */
872	export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
873	  // `keep` decides how many of a customer's restore points survive, so it is
874	  // validated rather than trusted. `mine.slice(Math.max(0, keep))` looks safe and
875	  // is not: Math.max(0, NaN) is NaN, Array.slice(NaN) coerces to slice(0), and the
876	  // delete set silently becomes EVERY backup the customer has. A keep that arrived
877	  // as undefined, "" or a bad Settings parse would wipe the lot with no error on
878	  // the way past. Fail closed instead — an over-retained archive costs disk, a
879	  // missing one costs the customer their only restore point.
880	  if (!Number.isInteger(keep) || keep < 1) {
881	    throw new Error(
882	      `pruneBackups: refusing to prune vmid ${vmid} with keep='${keep}' — ` +
883	        `retention must be a whole number of at least 1.`
884	    );
885	  }
886	
887	  const registry = await protectedVolids();
888	  if (registry === null) {
889	    // Fail closed: no retention this pass. Archives accumulating for one cycle is
890	    // recoverable; deleting the platform's only copy of a VM is not.
891	    console.error(`[proxmox] pruneBackups: protection state unknown, skipping prune for vmid ${vmid}`);
892	    return 0;
893	  }
894	
895	  const forVmid = await listBackupsOn(client, vmid);
896	  const shielded = forVmid.filter((b) => isPlatformArchive(b, registry));
897	  const mine = forVmid
898	    .filter((b) => !isPlatformArchive(b, registry))
899	    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
900	
901	  if (shielded.length > 0) {
902	    console.log(
903	      `[proxmox] pruneBackups: vmid ${vmid} — ${shielded.length} platform archive(s) excluded from retention`
904	    );
905	  }
906	
907	  const toDelete = mine.slice(Math.max(0, keep));
908	  let deleted = 0;
909	  for (const b of toDelete) {
910	    try {
911	      await deleteBackup(client, b.volid!);
912	      deleted++;
913	    } catch (e) {
914	      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
915	    }
916	  }
917	  return deleted;
918	}
