1032	/**
1033	 * Fetch the disk RRD series for a VM. `disk` = bytes used as seen by the
1034	 * hypervisor, `maxdisk` = provisioned size. Note: for QEMU guests Proxmox
1035	 * often cannot see in-guest usage, so `disk` may be 0/null — callers should
1036	 * fall back to the provisioned/plan size for the "total".
1037	 */
1038	export async function serverDiskRrd(
1039	  vmid: number,
1040	  timeframe: string,
1041	  conn?: NodeConn | null
1042	): Promise<DiskPoint[]> {
1043	  const tf = VALID_TF.includes(timeframe) ? timeframe : "day";
1044	  let raw: any[];
1045	  if (conn) {
1046	    const client = pveFor(conn);
1047	    raw = await client.get(`/nodes/${conn.pveNode}/qemu/${vmid}/rrddata`, {
1048	      timeframe: tf,
1049	      cf: "AVERAGE",
1050	    });
1051	  } else {
1052	    raw = await pve.get(`/nodes/${defaultNode}/qemu/${vmid}/rrddata`, { timeframe: tf, cf: "AVERAGE" });
1053	  }
1054	  return (raw ?? [])
1055	    .filter((r) => r && typeof r.time === "number")
1056	    .map((r) => ({
1057	      time: r.time,
1058	      disk: typeof r.disk === "number" ? r.disk : null,
1059	      maxdisk: typeof r.maxdisk === "number" ? r.maxdisk : null,
1060	    }));
