1063	/**
1064	 * Short-lived, encrypted authorization tokens for the in-portal web terminal.
1065	 *
1066	 * The browser never opens the terminal websocket with its session cookie —
1067	 * instead the app mints a 60-second, single-purpose token (this module) that
1068	 * encodes exactly {userId, serverId}. The standalone PTY backend
1069	 * (terminal-server/index.ts) verifies that token before it will SSH anywhere.
1070	 *
1071	 * The token is a JWE (encrypted, A256GCM) — mirroring the VNC console ticket in
1072	 * app/api/console/[serverId]/route.ts — so its contents are opaque to the
1073	 * browser and cannot be tampered with. The symmetric key is DERIVED from the
1074	 * app's AUTH_SECRET the same way the console does, with a terminal-specific
1075	 * salt, so the web app and the terminal backend agree on the key with no extra
1076	 * shared secret to configure.
1077	 *
1078	 * Plain server-side module (no "use server"): importable by both the Next route
1079	 * handler and the tsx-run terminal backend.
1080	 */
1081	import { createHash } from "node:crypto";
1082	import { EncryptJWT, jwtDecrypt } from "jose";
1083	
1084	/** Lifetime of a minted terminal token. It only needs to survive the round-trip
1085	 * from `POST /api/terminal/token` to the websocket upgrade. */
1086	export const TERMINAL_TOKEN_TTL_SECONDS = 60;
1087	
1088	/** What every terminal token carries. Nothing sensitive — just who + which VM. */
1089	export type TerminalTokenClaims = {
1090	  userId: string;
1091	  serverId: string;
1092	};
1093	
1094	/**
1095	 * 256-bit symmetric key for the terminal JWE, derived from AUTH_SECRET. The
1096	 * terminal backend derives the identical key the same way, so no separate
1097	 * secret needs distributing. Distinct salt from the console key so a console
1098	 * ticket can never be replayed as a terminal token (or vice-versa).
1099	 */
1100	function terminalKey(): Uint8Array {
1101	  const secret = process.env.AUTH_SECRET;
1102	  if (!secret) throw new Error("AUTH_SECRET is not set");
1103	  return new Uint8Array(createHash("sha256").update(`nxeon-terminal:${secret}`).digest());
1104	}
1105	
1106	/** Mint an encrypted, 60-second terminal token for {userId, serverId}. */
1107	export async function signTerminalToken(claims: TerminalTokenClaims): Promise<string> {
1108	  return new EncryptJWT({ userId: claims.userId, serverId: claims.serverId })
1109	    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
1110	    .setIssuedAt()
1111	    .setExpirationTime(`${TERMINAL_TOKEN_TTL_SECONDS}s`)
1112	    .encrypt(terminalKey());
1113	}
1114	
1115	/**
1116	 * Verify + decrypt a terminal token. Returns the claims, or throws if the token
1117	 * is missing, malformed, tampered with, or expired (jwtDecrypt enforces `exp`).
1118	 */
1119	export async function verifyTerminalToken(token: string): Promise<TerminalTokenClaims> {
1120	  const { payload } = await jwtDecrypt(token, terminalKey());
1121	  const userId = payload.userId;
1122	  const serverId = payload.serverId;
1123	  if (typeof userId !== "string" || typeof serverId !== "string" || !userId || !serverId) {
1124	    throw new Error("terminal token missing userId/serverId");
1125	  }
1126	  return { userId, serverId };
1127	}
