126	/**
127	 * If a GAME OsTemplate's setupScript installs the game via a detached
128	 * `docker run -d --name <container> ...` (true for every game image today —
129	 * see the OsTemplate rows for minecraft/terraria/ark/etc., all `docker run -d`),
130	 * rewrite the invocation to `docker create` and append a generated systemd unit
131	 * that starts/stops the container.
132	 *
133	 * WHY THIS EXISTS: the whole game control panel — GAME_POWER start/stop/restart,
134	 * GAME_BACKUP, log tailing (lib/game-control.ts + worker/game-control.ts) —
135	 * resolves the running game exclusively via `systemctl cat <serviceHint>` /
136	 * `journalctl -u <unit>`. A bare `docker run -d` creates no systemd unit at all,
137	 * so every one of those lookups comes back empty and every control action fails
138	 * silently, on every game family, on every order. Found 2026-08-26 diagnosing a
139	 * customer's Terraria server (cmt9ss7ln000xhlrx0gch9fcx) that could never be
140	 * started/stopped from the dashboard even though PROVISION had completed
141	 * successfully — the container was in fact running, just entirely invisible to
142	 * systemd.
143	 *
144	 * The generated unit is named after the family's FIRST serviceHint, not the
145	 * docker container's own `--name` — the two don't always match (minecraft's
146	 * image runs as container "mc" but its control-spec hints are "minecraft" /
147	 * "minecraft-server") — so `systemctl cat <hint>` resolves regardless of what an
148	 * individual image's setup script happened to call its container.
149	 *
150	 * Intentionally conservative: any setupScript that doesn't match the exact
151	 * `docker run -d --name X ...` shape (or any non-game family, e.g. the
152	 * LAMP/WordPress/Caddy panel images that already install a real native systemd
153	 * service) is returned completely unchanged.
154	 */
155	function wrapDockerGameService(setupScript: string, family: string | null): string {
156	  if (!isGameFamily(family)) return setupScript;
157	  const unitName = controlSpec(family)?.serviceHints[0];
158	  if (!unitName) return setupScript;
159	
160	  const re = /docker run\s+(?:-d|--detach)\b(.*?)\s+--name[= ]("?)([A-Za-z0-9_.-]+)\2(.*)$/.exec(setupScript.trim());
161	  if (!re) return setupScript;
162	  const [full, before, , containerName, after] = re;
163	  const matchIndex = setupScript.indexOf(full);
164	  if (matchIndex < 0) return setupScript;
165	
166	  // Strip docker's own restart policy — systemd now owns restart semantics for
167	  // this container, and leaving both in place makes the two supervisors fight
168	  // over a crash-looping process.
169	  const cleanedAfter = after.replace(/\s*--restart(?:=|\s+)\S+/, "");
170	  const createCmd = `docker create --name ${containerName}${before}${cleanedAfter}`.replace(/\s+/g, " ").trim();
171	
172	  const prefix = setupScript.slice(0, matchIndex);
173	  const unit = [
174	    `cat > /etc/systemd/system/${unitName}.service <<'NXUNIT'`,
175	    "[Unit]",
176	    `Description=Nxeon game service (docker: ${containerName})`,
177	    "After=docker.service",
178	    "Requires=docker.service",
179	    "",
180	    "[Service]",
181	    `ExecStart=/usr/bin/docker start -a ${containerName}`,
182	    `ExecStop=/usr/bin/docker stop -t 30 ${containerName}`,
183	    "Restart=always",
184	    "RestartSec=5",
185	    "TimeoutStartSec=0",
186	    "",
187	    "[Install]",
188	    "WantedBy=multi-user.target",
189	    "NXUNIT",
190	    "systemctl daemon-reload",
191	    `systemctl enable --now ${unitName}`,
192	  ].join("\n");
193	
194	  return `${prefix}${createCmd}\n${unit}`;
195	}
