202	/**
203	 * The nxeon-shipper install: fetch the static binary, drop its config (server
204	 * id + per-server token minted by the caller, see provision()), install the
205	 * systemd unit, and start it. Idempotent (safe to re-run on a retried
206	 * provision) and — like the Claude CLI install — backgrounded via the outer
207	 * nohup so a slow/blocked download never delays the VM reporting ready.
208	 *
209	 * `curl -fsSL … | sh`-style external installs are the established convention
210	 * here (see get.docker.com / claude.ai/install.sh above); this one pulls from
211	 * our own APP_URL instead of a third party since the binary is ours.
212	 */
213	function shipperInstallScript(serverId: string, token: string, nodeKind: "VPS" | "GAME"): string {
214	  const appUrl = process.env.APP_URL ?? "https://nxeon.cloud";
215	  const config = JSON.stringify({
216	    server_id: serverId,
217	    token,
218	    ingest_url: `${appUrl}/api/telemetry/ingest`,
219	    node_kind: nodeKind,
220	  });
221	  return [
222	    "mkdir -p /etc/nxeon",
223	    `cat > /etc/nxeon/shipper.json <<'NXTJSON'\n${config}\nNXTJSON`,
224	    "chmod 600 /etc/nxeon/shipper.json",
225	    `curl -fsSL "${appUrl}/dl/nxeon-shipper-linux-amd64" -o /usr/local/bin/nxeon-shipper.tmp && ` +
226	      "chmod +x /usr/local/bin/nxeon-shipper.tmp && mv /usr/local/bin/nxeon-shipper.tmp /usr/local/bin/nxeon-shipper",
227	    `curl -fsSL "${appUrl}/dl/nxeon-shipper.service" -o /etc/systemd/system/nxeon-shipper.service`,
228	    "systemctl daemon-reload && systemctl enable --now nxeon-shipper",
229	  ].join("\n");
230	}
