400	/**
401	 * Allocate a vmid for a brand-new server, refusing any id that still owns backup
402	 * archives from a previous tenant (see `pickProvisionVmid` for the incident).
403	 *
404	 * If the archive listing cannot be read we do NOT silently fall back to the raw
405	 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
406	 * and a provision that fails is recoverable while a cross-tenant disclosure is
407	 * not. The job retries; an operator sees why.
408	 */
409	async function allocateFreshVmid(conn: any): Promise<number> {
410	  const candidate = await conn.nextVmid();
411	  const archived = await archivedVmids(conn);
412	
413	  // Ids already in use, so skipping forward cannot land on a live VM. Read
414	  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
415	  let taken = new Set<number>();
416	  try {
417	    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
418	    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
419	  } catch {
420	    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
421	    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
422	  }
423	
424	  const { vmid, skipped } = pickProvisionVmid({ candidate, takenVmids: taken, archivedVmids: archived });
425	  if (skipped.length > 0) {
426	    console.warn(
427	      `[worker] vmid ${skipped.join(", ")} skipped for provisioning — still holds backup archives ` +
428	        `from a previous server; allocated ${vmid} instead`
429	    );
430	  }
431	  return vmid;
432	}
