15	async function reinstall(job: Job) {
16	  const server = await loadServer(job);
17	  if (SANDBOX) {
18	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
19	    await notify(
20	      server.userId,
21	      `Server ${server.hostname} reinstalled (sandbox)`,
22	      "The sandbox server was reinstalled (no real VM was touched).",
23	      `/dashboard/servers/${server.id}`
24	    );
25	    return;
26	  }
27	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
28	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
29	  // EVERY disk the vmid owns, including attached block-storage Volume disks
30	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
31	  // by that vmid, and both purge and the default destroy (which removes disks
32	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
33	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
34	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
35	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
36	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
37	  // can be re-attached after the reinstall. This runs BEFORE any status change or
38	  // destructive call, so a blocked reinstall touches nothing.
39	  //
40	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
41	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
42	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
43	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
44	  // let the worst path through: fill a volume, Detach (the UI says "Data is
45	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
46	  // Detaching is therefore NOT sufficient protection, and telling the customer to
47	  // detach was wrong advice; they must delete the volume (which destroys just
48	  // that disk, deliberately) or move it to another server first.
49	  const pinnedVolumes = await db.volume.findMany({
50	    where: { serverId: server.id },
51	  });
52	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
53	  const realPinned = pinnedVolumes.filter(
54	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
55	  );
56	  if (realPinned.length > 0) {
57	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
58	    throw new Error(
59	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
60	        `Reinstalling purges every disk this server owns — including detached volumes ` +
61	        `that are still assigned to it — and that cannot be undone.`
62	    );
63	  }
64	
65	  const { conn } = await nodeFor(server);
66	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
67	  if (server.vmid) await destroyVm(conn, server.vmid);
68	  await provision(job);
69	}
