71	async function suspend(job: Job, unsuspend: boolean) {
72	  const server = await loadServer(job);
73	  if (SANDBOX) {
74	    if (unsuspend) {
75	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null, suspendReason: null } });
76	    } else {
77	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
78	    }
79	    return;
80	  }
81	  const { conn, row: nodeRow } = await nodeFor(server);
82	  if (unsuspend) {
83	    // The dedicated IP was returned to the pool while suspended — re-allocate one
84	    // and reconfigure the public network before starting the VM back up.
85	    if (server.vmid) {
86	      const { getSettingBool: _sb } = await import("../lib/settings");
87	      const isGameSrv = !!server.gamePlanId;
88	      const wantDedicated = isGameSrv
89	        ? server.wantsDedicatedIp
90	        : server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
91	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
92	      let reconfigured = alreadyHas ? true : false;
93	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
94	        try {
95	          const d = await allocateDedicatedIp(server.id, server.vmid);
96	          if (d) {
97	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
98	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
99	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
100	            });
101	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
102	            reconfigured = true;
103	          }
104	        } catch (e) {
105	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
106	        }
107	      }
108	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
109	      // the Virtual MAC + failover IP that suspend released back to the pool — that
110	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
111	      // with a valid, non-conflicting network instead of a dead public config.
112	      if (!reconfigured) {
113	        try {
114	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
115	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
116	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
117	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
118	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
119	          });
120	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
121	        } catch (e) {
122	          console.error("[worker] NAT fallback on unsuspend failed", e);
123	        }
124	      }
125	    }
126	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null, suspendReason: null } });
127	    // Not fatal to the unsuspend itself (the customer is paid up and the VM must
128	    // come back), but never silent: an unproved sync is logged with its reason.
129	    if (!SANDBOX) await syncPortForwardsBestEffort(`unsuspend ${server.hostname}`);
130	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
131	    await conn.waitForTask(upid);
132	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
133	    // The dedicated-IP re-allocation (or NAT fallback) above may have handed this
134	    // server a genuinely different address than before suspension — resync.
135	    if (!SANDBOX && server.subdomain) await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId: server.id } });
136	  } else {
137	    try {
138	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
139	      await conn.waitForTask(upid);
140	    } catch { /* may already be stopped */ }
141	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
142	    // Tear the subdomain's DNS down while suspended — syncGameServerDns treats
143	    // SUSPENDED as terminal and deletes rather than pointing at a dead address.
144	    if (!SANDBOX && server.subdomain) await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId: server.id } });
145	    if (!SANDBOX) await syncPortForwardsBestEffort(`suspend ${server.hostname}`);
146	    // Return the dedicated IP to the pool while the server is suspended, so it
147	    // can be handed to a paying server. Re-allocated on unsuspend.
148	    if (ovhConfigured()) {
149	      try {
150	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
