177	/**
178	 * Tell the customer their server failed to provision. Before this, a terminal
179	 * PROVISION failure flipped the server to ERROR and sent NOTHING — the customer
180	 * paid, then sat on a dead screen with a red dot and no explanation. Persists a
181	 * short human reason on `Server.provisionError` (surfaced in the ERROR banner on
182	 * the detail page), drops an in-app notification, and emails them. Best-effort on
183	 * every leg — a failed notification must never mask the underlying job failure.
184	 *
185	 * `error` is the redacted Job.error; we keep a trimmed copy for the customer.
186	 */
187	async function notifyProvisionFailed(
188	  server: { id: string; userId: string; hostname: string },
189	  error: string,
190	): Promise<void> {
191	  // A concise, customer-facing reason. The raw Job.error can be a 2000-char stack;
192	  // the first line is almost always the meaningful message.
193	  const reason = (error.split("\n")[0] || error).trim().slice(0, 300);
194	  try {
195	    await db.server.update({ where: { id: server.id }, data: { provisionError: reason } });
196	  } catch (e) {
197	    console.error("[worker] persist provisionError failed", e);
198	  }
199	  // If this VM backs a managed NxCloud, mark the wrapper FAILED too — otherwise a
200	  // failed nxcloud provision leaves the instance stuck on "setting up" forever
201	  // while the backing Server sits in ERROR. Its dashboard card reads this to show
202	  // the failed/retry state (components/customer/NxcloudClient.tsx).
203	  try {
204	    await db.nxCloudInstance.updateMany({
205	      where: { serverId: server.id, status: { notIn: ["DELETING", "ACTIVE"] } },
206	      data: { status: "FAILED", error: reason },
207	    });
208	  } catch (e) {
209	    console.error("[worker] mark nxcloud instance failed", e);
210	  }
211	  await notify(
212	    server.userId,
213	    `We couldn't set up ${server.hostname}`,
214	    `Provisioning failed and our team has been notified. You can retry it or contact support from the server page.`,
215	    `/dashboard/servers/${server.id}`,
216	  );
217	  try {
218	    const { sendMail, emails } = await import("../lib/mailer");
219	    const user = await db.user.findUnique({ where: { id: server.userId }, select: { email: true } });
220	    if (user?.email) {
221	      const tpl = emails.provisionFailed({ hostname: server.hostname, reason });
222	      await sendMail({
223	        to: user.email,
224	        subject: tpl.subject,
225	        html: tpl.html,
226	        template: tpl.template,
227	        userId: server.userId,
228	        // No `kind` → always send. A paid-for server that failed to build is a
229	        // service-delivery failure the customer must hear about.
230	      });
231	    }
232	  } catch (e) {
233	    console.error("[worker] provision-failure email failed", e);
234	  }
235	}
