237	async function resize(job: Job) {
238	  const server = await loadServer(job);
239	  const payload = (job.payload ?? {}) as { planId?: string };
240	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
241	  if (!newPlan) throw new Error("resize: target plan not found");
242	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
243	
244	  // Any separately-purchased extra disk is ADDITIVE to whichever plan the server
245	  // sits on, so it survives the plan change untouched — `Server.extraDiskGB` is
246	  // never written here. Sizes below are therefore always the EFFECTIVE size
247	  // (new plan + extra); using the bare plan size would ask Proxmox to SHRINK the
248	  // disk of any server carrying extra storage, and the resize would hard-fail.
249	  const newTotalDiskGB = effectiveDiskGB(newPlan.diskGB, server.extraDiskGB);
250	  const currentTotalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
251	  const diskLine =
252	    server.extraDiskGB > 0
253	      ? `${newTotalDiskGB} GB disk (${newPlan.diskGB} GB plan + ${server.extraDiskGB} GB added storage)`
254	      : `${newPlan.diskGB} GB disk`;
255	
256	  if (SANDBOX) {
257	    await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
258	    await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
259	      `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
260	      `/dashboard/servers/${server.id}`);
261	    return;
262	  }
263	
264	  const { conn } = await nodeFor(server);
265	  const wasRunning = server.status === "RUNNING";
266	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
267	    cores: newPlan.cpuCores,
268	    memory: newPlan.ramMB,
269	  });
270	  if (newTotalDiskGB > currentTotalDiskGB) {
271	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
272	      disk: "scsi0",
273	      size: `${newTotalDiskGB}G`,
274	    });
275	  }
276	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
277	  // CPU/RAM changes need a power cycle to apply
278	  if (wasRunning) {
279	    try {
280	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
281	      await conn.waitForTask(stopUpid, 120_000);
282	    } catch {
283	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
284	      await conn.waitForTask(stopUpid);
285	    }
286	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
287	    await conn.waitForTask(startUpid);
288	  }
289	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
290	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
291	    `/dashboard/servers/${server.id}`);
292	}
