294	/**
295	 * ASSIGN_DEDICATED_IP — deliver a dedicated public IPv4 to an ALREADY-
296	 * provisioned server (VPS or game) that just paid for one
297	 * (lib/dedicated-ip-purchase.ts applyDedicatedIpPurchase). Payment already
298	 * happened at enqueue time; this handler is responsible only for claiming the
299	 * IP and reconfiguring the VM's network.
300	 *
301	 * Reuses the EXACT same allocate + reconfigure sequence `suspend(job, true)`
302	 * (UNSUSPEND) already runs to re-give a server its dedicated IP after it comes
303	 * back — see that function's `wantDedicated` branch above. Nothing here
304	 * invents new Proxmox/iptables behavior:
305	 *   1. `allocateDedicatedIp` claims a FREE pool IP + creates the OVH Virtual
306	 *      MAC (idempotent — a retry after a partial failure returns the same
307	 *      already-ASSIGNED IP rather than claiming a second one).
308	 *   2. The VM's `net0`/`ipconfig0` are pointed at it.
309	 *   3. `Server.ipAddress`/`sshPort` are updated (`sshPort: null` — dedicated
310	 *      servers own every port directly, and NULL is how a NAT slot is
311	 *      released back to the pool; `syncPortForwards`'s query already excludes
312	 *      any server with `sshPort: null`, so the old NAT/SSH forward rules are
313	 *      torn down on the very next sync below).
314	 *   4. `wantsDedicatedIp` is persisted so a LATER suspend/unsuspend cycle
315	 *      re-allocates this server a dedicated IP instead of silently dropping
316	 *      it back to NAT — `suspend(job, true)`'s game branch reads exactly this
317	 *      flag with no other fallback.
318	 *
319	 * A power cycle is required for the new net0/ipconfig0 to take effect (cloud-
320	 * init only re-applies network config at boot), so a running VM is stopped and
321	 * started, mirroring `resize()`'s own CPU/RAM power-cycle above. Listed in
322	 * VM_STATE_FAILURE_JOBS (like RESIZE) since a failure here can leave the VM
323	 * mid-power-cycle; `reconcileFailedDedicatedIp` below refunds the charge and
324	 * releases any IP this run managed to claim.
325	 */
326	async function assignDedicatedIp(job: Job) {
327	  const server = await loadServer(job);
328	  const existing = await db.dedicatedIp.findUnique({ where: { serverId: server.id } });
329	  if (existing) {
330	    // Already has one — a previous attempt at this same job must have
331	    // completed the DB/network side before failing on a later step (or this is
332	    // a harmless re-run). Nothing left to deliver.
333	    return;
334	  }
335	
336	  if (SANDBOX) {
337	    // Sandbox: synthesize a dedicated IP without any OVH/Proxmox call, but
338	    // still create the real DedicatedIp row (unlike provision()'s SANDBOX
339	    // path) — this is a customer-facing PAID purchase, and `server.dedicatedIp`
340	    // must actually reflect it so the dashboard, billing and a later
341	    // suspend/unsuspend cycle all see a real dedicated IP.
342	    const address = sandboxIp(server.vmid ?? 0);
343	    await db.$transaction([
344	      db.dedicatedIp.create({
345	        data: { address, ovhBlock: `${address}/32`, status: "ASSIGNED", serverId: server.id, purpose: "CUSTOMER" },
346	      }),
347	      db.server.update({
348	        where: { id: server.id },
349	        data: { ipAddress: address, sshPort: null, wantsDedicatedIp: true },
350	      }),
351	    ]);
352	    await notify(server.userId, `Dedicated IP added to ${server.hostname} (sandbox)`,
353	      `Your server now connects on ${address} (no real network was touched).`,
354	      `/dashboard/servers/${server.id}`);
355	    return;
356	  }
357	
358	  if (!server.vmid) throw new Error("assign dedicated ip: server has no VM yet");
359	  const d = await allocateDedicatedIp(server.id, server.vmid);
360	  if (!d) throw new Error("assign dedicated ip: no free IP available in the pool (or OVH not configured)");
361	
362	  const { conn } = await nodeFor(server);
363	  const wasRunning = server.status === "RUNNING";
364	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
365	    net0: `virtio=${d.virtualMac},bridge=vmbr0`,
366	    ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
367	  });
368	  await db.server.update({
369	    where: { id: server.id },
370	    data: { ipAddress: d.address, sshPort: null, wantsDedicatedIp: true },
371	  });
372	  if (wasRunning) {
373	    try {
374	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
375	      await conn.waitForTask(stopUpid, 120_000);
376	    } catch {
377	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
378	      await conn.waitForTask(stopUpid);
379	    }
380	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
381	    await conn.waitForTask(startUpid);
382	  }
383	  // The server no longer holds a NAT SSH port (sshPort is now null) — reconcile
384	  // the shared DNAT chain so its old port-forward/SSH rules are removed.
385	  await syncPortForwardsBestEffort(`assign dedicated ip ${server.hostname}`);
386	  // A Minecraft subdomain's SRV record points at the old ip:port — resync now
387	  // that the address changed, exactly like addPortForward/deletePortForward do.
388	  if (server.subdomain) await db.job.create({ data: { type: "SYNC_GAME_DNS", serverId: server.id } });
389	  await notify(server.userId, `Dedicated IP added to ${server.hostname}`,
390	    `Your server now connects on ${d.address}.`,
391	    `/dashboard/servers/${server.id}`);
392	}
