394	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
395	  const server = await loadServer(job);
396	  const payload = (job.payload ?? {}) as { name?: string };
397	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
398	  if (!name) throw new Error("snapshot: invalid name");
399	  if (SANDBOX) {
400	    await notify(
401	      server.userId,
402	      `Snapshot ${op} (sandbox): ${name}`,
403	      `Sandbox snapshot ${op} completed (no real VM was touched).`,
404	      `/dashboard/servers/${server.id}`
405	    );
406	    return;
407	  }
408	  const { conn } = await nodeFor(server);
409	  let upid: string;
410	  if (op === "create") {
411	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
412	  } else if (op === "delete") {
413	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
414	  } else {
415	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
416	  }
417	  await conn.waitForTask(upid, 600_000);
418	  if (op === "rollback") {
419	    // rollback leaves the VM stopped; bring it back if the server should be running
420	    const current = await db.server.findUnique({ where: { id: server.id } });
421	    if (current?.status === "RUNNING") {
422	      try {
423	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
424	        await conn.waitForTask(startUpid);
425	      } catch { /* may already be running */ }
426	
427	      // Resync the root password. `rollback` puts the snapshot's OLD disk
428	      // content back — including whatever /etc/shadow existed when it was
429	      // taken — which can hold an older password than Server.rootPasswordEnc
430	      // if a PASSWORD_RESET (or anything else) changed it since the snapshot
431	      // was created. Left alone, every later SSH from the platform would
432	      // authenticate with the DB's (now wrong) password against the guest's
433	      // reverted (now correct-for-the-snapshot) one — the exact "All
434	      // configured authentication methods failed" divergence documented on
435	      // applyPasswordToGuest (lib/proxmox.ts) and on provision()'s password-
436	      // reuse fix above. Best-effort: a failure here does not fail the
437	      // rollback itself (the VM genuinely is back at the requested restore
438	      // point) but is logged loudly since a stale password can otherwise look
439	      // exactly like an unrelated SSH outage.
440	      const pw = serverRootPassword(current ?? server);
441	      if (pw && server.vmid) {
442	        const ready = await waitForGuestAgent(conn, conn.node, server.vmid);
443	        if (ready) {
444	          const applied = await applyPasswordToGuest(conn, server.vmid, pw);
445	          if (!applied) {
446	            console.error(
447	              `[worker] snapshot rollback: could not resync guest password for server ${server.id} (vmid ${server.vmid})`
448	            );
449	          }
450	        } else {
451	          console.error(
452	            `[worker] snapshot rollback: guest agent never answered for server ${server.id} (vmid ${server.vmid}) — password may now be stale`
453	          );
454	        }
455	      }
456	    }
457	  }
458	}
