460	async function passwordReset(job: Job) {
461	  const server = await loadServer(job);
462	  if (SANDBOX) {
463	    // Sandbox: rotate the stored password only — never touch a real VM.
464	    const password = generatePassword();
465	    await db.server.update({ where: { id: server.id }, data: { rootPassword: null, rootPasswordEnc: encryptSecret(password) } });
466	    await notify(
467	      server.userId,
468	      `Root password reset (sandbox) for ${server.hostname}`,
469	      "Your new root password is on the server's Overview tab (no real VM was touched).",
470	      `/dashboard/servers/${server.id}`
471	    );
472	    return;
473	  }
474	  if (!server.vmid) throw new Error("password reset: server has no VM yet");
475	  const { conn } = await nodeFor(server);
476	  const password = generatePassword();
477	
478	  // Preferred path: set it live via the qemu-guest-agent (no reboot needed).
479	  // Shared with SNAPSHOT_ROLLBACK/BACKUP_RESTORE's post-revert resync — see
480	  // applyPasswordToGuest's doc-comment (lib/proxmox.ts) for why this exact
481	  // primitive is what both need.
482	  const applied = await applyPasswordToGuest(conn, server.vmid, password);
483	  if (!applied) console.error("[worker] agent set-user-password failed, falling back to cloud-init");
484	
485	  // Fallback: rewrite cloud-init password and reboot so it reapplies.
486	  if (!applied) {
487	    await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { cipassword: password });
488	    if (server.status === "RUNNING") {
489	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/reboot`, {});
490	      await conn.waitForTask(upid);
491	    }
492	  }
493	
494	  await db.server.update({ where: { id: server.id }, data: { rootPassword: null, rootPasswordEnc: encryptSecret(password) } });
495	  await notify(
496	    server.userId,
497	    `Root password reset for ${server.hostname}`,
498	    "Your new root password is available on the server's Overview tab.",
499	    `/dashboard/servers/${server.id}`
500	  );
501	}
