503	/**
504	 * Write live `progress`/`step` onto a running Job row. Best-effort: a failed
505	 * write must never abort the underlying backup/restore, so errors are swallowed.
506	 */
507	export async function reportJobProgress(jobId: string, progress: number, step: string) {
508	  try {
509	    await db.job.update({
510	      where: { id: jobId },
511	      data: { progress: Math.max(0, Math.min(100, Math.round(progress))), step },
512	    });
513	  } catch (e) {
514	    console.error("[worker] job progress update failed", e);
515	  }
