518	/** Animate a sandbox job 0→100 so staging demonstrates the live bar. */
519	async function sandboxAnimateJob(
520	  jobId: string,
521	  steps: { pct: number; step: string }[],
522	  delayMs = 500
523	) {
524	  for (const s of steps) {
525	    await reportJobProgress(jobId, s.pct, s.step);
