530	/**
531	 * Create one backup and PROVE it exists before saying so.
532	 *
533	 * INCIDENT H4 (2026-07-26 rehearsal): this handler gated only the vzdump task's
534	 * exit status — it never checked that an archive was written, had no failure
535	 * notification, and `Server.lastAutoBackup` was stamped by the SWEEP at enqueue
536	 * time. A customer could read "Last automatic backup: today" every night for a
537	 * month with nothing in storage, and find out at restore time.
538	 *
539	 * Now: snapshot the archive list before the run, re-read it after, and require a
540	 * volid that was not there and is not empty (`freshBackupProof`). Only that
541	 * writes `lastAutoBackup`. A failure notifies the customer with the reason and a
542	 * command, rather than leaving a stale-but-cheerful timestamp behind.
543	 */
544	async function backupCreate(job: Job) {
545	  const server = await loadServer(job);
546	  if (SANDBOX) {
547	    await sandboxAnimateJob(job.id, [
548	      { pct: 5, step: "Starting" },
549	      { pct: 25, step: "Creating archive… 25%" },
550	      { pct: 55, step: "Creating archive… 55%" },
551	      { pct: 80, step: "Creating archive… 80%" },
552	      { pct: 95, step: "Finalizing" },
553	      { pct: 100, step: "Backup complete" },
554	    ]);
555	    // Deliberately NOT stamping lastAutoBackup here: no archive exists, and the
556	    // column means "a backup was observed in storage".
557	    await notify(
558	      server.userId,
559	      `Backup simulated (sandbox) for ${server.hostname}`,
560	      "Sandbox only — no VM was contacted and no archive was written. This is not a restore point.",
561	      `/dashboard/servers/${server.id}`
562	    );
563	    return;
564	  }
565	  if (server.vmid == null) {
566	    throw new Error("backup: this server has no VMID yet, so there is nothing to back up.");
567	  }
568	  const vmid = server.vmid;
569	
570	  try {
571	    await reportJobProgress(job.id, 2, "Starting");
572	    const { conn } = await nodeFor(server);
573	
574	    // Snapshot what already exists. Membership of this set — not a timestamp
575	    // comparison — is what makes "a new archive appeared" unarguable: ctime comes
576	    // off the hypervisor and our window would come off the worker's clock.
577	    const before = await listBackupsOn(conn, vmid);
578	
579	    const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
580	      vmid,
581	      storage: "backup",
582	      mode: "snapshot",
583	      compress: "zstd",
584	    });
585	    await waitForTaskProgress(
586	      conn,
587	      upid,
588	      (progress, step) => reportJobProgress(job.id, progress, step),
589	      { timeoutMs: 3_600_000, phase: "backup" }
590	    );
591	
592	    await reportJobProgress(job.id, 96, "Verifying archive");
593	    const after = await listBackupsOn(conn, vmid);
594	    const proof = freshBackupProof({ vmid, before, after });
595	    if (!proof.proven) throw new Error(`backup not verified — ${proof.reason}`);
596	
597	    await reportJobProgress(job.id, 100, "Backup complete");
598	
599	    // Retention: keep the latest N backups for this server (N = the paid backup
600	    // tier's keep count, an explicit backupKeep override winning); prune the rest.
601	    const keep = resolveBackupKeep(server.backupTier, server.backupKeep);
602	    try {
603	      const pruned = await pruneBackups(conn, vmid, keep);
604	      if (pruned > 0) console.log(`[backup] pruned ${pruned} old backup(s) for vmid ${vmid} (keep ${keep})`);
605	    } catch (e) {
606	      console.error(`[backup] prune failed for vmid ${vmid}`, e);
607	    }
608	
609	    // The ONLY writer of lastAutoBackup, and only on proof.
610	    await db.server.update({ where: { id: server.id }, data: { lastAutoBackup: new Date() } });
611	
612	    await notify(
613	      server.userId,
614	      `Backup completed for ${server.hostname}`,
615	      `Verified present in backup storage: ${proof.volid} (${humanBytes(proof.sizeBytes)}).`,
616	      `/dashboard/servers/${server.id}`
617	    );
618	  } catch (e: any) {
619	    // Tell the customer it broke. Only on the final attempt, so the worker's
620	    // three retries do not produce three notifications for one bad night.
621	    if (job.attempts >= MAX_ATTEMPTS) {
622	      await notify(
623	        server.userId,
624	        `Backup FAILED for ${server.hostname}`,
625	        `${String(e?.message ?? e).slice(0, 400)} — this server has no new restore point. ` +
626	          `Your last verified backup (if any) is shown under Backups.`,
627	        `/dashboard/servers/${server.id}`
628	      );
629	    }
630	    throw e;
631	  }
632	}
