681	/**
682	 * Refund a per-server disk expansion that was paid for but never delivered.
683	 *
684	 * The DISK_EXPAND handler advances `Server.extraDiskGB` only AFTER the disk has
685	 * really grown, so that field is the ground truth for "did the customer get what
686	 * they paid for". We refund only when it never reached the job's target — which
687	 * also keeps this safe against the partial-success case (disk grown, filesystem
688	 * left for the customer to grow by hand): that path completes successfully, sets
689	 * extraDiskGB, and is therefore never refunded.
690	 *
691	 * Idempotent per job via the reconcile audit marker.
692	 */
693	async function reconcileFailedDiskExpand(job: Job) {
694	  const p = (job.payload ?? {}) as { prorateCents?: number; addGB?: number; targetExtraDiskGB?: number };
695	  const cents = p.prorateCents ?? 0;
696	  if (cents <= 0 || !job.serverId) return;
697	
698	  const already = await db.auditLog.findFirst({
699	    where: { action: "server.disk_expand.reconcile", detail: { contains: `job=${job.id}` } },
700	  });
701	  if (already) return;
702	
703	  const server = await db.server.findUnique({
704	    where: { id: job.serverId },
705	    select: { userId: true, hostname: true, extraDiskGB: true },
706	  });
707	  if (!server) return;
708	
709	  // The expansion actually landed (or a later one superseded it) — the customer
710	  // has the storage, so the charge stands. Nothing to unwind.
711	  const target = Number(p.targetExtraDiskGB ?? 0);
712	  if (target > 0 && server.extraDiskGB >= target) return;
713	
714	  try {
715	    await db.$transaction([
716	      db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
717	      db.walletTransaction.create({
718	        data: {
719	          userId: server.userId,
720	          amountCents: cents,
721	          description: `Refund: failed storage expansion (+${p.addGB ?? "?"} GB) — ${server.hostname}`,
722	        },
723	      }),
724	      db.notification.create({
725	        data: {
726	          userId: server.userId,
727	          title: `Storage expansion failed on ${server.hostname} — refunded`,
728	          body: `We couldn't add the storage, so $${(cents / 100).toFixed(2)} has been credited back to your wallet. Your server and its data are untouched.`,
729	          href: `/dashboard/servers/${job.serverId}`,
730	        },
731	      }),
732	    ]);
733	    await db.auditLog.create({
734	      data: {
735	        userId: server.userId,
736	        action: "server.disk_expand.reconcile",
737	        detail: `job=${job.id} addGB=${p.addGB} cents=${cents}`,
738	      },
739	    });
740	  } catch (e: any) {
741	    await db.auditLog
742	      .create({
743	        data: {
744	          userId: server.userId,
745	          action: "server.disk_expand.reconcile.uncharged",
746	          detail: `job=${job.id} cents=${cents} :: ${e?.message ?? e}`,
747	        },
748	      })
749	      .catch(() => {});
750	  }
751	}
