753	/**
754	 * Refund a dedicated-IP purchase that was paid for but never delivered, and
755	 * release any pool IP the failed run managed to claim — see the ROLLBACK
756	 * SAFETY note on applyDedicatedIpPurchase (lib/dedicated-ip-purchase.ts) for
757	 * why "charge" and "allocate" are two independently-failable steps.
758	 *
759	 * Ground truth is `server.dedicatedIp`, exactly like reconcileFailedDiskExpand
760	 * uses `server.extraDiskGB`: if the server actually ended up with one (this run
761	 * got far enough, or a later retry/attempt succeeded), the charge stands and
762	 * there is nothing to unwind. Idempotent per job via the reconcile audit
763	 * marker.
764	 */
765	async function reconcileFailedDedicatedIp(job: Job) {
766	  const p = (job.payload ?? {}) as { prorateCents?: number };
767	  const cents = p.prorateCents ?? 0;
768	  if (!job.serverId) return;
769	
770	  const already = await db.auditLog.findFirst({
771	    where: { action: "server.dedicated_ip_purchase.reconcile", detail: { contains: `job=${job.id}` } },
772	  });
773	  if (already) return;
774	
775	  const server = await db.server.findUnique({
776	    where: { id: job.serverId },
777	    select: { userId: true, hostname: true, dedicatedIp: { select: { id: true } } },
778	  });
779	  if (!server) return;
780	  if (server.dedicatedIp) return; // delivered after all — charge stands, nothing to release
781	
782	  // Best-effort: an IP that never got a Virtual MAC bound is already back to
783	  // FREE (allocateDedicatedIp rolls itself back on failure); this only matters
784	  // if a LATER step failed after the claim succeeded.
785	  await releaseDedicatedIp(job.serverId).catch((e) =>
