32	async function reconcileFailedJob(job: Job) {
33	  if (job.type === "DISK_EXPAND") return reconcileFailedDiskExpand(job);
34	  if (job.type === "ASSIGN_DEDICATED_IP") return reconcileFailedDedicatedIp(job);
35	  if (job.type !== "RESIZE") return;
36	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
37	  const cents = p.prorateCents ?? 0;
38	  if (cents <= 0 || !job.serverId) return;
39	
40	  // Idempotency: skip if we already reversed this exact job.
41	  const already = await db.auditLog.findFirst({
42	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
43	  });
44	  if (already) return;
45	
46	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
47	  if (!server) return;
48	
49	  try {
50	    if (p.direction === "up") {
51	      // Upgrade charge never delivered → refund the prorated charge.
52	      await db.$transaction([
53	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
54	        db.walletTransaction.create({
55	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
56	        }),
57	      ]);
58	    } else if (p.direction === "down") {
59	      // Downgrade credit was given but hardware unchanged → claw the credit back.
60	      // Guarded so it can never drive the balance negative; if the customer already
61	      // spent it, we log and leave it (best-effort — they keep a small windfall).
62	      await db.$transaction(async (tx) => {
63	        await debitWallet(tx, server.userId, cents);
64	        await tx.walletTransaction.create({
65	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
66	        });
67	      });
68	    }
69	    await db.auditLog.create({
70	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
71	    });
72	  } catch (e: any) {
73	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
74	    await db.auditLog.create({
75	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
76	    }).catch(() => {});
77	  }
78	}
