80	async function runJob(job: Job) {
81	  // The job is already atomically claimed (status RUNNING, attempts incremented)
82	  // by the loop's compare-and-swap before we get here — see the CAS in main().
83	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
84	  try {
85	    await handlers[job.type](job);
86	    // Clear any error left over from an earlier failed attempt of THIS job. Without
87	    // this, a job that failed once (error persisted, status QUEUED for retry) and
88	    // then succeeded on a later attempt ends up DONE with a stale, misleading error
89	    // still attached — indistinguishable from an actual silent failure to anyone
90	    // reading Job.error (confirmed: a real PROVISION did exactly this today).
91	    await db.job.update({ where: { id: job.id }, data: { status: "DONE", error: null } });
92	    console.log(`[worker] job ${job.id} DONE`);
93	  } catch (e: any) {
94	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
95	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
96	    // leak the server's root password into the thrown message. Redact it before
97	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
98	    // sever the match. Best-effort — never let redaction lookup fail the job path.
99	    if (job.serverId) {
100	      try {
101	        const s = await db.server.findUnique({
102	          where: { id: job.serverId },
103	          select: { rootPassword: true, rootPasswordEnc: true },
104	        });
105	        const pw = s ? serverRootPassword(s) : null;
106	        if (pw) error = error.split(pw).join("***");
107	      } catch {
108	        /* best-effort redaction */
109	      }
110	    }
111	    error = error.slice(0, 2000);
112	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
113	    const current = await db.job.findUnique({ where: { id: job.id } });
114	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
115	    await db.job.update({
116	      where: { id: job.id },
117	      data: { status: retriable ? "QUEUED" : "FAILED", error },
118	    });
119	    if (!retriable) {
120	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
121	      // Persist terminal job failures to ErrorLog (deduped by fingerprint) so the
122	      // admin Error Logs view surfaces what broke on the customer side, not just
123	      // the transient Job.error. logError is already non-throwing; guard anyway.
124	      await logError(`job.${String(job.type).toLowerCase()}`, new Error(error), {
125	        source: "job",
126	        jobId: job.id,
127	        serverId: job.serverId ?? undefined,
128	      }).catch(() => {});
129	      if (job.serverId) {
