188	/**
189	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
190	 * killed worker leaves a job RUNNING forever, which permanently blocks the
191	 * server's "one in-flight job" guard and strands it in a transitional state.
192	 */
193	async function reapStuckJobs() {
194	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
195	  for (const job of stuck) {
196	    const retriable = job.attempts < MAX_ATTEMPTS;
197	    await db.job.update({
198	      where: { id: job.id },
199	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
200	    });
201	    if (!retriable) {
202	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
203	      if (job.serverId) {
204	        const s = await db.server.findUnique({ where: { id: job.serverId } });
205	        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
206	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
207	        }
208	        // Same IP-leak cleanup the runJob catch-path does — a PROVISION reaped here
209	        // (killed on its final attempt) would otherwise strand its dedicated IP +
210	        // billable OVH vMAC forever (audit 2026-08-01).
211	        if (job.type === "PROVISION") {
212	          await cleanupFailedProvision(job.serverId).catch((err) =>
213	            console.error(`[worker] cleanup failed provision (reap) ${job.id}`, err)
214	          );
215	          // Same customer-facing failure notification as the runJob catch-path,
216	          // so a provision killed by a worker restart is not silently stranded.
217	          if (s) {
218	            await notifyProvisionFailed(s, "Worker restarted mid-job").catch((err) =>
219	              console.error(`[worker] notify provision failure (reap) ${job.id} failed`, err)
220	            );
221	          }
222	        }
223	      }
224	    }
225	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
226	  }
227	}
