20	/**
21	 * Control-panel CRON_SYNC / SERVICE_ACTION handlers.
22	 *
23	 * Registered in worker/index.ts:
24	 *   CRON_SYNC:      cronSync,
25	 *   SERVICE_ACTION: serviceAction,
26	 *
27	 * CRON_SYNC rebuilds a single Nxeon-managed block in root's crontab from all of
28	 * the server's enabled CronJob rows (removing DELETING ones). The whole crontab
29	 * body is installed via `crontab -`'s STDIN, so user command lines are never
30	 * interpolated into a shell we run. Schedules are allowlist-validated.
31	 *
32	 * SANDBOX / non-ENABLE_REAL_CPANEL: no SSH — rows just settle to ACTIVE.
33	 */
34	
35	const REAL = !SANDBOX && process.env.ENABLE_REAL_CPANEL === "1";
36	const BEGIN = "# BEGIN NXEON CONTROL PANEL — managed block, do not edit";
37	const END = "# END NXEON CONTROL PANEL";
38	
39	async function notify(userId: string, title: string, body?: string, href?: string) {
