47	async function sshServer(serverId: string): Promise<SftpServer> {
48	  const s = await db.server.findUnique({
49	    where: { id: serverId },
50	    select: {
51	      id: true,
52	      rootPassword: true,
53	      rootPasswordEnc: true,
54	      sshPort: true,
55	      dedicatedIp: { select: { address: true } },
56	    },
