62	/** Strip any existing Nxeon-managed block from an existing crontab body. */
63	function stripManaged(current: string): string {
64	  const lines = current.split("\n");
65	  const out: string[] = [];
66	  let inBlock = false;
67	  for (const line of lines) {
68	    if (line.trim() === BEGIN) {
69	      inBlock = true;
70	      continue;
71	    }
72	    if (line.trim() === END) {
73	      inBlock = false;
74	      continue;
75	    }
76	    if (!inBlock) out.push(line);
77	  }
78	  return out.join("\n").replace(/\n{3,}/g, "\n\n").trimEnd();
79	}
