81	export async function cronSync(job: Job): Promise<void> {
82	  if (!job.serverId) throw new Error("cron sync: missing serverId");
83	  const serverId = job.serverId;
84	
85	  // Remove any DELETING rows first — they must not reappear in the crontab.
86	  await db.cronJob.deleteMany({ where: { serverId, status: "DELETING" } });
87	
88	  const rows = await db.cronJob.findMany({ where: { serverId }, orderBy: { createdAt: "asc" } });
89	  const enabled = rows.filter((r) => r.enabled);
90	
91	  // Build the managed block (validate every schedule again).
92	  const blockLines = [BEGIN];
93	  for (const r of enabled) {
94	    const sched = assertCronSchedule(r.schedule); // throws on anything unexpected
95	    if (r.comment) blockLines.push(`# ${r.comment.replace(/[\r\n]/g, " ").slice(0, 80)}`);
96	    // command validated at enqueue time (no newline/control chars).
97	    blockLines.push(`${sched} ${r.command}`);
98	  }
99	  blockLines.push(END);
100	  const managedBlock = blockLines.join("\n");
101	
102	  try {
103	    if (REAL) {
104	      const server = await sshServer(serverId);
105	      await withServerSsh(server, async (conn) => {
106	        const cur = await exec(conn, "crontab -l 2>/dev/null || true", QUICK_TIMEOUT_MS);
107	        const base = stripManaged(cur.stdout);
108	        const body = (base ? base + "\n\n" : "") + managedBlock + "\n";
109	        // Install the whole crontab via STDIN — user command lines are data here,
110	        // never a shell we execute.
111	        const r = await execInput(conn, "crontab -", body, SETUP_TIMEOUT_MS);
112	        if (r.code !== 0) throw new Error(`crontab install failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
113	      });
114	    }
115	    await db.cronJob.updateMany({ where: { serverId }, data: { status: "ACTIVE", error: null } });
116	  } catch (e: any) {
117	    const reason = String(e?.message ?? e).slice(0, 400);
118	    await db.cronJob.updateMany({ where: { serverId, status: "PENDING" }, data: { status: "FAILED", error: reason } });
119	    const first = rows[0];
120	    if (first) await notify(first.userId, "Cron update failed", reason.slice(0, 200), `/dashboard/servers/${serverId}`);
121	  }
122	}
