124	/** Resolve + run a systemctl action for one of the fixed common services. */
125	async function runService(conn: Client, unit: string, action: string): Promise<void> {
126	  assertService(unit);
127	  assert((SERVICE_ACTIONS as readonly string[]).includes(action), `Unsupported action: ${action}`);
128	  let cmd: string;
129	  if (unit === "php-fpm") {
130	    // php-fpm is version-suffixed on Debian/Ubuntu; resolve the real unit name.
131	    cmd =
132	      `u=$(systemctl list-unit-files --no-legend 'php*-fpm.service' 2>/dev/null | awk '{print $1}' | head -n1); ` +
133	      `[ -n "$u" ] || u=php-fpm; systemctl ${action} "$u"`;
134	  } else if (unit === "mysql") {
135	    cmd = `systemctl ${action} mariadb 2>/dev/null || systemctl ${action} mysql`;
136	  } else {
137	    cmd = `systemctl ${action} ${shellQuote(unit)}`;
138	  }
139	  const r = await exec(conn, cmd, SETUP_TIMEOUT_MS);
140	  if (r.code !== 0) throw new Error(`${action} ${unit} failed: ${(r.stderr || r.stdout).trim().slice(0, 200)}`);
141	}
