143	export async function serviceAction(job: Job): Promise<void> {
144	  if (!job.serverId) throw new Error("service action: missing serverId");
145	  const p = (job.payload ?? {}) as { unit?: string; action?: string };
146	  const unit = String(p.unit ?? "");
147	  const action = String(p.action ?? "");
148	  assertService(unit);
149	  assert((SERVICE_ACTIONS as readonly string[]).includes(action), `Unsupported action: ${action}`);
150	
151	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
152	
153	  try {
154	    if (REAL) {
155	      const s = await sshServer(job.serverId);
156	      await withServerSsh(s, async (conn) => runService(conn, unit, action));
157	    }
158	    if (server) {
159	      await notify(
160	        server.userId,
161	        `${action[0].toUpperCase()}${action.slice(1)}ed ${unit}`,
162	        REAL ? `${unit} was ${action}ed on ${server.hostname}.` : `${unit} ${action} (sandbox — no real VM was touched).`,
163	        `/dashboard/servers/${job.serverId}?tab=control panel`
164	      );
165	    }
166	  } catch (e: any) {
167	    const reason = String(e?.message ?? e).slice(0, 300);
168	    if (server) await notify(server.userId, `Could not ${action} ${unit}`, reason, `/dashboard/servers/${job.serverId}`);
169	    throw e; // let the worker mark the job FAILED/retry
170	  }
171	}
