184	/**
185	 * Apply a customer's inbound firewall to their guest, idempotently.
186	 *
187	 * MECHANISM: guest-side iptables over SSH, mirroring how the platform already
188	 * reaches VMs (worker/claude.ts, worker/ssl.ts — sshpass + execFile ARRAY args,
189	 * never a shell string on the host). The Proxmox per-VM firewall API was the
190	 * alternative, but lib/proxmox.ts exposes only a generic REST client with no
191	 * firewall helper, and enabling it requires flipping cluster/node/NIC firewall
192	 * flags that interact with the existing NAT model — a far larger, riskier change
193	 * for guests that are already reachable as root over SSH. So: guest iptables.
194	 *
195	 * SAFETY: the reconcile SCRIPT is built by lib/firewall-rules.ts from VALIDATED,
196	 * structured fields only. Each DB row is re-run through `validateRule` here
197	 * (defence in depth) before it can contribute a line; a row that fails is skipped
198	 * and logged, never interpolated. Ports are integers, protocol/action are closed
199	 * enums, and the source CIDR is regex-validated + normalised — so no raw customer
200	 * string (the free-text `comment` least of all) ever reaches the guest shell.
201	 *
202	 * IDEMPOTENT: the script creates the NXEON_FW chain once, ensures INPUT jumps to
203	 * it once, then FLUSHES only that chain and rebuilds it — so re-running yields
204	 * identical kernel state and never accumulates stale rules or touches the
205	 * customer's own INPUT rules.
206	 *
207	 * ANTI-LOCKOUT: the baseline always accepts loopback, ESTABLISHED/RELATED and
208	 * tcp/22, so SSH stays reachable no matter what the customer configures, and the
209	 * default DROP is appended only when they have at least one ALLOW rule.
210	 */
211	export async function syncFirewall(job: Job): Promise<void> {
212	  const serverId = job.serverId;
213	  if (!serverId) throw new Error("syncFirewall: job has no serverId");
214	
215	  const server = await db.server.findUnique({
216	    where: { id: serverId },
217	    include: { firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] } },
218	  });
219	  if (!server) {
220	    // Row is gone (server deleted); the cascade removed its rules too. Nothing to do.
221	    console.log(`[fw] server ${serverId} not found — skipping firewall sync`);
222	    return;
223	  }
224	
225	  // Don't fight the lifecycle: a suspended/deleting/not-yet-provisioned VM has no
226	  // reachable guest to configure. The rules stay in the DB and re-apply on the
227	  // next sync once the server is steady again.
228	  if (["SUSPENDED", "DELETING", "PENDING", "PROVISIONING", "REINSTALLING", "STOPPED", "ERROR"].includes(server.status)) {
229	    console.log(`[fw] server ${serverId} status=${server.status} — deferring firewall sync`);
230	    return;
231	  }
232	
233	  // Re-validate every ENABLED row through the SAME gate the action used. A row
234	  // that somehow got into the DB malformed is dropped from the applied set (and
235	  // reported) rather than allowed to break the build.
236	  const validated: ValidatedRule[] = [];
237	  for (const r of server.firewallRules) {
238	    if (!r.enabled) continue;
239	    const result = validateRule({
240	      action: r.action,
241	      protocol: r.protocol,
242	      portFrom: r.portFrom,
243	      portTo: r.portTo,
244	      sourceCidr: r.sourceCidr,
245	    });
246	    if (!result.ok) {
247	      console.error(`[fw] server ${serverId} rule ${r.id} rejected at apply: ${result.error}`);
248	      continue;
249	    }
250	    validated.push(result.rule);
251	  }
252	
253	  const script = buildReconcileScript(validated);
254	
255	  if (SANDBOX) {
256	    console.log(`[fw] SANDBOX — would apply ${validated.length} rule(s) to ${server.hostname}:\n${script}`);
257	    return;
258	  }
259	
260	  const password = serverRootPassword(server);
261	  if (!server.ipAddress || !password) {
262	    throw new Error(`syncFirewall: server ${serverId} has no reachable IP or root password`);
263	  }
264	
265	  // sshpass + execFile ARRAY args: the script travels as a single-quoted payload
266	  // to `bash -c` on the guest; nothing here is assembled by a host shell.
267	  const args = [
268	    "-p",
269	    password,
270	    "ssh",
271	    "-o",
272	    "StrictHostKeyChecking=no",
273	    "-o",
274	    "UserKnownHostsFile=/dev/null",
275	    "-o",
276	    "ConnectTimeout=10",
277	    `root@${server.ipAddress}`,
278	    `bash -c ${shSingleQuote(script)}`,
279	  ];
280	
281	  try {
282	    await execFileAsync("sshpass", args, {
283	      timeout: CMD_TIMEOUT_MS,
284	      maxBuffer: 4 * 1024 * 1024,
285	      env: { ...process.env, DEBIAN_FRONTEND: "noninteractive" },
286	    });
287	  } catch (e: any) {
288	    const out = `${e?.stdout ?? ""}${e?.stderr ? `\n${e.stderr}` : ""}`.trim();
289	    throw new Error(
290	      `syncFirewall: applying ${FW_CHAIN} to ${server.hostname} failed — ${e?.killed ? "timed out" : `exit ${e?.code ?? "?"}`}` +
291	        (out ? `: ${out.slice(0, 400)}` : "")
292	    );
293	  }
294	
295	  console.log(`[fw] applied ${validated.length} rule(s) to ${server.hostname} (${FW_CHAIN})`);
296	}
