318	const CHAIN = process.env.NXEON_NAT_CHAIN ?? "NXEON_FWD";
319	
320	async function iptables(args: string[]) {
321	  await exec("iptables", args);
322	}
323	
324	async function ensureChain() {
325	  try {
326	    await iptables(["-t", "nat", "-N", CHAIN]);
327	  } catch {
328	    /* chain exists */
329	  }
330	  // Ensure PREROUTING jumps to our chain exactly once — this is the path for
331	  // EXTERNAL clients (real customers) reaching a NAT guest's forwarded port.
332	  try {
333	    await iptables(["-t", "nat", "-C", "PREROUTING", "-j", CHAIN]);
334	  } catch {
335	    await iptables(["-t", "nat", "-A", "PREROUTING", "-j", CHAIN]);
336	  }
337	  // Also jump from OUTPUT for HOST-LOCAL traffic aimed at our own public IP.
338	  // PREROUTING DNAT never fires for packets a process on THIS box originates, so
339	  // the platform's own ops that connect to <PUBLIC_IP>:<forwarded-port> — SSL
340	  // issuance, migration remediation, backups, the Claude backfill — were hitting
341	  // the host's own (empty) port and getting ECONNREFUSED for every NAT server.
342	  // Scoping the jump to `-d <PUBLIC_IP>` means only traffic addressed to the
343	  // public IP is redirected; host-local :port traffic to anything else is
344	  // untouched, and the shared DNAT rules only match ports that actually forward.
345	  const publicIp = (process.env.PUBLIC_IP ?? "").trim();
346	  if (publicIp) {
347	    try {
348	      await iptables(["-t", "nat", "-C", "OUTPUT", "-d", publicIp, "-j", CHAIN]);
349	    } catch {
350	      await iptables(["-t", "nat", "-A", "OUTPUT", "-d", publicIp, "-j", CHAIN]);
351	    }
352	  }
353	}
