355	/**
356	 * The real, iptables-backed NatHost — the only implementation production uses.
357	 * The decision logic it is handed to lives in lib/nat-rules.ts and is tested
358	 * against an in-memory fake; see the H5 incident note at the top of that file.
359	 */
360	function iptablesHost(): NatHost {
361	  return {
362	    ensureChain,
363	    listChain: async () => {
364	      const { stdout } = await exec("iptables", ["-t", "nat", "-S", CHAIN]);
365	      return stdout;
366	    },
367	    addRule: (r: NatRule) => iptables(["-t", "nat", "-A", CHAIN, ...ruleSpec(r)]),
368	    deleteRule: (r: NatRule) => iptables(["-t", "nat", "-D", CHAIN, ...ruleSpec(r)]),
369	  };
370	}
