372	/**
373	 * Reconcile the NXEON_FWD chain with the database, and verify the result.
374	 *
375	 * This used to open with `iptables -t nat -F NXEON_FWD` and rebuild the chain in
376	 * an unguarded loop, so a single failed `-A` aborted the rebuild and left every
377	 * subsequent server with no DNAT rule — a fleet-wide SSH blackhole that reported
378	 * DONE, because DONE meant "the last iptables call exited 0" (incident H5).
379	 *
380	 * There is no flush now. `reconcileNatChain` reads the chain, applies only the
381	 * difference, then reads it BACK and throws with the exact missing rules and the
382	 * command to inspect them if the kernel does not hold what the database says it
383	 * should. Rules that were already correct are never removed, so no failure in
384	 * this path can take down a customer who was working before it ran.
385	 *
386	 * Throws on an unproven ruleset — callers that cannot tolerate a throw must say
387	 * so; `remove()` in worker/index.ts calls this after deleting the server row, so
388	 * a throw there re-queues DELETE onto a row that no longer exists. That caller
389	 * uses `syncPortForwardsBestEffort` below.
390	 */
391	export async function syncPortForwards(): Promise<NatSyncResult> {
392	  const servers = await db.server.findMany({
393	    where: {
394	      ipAddress: { not: null },
395	      sshPort: { not: null },
396	      status: { notIn: ["SUSPENDED", "DELETING"] },
397	    },
398	    include: { portForwards: true },
399	  });
400	
401	  const intent = planNatRules(servers as unknown as ForwardSource[]);
402	
403	  // Two data problems that used to be invisible because the old loop just built
404	  // whatever it was handed. Neither blocks the sync — the ruleset we install is
405	  // still verified end to end — but neither is swallowed either.
406	  for (const c of intent.conflicts) {
407	    console.error(
408	      `[nat] port collision: ${c.proto}/${c.dport} is claimed by ${c.winner} and also by ` +
409	        `${c.losers.join(", ")}. Only ${c.winner} is forwarded; the others get NOTHING on that port.`
410	    );
411	  }
412	  for (const r of intent.rejected) {
413	    console.error(`[nat] ${r.hostname}: no rule installed — ${r.reason}`);
414	  }
415	
416	  const result = await reconcileNatChain(iptablesHost(), CHAIN, intent);
417	  if (result.unparsed.length) {
418	    console.warn(
419	      `[nat] ${CHAIN} contains ${result.unparsed.length} rule(s) this engine did not write and ` +
420	        `will not touch: ${result.unparsed.slice(0, 5).join(" | ")}`
421	    );
422	  }
423	  console.log(
424	    `[nat] ${CHAIN} verified: ${result.verified} rule(s) present (+${result.added} / -${result.deleted})`
425	  );
426	  return result;
427	}
