429	/**
430	 * For callers that must not be re-queued by a sync failure (server DELETE runs
431	 * this after the row is gone, so a throw dies on "Server not found" on retry and
432	 * the sync is never re-attempted — H5's aggravating factor).
433	 *
434	 * It still never claims success: the failure is logged in full and returned, so
435	 * the caller can surface it. What it will not do is convert a networking problem
436	 * into a stuck job that hides it.
437	 */
438	export async function syncPortForwardsBestEffort(context: string): Promise<Error | null> {
439	  try {
440	    await syncPortForwards();
441	    return null;
442	  } catch (e: any) {
443	    console.error(`[nat] port-forward sync FAILED after ${context} — forwarding may be wrong: ${e?.message ?? e}`);
444	    return e instanceof Error ? e : new Error(String(e));
445	  }
446	}
