529	/**
530	 * Put the VM's identity back after `qmrestore --force` replaced its config with
531	 * the archive's, then PROVE it took before anything is started.
532	 *
533	 * The order is load-bearing: this runs BETWEEN the restore and the start. A VM
534	 * that boots first and is corrected afterwards has already spoken on the wire
535	 * with the archive's address, which may now belong to another customer. Any
536	 * failure here throws, which fails the job and leaves the machine stopped —
537	 * the only safe outcome.
538	 */
539	async function reapplyIdentity(conn: any, nodeRow: any, server: any, vmid: number): Promise<void> {
540	  const desired = restoreIdentityConfig({
541	    plan: { cpuCores: server.plan?.cpuCores, ramMB: server.plan?.ramMB },
542	    natIp: server.ipAddress ?? null,
543	    natGateway: gatewayIp(nodeRow?.subnetPrefix),
544	    natBridge: nodeRow?.bridge ?? "vmbr1",
545	    dedicated: server.dedicatedIp
546	      ? {
547	          address: server.dedicatedIp.address,
548	          virtualMac: server.dedicatedIp.virtualMac ?? null,
549	          gateway: ovhGateway(),
550	        }
