580	export async function backupRestore(job: Job): Promise<void> {
581	  const server = await loadServer(job.serverId!);
582	  if (SANDBOX) {
583	    // Simulate a successful restore — animate the bar 0→100 so staging shows it.
584	    const steps = [
585	      { pct: 8, step: "Stopping server" },
586	      { pct: 30, step: "Restoring archive… 25%" },
587	      { pct: 55, step: "Restoring archive… 55%" },
588	      { pct: 80, step: "Restoring archive… 85%" },
589	      { pct: 95, step: "Starting server" },
590	      { pct: 100, step: "Restore complete" },
591	    ];
592	    for (const s of steps) {
593	      await reportJobProgress(job.id, s.pct, s.step);
594	      await new Promise((r) => setTimeout(r, 500));
595	    }
596	    await notify(
597	      server.userId,
598	      `Backup restored on ${server.hostname}`,
599	      "Your server was restored from the selected backup (sandbox).",
600	      `/dashboard/servers/${server.id}`
601	    );
602	    return;
603	  }
604	  if (!server.vmid) throw new Error("restore: server has no VM");
605	
606	  const payload = (job.payload ?? {}) as { volid?: string };
607	  const volid = payload.volid;
608	  if (!volid) throw new Error("restore: missing volid");
609	
610	  // DATA SAFETY (critical): step 2 below runs `qmrestore --force` over the live
611	  // vmid. PVE calls destroy_vm first ("avoid zombie disks when restoring over an
612	  // existing VM"), and destroy_vm frees EVERY volume that vmid owns — including
613	  // detached `unusedN` entries, because it passes include_unused => 1. Restoring
614	  // an archive taken before a volume was attached would therefore wipe that
615	  // volume's data while the Volume row still bills for it.
616	  //
617	  // Matches the reinstall guard, and mirrors requestRestore()'s check so a job
618	  // queued before that check existed (or enqueued by any other path) still cannot
619	  // destroy data. Counting by serverId alone is deliberate — detaching keeps the
620	  // disk owned by this vmid, so DETACHED volumes are just as exposed as attached.
621	  const pinnedVolumes = await db.volume.findMany({ where: { serverId: server.id } });
622	  const realPinned = pinnedVolumes.filter(
623	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
624	  );
625	  if (realPinned.length > 0) {
626	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
627	    throw new Error(
628	      `Restore blocked to protect your data volume(s): ${names}. Restoring replaces every ` +
629	        `disk this server owns, which would destroy them permanently. Move or delete them first.`
630	    );
631	  }
632	
633	  const { conn, row: nodeRow } = await nodeFor(server);
634	  const vmid = server.vmid;
635	  const wasRunning = server.status === "RUNNING";
636	
637	  // 1) Stop the VM so the disk can be overwritten (ignore "already stopped").
638	  await reportJobProgress(job.id, 3, "Stopping server");
639	  try {
640	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
641	    await conn.waitForTask(stopUpid);
642	  } catch {
643	    /* already stopped / not running */
644	  }
645	  await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });
646	
647	  // 2) Restore the archive over the existing VMID (force overwrite). Storage is
648	  //    left to the archive's recorded config so disks land where they were.
649	  //    Task progress (0..100) is mapped into the 10..90 window of the bar.
650	  await reportJobProgress(job.id, 10, "Restoring archive…");
