681	    );
682	    throw e;
683	  }
684	
685	  // 4) Bring the VM back up if it was running before the restore.
686	  if (wasRunning) {
687	    await reportJobProgress(job.id, 95, "Starting server");
688	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
