734	/**
735	 * Scheduled-backup sweep.
736	 *
737	 * `scheduledBackupSweep` finds RUNNING servers that opted into recurring backups
738	 * (`autoBackup=true`) whose last backup ATTEMPT is older than their configured
739	 * cadence (or which have never had one), and enqueues a BACKUP_CREATE job for
740	 * each — de-duping on any in-flight job so it's safe to call on a timer.
741	 *
742	 * It deliberately writes NOTHING to `Server.lastAutoBackup`. That used to be
743	 * stamped right here, at enqueue time, which is how a customer could read "Last
744	 * automatic backup: today" every night while vzdump silently failed every night
745	 * (incident H4). The column now means "an archive was observed in storage", and
746	 * `backupCreate` in worker/index.ts is its only writer. All the decision logic
747	 * lives in lib/backup-verify.ts so it can be tested without a DB or a clock.
748	 *
749	 * NOTE: `worker/index.ts` owns the job loop; it already knows how to run
750	 * BACKUP_CREATE jobs. Wire this sweep into the main loop on a timer, e.g.:
751	 *
752	 *   import { scheduledBackupSweep } from "./backup-schedule";
753	 *   if (Date.now() - lastBackupSweep > 15 * 60_000) {
754	 *     lastBackupSweep = Date.now();
755	 *     try { await scheduledBackupSweep(); } catch (e) { console.error(e); }
756	 *   }
757	 */
758	export async function scheduledBackupSweep(): Promise<void> {
759	  if (SANDBOX) return; // no real backups run in the sandbox
760	  const now = Date.now();
761	
762	  const candidates = await db.server.findMany({
763	    where: {
764	      status: "RUNNING",
765	      autoBackup: true,
766	      backupIntervalHours: { not: null },
767	    },
768	    select: {
769	      id: true,
770	      hostname: true,
771	      backupIntervalHours: true,
772	      lastAutoBackup: true,
773	    },
774	  });
775	  if (candidates.length === 0) return;
776	
777	  // One row per server: the most recent BACKUP_CREATE job, whatever its outcome.
778	  // This is the attempt anchor — see `isAutoBackupDue` for why anchoring on
779	  // success instead would hammer a server whose backups always fail.
780	  const lastAttempts = await db.job.findMany({
781	    where: { serverId: { in: candidates.map((s) => s.id) }, type: "BACKUP_CREATE" },
782	    orderBy: { createdAt: "desc" },
783	    distinct: ["serverId"],
784	    select: { serverId: true, createdAt: true, status: true },
785	  });
786	  const attemptBy = new Map(lastAttempts.map((j) => [j.serverId as string, j]));
787	
788	  let enqueued = 0;
789	  for (const s of candidates) {
790	    const attempt = attemptBy.get(s.id) ?? null;
791	    const due = isAutoBackupDue({
792	      now,
793	      intervalHours: s.backupIntervalHours,
794	      lastAttemptAt: attempt?.createdAt ?? null,
795	    });
796	    if (!due) continue;
797	
798	    // Respect the one-in-flight-job-per-server invariant.
799	    const inflight = await db.job.count({
800	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
801	    });
802	    if (inflight > 0) continue;
803	
804	    // Surface a schedule that is quietly not producing backups. The customer's
805	    // own notification comes from the failing job; this is the operator's copy,
806	    // and it is the signal that used to be invisible.
807	    const health = backupScheduleHealth({
808	      now,
809	      autoBackup: true,
810	      intervalHours: s.backupIntervalHours,
811	      lastVerifiedAt: s.lastAutoBackup,
812	      lastAttempt: attempt ? { at: attempt.createdAt, status: attempt.status } : null,
813	    });
814	    if (health.state === "never" || health.state === "stale" || health.state === "failing") {
815	      console.error(`[backup-schedule] ${s.hostname}: ${health.state} — ${health.detail}`);
816	    }
817	
818	    await db.job.create({ data: { type: "BACKUP_CREATE", serverId: s.id, payload: { auto: true } } });
819	    enqueued++;
820	  }
821	
822	  if (enqueued > 0) console.log(`[backup-schedule] sweep enqueued ${enqueued} backup job(s)`);
823	}
