850	// ---------------------------------------------------------------------------
851	// Pure retry math — no I/O, safe to unit test directly.
852	// ---------------------------------------------------------------------------
853	
854	/**
855	 * How many attempts a retry window of `timeoutMs` at `intervalMs` cadence
856	 * allows, counting the first (immediate) attempt. Always at least 1, so a
857	 * misconfigured zero/negative timeout still tries once rather than looping
858	 * forever or never trying at all.
859	 */
860	export function attemptsFor(timeoutMs: number, intervalMs: number): number {
861	  if (!Number.isFinite(timeoutMs) || !Number.isFinite(intervalMs) || intervalMs <= 0) return 1;
862	  return Math.max(1, Math.floor(timeoutMs / intervalMs) + 1);
863	}
864	
865	export type CheckOnce = () => Promise<{ ok: true; detail?: string } | { ok: false; error: string }>;
866	
867	export type RetryResult =
868	  | { ok: true; detail?: string; attempts: number; elapsedMs: number }
869	  | { ok: false; error: string; attempts: number; elapsedMs: number };
870	
871	/**
872	 * Generic bounded retry: call `checkOnce` up to `attemptsFor(timeoutMs,
873	 * intervalMs)` times, sleeping `intervalMs` between attempts, stopping early
874	 * on the first success. `sleep` is injectable so tests can run this at real
875	 * speed with zero wall-clock delay instead of mocking timers.
876	 */
877	export async function retryCheck(
878	  checkOnce: CheckOnce,
879	  opts: { timeoutMs: number; intervalMs: number; sleep?: (ms: number) => Promise<void>; now?: () => number }
880	): Promise<RetryResult> {
881	  const sleep = opts.sleep ?? ((ms: number) => new Promise((resolve) => setTimeout(resolve, ms)));
882	  const now = opts.now ?? (() => Date.now());
883	  const attempts = attemptsFor(opts.timeoutMs, opts.intervalMs);
884	  const start = now();
885	  let lastError = "no attempt was made";
886	  for (let i = 0; i < attempts; i++) {
887	    const res = await checkOnce();
888	    if (res.ok) return { ok: true, detail: res.detail, attempts: i + 1, elapsedMs: now() - start };
889	    lastError = res.error;
890	    if (i < attempts - 1) await sleep(opts.intervalMs);
891	  }
892	  return { ok: false, error: lastError, attempts, elapsedMs: now() - start };
893	}
