925	// ---------------------------------------------------------------------------
926	// Real network I/O — single-attempt probes.
927	// ---------------------------------------------------------------------------
928	
929	/** Default per-attempt socket timeout — how long ONE connect (not the whole
930	 *  retry window) is allowed before giving up and trying again. */
931	export const TCP_ATTEMPT_TIMEOUT_MS = 5_000;
932	
933	/**
934	 * One TCP connect attempt, optionally requiring an SSH banner
935	 * ("SSH-2.0-...") rather than just a completed handshake — a closed port
936	 * that drops the connection can otherwise look indistinguishable from a real
937	 * refusal on some networks, so getting the actual banner is the proof.
938	 */
939	function tcpAttempt(
940	  host: string,
941	  port: number,
942	  opts: { timeoutMs: number; expectSshBanner: boolean }
943	): Promise<{ ok: true; detail?: string } | { ok: false; error: string }> {
944	  return new Promise((resolve) => {
945	    const socket = new net.Socket();
946	    let settled = false;
947	    let buf = "";
948	    const finish = (result: { ok: true; detail?: string } | { ok: false; error: string }) => {
949	      if (settled) return;
950	      settled = true;
951	      clearTimeout(timer);
952	      socket.removeAllListeners();
953	      socket.destroy();
954	      resolve(result);
955	    };
956	    const timer = setTimeout(() => finish({ ok: false, error: "timed out" }), opts.timeoutMs);
957	    socket.once("error", (err: NodeJS.ErrnoException) => finish({ ok: false, error: err.code ?? err.message }));
958	    socket.once("connect", () => {
959	      if (!opts.expectSshBanner) finish({ ok: true });
960	      // else: wait for the banner line on "data" below.
961	    });
962	    if (opts.expectSshBanner) {
963	      socket.on("data", (chunk) => {
964	        buf += chunk.toString("utf8");
965	        if (buf.includes("\n") || buf.length >= 256) {
966	          const line = buf.trim();
967	          if (line.startsWith("SSH-")) finish({ ok: true, detail: line.slice(0, 120) });
968	          else finish({ ok: false, error: `connected but no SSH banner (got: ${line.slice(0, 80) || "<empty>"})` });
969	        }
970	      });
971	    }
972	    socket.connect(port, host);
973	  });
974	}
975	
976	/**
977	 * One UDP reachability probe. UDP has no handshake, so this cannot PROVE a
978	 * listener exists the way a TCP connect can — but on Linux, a datagram sent
979	 * to a UDP port nothing is bound to draws a prompt ICMP port-unreachable,
980	 * which node surfaces as an `ECONNREFUSED` error on a *connected* UDP socket.
981	 * No error within the window is treated as reachable. This is the same class
982	 * of "did the process actually bind the port" evidence the TCP check gives —
983	 * it would have caught the Terraria-style bug (container up, nothing bound)
984	 * on a UDP-only game exactly the same way.
985	 */
986	function udpAttempt(host: string, port: number, opts: { timeoutMs: number }): Promise<{ ok: true } | { ok: false; error: string }> {
987	  return new Promise((resolve) => {
988	    const socket = dgram.createSocket("udp4");
989	    let settled = false;
990	    const finish = (result: { ok: true } | { ok: false; error: string }) => {
991	      if (settled) return;
992	      settled = true;
993	      clearTimeout(timer);
994	      socket.removeAllListeners();
995	      socket.close();
996	      resolve(result);
997	    };
998	    const timer = setTimeout(() => finish({ ok: true }), opts.timeoutMs);
999	    socket.once("error", (err: NodeJS.ErrnoException) => finish({ ok: false, error: err.code ?? err.message }));
1000	    socket.connect(port, host, () => {
1001	      socket.send(Buffer.from([0]), (err) => {
1002	        if (err) finish({ ok: false, error: (err as NodeJS.ErrnoException).code ?? err.message });
1003	      });
1004	    });
1005	  });
1006	}
