1012	/**
1013	 * Retries every ~5s for up to 2 minutes. SSH normally comes up within
1014	 * seconds of the guest booting — cloud-init's user/ssh-key modules run near
1015	 * the START of boot, well before the game/app install `runcmd` — and by the
1016	 * time provision() reaches this check it has usually already waited up to
1017	 * 180s for the guest agent, so sshd has almost always had time. Two minutes
1018	 * of its own headroom on top covers the case where the agent never answers
1019	 * (not every image ships qemu-guest-agent) but sshd is merely slow.
1020	 */
1021	export const SSH_CHECK_TIMEOUT_MS = 120_000;
1022	export const SSH_CHECK_INTERVAL_MS = 5_000;
1023	
1024	/**
1025	 * Real TCP connect + SSH banner check against the server's actual reachable
1026	 * address (caller passes the dedicated IP, or the NAT host + assigned SSH
1027	 * port — see worker/index.ts's `dedicated`/`sshPort` computation, reused
1028	 * here rather than recomputed).
1029	 */
1030	export async function checkSshReachable(
1031	  host: string,
1032	  port: number,
1033	  opts?: { timeoutMs?: number; intervalMs?: number; sleep?: (ms: number) => Promise<void> }
1034	): Promise<RetryResult> {
1035	  return retryCheck(() => tcpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS, expectSshBanner: true }), {
1036	    timeoutMs: opts?.timeoutMs ?? SSH_CHECK_TIMEOUT_MS,
1037	    intervalMs: opts?.intervalMs ?? SSH_CHECK_INTERVAL_MS,
1038	    sleep: opts?.sleep,
1039	  });
1040	}
1041	
1042	/**
1043	 * Retries every 10s for up to 5 minutes (30 attempts). A game server takes
1044	 * meaningfully longer than SSH to actually start listening — the setup
1045	 * script still has to run AFTER boot (docker install if not cached, image
1046	 * pull, first-run world/save generation) once cloud-init's `runcmd` fires.
1047	 * 5 minutes is a principled default sized for a cold Docker image pull on
1048	 * this host, not an empirically measured figure (no real order was placed
1049	 * to time one for this change) — the timeout/interval are named exports so
1050	 * they can be retuned in one place once real timings are observed.
1051	 */
1052	export const GAME_PORT_CHECK_TIMEOUT_MS = 300_000;
1053	export const GAME_PORT_CHECK_INTERVAL_MS = 10_000;
1054	
1055	/**
1056	 * Real TCP-or-UDP connect check (per `GAME_PORT`'s `protocol`) against the
1057	 * server's own address at the game's actual listen port — see
1058	 * `gamePortForServer`. Reuses the caller's already-computed `ip` (the
1059	 * dedicated public IP, or the NAT server's private address) rather than
1060	 * recomputing it.
1061	 *
1062	 * NOTE on NAT servers: only SSH gets an automatic port-forward at provision
1063	 * time (`syncPortForwardsBestEffort`); the game's own port is forwarded only
1064	 * if the customer adds a `PortForward` for it (lib/actions-server.ts) — a
1065	 * separate, pre-existing product gap this task does not touch. Checking
1066	 * against the VM's own address (not the public NAT address) still verifies
1067	 * the thing this check exists to catch — the game process itself bound the
1068	 * port — independent of whether that port is yet forwarded to the internet.
1069	 */
1070	export async function checkGamePortOpen(
1071	  host: string,
1072	  port: number,
1073	  protocol: "tcp" | "udp",
1074	  opts?: { timeoutMs?: number; intervalMs?: number; sleep?: (ms: number) => Promise<void> }
1075	): Promise<RetryResult> {
1076	  const checkOnce: CheckOnce =
1077	    protocol === "tcp"
1078	      ? () => tcpAttempt(host, port, { timeoutMs: TCP_ATTEMPT_TIMEOUT_MS, expectSshBanner: false })
