1081	    timeoutMs: opts?.timeoutMs ?? GAME_PORT_CHECK_TIMEOUT_MS,
1082	    intervalMs: opts?.intervalMs ?? GAME_PORT_CHECK_INTERVAL_MS,
1083	    sleep: opts?.sleep,
1084	  });
1085	}
