472	export async function installApp(
473	  serverId: string,
474	  appSlug: string,
475	  domainInput: string,
476	  adminUserInput?: string
477	): Promise<InstallResult> {
478	  try {
479	    const { user, server } = await ownedServer(serverId);
480	    const limited = throttle(user.id, "install", 6);
481	    if (limited) return { ok: false, error: limited };
482	    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to install an app." };
483	    if (await lifecycleBusy(server.id))
484	      return { ok: false, error: "Another server operation is in progress — try again shortly." };
485	
486	    const app = appBySlug(appSlug);
487	    if (!app) return { ok: false, error: "Unknown application." };
488	
489	    // Apps we cannot install end to end are not sold as one-click installs; say
490	    // so up front instead of queueing a job that would have to lie or fail.
491	    const info = appMode(app.slug);
492	    if (info.mode === "unavailable") return { ok: false, error: `${app.name} — ${info.remaining}` };
493	
494	    const domain = String(domainInput ?? "").toLowerCase().trim().replace(/\.$/, "");
495	    if (!DOMAIN_RE.test(domain))
496	      return { ok: false, error: "Enter a valid domain (e.g. blog.example.com) pointed at this server." };
497	
498	    // Domain must be free of an existing website on this server.
499	    const dupSite = await db.website.findFirst({ where: { serverId: server.id, domain } });
500	    if (dupSite) return { ok: false, error: `A website for ${domain} already exists on this server.` };
501	
502	    // An admin account only exists for apps whose install we complete ourselves.
503	    const managed = info.mode === "managed";
504	    const adminUser = managed
505	      ? (String(adminUserInput ?? "admin").replace(/[^a-z0-9_]/gi, "") || "admin").slice(0, 32)
506	      : null;
507	    const adminPassword = managed ? generateStrongPassword(18) : "";
508	    const dbName = app.engine ? dbIdentFromDomain(domain, "db") : "";
509	    const dbUser = app.engine ? dbIdentFromDomain(domain, "u") : "";
510	    const dbPassword = app.engine ? generateStrongPassword(20) : "";
511	
512	    // Create the primitives + the install record in one transaction.
513	    const { appRow } = await db.$transaction(async (tx) => {
514	      const website = await tx.website.create({
515	        data: {
516	          userId: user.id,
517	          serverId: server.id,
518	          domain,
519	          docRoot: `/var/www/${domain}`,
520	          phpVersion: app.php,
521	          isSubdomain: domain.split(".").length > 2,
522	          appSlug: app.slug,
523	          status: "PENDING",
524	        },
525	      });
526	      let database: { id: string } | null = null;
527	      if (app.engine) {
528	        database = await tx.vpsDatabase.create({
529	          data: {
530	            userId: user.id,
531	            serverId: server.id,
532	            engine: app.engine,
533	            name: dbName,
534	            dbUser,
535	            passwordEnc: encryptSecret(dbPassword),
536	            status: "PENDING",
537	          },
538	        });
539	      }
540	      const appRow = await tx.appInstall.create({
541	        data: {
542	          userId: user.id,
543	          serverId: server.id,
544	          appSlug: app.slug,
545	          domain,
546	          websiteId: website.id,
547	          databaseId: database?.id ?? null,
548	          adminUser,
549	          // Nothing is stored for an assisted app: the customer creates that
550	          // account inside the application's own wizard, so there is no
551	          // password for us to keep, apply — or claim.
552	          adminPassEnc: managed ? encryptSecret(adminPassword) : null,
553	          status: "PENDING",
554	        },
555	      });
556	      return { appRow };
557	    });
558	
559	    await db.job.create({ data: { type: "APP_INSTALL", serverId: server.id, payload: { appId: appRow.id } } });
560	    await db.auditLog.create({
561	      data: { userId: user.id, action: "cpanel.app.install", detail: `${app.slug} → ${domain} on ${server.hostname}` },
562	    });
563	    revalidatePath(`/dashboard/servers/${serverId}`);
564	
565	    // Credentials returned ONCE — and only the ones that actually exist.
566	    const credentials: { label: string; value: string }[] = [{ label: "URL", value: `http://${domain}/` }];
567	    if (managed && adminUser) {
568	      credentials.push({ label: "Admin user", value: adminUser });
569	      credentials.push({ label: "Admin password", value: adminPassword });
570	    }
571	    if (dbName) {
572	      credentials.push({ label: "Database", value: dbName });
573	      credentials.push({ label: "DB user", value: dbUser });
574	      credentials.push({ label: "DB password", value: dbPassword });
575	      credentials.push({ label: "DB host", value: "localhost" });
576	    }
577	    const note = managed
578	      ? `Installing now. ${app.name} is only marked installed once we have fetched the site from your server and ` +
579	        `checked that this admin password signs in — if that fails you will get a failure, not a green tick.`
580	      : `Installing now. This prepares the site, the database and ${app.name}'s files — it does NOT finish the ` +
581	        `install. ${info.remaining} Keep the database credentials above: the wizard asks for them.`;
582	
583	    return { ok: true, id: appRow.id, domain, appName: app.name, mode: info.mode, credentials, note };
584	  } catch (err) {
585	    return { ok: false, error: safeError(err) };
586	  }
587	}
