687	 */
688	export async function orderVolume(
689	  name: string,
690	  sizeGB: number
691	): Promise<{ error?: string; id?: string }> {
692	  // Spend path: this debits the wallet up front, so it takes the same guard as
693	  // every other purchase (lib/actions.ts payAndDeploy, lib/actions-disk.ts
694	  // expandServerDisk, the domain transfer actions). It was the only wallet debit
695	  // in the storage product without one.
696	  await assertNotImpersonating();
697	  const user = await requireUser();
698	  // Purchase gate: an unverified address means we cannot reach the person we
699	  // are about to charge. See lib/email-verification.ts.
700	  const unverified = await emailVerificationError(user);
701	  if (unverified) return { error: unverified };
702	
703	  const clean = (name ?? "")
704	    .replace(/[\x00-\x1f\x7f]/g, "")
705	    .replace(/\s+/g, " ")
706	    .trim();
707	  if (clean.length < 2 || clean.length > 40) {
708	    return { error: "Name must be 2–40 characters." };
709	  }
710	  const size = Math.round(Number(sizeGB));
711	  if (!Number.isFinite(size) || size < MIN_GB || size > MAX_GB) {
712	    return { error: `Size must be between ${MIN_GB} and ${MAX_GB} GB.` };
713	  }
714	
715	  const priceCents = await volumePriceCents(size);
716	
717	  let volumeId: string;
718	  try {
719	    volumeId = await db.$transaction(async (tx) => {
720	      await debitWallet(tx, user.id, priceCents);
721	      await tx.walletTransaction.create({
722	        data: {
723	          userId: user.id,
724	          amountCents: -priceCents,
725	          description: `Block storage volume: ${clean} (${size} GB)`,
726	        },
727	      });
728	      const v = await tx.volume.create({
729	        data: {
730	          userId: user.id,
731	          name: clean,
732	          sizeGB: size,
733	          priceCents,
734	          status: "PENDING",
735	          expiresAt: addMonths(new Date(), 1),
736	        },
737	      });
738	      await tx.job.create({ data: { type: "VOLUME_CREATE", payload: { volumeId: v.id } } });
739	      return v.id;
740	    });
741	  } catch (e) {
742	    if (e instanceof InsufficientBalanceError) {
743	      return { error: "Insufficient balance — top up your wallet first." };
744	    }
745	    throw e;
746	  }
747	
748	  await db.auditLog.create({
749	    data: { userId: user.id, action: "volume.order", detail: `${volumeId} ${clean} ${size}GB` },
750	  });
751	  revalidatePath("/dashboard/volumes");
752	  return { id: volumeId };
753	}
