755	/** Attach a DETACHED volume to one of the caller's RUNNING servers. */
756	export async function attachVolume(
757	  volumeId: string,
758	  serverId: string
759	): Promise<{ error?: string }> {
760	  const { user, volume } = await ownedVolume(volumeId);
761	  const { server } = await ownedServer(serverId);
762	
763	  if (volume.status !== "DETACHED") {
764	    return { error: "Only an available (detached) volume can be attached." };
765	  }
766	  if (!server.vmid || server.status !== "RUNNING") {
767	    return { error: "Target server must be running." };
768	  }
769	  // A volume that already holds data physically lives on one server's VM; it can
770	  // only be re-attached there (cross-node disk migration is out of scope).
771	  if (volume.serverId && volume.serverId !== serverId) {
772	    return { error: "This volume holds data on another server. Attach it there, or delete it first." };
773	  }
774	  if (await serverBusy(serverId)) {
775	    return { error: "Another operation is already in progress on this server." };
776	  }
777	
778	  // Claim the volume with a compare-and-swap on the state we just read, then
779	  // enqueue in the SAME transaction.
780	  //
781	  // The status check above is a snapshot. Two overlapping attach requests — a
782	  // double-click, or the same volume aimed at two different servers from two
783	  // tabs — both saw DETACHED, both wrote `serverId`, and both queued a
784	  // VOLUME_ATTACH. The row ended up pointing at one server while a job tried to
785	  // hot-plug the same disk onto another, and the second attach reports success
786	  // for work that cannot happen. The CAS makes exactly one of them win.
787	  const claimed = await db.volume.updateMany({
788	    where: {
789	      id: volumeId,
790	      status: "DETACHED",
791	      // Re-assert the "lives on one VM" rule inside the swap.
792	      OR: [{ serverId: null }, { serverId }],
793	    },
794	    data: { serverId },
795	  });
796	  if (claimed.count === 0) {
797	    return { error: "This volume was just claimed by another request — refresh the page to see where it is now." };
798	  }
799	  await db.job.create({ data: { type: "VOLUME_ATTACH", serverId, payload: { volumeId } } });
800	  await db.auditLog.create({
801	    data: { userId: user.id, action: "volume.attach", detail: `${volumeId} -> ${serverId}` },
802	  });
803	  revalidatePath("/dashboard/volumes");
804	  revalidatePath(`/dashboard/servers/${serverId}`);
805	  return {};
806	}
807	
808	/** Detach an ATTACHED volume from its server (data is preserved as an unused disk). */
809	export async function detachVolume(volumeId: string): Promise<{ error?: string }> {
810	  const { user, volume } = await ownedVolume(volumeId);
811	  if (volume.status !== "ATTACHED" || !volume.serverId) {
812	    return { error: "Volume is not attached." };
813	  }
814	  if (await serverBusy(volume.serverId)) {
815	    return { error: "Another operation is already in progress on this server." };
816	  }
817	  await db.job.create({
818	    data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId } },
819	  });
820	  await db.auditLog.create({
821	    data: { userId: user.id, action: "volume.detach", detail: `${volumeId}` },
822	  });
823	  revalidatePath("/dashboard/volumes");
824	  revalidatePath(`/dashboard/servers/${volume.serverId}`);
825	  return {};
826	}
827	
828	/** Permanently delete a volume: detaches + destroys the disk, then removes the row. */
829	export async function deleteVolume(volumeId: string): Promise<{ error?: string }> {
830	  const { user, volume } = await ownedVolume(volumeId);
831	  if (volume.status === "DELETING") return { error: "Volume is already being deleted." };
832	
833	  // If the disk physically lives on a server, route the delete through it and
834	  // honour the one-in-flight-job guard so we don't collide with another op.
835	  if (volume.serverId) {
836	    if (await serverBusy(volume.serverId)) {
837	      return { error: "Another operation is already in progress on this server." };
838	    }
839	  }
840	  // Same compare-and-swap as attach, for the same reason and with worse stakes:
841	  // this destroys a disk. Two overlapping deletes both read a non-DELETING row
842	  // and both queued a VOLUME_DELETE for it.
843	  const claimed = await db.volume.updateMany({
844	    where: { id: volumeId, status: { not: "DELETING" } },
845	    data: { status: "DELETING" },
846	  });
847	  if (claimed.count === 0) return { error: "Volume is already being deleted." };
848	  await db.job.create({
849	    data: {
850	      type: "VOLUME_DELETE",
851	      serverId: volume.serverId ?? undefined,
852	      payload: { volumeId },
853	    },
854	  });
855	  await db.auditLog.create({
856	    data: { userId: user.id, action: "volume.delete", detail: `${volumeId}` },
857	  });
858	  revalidatePath("/dashboard/volumes");
859	  if (volume.serverId) revalidatePath(`/dashboard/servers/${volume.serverId}`);
860	  return {};
861	}
