893	export async function purchaseDedicatedIp(
894	  serverId: string,
895	  useWallet: boolean = true,
896	): Promise<{ error?: string; checkout?: EmbeddedCheckout }> {
897	  // Spend path: block wallet debits while an admin is impersonating — same
898	  // guard as every other money movement on a server (resizeServer,
899	  // expandServerDisk).
900	  await assertNotImpersonating();
901	  const { user, server } = await ownedServer(serverId);
902	  // Purchase gate: this is an irreversible real-infra charge. See
903	  // lib/email-verification.ts.
904	  const unverified = await emailVerificationError(user);
905	  if (unverified) return { error: unverified };
906	
907	  if (server.dedicatedIp) return { error: "This server already has a dedicated IP." };
908	
909	  // Reject while another job is in flight, and only from a steady run state.
910	  // (applyDedicatedIpPurchase re-checks both; this returns the friendlier
911	  // message first.)
912	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
913	    return { error: "Server must be running or stopped to add a dedicated IP." };
914	  }
915	  const pending = await db.job.count({ where: { serverId, status: { in: ["QUEUED", "RUNNING"] } } });
916	  if (pending > 0) return { error: "Another operation is already in progress on this server." };
917	
918	  let quote;
919	  try {
920	    quote = await dedicatedIpPurchaseQuote(serverId);
921	  } catch (e) {
922	    if (e instanceof DedicatedIpPurchaseError) return { error: e.message };
923	    throw e;
924	  }
925	  const { prorateCents } = quote;
926	
927	  // Wallet-aware split — identical logic to the resize/disk-expand flows.
928	  // AddDedicatedIp computes the same split (lib/wallet-split.ts) so
929	  // displayed === charged.
930	  const { cardCents } = walletSplit({
931	    dueCents: prorateCents,
932	    balanceCents: user.balanceCents,
933	    useWallet,
934	  });
935	
936	  if (cardCents > 0) {
937	    const checkout = await createDedicatedIpCheckout(user, cardCents, {
938	      serverId,
939	      hostname: server.hostname,
940	      prorateCents,
941	    });
942	    if (!checkout) {
943	      return {
944	        error: `A dedicated IP costs $${(prorateCents / 100).toFixed(2)} for the rest of your term, and card payments aren't set up — top up your wallet first.`,
945	      };
946	    }
947	    return { checkout };
948	  }
949	
950	  try {
951	    await applyDedicatedIpPurchase({ serverId, actorUserId: user.id });
952	  } catch (e) {
953	    if (e instanceof DedicatedIpPurchaseError) return { error: e.message };
954	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
