963	// Server actions for the "Build with Claude AI" feature.
964	// Only async functions are exported (Next.js "use server" constraint).
965	//
966	// Flow: submitBuild -> (worker plans) -> AWAITING_APPROVAL
967	//       -> approveBuild (owner) -> (worker executes) -> DONE/FAILED
968	//       -> rejectBuild (owner) -> FAILED. Nothing runs on the server until the
969	//       owner approves the proposed command plan.
970	
971	import { revalidatePath } from "next/cache";
972	import { db } from "./db";
973	import { requireUser } from "./auth";
974	import { effectiveKeyFor } from "./anthropic";
975	import { serverRootPassword } from "./sftp";
976	import { getSettingBool } from "./settings";
977	
978	const MAX_PROMPT_CHARS = 2000;
979	const MIN_PROMPT_CHARS = 8;
980	// Cap how many builds a user may have in flight, and how many they can start in
981	// a short window, to keep API + SSH usage sane.
982	const MAX_ACTIVE_BUILDS_PER_USER = 3;
983	const RATE_WINDOW_MS = 60_000;
984	const MAX_BUILDS_PER_WINDOW = 5;
985	
986	// Statuses that mean a build is not yet finished (planning, awaiting approval,
987	// queued, or executing) — used for in-flight accounting.
988	const ACTIVE_STATUSES = ["QUEUED", "PLANNING", "AWAITING_APPROVAL", "RUNNING"] as const;
989	
990	export async function submitBuild(
991	  serverId: string,
992	  prompt: string
993	): Promise<{ error?: string; buildId?: string }> {
994	  const user = await requireUser();
995	
996	  // Feature flag: "Build with Claude" can be switched off platform-wide.
997	  if (!(await getSettingBool("feature_claude_builder", true))) {
998	    return { error: "Build with Claude is currently unavailable." };
999	  }
1000	
1001	  const clean = (prompt ?? "").trim();
1002	  if (clean.length < MIN_PROMPT_CHARS) {
1003	    return { error: "Please describe what you'd like Claude to build (a sentence or two)." };
1004	  }
1005	  if (clean.length > MAX_PROMPT_CHARS) {
1006	    return { error: `Prompt is too long (max ${MAX_PROMPT_CHARS} characters).` };
1007	  }
1008	
1009	  // BYOK gate: the owner must have an effective key (their own, or a platform fallback).
1010	  const owner = await db.user.findUnique({
1011	    where: { id: user.id },
1012	    select: { anthropicKeyEnc: true },
1013	  });
1014	  if (!effectiveKeyFor(owner)) {
1015	    return { error: "Add your Anthropic API key in Settings to use Build with AI." };
1016	  }
1017	
1018	  // Ownership: the server must belong to this user.
1019	  const server = await db.server.findFirst({ where: { id: serverId, userId: user.id } });
1020	  if (!server) return { error: "Server not found." };
1021	  if (server.status !== "RUNNING") {
1022	    return { error: "The server must be running to build on it." };
1023	  }
1024	  if (!server.ipAddress || !serverRootPassword(server)) {
1025	    return { error: "This server isn't reachable yet — try again once it finishes provisioning." };
1026	  }
1027	
1028	  // Rate sanity.
1029	  const active = await db.claudeBuild.count({
1030	    where: { userId: user.id, status: { in: [...ACTIVE_STATUSES] } },
1031	  });
1032	  if (active >= MAX_ACTIVE_BUILDS_PER_USER) {
1033	    return { error: "You already have builds in progress. Wait for them to finish before starting another." };
1034	  }
1035	  const recent = await db.claudeBuild.count({
1036	    where: { userId: user.id, createdAt: { gt: new Date(Date.now() - RATE_WINDOW_MS) } },
1037	  });
1038	  if (recent >= MAX_BUILDS_PER_WINDOW) {
1039	    return { error: "Too many builds started just now — please wait a minute and try again." };
1040	  }
1041	  // One in-flight build per server keeps the SSH session serialized.
1042	  const serverBusy = await db.claudeBuild.count({
1043	    where: { serverId, status: { in: [...ACTIVE_STATUSES] } },
1044	  });
1045	  if (serverBusy > 0) {
1046	    return { error: "A build is already in progress on this server." };
1047	  }
1048	
1049	  const build = await db.claudeBuild.create({
1050	    data: { userId: user.id, serverId, prompt: clean, status: "QUEUED", approved: false },
1051	  });
1052	
1053	  // Enqueue the worker job; the handler reads the build via payload.buildId.
1054	  // Because approved=false, the worker will PLAN (not execute).
1055	  await db.job.create({
1056	    data: { type: "CLAUDE_BUILD", serverId, payload: { buildId: build.id } },
1057	  });
1058	
1059	  await db.auditLog
1060	    .create({
1061	      data: { userId: user.id, action: "server.claude_build", detail: `${serverId} ${build.id}` },
1062	    })
1063	    .catch(() => {});
1064	
1065	  revalidatePath("/dashboard/build");
1066	  return { buildId: build.id };
1067	}
