1069	/**
1070	 * Owner approves the proposed plan. Marks it approved and enqueues a second
1071	 * CLAUDE_BUILD job; the worker then executes the stored plan over SSH.
1072	 */
1073	export async function approveBuild(id: string): Promise<{ error?: string; ok?: boolean }> {
1074	  const user = await requireUser();
1075	
1076	  const build = await db.claudeBuild.findFirst({ where: { id, userId: user.id } });
1077	  if (!build) return { error: "Build not found." };
1078	  if (build.status !== "AWAITING_APPROVAL") {
1079	    return { error: "This build isn't awaiting approval." };
1080	  }
1081	  if (!build.plan) {
1082	    return { error: "This build has no plan to approve." };
1083	  }
1084	
1085	  // Compare-and-swap off AWAITING_APPROVAL, then enqueue in the same
1086	  // transaction. The status read above is a snapshot: two overlapping approvals
1087	  // (a double-click, an impatient retry) both saw AWAITING_APPROVAL and both
1088	  // queued a CLAUDE_BUILD job, so the AI's command plan — arbitrary shell run
1089	  // over SSH as root on the customer's server — was executed TWICE. Almost none
1090	  // of those plans are idempotent. Only the swap that flips the row wins.
1091	  const claimed = await db.claudeBuild.updateMany({
1092	    where: { id, userId: user.id, status: "AWAITING_APPROVAL" },
1093	    data: { approved: true, status: "QUEUED" },
1094	  });
1095	  if (claimed.count === 0) {
1096	    return { error: "This build was already approved — refresh the page to watch it run." };
1097	  }
1098	
1099	  await db.job.create({
1100	    data: { type: "CLAUDE_BUILD", serverId: build.serverId, payload: { buildId: build.id } },
1101	  });
1102	
1103	  await db.auditLog
1104	    .create({
1105	      data: { userId: user.id, action: "server.claude_build_approve", detail: `${build.serverId} ${id}` },
1106	    })
1107	    .catch(() => {});
1108	
1109	  revalidatePath("/dashboard/build");
1110	  return { ok: true };
1111	}
