1113	/** Owner rejects the proposed plan. Marks the build FAILED; nothing runs. */
1114	export async function rejectBuild(id: string): Promise<{ error?: string; ok?: boolean }> {
1115	  const user = await requireUser();
1116	
1117	  const build = await db.claudeBuild.findFirst({ where: { id, userId: user.id } });
1118	  if (!build) return { error: "Build not found." };
1119	  if (build.status !== "AWAITING_APPROVAL") {
1120	    return { error: "This build isn't awaiting approval." };
1121	  }
1122	
1123	  // Same compare-and-swap as approveBuild — a reject that races an approve must
