1129	  if (claimed.count === 0) {
1130	    return { error: "This build is no longer awaiting approval — refresh the page to see its current state." };
1131	  }
1132	
1133	  await db.auditLog
1134	    .create({
1135	      data: { userId: user.id, action: "server.claude_build_reject", detail: `${build.serverId} ${id}` },
1136	    })
1137	    .catch(() => {});
1138	
1139	  revalidatePath("/dashboard/build");
1140	  return { ok: true };
1141	}
