147	/**
148	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
149	 * the wallet transaction + PAID invoice, and queue the RESIZE job that the worker
150	 * performs on Proxmox. Re-validates every guard (plan availability, disk-grow,
151	 * not a downgrade, steady state, one in-flight job) so it is safe to call from the
152	 * unauthenticated confirm route. Throws ResizeError on any guard failure.
153	 *
154	 * `chargeCents` overrides the recomputed proration — the paid path passes the exact
155	 * amount the customer paid into their wallet at checkout so the debit here nets to
156	 * zero against that credit (mirrors how the deploy confirm re-runs placeOrder to
157	 * spend the just-credited funds). The wallet path omits it and debits the quote.
158	 */
159	export async function applyResize(opts: {
160	  serverId: string;
161	  planId: string;
162	  actorUserId: string;
163	  chargeCents?: number;
164	}): Promise<void> {
165	  const { server, newPlan, prorateCents: quoted } = await resizeQuote(opts.serverId, opts.planId);
166	  const prorateCents = opts.chargeCents ?? quoted;
167	
168	  const pending = await db.job.count({ where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } } });
169	  if (pending > 0) throw new ResizeError("Another operation is already in progress on this server.");
170	
171	  try {
172	    await db.$transaction(async (tx) => {
173	      if (prorateCents > 0) {
174	        await debitWallet(tx, server.userId, prorateCents);
175	        await tx.walletTransaction.create({
176	          data: {
177	            userId: server.userId,
178	            amountCents: -prorateCents,
179	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
180	          },
181	        });
182	        // PAID invoice for the proration charge (one per user-initiated resize).
183	        await tx.invoice.create({
184	          data: invoiceCreateData({
185	            userId: server.userId,
186	            description: `Upgrade to ${newPlan.name} (prorated) — ${server.hostname}`,
187	            status: "PAID",
188	            lineItems: [
189	              { description: `Upgrade to ${newPlan.name} — prorated for remaining term (${server.hostname})`, qty: 1, unitCents: prorateCents, amountCents: prorateCents },
190	            ],
191	          }),
192	        });
193	      }
194	      // NOTE: a plan change deliberately does NOT touch `termPromoPercent`. It does
195	      // not re-base the term — `expiresAt` is untouched and no new months are sold —
196	      // it only moves the customer to a different plan at the rate they already
197	      // bought. Keeping the scalar is exactly what makes upgrade-then-downgrade net
198	      // to zero: both halves read the same stored basis. (This is also why the basis
199	      // is stored as a percent rather than a $/mo figure: a cents rate would have to
200	      // be rewritten here, and that rewrite is one more place to get it wrong.)
201	      //
202	      // Record the amount charged on the job so the worker's RESIZE handler can
203	      // REVERSE it (credit `payload.prorateCents` back to the wallet) if the
204	      // resize terminally fails — money is committed here, before the job runs.
205	      await tx.job.create({
206	        data: { type: "RESIZE", serverId: server.id, payload: { planId: opts.planId, prorateCents, direction: "up" } as any },
207	      });
208	      await tx.auditLog.create({
209	        data: { userId: opts.actorUserId, action: "server.resize", detail: `${server.id} -> ${newPlan.slug} prorate=${prorateCents}` },
210	      });
211	    });
212	  } catch (e) {
213	    if (e instanceof InsufficientBalanceError) throw new ResizeError("Insufficient balance — top up your wallet first.");
214	    throw e;
215	  }
216	}
