399	/**
400	 * The iptables arguments for one validated rule, AFTER `-A <CHAIN>`.
401	 * Every element is a validated primitive; there is no customer free text here.
402	 */
403	export function ruleToArgs(rule: ValidatedRule): string[] {
404	  const args: string[] = ["-s", rule.sourceCidr];
405	  if (rule.protocol !== "ALL") {
406	    args.push("-p", rule.protocol.toLowerCase());
407	  }
408	  if ((rule.protocol === "TCP" || rule.protocol === "UDP") && rule.portFrom !== null && rule.portTo !== null) {
409	    const spec = rule.portFrom === rule.portTo ? String(rule.portFrom) : `${rule.portFrom}:${rule.portTo}`;
410	    args.push("--dport", spec);
411	  }
412	  args.push("-j", rule.action === "ALLOW" ? "ACCEPT" : "DROP");
413	  return args;
414	}
