416	/** True when the customer has expressed at least one ALLOW → whitelist semantics. */
417	export function hasAnyAllow(rules: ValidatedRule[]): boolean {
418	  return rules.some((r) => r.action === "ALLOW");
419	}
420	
421	/**
422	 * Build the idempotent reconcile script for a guest.
423	 *
424	 * Model: a dedicated chain (NXEON_FW) is created once and INPUT is made to jump
425	 * to it exactly once, at the top. On every sync the chain is FLUSHED and rebuilt
426	 * from scratch, so re-running with the same rule set yields the identical kernel
427	 * state (idempotent) and a partial previous run cannot accumulate stale rules.
428	 * Only OUR chain is ever flushed — the customer's own INPUT rules are untouched.
429	 *
430	 * Baseline (always, before any customer rule):
431	 *   - accept loopback
432	 *   - accept ESTABLISHED,RELATED (so existing/return traffic never breaks)
433	 *   - accept tcp/22  ← ANTI-LOCKOUT: SSH stays reachable no matter what the
434	 *     customer configures; a DENY on 22 can therefore never strand them.
435	 *
436	 * Customer rules follow in `position` order; iptables is first-match-wins, so
437	 * that order is the precedence the UI lets them control.
438	 *
439	 * Trailing default: a final DROP is appended ONLY when the customer has at least
440	 * one ALLOW rule (i.e. they have opted into whitelist / security-group
441	 * semantics). With only DENY rules, or none, the chain RETURNs and the packet
442	 * continues through the guest's own INPUT rules — so enabling the feature can
443	 * never silently black-hole a service the customer was already running.
444	 *
445	 * `rules` MUST be pre-validated (worker re-runs `validateRule` on each row).
446	 */
447	export function buildReconcileScript(rules: ValidatedRule[]): string {
448	  const lines: string[] = [];
449	  lines.push("set -o pipefail");
450	  lines.push("IPT=iptables");
451	  lines.push(`CHAIN=${FW_CHAIN}`);
452	  // Create the chain if missing (ignore "exists"), and jump INPUT → CHAIN once,
453	  // inserted at the top so our decisions run before the guest's own rules.
454	  lines.push('"$IPT" -N "$CHAIN" 2>/dev/null || true');
455	  lines.push('"$IPT" -C INPUT -j "$CHAIN" 2>/dev/null || "$IPT" -I INPUT 1 -j "$CHAIN"');
456	  // Rebuild our chain from scratch — the only flush, and only of our chain.
457	  lines.push('"$IPT" -F "$CHAIN"');
458	  lines.push('"$IPT" -A "$CHAIN" -i lo -j ACCEPT');
459	  lines.push('"$IPT" -A "$CHAIN" -m conntrack --ctstate ESTABLISHED,RELATED -j ACCEPT');
460	  for (const p of FW_KEEP_OPEN_TCP_PORTS) {
461	    lines.push(`"$IPT" -A "$CHAIN" -p tcp --dport ${p} -j ACCEPT`);
462	  }
463	  for (const rule of rules) {
464	    lines.push(['"$IPT"', "-A", '"$CHAIN"', ...ruleToArgs(rule)].join(" "));
465	  }
466	  if (hasAnyAllow(rules)) {
467	    lines.push('"$IPT" -A "$CHAIN" -j DROP');
468	  }
469	  return lines.join("\n");
470	}
