472	/**
473	 * Human port/range label for one firewall rule. Lives in this PLAIN module (not the
474	 * "use client" NetworkingControls) so the server-rendered rules table can call it
475	 * directly — calling it from a client module crashed the page for any server that
476	 * actually had a rule to render.
477	 */
478	export function firewallPortLabel(rule: {
479	  protocol: string;
480	  portFrom: number | null;
481	  portTo: number | null;
482	}): string {
483	  if (rule.protocol === "ICMP" || rule.protocol === "ALL") return "—";
484	  if (rule.portFrom == null && rule.portTo == null) return "all";
485	  if (rule.portFrom === rule.portTo) return String(rule.portFrom);
486	  return `${rule.portFrom}–${rule.portTo}`;
487	}
