507	/**
508	 * Usable NVMe VM-disk pool in GB, used as a fallback when the live Proxmox
509	 * storage total can't be read. Unlike RAM we do NOT oversell disk — thin
510	 * provisioning already lets guests share the pool, so we commit against the
511	 * real pool size minus a safety margin.
512	 */
513	export const HOST_DISK_GB = Number(process.env.NXEON_HOST_DISK_GB ?? 800);
514	/** Fraction of usable disk we allow to be committed before refusing deploys. */
515	export const DISK_SAFETY_RATIO = Number(process.env.NXEON_DISK_SAFETY ?? 0.9);
516	/**
517	 * VM disk on ZFS is THIN-provisioned: a guest only consumes what it actually
518	 * writes, not its full nominal plan size. So committing raw plan sizes against
519	 * the pool wildly under-counts real capacity (e.g. four ~2 GB-used guests read
520	 * as 275 GB "committed"). We therefore oversell nominal disk like RAM, and rely
521	 * on the live free-space floor below as the true overflow guard.
522	 */
523	export const DISK_OVERSELL_FACTOR = Number(process.env.NXEON_DISK_OVERSELL ?? 3);
524	/** Refuse deploys once the pool's REAL free space would sit below this (GB). */
525	export const DISK_MIN_FREE_GB = Number(process.env.NXEON_DISK_MIN_FREE_GB ?? 20);
526	
527	/** Effective committable RAM ceiling in MB after reserve + oversell. */
528	export function ramCeilingMB(): number {
529	  return Math.max(0, (HOST_RAM_MB - HOST_RAM_RESERVE_MB) * RAM_OVERSELL_FACTOR);
530	}
531	
532	export type CapacitySnapshot = {
533	  committedRamMB: number;
534	  committedDiskGB: number;
535	  ceilingRamMB: number;
536	  serverCount: number;
537	  /** 0..1 fraction of the RAM ceiling already committed. */
538	  ramUtilization: number;
539	  /** true once committed RAM is within 15% of the ceiling. */
540	  nearCapacity: boolean;
541	};
542	
543	/** Sum committed RAM/disk across all servers that are not being torn down. */
544	export async function capacitySnapshot(): Promise<CapacitySnapshot> {
545	  const servers = await db.server.findMany({
546	    where: { status: { not: "DELETING" } },
547	    select: { extraDiskGB: true, plan: { select: { ramMB: true, diskGB: true } } },
548	  });
549	  const committedRamMB = servers.reduce((sum, s) => sum + s.plan.ramMB, 0);
550	  const committedDiskGB = servers.reduce((sum, s) => sum + effectiveDiskGB(s.plan.diskGB, s.extraDiskGB), 0);
551	  const ceilingRamMB = ramCeilingMB();
552	  const ramUtilization = ceilingRamMB > 0 ? committedRamMB / ceilingRamMB : 1;
553	  return {
554	    committedRamMB,
555	    committedDiskGB,
556	    ceilingRamMB,
557	    serverCount: servers.length,
558	    ramUtilization,
559	    nearCapacity: ramUtilization >= 0.85,
560	  };
561	}
