563	/**
564	 * Pure boundary check, split out of `capacityCheckRamMB` so it can be unit-tested
565	 * with no DB (see test/custom-plan-capacity.test.ts): would adding `addRamMB` to
566	 * what's already committed push past the ceiling?
567	 */
568	export function ramProjectionExceedsCeiling(committedRamMB: number, ceilingRamMB: number, addRamMB: number): boolean {
569	  return committedRamMB + addRamMB > ceilingRamMB;
570	}
571	
572	/**
573	 * Would committing `ramMB` more push committed RAM past the oversell ceiling?
574	 * Returns { ok:false, reason } when the host cannot take it.
575	 *
576	 * Factored out of `capacityCheck` so a caller that doesn't have (or want) a
577	 * `Plan` row — a CUSTOM spec, which by definition doesn't match any catalog
578	 * plan — gets the exact same oversell guard a premade-plan order gets, instead
579	 * of a second, drifting copy of this math. See lib/custom-plan.ts.
580	 */
581	export async function capacityCheckRamMB(ramMB: number): Promise<{ ok: boolean; reason?: string }> {
582	  const snap = await capacitySnapshot();
583	  if (ramProjectionExceedsCeiling(snap.committedRamMB, snap.ceilingRamMB, ramMB)) {
584	    return {
585	      ok: false,
586	      reason:
587	        "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
588	        "Please try a smaller plan or contact support.",
589	    };
590	  }
591	  return { ok: true };
592	}
593	
594	/**
595	 * Would deploying `planId` push committed RAM past the oversell ceiling?
596	 * Returns { ok:false, reason } when the host cannot take the new server.
597	 */
598	export async function capacityCheck(planId: string): Promise<{ ok: boolean; reason?: string }> {
599	  const plan = await db.plan.findUnique({ where: { id: planId }, select: { ramMB: true } });
600	  if (!plan) return { ok: false, reason: "Plan not found." };
601	  return capacityCheckRamMB(plan.ramMB);
602	}
603	
604	/**
605	 * Would committing `addDiskGB` more of VM disk overflow the node's usable
606	 * storage? Mirrors `capacityCheck` but for disk: sums committed plan disk on
607	 * the node and compares against the usable NVMe pool times a safety ratio.
608	 *
609	 * Usable pool size is read live from Proxmox (`storageNvme` status) when the
610	 * node is reachable, falling back to `HOST_DISK_GB`. Pass `nodeId = null` to
611	 * check against all non-deleting servers / the primary node.
612	 */
613	export async function diskCapacityCheck(
614	  nodeId: string | null | undefined,
615	  addDiskGB: number
616	): Promise<{ ok: boolean; reason?: string }> {
617	  const servers = await db.server.findMany({
618	    where: { status: { not: "DELETING" }, ...(nodeId ? { nodeId } : {}) },
619	    select: { extraDiskGB: true, plan: { select: { diskGB: true } } },
620	  });
621	  // Committed disk counts the EFFECTIVE size of every server (plan + purchased
622	  // extra), otherwise expansions would silently oversubscribe the pool.
623	  const committedDiskGB = servers.reduce((sum, s) => sum + effectiveDiskGB(s.plan.diskGB, s.extraDiskGB), 0);
624	
625	  // Resolve usable pool size + REAL usage — prefer the live Proxmox NVMe pool.
626	  let usableGB = HOST_DISK_GB;
627	  let freeGB: number | null = null; // real free space (total − used), when known
628	  try {
629	    const n = nodeId
630	      ? await db.node.findUnique({ where: { id: nodeId } })
631	      : await db.node.findFirst({ where: { isPrimary: true } });
632	    if (n) {
633	      const client = pveFor({
634	        apiUrl: n.apiUrl,
635	        pveNode: n.pveNode,
636	        tokenId: n.tokenId,
637	        tokenSecret: n.tokenSecret,
638	      });
639	      const st = await client.get(`/nodes/${n.pveNode}/storage/${n.storageNvme}/status`);
640	      const totalGB = Number(st?.total ?? 0) / 1024 ** 3;
641	      const usedGB = Number(st?.used ?? 0) / 1024 ** 3;
642	      if (totalGB > 0) usableGB = totalGB;
643	      if (totalGB > 0 && usedGB >= 0) freeGB = Math.max(0, totalGB - usedGB);
644	    }
645	  } catch {
646	    // Proxmox unreachable — fall back to the configured HOST_DISK_GB (no live free).
647	  }
648	
649	  // Guard 1 (the real one): never provision into a genuinely near-full pool.
650	  // Thin guests consume only what they write, so live free space is the true
651	  // constraint — not the sum of nominal plan sizes.
652	  if (freeGB != null && freeGB - addDiskGB < DISK_MIN_FREE_GB) {
653	    return {
654	      ok: false,
655	      reason:
656	        "This node's storage pool is nearly full — we can't safely deploy this plan right now. " +
657	        "Please choose a smaller disk or contact support so we can add capacity.",
658	    };
659	  }
660	
661	  // Guard 2 (backstop): cap nominal thin overcommit so oversell can't run away
662	  // even if the live free-space read is unavailable.
663	  const nominalCeilingGB = usableGB * DISK_SAFETY_RATIO * DISK_OVERSELL_FACTOR;
664	  if (committedDiskGB + addDiskGB > nominalCeilingGB) {
665	    return {
666	      ok: false,
667	      reason:
668	        "Not enough disk headroom on this node to deploy this plan right now. " +
669	        "Please choose a smaller disk or contact support.",
670	    };
671	  }
672	  return { ok: true };
673	}
