675	// Per-node capacity / utilization math for the node-capacity warning feature.
676	//
677	// Plain (non-"use server") module — safe to import from admin server components
678	// (the Compute-nodes and Web-hosting pages render bars off it) AND from the
679	// worker sweep (worker/monitor.ts → nodeCapacitySweep raises/clears NodeAlerts
680	// off it). No mutations here; the alert lifecycle lives in the worker so this
681	// file stays a pure-ish reader other surfaces can share, exactly like the
682	// read-only helpers in lib/monitoring.ts.
683	//
684	// TWO NODE TYPES, ONE MODEL. Nxeon schedules customer VMs onto Proxmox `Node`s
685	// and shared-hosting accounts onto `HostingNode`s. Both fill up and both refuse
686	// new work when they do, so both are reduced to the same shape: a list of
687	// per-DIMENSION utilization percentages (CPU/RAM/DISK for Proxmox, ACCOUNTS/DISK
688	// for hosting) that the thresholds below turn into OK / WARN / CRITICAL.
689	//
690	// ALLOCATION vs REAL USAGE. For each dimension we take the WORSE of two numbers:
691	//   - allocation: what the DB has COMMITTED to the node (sum of every server's
692	//     plan RAM/disk/vCPU, or the account count). This is what makes the NEXT
693	//     provision fail — a node can be 100% committed while barely warm.
694	//   - real usage: what Proxmox actually reports in use right now (RAM/CPU/disk),
695	//     which is what makes a node DEGRADE.
696	// Warning on max(alloc, real) means we fire on whichever ceiling is hit first,
697	// which is the honest "add a node before this bites" signal the feature exists
698	// to give.
699	
700	import { db } from "./db";
701	import { nodeRamUsage, nodeStorageUsage, type NodeRam, type StorageUsage } from "./monitoring";
702	import { effectiveDiskGB } from "./extra-disk";
703	import { getSettingInt } from "./settings";
704	// severityFor/capBarColor/CapSeverity/NodeThresholds live in capacity-severity.ts
705	// (a dependency-free, client-safe module) and are re-exported here unchanged —
706	// see that file's doc comment for why they were split out.
707	import { severityFor, capBarColor, type CapSeverity, type NodeThresholds } from "./capacity-severity";
708	
709	export { severityFor, capBarColor, type CapSeverity, type NodeThresholds };
710	
711	const MB = 1024 * 1024;
712	const GB = 1024 ** 3;
713	
714	export type CapDimension = "CPU" | "RAM" | "DISK" | "ACCOUNTS";
715	export type NodeKind = "PROXMOX" | "HOSTING";
716	
717	export const NODE_CAP_DEFAULT_WARN = 80;
718	export const NODE_CAP_DEFAULT_CRIT = 90;
719	
720	/**
721	 * Hysteresis: an OPEN alert only auto-resolves once utilization falls this many
722	 * points BELOW the WARN threshold. Without the gap a node parked right on the
723	 * line (79 ⇄ 81) would flap open/closed every sweep and bury the operator in
724	 * churn. Env-overridable for tuning without a redeploy.
725	 */
726	export const NODE_CAP_RESOLVE_MARGIN = Number(process.env.NXEON_NODE_ALERT_RESOLVE_MARGIN ?? 5);
727	
728	/**
729	 * A persistent (unchanged-severity) condition re-notifies at most once per this
730	 * many hours — the debounce that stops "node stuck at 92%" emailing ops every
731	 * 10-minute sweep. A NEW alert and a WARN⇄CRITICAL change always notify
732	 * immediately regardless of the cooldown.
733	 */
734	export const NODE_CAP_COOLDOWN_HOURS = Number(process.env.NXEON_NODE_ALERT_COOLDOWN_HOURS ?? 6);
735	
736	/**
737	 * Every server status EXCEPT DELETING still holds committed capacity on its node
738	 * — its VM (and its RAM/disk reservation) exists until the delete completes. This
739	 * matches the exclusion the existing scheduler and infra pages already use
740	 * (`status: { not: "DELETING" }`), so the utilization shown here agrees with what
741	 * scheduleNode commits against.
742	 */
743	const VPS_COMMITTED_EXCLUDE = ["DELETING"] as const;
744	/** Hosting-account statuses that still occupy a slot / quota on their node. */
745	const HOSTING_LIVE_STATUSES = ["PENDING", "PROVISIONING", "ACTIVE", "SUSPENDED"] as const;
746	
747	/**
748	 * Resolve the admin-configured thresholds, clamped so they are always usable:
749	 * both in 1..100, and CRITICAL never below WARN (a CRITICAL under WARN would make
750	 * the amber band unreachable and every warn instantly read critical).
751	 */
752	export async function nodeThresholds(): Promise<NodeThresholds> {
753	  let warnPct = await getSettingInt("node_warn_pct", NODE_CAP_DEFAULT_WARN);
754	  let critPct = await getSettingInt("node_critical_pct", NODE_CAP_DEFAULT_CRIT);
755	  if (!Number.isFinite(warnPct) || warnPct < 1 || warnPct > 100) warnPct = NODE_CAP_DEFAULT_WARN;
756	  if (!Number.isFinite(critPct) || critPct < 1 || critPct > 100) critPct = NODE_CAP_DEFAULT_CRIT;
757	  if (critPct < warnPct) critPct = warnPct;
758	  return { warnPct, critPct };
759	}
760	
761	
762	/** The percent below which an OPEN alert is allowed to auto-resolve. */
763	export function resolveFloor(t: NodeThresholds): number {
764	  return Math.max(0, t.warnPct - NODE_CAP_RESOLVE_MARGIN);
765	}
766	
767	export type DimUtil = {
768	  dimension: CapDimension;
769	  /** The value thresholded — the worse of allocation and real usage. */
770	  pct: number;
771	  /** DB-committed percent (null when the dimension has no allocation basis). */
772	  allocPct: number | null;
773	  /** Live-usage percent from Proxmox (null when unreachable / not applicable). */
774	  realPct: number | null;
775	  /** Short human breakdown, e.g. "48 / 56 GB committed · 61% used". */
776	  detail: string;
777	};
778	
779	export type NodeUtil = {
780	  kind: NodeKind;
781	  id: string;
782	  name: string;
783	  enabled: boolean;
784	  /** For Proxmox: node status endpoint reachable. Hosting is DB-only → always true. */
785	  reachable: boolean;
786	  dims: DimUtil[];
787	  /** Worst dimension percent across `dims` (0 when there are none). */
788	  worstPct: number;
789	  severity: CapSeverity;
790	};
791	
792	function pct(part: number, whole: number): number | null {
793	  if (!(whole > 0)) return null;
794	  return (part / whole) * 100;
795	}
796	
797	/** Combine allocation + real into the thresholded value (worse of the two). */
798	function worse(allocPct: number | null, realPct: number | null): number {
799	  return Math.max(allocPct ?? 0, realPct ?? 0);
800	}
801	
802	function rollup(dims: DimUtil[], t: NodeThresholds): { worstPct: number; severity: CapSeverity } {
803	  const worstPct = dims.reduce((m, d) => Math.max(m, d.pct), 0);
804	  return { worstPct, severity: severityFor(worstPct, t) };
805	}
806	
807	// ---------------------------------------------------------------------------
808	// Proxmox compute nodes
809	// ---------------------------------------------------------------------------
810	
811	/**
812	 * Utilization for every registered Proxmox node.
813	 *
814	 * RAM is always computable (allocation from `Node.capacityRamMB` + the sum of
815	 * each live server's `plan.ramMB`; real usage from the node status endpoint when
816	 * reachable). CPU and DISK need Proxmox to be reachable for their denominator
817	 * (physical thread count / storage pool size), so on an unreachable node they are
818	 * simply omitted rather than guessed — `reachable:false` tells the UI and the
819	 * sweep to treat their absence as "unknown", never as "recovered".
820	 */
821	export async function proxmoxNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
822	  const nodes = await db.node.findMany({
823	    orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }],
824	    include: {
825	      servers: {
826	        where: { status: { notIn: [...VPS_COMMITTED_EXCLUDE] } },
827	        select: {
828	          extraDiskGB: true,
829	          plan: { select: { cpuCores: true, ramMB: true, diskGB: true } },
830	        },
831	      },
832	    },
833	  });
834	
835	  // Real usage, best-effort. Keyed by node NAME — nodeRamUsage/nodeStorageUsage
836	  // label every row with `Node.name` (see lib/monitoring.ts nodeTargets).
837	  let ramRows: NodeRam[] = [];
838	  let storageRows: StorageUsage[] = [];
839	  try {
840	    ramRows = await nodeRamUsage();
841	  } catch {
842	    /* leave empty — every node reads unreachable */
843	  }
844	  try {
845	    storageRows = await nodeStorageUsage();
846	  } catch {
847	    /* leave empty */
848	  }
849	  const ramByNode = new Map(ramRows.map((r) => [r.node, r]));
850	
851	  return nodes.map((n) => {
852	    const committedRamMB = n.servers.reduce((s, sv) => s + sv.plan.ramMB, 0);
853	    const committedDiskGB = n.servers.reduce(
854	      (s, sv) => s + effectiveDiskGB(sv.plan.diskGB, sv.extraDiskGB),
855	      0,
856	    );
857	    const committedVcpu = n.servers.reduce((s, sv) => s + sv.plan.cpuCores, 0);
858	
859	    const real = ramByNode.get(n.name);
860	    const reachable = !!real?.reachable;
861	    // The node's own VM-disk pool (storageNvme) is the disk denominator.
862	    const vmStorage = storageRows.find((s) => s.node === n.name && s.storage === n.storageNvme);
863	
864	    const dims: DimUtil[] = [];
865	
866	    // RAM — allocation always available; real when reachable.
867	    {
868	      const allocPct = pct(committedRamMB, n.capacityRamMB);
869	      const realPct = reachable && real ? real.ratio * 100 : null;
870	      const p = worse(allocPct, realPct);
871	      const parts = [
872	        `${(committedRamMB / 1024).toFixed(0)} / ${(n.capacityRamMB / 1024).toFixed(0)} GB committed`,
873	      ];
874	      if (realPct !== null) parts.push(`${Math.round(realPct)}% used`);
875	      dims.push({ dimension: "RAM", pct: p, allocPct, realPct, detail: parts.join(" · ") });
876	    }
877	
878	    // CPU — real usage is the signal (vCPU is normally overcommitted, so an
879	    // allocation ratio is context, not an alarm). Only present when reachable.
880	    if (reachable && real) {
881	      const realPct = real.cpu * 100;
882	      const allocPct = real.cores > 0 ? (committedVcpu / real.cores) * 100 : null;
883	      const parts = [`${Math.round(realPct)}% used`];
884	      if (allocPct !== null) {
885	        parts.push(`${committedVcpu} vCPU / ${real.cores} threads (${Math.round(allocPct)}% committed)`);
886	      }
887	      // CPU is thresholded on REAL load only; overcommit alloc is informational.
888	      dims.push({ dimension: "CPU", pct: realPct, allocPct, realPct, detail: parts.join(" · ") });
889	    }
890	
891	    // DISK — needs the pool size from Proxmox. Allocation = committed effective
892	    // disk vs pool total; real = pool used vs pool total. Worse of the two.
893	    if (vmStorage?.reachable && vmStorage.total > 0) {
894	      const allocPct = pct(committedDiskGB * GB, vmStorage.total);
895	      const realPct = vmStorage.ratio * 100;
896	      const p = worse(allocPct, realPct);
897	      const parts = [
898	        `${committedDiskGB} GB committed of ${(vmStorage.total / GB).toFixed(0)} GB`,
899	        `${Math.round(realPct)}% used`,
900	      ];
901	      dims.push({ dimension: "DISK", pct: p, allocPct, realPct, detail: parts.join(" · ") });
902	    }
903	
904	    return {
905	      kind: "PROXMOX" as const,
906	      id: n.id,
907	      name: n.name,
908	      enabled: n.enabled,
909	      reachable,
910	      dims,
911	      ...rollup(dims, t),
912	    };
913	  });
914	}
