917	// Shared-hosting nodes
918	// ---------------------------------------------------------------------------
919	
920	/**
921	 * Utilization for every HostingNode. Purely DB-derived (the accounts and their
922	 * quotas live in our own tables), so it is always reachable:
923	 *   - ACCOUNTS: live account count vs `HostingNode.maxAccounts` — the hard
924	 *     scheduler cap; the next account is refused once it's full.
925	 *   - DISK: worse of committed quota (Σ diskQuotaMB) and measured usage
926	 *     (Σ diskUsedMB, filled by hostingUsageSweep) vs `diskTotalGB`.
927	 */
928	export async function hostingNodeUtil(t: NodeThresholds): Promise<NodeUtil[]> {
929	  const nodes = await db.hostingNode.findMany({ orderBy: { name: "asc" } });
930	
931	  return Promise.all(
932	    nodes.map(async (n) => {
933	      const [count, agg] = await Promise.all([
934	        db.hostingAccount.count({
935	          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
936	        }),
937	        db.hostingAccount.aggregate({
938	          where: { hostingNodeId: n.id, status: { in: [...HOSTING_LIVE_STATUSES] } },
939	          _sum: { diskQuotaMB: true, diskUsedMB: true },
940	        }),
941	      ]);
942	
943	      const totalDiskMB = n.diskTotalGB * 1024;
944	      const quotaMB = agg._sum.diskQuotaMB ?? 0;
945	      const usedMB = agg._sum.diskUsedMB ?? 0;
946	
947	      const dims: DimUtil[] = [];
948	
949	      // ACCOUNTS
950	      {
951	        const allocPct = pct(count, n.maxAccounts);
952	        const p = allocPct ?? 0;
953	        dims.push({
954	          dimension: "ACCOUNTS",
955	          pct: p,
956	          allocPct,
957	          realPct: null,
958	          detail: `${count} / ${n.maxAccounts} accounts`,
959	        });
960	      }
961	
962	      // DISK
963	      {
964	        const allocPct = pct(quotaMB, totalDiskMB);
965	        const realPct = pct(usedMB, totalDiskMB);
966	        const p = worse(allocPct, realPct);
967	        const parts = [`${(quotaMB / 1024).toFixed(0)} GB quota of ${n.diskTotalGB} GB`];
968	        if (realPct !== null) parts.push(`${(usedMB / 1024).toFixed(0)} GB used`);
969	        dims.push({ dimension: "DISK", pct: p, allocPct, realPct, detail: parts.join(" · ") });
970	      }
971	
972	      return {
973	        kind: "HOSTING" as const,
974	        id: n.id,
975	        name: n.name,
976	        enabled: n.enabled,
977	        reachable: true,
978	        dims,
979	        ...rollup(dims, t),
980	      };
981	    }),
982	  );
983	}
