985	/** Every node (both kinds) with its utilization, plus the resolved thresholds. */
986	export async function allNodeUtil(): Promise<{ thresholds: NodeThresholds; nodes: NodeUtil[] }> {
987	  const thresholds = await nodeThresholds();
