1028	    }),
1029	  );
1030	  const { critPct } = await nodeThresholds();
1031	  const roomy = loads.filter((l) => l.projectedPct < critPct);
1032	  const pool = roomy.length > 0 ? roomy : loads;
1033	  pool.sort((a, b) => b.free - a.free);
1034	  return pool[0].node;
1035	}
