207	/**
208	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
209	 * well-formed: a half-parsed price would be worse than no price at all, because
210	 * the caller's fallback (re-quote) is at least internally consistent.
211	 */
212	export function parseOrderPrice(raw: unknown): OrderPrice | null {
213	  let obj: unknown = raw;
214	  if (typeof raw === "string") {
215	    try {
216	      obj = JSON.parse(raw);
217	    } catch {
218	      return null;
219	    }
220	  }
221	  if (!obj || typeof obj !== "object") return null;
222	  const { chargeCents, promoPercent, promoName, taxCents, taxRatePercent, taxCountry } =
223	    obj as Record<string, unknown>;
224	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
225	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
226	  if (promoPercent < 0 || promoPercent > 100) return null;
227	  // Tax fields are ADDITIVE and lenient: a session written before Finding 1 (or with a
228	  // malformed tax field) carries none, and the charge path recomputes tax from the
229	  // owner's country — which undertaxes at worst, never overcharges.
230	  const tc = typeof taxCents === "number" && Number.isInteger(taxCents) && taxCents >= 0 ? taxCents : 0;
231	  const tr =
232	    typeof taxRatePercent === "number" && Number.isFinite(taxRatePercent) && taxRatePercent >= 0
233	      ? taxRatePercent
234	      : 0;
235	  return {
236	    chargeCents,
237	    promoPercent,
238	    promoName: typeof promoName === "string" ? promoName : "",
239	    taxCents: tc,
240	    taxRatePercent: tr,
241	    taxCountry: typeof taxCountry === "string" ? taxCountry : "",
242	  };
243	}
