337	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
338	  // real renewal price and this discounted value is the real first-term price.
339	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
340	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
341	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);
342	
343	  // LOW intro price → RENEWS at regular. A per-plan `introPriceCents` (set by an
344	  // admin) makes the FIRST term cheaper and leaves every renewal at the regular
345	  // `priceCents` — renewal code never reads the intro column, so renewal === regular
346	  // by construction (lib/renewal-charge.ts). Modelled as a first-term REDUCTION of
347	  // the regular term total (not a second price), so the regular term stays the one
348	  // basis renewals bill and proration prices against. `introDiscountCents` is 0 for
349	  // every plan without an intro price, so the whole VPS flow below is unchanged for
350	  // them. VPS never carries the first-month-free promo (`firstMonthFreeAppliesTo`),
351	  // so intro and FMF never stack here.
352	  const introMonthlyCents = planIntroMonthlyCents(plan);
353	  const introTermMonths = planIntroTermMonths(plan);
354	  const introDiscountCents = introFirstTermDiscountCents(
355	    plan.priceCents,
356	    introMonthlyCents,
357	    term.months,
358	    introTermMonths,
359	    annualPct,
360	  );
361	  // The plan-portion cash the FIRST term is sold at, intro applied. Renewals ignore it.
362	  const introFirstTermPlanCents = Math.max(0, regularPlanCents - introDiscountCents);
363	  // The rate this first term is sold at (percent off the regular term total) — stamped
364	  // on Server.termPromoPercent below via the promo object so proration/refunds price
365	  // against it exactly like a seasonal promo.
366	  const introPercent = introSoldPercent(regularPlanCents, introDiscountCents);
367	  const introRenewalMonthly = plan.priceCents; // what the "then $X/mo" copy quotes
368	  // When a plan has an intro price we present it THROUGH the same `promo` channel the
369	  // seasonal-sale plumbing uses (name + percent travel on OrderPrice and stamp
370	  // termPromoPercent). `firstMonthFree: false` keeps it out of the one-month-free
371	  // redemption machinery — an intro price has no per-account cap; it is simply this
372	  // plan's first-term price.
373	  const promo =
374	    introDiscountCents > 0
375	      ? {
376	          id: "intro-price",
377	          name: `Intro price — renews at $${(introRenewalMonthly / 100).toFixed(2)}/mo`,
378	          label: "Intro price",
379	          discountPercent: introPercent,
380	          firstMonthFree: false,
381	        }
382	      : currentPromo(new Date());
383	  // The promo is now MANAGED: the owner can switch it off, and every claim is
384	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
385	  // quote shows — and placeOrder charges — the full price, so display === charged
386	  // on the disabled path. When it is on, the quote shows the first-month-free
387	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
388	  // the credit is actually granted (a lost race there is charged full).
389	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
390	  // the card path uses it to re-quote for a customer who has already redeemed
391	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
392	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
393	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
394	  // false here and planFirstTermCents falls through to the regular term total.
395	  const promoEnabled =
396	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
397	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
398	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
399	  // YEARS free. So we subtract one month of the plan's rate from the term total.
400	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
401	  // 36-month term the customer pays the term minus one month. Renewals bill the
402	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
403	  const planFirstTermCents =
404	    promoEnabled && promo.firstMonthFree
405	      ? Math.max(0, regularPlanCents - plan.priceCents)
406	      : regularPlanCents;
407	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
408	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
409	  const promoCreditCents = regularPlanCents - planFirstTermCents;
410	
411	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
412	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
413	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
414	  // so the deploy preview can show it; the redemption itself (count + per-user +
415	  // per-IP guards) is claimed atomically in placeOrder.
416	  let couponId: string | null = null;
417	  let couponDiscountCents = 0;
418	  let couponLabel = "";
419	  let couponError = "";
420	  let couponMaxRedemptions: number | null = null;
421	  let couponFirstTimeOnly = false;
422	  const code = (intent.couponCode ?? "").trim().toUpperCase();
423	  if (code) {
424	    if (!(await getSettingBool("coupons_enabled", true))) {
425	      couponError = "Promo codes are currently disabled.";
426	    } else {
427	      const coupon = await db.coupon.findUnique({ where: { code } });
428	      if (!coupon) {
429	        couponError = "That code isn’t valid.";
430	      } else {
431	        const verdict = couponOrderDiscountCents(
432	          {
433	            kind: coupon.kind,
434	            value: coupon.value,
435	            serviceKind: coupon.serviceKind,
436	            planSlug: coupon.planSlug,
437	            maxTermMonths: coupon.maxTermMonths,
438	            active: coupon.active,
439	            expiresAt: coupon.expiresAt,
440	            maxRedemptions: coupon.maxRedemptions,
441	            timesRedeemed: coupon.timesRedeemed,
442	            minAmountCents: coupon.minAmountCents,
443	          },
444	          {
445	            serviceKind: "VPS",
446	            planSlug: plan.slug,
447	            planMonthlyCents: plan.priceCents,
448	            termMonths: term.months,
449	            // Coupon discounts the intro-reduced plan portion, so an intro price and a
450	            // coupon cannot together drive the plan charge below zero, and a percentage
451	            // coupon is honestly "% off what you actually pay this term".
452	            planChargeCents: introFirstTermPlanCents,
453	          },
454	          new Date(),
455	        );
456	        if (verdict.ok) {
457	          couponId = coupon.id;
458	          couponDiscountCents = verdict.discountCents;
459	          couponLabel = verdict.label;
460	          couponMaxRedemptions = coupon.maxRedemptions;
461	          couponFirstTimeOnly = coupon.firstTimeOnly;
462	        } else {
463	          couponError = verdict.error;
464	        }
465	      }
466	    }
467	  }
468	
469	  const chargeCents = introFirstTermPlanCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
470	  return {
471	    plan,
472	    os,
473	    term,
474	    chargeCents,
475	    // Intro pricing (0 / null on plans without one). `introDiscountCents` is the
476	    // first-term saving already baked into `chargeCents`; `introFirstTermPlanCents`
477	    // is the plan-portion cash the first term is sold at; the monthly figures drive
478	    // the honest "$intro first term, then $regular/mo" copy on the pricing cards.
479	    introDiscountCents,
480	    introFirstTermPlanCents,
481	    introMonthlyCents,
482	    introTermMonths,
483	    introRenewalMonthly,
484	    introPercent,
485	    // The annual-discount rate this quote was priced at — snapshot onto the Server at
486	    // sale (Finding 2) so every later proration reads the SAME basis and a round trip
487	    // nets to zero even if the admin retunes `annual_discount_percent` in between.
488	    annualPct,
489	    promo,
490	    promoCreditCents,
491	    regularPlanCents,
492	    extraDiskGB,
493	    extraDiskMonthlyCents,
494	    extraDiskCents,
495	    backupTier,
496	    backupMonthlyCents,
497	    backupCents,
498	    couponId,
499	    couponDiscountCents,
500	    couponLabel,
501	    couponError,
502	    couponMaxRedemptions,
503	    couponFirstTimeOnly,
504	  };
505	}
