507	/**
508	 * Place an order: validate, charge the wallet (unless a free admin grant),
509	 * create the Server + PROVISION job. Returns the new server id. Does NOT
510	 * redirect. Callers must ensure funds exist (or pass free) — this still
511	 * enforces balance and throws OrderError("Insufficient balance.") otherwise.
512	 *
513	 * `sold` overrides the recomputed price with the one the order was actually SOLD
514	 * at — the card-paid path passes the figure stamped on the Checkout session
515	 * BEFORE the card was charged, so the confirm redirect settles the price the
516	 * customer consented to instead of re-pricing against whatever promo is running
517	 * when they get back (mirrors `chargeCents` in lib/resize.ts applyResize and
518	 * lib/disk-expand.ts applyDiskExpand). The wallet path omits it and pays the
519	 * quote, which it computed moments ago in the same request. See OrderPrice.
520	 */
521	/**
522	 * Claim a checkout coupon in ITS OWN atomic transaction, throwing OrderError on
523	 * any failure so nothing partial survives. Kept separate from the order tx so a
524	 * wallet order can surface the failure before any money moves, and a card order
525	 * (already paid) can swallow it without stranding the paid provision.
526	 *
527	 * Guards, all enforced here: first-time-only (no prior paid server), the
528	 * redemption cap (atomic conditional increment), one-per-account and one-per-IP
529	 * (the two @@unique constraints on CouponRedemption).
530	 */
531	async function claimOrderCoupon(opts: {
532	  couponId: string;
533	  maxRedemptions: number | null;
534	  firstTimeOnly: boolean;
535	  userId: string;
536	  ipHash: string | null;
537	  amountCents: number;
538	}): Promise<void> {
539	  await db.$transaction(async (tx) => {
540	    // Self-heal first: a dead hold from THIS customer's own abandoned card checkout must
541	    // not stand between them and this coupon on a fresh (wallet) order — and its global
542	    // slot is handed back here too. Guarded to expired RESERVED rows (lib/coupon-redemption.ts).
543	    await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
544	    if (opts.firstTimeOnly) {
545	      const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
546	      if (prior > 0) throw new OrderError("This code is for first-time customers only.");
547	    }
548	    // Atomic conditional increment — the only thing between the last free slot and
549	    // an over-redemption when two orders race for it.
550	    const claim = await tx.coupon.updateMany({
551	      where:
552	        opts.maxRedemptions === null
553	          ? { id: opts.couponId, active: true }
554	          : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
555	      data: { timesRedeemed: { increment: 1 } },
556	    });
557	    if (claim.count !== 1) throw new OrderError("That code has just been fully claimed.");
558	    try {
559	      await tx.couponRedemption.create({
560	        data: { couponId: opts.couponId, userId: opts.userId, ipHash: opts.ipHash, amountCents: opts.amountCents, context: "order" },
561	      });
562	    } catch {
563	      // Unique violation on (coupon,user) or (coupon,ipHash): already claimed by
564	      // this person. Throwing rolls back the increment above with it.
565	      throw new OrderError("You’ve already used this code.");
566	    }
567	  });
568	}
