570	/**
571	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
572	 *
573	 * The card leg discounts `cardCents` up front and only settles the redemption
574	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
575	 * paid provision is never stranded. Without this pre-check, a customer who has
576	 * already used a one-per-person code (or isn't first-time) still gets the
577	 * discounted card charge and the swallow hides it. So before we send them to
578	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
579	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
580	 * (a race could still lose the atomic claim at settle time — that path stays
581	 * swallowed by design), but it closes the everyday bypass.
582	 */
583	export async function orderCouponClaimable(opts: {
584	  couponId: string;
585	  firstTimeOnly: boolean;
586	  maxRedemptions: number | null;
587	  userId: string;
588	  ipHash: string | null;
589	}): Promise<{ ok: true } | { ok: false; error: string }> {
590	  if (opts.firstTimeOnly) {
591	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
592	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
593	  }
594	  const byUser = await db.couponRedemption.findUnique({
595	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
596	  });
597	  if (byUser) return { ok: false, error: "You’ve already used this code." };
598	  if (opts.ipHash) {
599	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
600	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
601	  }
602	  if (opts.maxRedemptions !== null) {
603	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
604	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
605	  }
606	  return { ok: true };
607	}
