609	export async function placeOrder(
610	  user: User,
611	  intent: OrderIntent,
612	  sold?: OrderPrice | null,
613	  opts?: {
614	    ipHash?: string | null;
615	    campaign?: string;
616	    promoReservationToken?: string | null;
617	    couponReservationToken?: string | null;
618	  },
619	): Promise<string> {
620	  const quote = await orderQuote(intent);
621	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents } = quote;
622	  // Everything below bills off THESE three, never off `quote.chargeCents` /
623	  // `promo` directly: when a sold price is present it is the whole truth about
624	  // what this order costs and what rate it was sold at.
625	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
626	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
627	  const promoName = sold?.promoName || promo.name;
628	
629	  // Managed first-month-free — how this order settles the credit depends on the path:
630	  //   WALLET path (no `sold`): the credit rides on the fresh quote (promoCreditCents
631	  //     > 0), and we contend for it with an atomic INSERT inside the charge tx below.
632	  //   CARD/Stripe path (`sold` present): the credit was already RESERVED before the
633	  //     card was charged, and its hold token travels in `opts.promoReservationToken`.
634	  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
635	  //     the double-claim race. No token => this order was sold at FULL price, so there
636	  //     is nothing to grant. We deliberately do NOT infer the credit from
637	  //     `sold.promoPercent` (currentPromo always stamps 100, even on a full-price VPS
638	  //     order), which would record a redemption for a purchase that never got one.
639	  const walletPromoApplied = !sold && promoCreditCents > 0;
640	  const cardPromoToken = sold ? opts?.promoReservationToken ?? null : null;
641	  // Note the intro discount on the billing document (first term only; renews full) —
642	  // ONLY when this specific order actually earned the credit (real customer report:
643	  // a full-price $8.88 VPS invoice read "First month free · 100% off first term",
644	  // because `promo.discountPercent` is a raw, ALWAYS-100 constant — see the comment
645	  // above — and this used to gate on that instead of on whether the credit was
646	  // actually granted to THIS order, same signal walletPromoApplied/cardPromoToken
647	  // already use to decide whether to grant it).
648	  const promoNote = walletPromoApplied || cardPromoToken ? ` · ${promoName} ${promoPercent}% off first term` : "";
649	  // The checkout coupon settles the same two ways:
650	  //   WALLET path (no `sold`): atomic claim in its OWN tx below (claimOrderCoupon), which
651	  //     throws and surfaces before any money moves if the last slot just went.
652	  //   CARD/Stripe path (`sold`): the coupon was RESERVED before the card was charged and
653	  //     its hold token travels in `opts.couponReservationToken`. We CONFIRM that hold
654	  //     inside the charge tx (never a fresh contended claim — that would double-count the
655	  //     global cap and collide on the per-person unique). No token => full-price order.
656	  const cardCouponToken = sold ? opts?.couponReservationToken ?? null : null;
657	
658	  const cap = await capacityCheck(plan.id);
659	  if (!cap.ok) throw new OrderError(cap.reason);
660	
661	  let nodeId: string | null = null;
662	  if (intent.nodeId) {
663	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
664	    if (!n) throw new OrderError("Selected location is not available.");
665	    nodeId = n.id;
666	  } else {
667	    const n = await scheduleNode(plan.ramMB);
668	    nodeId = n?.id ?? null;
669	  }
670	
671	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
672	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
673	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
674	
675	  const addons = {
676	    malwareScanner: !!intent.addonMalware,
677	    dailyBackup: !!intent.addonBackup,
678	    docker: !!intent.addonDocker,
679	  };
680	  const isAdmin = user.role === "ADMIN";
681	  const freeRequested = !!intent.free && isAdmin;
682	
683	  // VAT/GST to add to this order (Finding 1). CARD path: settle exactly the tax the
684	  // card leg was split from, carried on `sold` (never re-quoted after the card
685	  // cleared). WALLET path: resolve from the owner's billing country now. The RATE is
686	  // resolved here; the tax cents are recomputed from it inside the charge tx against
687	  // the amount actually debited, so a promo-lost full-price recompute is taxed on the
688	  // real net rather than the discounted one. A free admin grant is never taxed.
689	  let taxRatePercent = 0;
690	  let taxCountry = "";
691	  if (!freeRequested) {
692	    if (sold) {
693	      taxRatePercent = sold.taxRatePercent ?? 0;
694	      taxCountry = sold.taxCountry ?? "";
695	    } else {
696	      const ctx = await taxContextForUser(user);
697	      taxRatePercent = ctx.ratePercent;
698	      taxCountry = ctx.country;
699	    }
700	  }
701	  const orderTaxCents = Math.round((chargeCents * taxRatePercent) / 100);
702	
703	  if (!freeRequested && user.balanceCents < chargeCents + orderTaxCents) throw new OrderError("Insufficient balance.");
704	
705	  // Hard monthly spend cap (Finding 3): refuse a new paid order that would push this
706	  // account past its own cap. No-op unless the customer enabled one. Surfaced as an
707	  // OrderError so the deploy action shows the message verbatim.
708	  if (!freeRequested) {
709	    try {
710	      await assertSpendCap(user, chargeCents + orderTaxCents);
711	    } catch (e) {
712	      if (e instanceof SpendCapError) throw new OrderError(e.message);
713	      throw e;
714	    }
715	  }
716	
717	  // WALLET path ONLY: claim the coupon atomically BEFORE the order tx, so a wallet order
718	  // fails cleanly (no money moved) if the last slot just went. A free admin grant never
719	  // consumes a customer coupon. The CARD path does NOT claim here — it reserved the coupon
720	  // before checkout and CONFIRMS that hold inside the charge tx below (`cardCouponToken`),
721	  // which is what closes the concurrent-checkout bypass the read-then-swallow left open.
722	  if (!freeRequested && !sold && quote.couponId && quote.couponDiscountCents > 0) {
723	    await claimOrderCoupon({
724	      couponId: quote.couponId,
725	      maxRedemptions: quote.couponMaxRedemptions,
726	      firstTimeOnly: quote.couponFirstTimeOnly,
727	      userId: user.id,
728	      ipHash: opts?.ipHash ?? null,
729	      amountCents: quote.couponDiscountCents,
730	    });
731	  }
732	
733	  const newKey = (intent.sshPublicKey ?? "").trim();
734	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
735	
736	  let server;
737	  // Captured from the in-tx invoice.create so the paid ORDER invoice can be emailed
738	  // (with its PDF) AFTER the transaction commits — a rolled-back order leaves this
739	  // null and emails nothing. Only paid orders create an invoice (free admin grants
740	  // skip the `if (!freeRequested)` block below), so this stays null for those.
741	  let orderInvoice: { id: string; number: number; amountCents: number; description: string } | null = null;
742	  try {
743	    server = await db.$transaction(async (tx) => {
744	      // ATOMIC first-month-free claim, INSIDE the charge tx (mirrors claimOrderCoupon).
745	      // Contend for the redemption BEFORE debiting so the debit amount matches the
746	      // outcome. A lost claim never throws — on the wallet path we add the credit
747	      // back and charge FULL; on the card path the money already settled at the sold
748	      // price (screened by the pre-checkout guard in actions.ts), so we keep it and
749	      // record nothing — the same swallow discipline the coupon path uses.
750	      let debitCents = chargeCents;
751	      let promoNoteFinal = promoNote;
752	      let promoClaimId: string | null = null;
753	      let soldFull = false; // wallet order that lost the claim and paid full price
754	      if (!freeRequested && cardPromoToken) {
755	        // CARD/Stripe path: confirm the hold reserved before the card was charged.
756	        // The card already settled at the sold (discounted) price; confirming just
757	        // flips the hold to CONSUMED and anchors it. NEVER a second debit here.
758	        const confirmed = await confirmReservation(tx, cardPromoToken);
759	        if (confirmed) {
760	          promoClaimId = confirmed.id;
761	        } else {
762	          // The hold is gone (released/swept) but the card already paid the discounted
763	          // leg. This is unreachable while the hold outlives the payable session, but
764	          // if it ever happens we must NOT charge more than the customer was shown.
765	          // Try to record the grant so a later renewal can convert it; if even that
766	          // loses (the slot is now another order's), keep the discounted charge and
767	          // log — the same swallow discipline the paid-coupon path uses.
768	          const fallback = await claimFirstMonthFree(tx, {
769	            userId: user.id,
770	            ipHash: opts?.ipHash ?? null,
771	            serviceType: "VPS",
772	            campaign: opts?.campaign ?? "",
773	            chargedCents: chargeCents,
774	          });
775	          if (fallback.claimed) promoClaimId = fallback.id;
776	          else console.error(`[order] first-month-free hold ${cardPromoToken} vanished before confirm for ${user.id}; kept sold price`);
