778	      } else if (!freeRequested && walletPromoApplied) {
779	        // WALLET path: atomic INSERT inside the charge tx. A lost claim means this
780	        // account/IP already redeemed — add the credit back and charge FULL price.
781	        const claim = await claimFirstMonthFree(tx, {
782	          userId: user.id,
783	          ipHash: opts?.ipHash ?? null,
784	          serviceType: "VPS",
785	          campaign: opts?.campaign ?? "",
786	          chargedCents: chargeCents,
787	        });
788	        if (claim.claimed) {
789	          promoClaimId = claim.id;
790	        } else {
791	          debitCents = chargeCents + promoCreditCents; // full price
792	          promoNoteFinal = "";
793	          soldFull = true;
794	        }
795	      }
796	      // CARD/Stripe path: confirm the coupon hold reserved before the card was charged
797	      // (RESERVED→CONSUMED), inside this tx so the discount's slot commits with the
798	      // provision. NEVER a fresh claim — that would re-increment the cap and collide on
799	      // the per-person unique. `sold` already carries the discounted total the customer
800	      // paid, so no debit changes here.
