2	// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
3	// success-redirect route and the webhook. Plain server module (not "use server").
4	//
5	// WHY THIS EXISTS (2026-07-25)
6	// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
7	// whether `creditCheckoutSession()` returned true. That boolean is true only for
8	// the caller that won the race to insert the wallet credit — and the webhook
9	// calls the same function and discards the result. So:
10	//
11	//   * Race: the webhook's insert lands first, the confirm request gets P2002,
12	//     `credited === false`, and the redirect quietly lands on an empty page.
13	//     $249 charged, $249 credited, no server, no error, no notification.
14	//   * Deterministic: the customer closes the tab before `success_url` resolves,
15	//     so the confirm route never runs at all. Same outcome, 100% reproducible.
16	//
17	// Stripe's own guidance is explicit that a browser redirect must not be the
18	// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
19	// its own marker, not a side effect of crediting — decides the single winner.
20	
21	import type Stripe from "stripe";
22	import { db } from "./db";
23	import {
24	  classifyCheckoutSession,
25	  creditCheckoutSession,
26	  retrieveCheckoutSession,
27	  isPurchaseLegSession,
28	  packMetadata,
29	  STRIPE_METADATA_VALUE_MAX,
30	  type CheckoutPurpose,
31	} from "./stripe";
32	import { saveCardFromPaymentSession } from "./stripe-cards";
33	import { placeOrder } from "./order";
34	import { placeGameOrder } from "./game-order";
35	import { placeHostingCardOrder } from "./actions-hosting";
36	import { placeEmailCardOrder } from "./actions-email-hosting";
37	import { placeDomainCardOrder } from "./actions-domains";
38	import { applyResize } from "./resize";
39	import { applyDiskExpand } from "./disk-expand";
40	import { applyDedicatedIpPurchase } from "./dedicated-ip-purchase";
41	import { recordDeployFunnelError } from "./deploy-funnel";
42	import { sendMetaConversion } from "./tracking";
43	import { cookies, headers } from "next/headers";
