45	/**
46	 * Which rail actually moved the money. Stripe is the only one with a real
47	 * Checkout Session (so `saveCardFromPaymentSession` and the Stripe-specific
48	 * ledger label only ever run for it); PayPal and Coinbase Commerce reach this
49	 * same dispatch through `fulfilExternalPayment` below with a SYNTHETIC
50	 * session-shaped object carrying the identical nxeon* metadata keys.
51	 */
52	export type PaymentProvider = "stripe" | "paypal" | "coinbase";
53	
54	export type FulfilResult = {
55	  /** Where the browser should end up. The webhook ignores this. */
56	  redirect: string;
57	  /** True when THIS call performed the fulfilment work. */
58	  fulfilled: boolean;
59	  kind: "order" | "gameOrder" | "hostOrder" | "emailOrder" | "domainOrder" | "resize" | "diskExpand" | "dedicatedIp" | "topup" | "none";
60	  error?: string;
61	};
