63	/**
64	 * Claim exclusive responsibility for fulfilling `sessionId`.
65	 * Returns false when another caller already holds the claim — the UNIQUE index,
66	 * not a read-then-write check, is what makes this safe under concurrency.
67	 */
68	async function claim(sessionId: string, kind: string): Promise<boolean> {
69	  try {
70	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
71	    return true;
72	  } catch (e) {
73	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
74	    throw e;
75	  }
76	}
