78	async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
79	  await db.fulfilledSession
80	    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
81	    .catch(() => {});
