102	/**
103	 * Report a completed order as an ad-conversion, exactly once, on the WINNING fulfil
104	 * call (this only runs where `fulfilled === true`, so no double count under the
105	 * redirect/webhook race). Fires the server-side Meta Conversions API event — best
106	 * effort, inert unless the pixel id + CAPI token are set, and it never throws into
107	 * fulfilment — then returns the redirect tagged with the SAME event_id and the real
108	 * charged amount (`session.amount_total`, what Stripe actually took), so the browser
109	 * pixel (`PurchaseTracker`) can fire and Meta dedupes the pair into ONE conversion.
110	 * READ-ONLY on money: it reports the amount, it never changes a charge.
111	 */
112	async function reportPurchase(
113	  redirect: string,
114	  session: Awaited<ReturnType<typeof retrieveCheckoutSession>>,
115	  email?: string,
116	  userId?: string,
117	  /** Product kind for the per-funnel Google Ads conversion ("vps" | "game"). */
118	  prod?: string,
119	): Promise<string> {
120	  const value = typeof session.amount_total === "number" ? session.amount_total / 100 : 0;
121	  if (!(value > 0)) return redirect; // free / zero-charge order — nothing to report
122	  const currency = (session.currency ?? "usd").toUpperCase();
123	  // Best-effort match signals from the request: the Meta _fbc/_fbp cookies + UA/IP.
124	  // Wrapped so the webhook path (no browser request scope) simply sends without them.
125	  let fbc: string | undefined, fbp: string | undefined, userAgent: string | undefined, clientIp: string | undefined;
126	  try {
127	    const [ck, h] = await Promise.all([cookies(), headers()]);
128	    fbc = ck.get("_fbc")?.value || undefined;
129	    fbp = ck.get("_fbp")?.value || undefined;
130	    userAgent = h.get("user-agent") ?? undefined;
131	    clientIp = (h.get("x-forwarded-for")?.split(",")[0] ?? "").trim() || undefined;
132	  } catch {
133	    /* no request scope (webhook) — send without cookie/UA signals */
134	  }
135	  const { eventId } = await sendMetaConversion({
136	    eventName: "Purchase",
137	    email,
138	    value,
139	    currency,
140	    sourceUrl: redirect,
141	    fbc,
142	    fbp,
143	    userAgent,
144	    clientIp,
145	    externalId: userId,
146	  });
147	  // SERVER-SIDE Google Ads offline conversion for the paid order, using the captured
148	  // gclid — reliable where the browser gtag is not. Best-effort + idempotent (deduped
149	  // on the Stripe session id). Fires the product-specific action (vps/hosting/game/…)
150	  // AND a generic "purchase". Inert until the Ads API creds are configured.
151	  if (userId) {
152	    try {
153	      const { recordAdsConversion } = await import("./google-ads");
154	      const valueCents = Math.round(value * 100);
155	      if (prod) await recordAdsConversion({ kind: prod, userId, dedupeKey: `${prod}:${session.id}`, valueCents, currency });
156	      await recordAdsConversion({ kind: "purchase", userId, dedupeKey: `purchase:${session.id}`, valueCents, currency });
157	    } catch {
158	      /* tracking is best-effort — the order is already fulfilled */
159	    }
160	  }
161	  const params = new URLSearchParams({ purchase: "1", pv: value.toFixed(2), pc: currency, pe: eventId, ...(prod ? { prod } : {}) });
162	  return `${redirect}${redirect.includes("?") ? "&" : "?"}${params.toString()}`;
163	}
