165	/**
166	 * Credit the wallet and fulfil whatever the session was for, exactly once.
167	 * Safe to call repeatedly and concurrently from the redirect and the webhook.
168	 *
169	 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
170	 * defect found on 2026-07-27: this function used to ask three helpers for the
171	 * session, each of which swallowed every error into `null`, so a transient Stripe
172	 * failure was indistinguishable from "no purchase metadata" and fell through to
173	 * the top-up branch below reporting `fulfilled: true`. A real order then had its
174	 * card charged with no server, no FulfilledSession row and no notification — and
175	 * because the webhook returns 200 either way, Stripe never retried it. A throw
176	 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
177	 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
178	 */
179	export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
180	  // ONE retrieve, one view of the session, shared by the credit and the routing.
181	  const session = await retrieveCheckoutSession(sessionId);
182	  const purpose = classifyCheckoutSession(session);
183	  return runFulfilment(session, purpose, base, "stripe");
