610	
611	/**
612	 * Credit the wallet for a paid PayPal/Coinbase Commerce session — the non-Stripe
613	 * analogue of `creditCheckoutSession` (lib/stripe.ts). Deliberately a SEPARATE,
614	 * smaller function rather than a call into that one, for two reasons:
615	 *
616	 *  1. Honesty of the ledger. `creditCheckoutSession` hard-codes the wallet-
617	 *     transaction description as `Stripe payment (${session.id})`. Reusing it for
618	 *     PayPal/Coinbase would label a customer's PayPal or crypto payment as a
619	 *     "Stripe payment" in their own billing history AND in the admin refund
620	 *     tool's ledger search (`lib/actions-admin-billing.ts`'s `description:
621	 *     {contains: "Stripe payment (cs_"}` — that regex's `cs_` prefix requirement
622	 *     means a synthetic `paypal:`/`coinbase:` id would never match it anyway, so
623	 *     nothing is UNSAFE, but the label would still be a plain false statement.
624	 *  2. Every external-payment session reaching this function was created by our
625	 *     own `lib/actions-payment-providers.ts` order/charge-creation actions, which
626	 *     never create one without purchase metadata (order/gameOrder/hostOrder/
627	 *     emailOrder) — there is no "top up your wallet with PayPal/crypto" product.
628	 *     So unlike `creditCheckoutSession`, there is no top-up invoice branch here;
629	 *     `isPurchaseLegSession` is asserted rather than branched on, and a session
630	 *     that somehow fails it is refused loudly rather than silently treated as a
631	 *     top-up (exactly the "unrecognised metadata → top-up" bug `packMetadata`'s
632	 *     doc comment and the `unreadable` classification exist to end — the failure
633	 *     mode this function must never reintroduce from a different code path).
634	 *
635	 * Idempotent the same way: UNIQUE(stripeSessionId) on `WalletTransaction`, so a
636	 * client-driven capture racing the provider's webhook is safe — P2002 means
637	 * someone else already credited this exact session id.
638	 */
639	async function creditExternalPayment(
640	  session: Stripe.Checkout.Session,
641	  provider: Exclude<PaymentProvider, "stripe">,
642	): Promise<boolean> {
643	  const userId = session.metadata?.nxeonUserId;
644	  const cents = session.amount_total ?? 0;
645	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
646	
647	  if (!isPurchaseLegSession(session.metadata)) {
648	    throw new Error(
649	      `${provider} payment ${session.id} carries no recognised purchase metadata — refusing to treat unrecognised money as a top-up`,
650	    );
651	  }
652	
653	  const label = provider === "paypal" ? "PayPal" : "Coinbase Commerce";
654	  try {
655	    await db.$transaction([
656	      db.walletTransaction.create({
657	        data: {
658	          userId,
659	          amountCents: cents,
660	          description: `${label} payment (${session.id})`,
661	          stripeSessionId: session.id,
662	        },
663	      }),
664	      db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
665	      db.notification.create({
666	        data: {
667	          userId,
668	          title: `Payment of $${(cents / 100).toFixed(2)} received`,
669	          href: "/dashboard/billing",
670	        },
671	      }),
672	    ]);
673	  } catch (e) {
674	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
675	    throw e;
676	  }
677	  // Best-effort side effects, same as creditCheckoutSession — never allowed to
678	  // turn a completed credit into a reported failure.
679	  try {
680	    const { maybeRewardReferral } = await import("./actions-growth");
681	    await maybeRewardReferral(userId);
682	  } catch {
683	    /* best-effort */
684	  }
685	  // No generic "Payment received" receipt here: every session this function
686	  // credits is a purchase leg (see this function's doc comment — there is no
687	  // "top up with PayPal/crypto" product), so the order this money is funding
688	  // sends its own specific, itemised invoice_new email moments later. Sending
689	  // both meant a generic, invoice-less "your Nxeon order" receipt landed right
690	  // before the real invoice on every PayPal/Coinbase purchase — the exact
691	  // "this email is weak" duplication already removed from the Stripe path in
692	  // creditCheckoutSession.
693	  return true;
694	}
