696	export type ExternalPaymentInput = {
697	  provider: Exclude<PaymentProvider, "stripe">;
698	  /** PayPal's order id, or Coinbase Commerce's charge code — the provider's own reference. */
699	  externalId: string;
700	  /** The `PendingExternalPayment` row id created when the order/charge was opened
701	   *  (lib/actions-payment-providers.ts) — the ONE place the full order metadata lives. */
702	  pendingId: string;
703	  base?: string;
704	};
705	
706	/**
707	 * Fulfil a PAID PayPal order or Coinbase Commerce charge through the EXACT SAME
708	 * `runFulfilment` dispatch Stripe's `fulfilCheckoutSession` uses — the seam this
709	 * whole module exists to provide. Builds a SYNTHETIC `Stripe.Checkout.Session`-
710	 * shaped object from the `PendingExternalPayment` row (same nxeon* metadata keys,
711	 * `payment_status: "paid"`, the row's own server-computed `amountCents`) and hands
712	 * it to `runFulfilment` with `provider` set so the two Stripe-only steps above are
713	 * skipped. There is exactly ONE dispatch function in this codebase; this is how a
714	 * second payment rail reaches it without a second copy of the claim/settle/
715	 * provision/notify logic.
716	 *
717	 * Callers: the PayPal capture server action (client-driven, like Stripe's confirm
718	 * redirect) AND the PayPal webhook (the reliable backstop) — the SAME
719	 * confirm/webhook race Stripe already runs safely, because the claim below is the
720	 * same `FulfilledSession` UNIQUE(stripeSessionId) index, just keyed
721	 * `"paypal:<orderId>"` instead of a Stripe session id. Coinbase Commerce has no
722	 * client-driven capture step (crypto confirmation only ever arrives by webhook),
723	 * so its webhook is the only caller — still idempotent on its own if Coinbase ever
724	 * redelivers the event.
725	 *
726	 * THROWS if the `PendingExternalPayment` row cannot be found or its stored
727	 * metadata is not valid JSON — the same "throw rather than silently misclassify"
728	 * discipline `retrieveCheckoutSession` and `fulfilCheckoutSession` already apply
729	 * to a Stripe read failure. A row that cannot be trusted must never fall through
730	 * to the top-up branch.
731	 */
732	export async function fulfilExternalPayment(input: ExternalPaymentInput): Promise<FulfilResult> {
733	  const row = await db.pendingExternalPayment.findUnique({ where: { id: input.pendingId } });
734	  if (!row) {
735	    throw new Error(`No PendingExternalPayment row for id ${input.pendingId} (${input.provider} ${input.externalId})`);
736	  }
737	  if (row.provider !== input.provider) {
738	    throw new Error(
739	      `PendingExternalPayment ${input.pendingId} provider mismatch: expected ${input.provider}, stored ${row.provider}`,
740	    );
741	  }
742	
743	  let metadata: Record<string, string>;
744	  try {
745	    const parsed = JSON.parse(row.metadata);
746	    if (!parsed || typeof parsed !== "object") throw new Error("not an object");
747	    metadata = parsed as Record<string, string>;
748	  } catch {
749	    throw new Error(`PendingExternalPayment ${input.pendingId} metadata is not readable JSON`);
750	  }
751	
752	  // The provider-qualified id IS the FulfilledSession/WalletTransaction claim key —
753	  // "paypal:5O190127TN364715T" can never collide with a real Stripe `cs_...` id or
754	  // with the other provider's charge codes.
755	  const sessionId = `${input.provider}:${input.externalId}`;
756	  const synthetic = {
757	    id: sessionId,
758	    metadata,
759	    payment_status: "paid",
760	    amount_total: row.amountCents,
761	    currency: row.currency,
762	    customer: null,
763	    payment_intent: null,
764	  } as unknown as Stripe.Checkout.Session;
765	
766	  const purpose = classifyCheckoutSession(synthetic);
767	
768	  try {
769	    const result = await runFulfilment(synthetic, purpose, input.base ?? "", input.provider);
770	    await db.pendingExternalPayment
771	      .update({ where: { id: row.id }, data: { status: "PAID", providerRef: input.externalId } })
772	      .catch(() => {});
773	    return result;
774	  } catch (e) {
775	    await db.pendingExternalPayment.update({ where: { id: row.id }, data: { status: "FAILED" } }).catch(() => {});
776	    throw e;
777	  }
778	}
