48	/** Compact human age from a millisecond duration. */
49	export function fmtAge(ms: number): string {
50	  if (ms < 0) ms = 0;
51	  const m = Math.floor(ms / 60_000);
52	  if (m < 1) return "just now";
53	  if (m < 60) return `${m}m`;
54	  const h = Math.floor(m / 60);
55	  if (h < 24) return `${h}h`;
56	  const d = Math.floor(h / 24);
57	  return `${d}d ${h % 24}h`;
