188	/**
189	 * Summarise backups across all nodes' `backup` storage. Best-effort: if the
190	 * storage/content endpoint isn't available the node is simply skipped.
191	 */
192	export async function backupSummary(): Promise<BackupSummary> {
193	  const targets = await nodeTargets();
194	  let count = 0;
195	  let newest: number | null = null;
196	  let oldest: number | null = null;
197	  let reachable = false;
198	  for (const t of targets) {
199	    try {
200	      const items: any[] = await t.get(`/nodes/${t.pveNode}/storage/backup/content`, {
201	        content: "backup",
202	      });
203	      reachable = true;
204	      for (const b of items ?? []) {
205	        const ct = Number(b?.ctime ?? 0);
206	        if (!ct) continue;
207	        count++;
208	        if (newest === null || ct > newest) newest = ct;
209	        if (oldest === null || ct < oldest) oldest = ct;
210	      }
211	    } catch {
212	      // storage/content not available on this node — skip
213	    }
214	  }
215	  return { count, newestCtime: newest, oldestCtime: oldest, reachable };
216	}
