263	/**
264	 * Worker liveness inferred from the Job queue:
265	 *  - QUEUED work older than WORKER_STALE_MS that hasn't been picked up ⇒ down
266	 *    (the loop isn't draining the queue).
267	 *  - Jobs stuck RUNNING past STUCK_JOB_MS ⇒ degraded.
268	 *  - Otherwise operational (an empty/fresh queue is healthy, even if idle).
269	 */
270	export async function workerHealth(): Promise<WorkerHealth> {
271	  const now = Date.now();
272	  const [newest, stuckRunning, queuedBacklog, staleQueued] = await Promise.all([
273	    db.job.findFirst({ orderBy: { updatedAt: "desc" }, select: { updatedAt: true } }),
274	    db.job.count({ where: { status: "RUNNING", updatedAt: { lt: new Date(now - STUCK_JOB_MS) } } }),
275	    db.job.count({ where: { status: "QUEUED" } }),
276	    db.job.count({ where: { status: "QUEUED", createdAt: { lt: new Date(now - WORKER_STALE_MS) } } }),
277	  ]);
278	
279	  let status: CompStatus = "operational";
280	  let detail = newest
281	    ? `last job update ${fmtAge(now - newest.updatedAt.getTime())} ago`
282	    : "idle — no jobs processed yet";
283	
284	  if (staleQueued > 0) {
285	    status = "down";
286	    detail = `${staleQueued} job(s) queued but not picked up — worker may be stopped`;
287	  } else if (stuckRunning > 0) {
288	    status = "degraded";
289	    detail = `${stuckRunning} job(s) stuck running > ${Math.round(STUCK_JOB_MS / 60_000)}m`;
290	  }
291	
292	  return {
293	    status,
294	    detail,
295	    newestUpdatedAt: newest?.updatedAt ?? null,
296	    stuckRunning,
297	    queuedBacklog,
298	    staleQueued,
299	  };
300	}
