365	/** Consecutive unhealthy samples before an incident auto-opens. */
366	export const INCIDENT_OPEN_STREAK = Number(process.env.NXEON_INCIDENT_OPEN_STREAK ?? 3);
367	/** Consecutive healthy samples before an auto-incident auto-resolves. */
368	export const INCIDENT_RESOLVE_STREAK = Number(process.env.NXEON_INCIDENT_RESOLVE_STREAK ?? 2);
369	/** HealthSample rows older than this are pruned each sweep (keeps the 90-day window backed). */
370	export const HEALTH_SAMPLE_RETENTION_DAYS = Number(process.env.NXEON_HEALTH_RETENTION_DAYS ?? 95);
371	/** Default uptime / timeline window. */
372	export const UPTIME_WINDOW_MS = Number(process.env.NXEON_UPTIME_WINDOW_MS ?? 90 * 24 * 60 * 60_000);
373	
374	/** Worst-of over a set of statuses (down > degraded > operational). */
375	export function worstStatus(statuses: CompStatus[]): CompStatus {
376	  if (statuses.includes("down")) return "down";
377	  if (statuses.includes("degraded")) return "degraded";
378	  return "operational";
379	}
