381	// ---- Pure math (no DB, injected clock) ----------------------------------
382	
383	/** Minimal shape the pure readers work on — a status stamped at a time. */
384	export type SampleLite = { status: CompStatus; ts: Date | string | number };
385	
386	function tsMs(t: Date | string | number): number {
387	  return t instanceof Date ? t.getTime() : new Date(t).getTime();
388	}
389	
390	export type UptimeResult = {
391	  /** Fraction operational over the window, 0..100. `null` = no samples yet ("collecting data"). */
392	  pct: number | null;
393	  total: number;
394	  up: number;
395	  degraded: number;
396	  down: number;
397	};
398	
399	/**
400	 * Uptime % from samples in `[now - windowMs, now]`. Only `operational` counts as
401	 * up — degraded/down are both downtime. Returns `pct: null` when the window has
402	 * NO samples, so callers say "collecting data" instead of fabricating 100%.
403	 */
404	export function uptimeFromSamples(samples: SampleLite[], now: number, windowMs: number): UptimeResult {
405	  const cutoff = now - windowMs;
406	  let total = 0;
407	  let up = 0;
408	  let degraded = 0;
409	  let down = 0;
410	  for (const s of samples) {
411	    const t = tsMs(s.ts);
412	    if (t < cutoff || t > now) continue;
413	    total++;
414	    if (s.status === "operational") up++;
415	    else if (s.status === "degraded") degraded++;
416	    else down++;
417	  }
418	  return { pct: total === 0 ? null : (up / total) * 100, total, up, degraded, down };
419	}
420	
421	export type TimelineBucket = {
422	  start: number;
423	  end: number;
424	  /** Worst status observed in the bucket, or `null` when no samples landed in it. */
425	  status: CompStatus | null;
426	  total: number;
427	};
428	
429	/**
430	 * Split the window into `bucketCount` equal buckets and reduce each to its WORST
431	 * status (a single degraded reading in a day colours that day amber). Empty
432	 * buckets stay `null` — the strip renders them as "no data", never as green.
433	 */
434	export function bucketTimeline(
435	  samples: SampleLite[],
436	  now: number,
437	  windowMs: number,
438	  bucketCount: number
439	): TimelineBucket[] {
440	  const n = Math.max(1, Math.floor(bucketCount));
441	  const bucketMs = windowMs / n;
442	  const start0 = now - windowMs;
443	  const buckets: TimelineBucket[] = Array.from({ length: n }, (_, i) => ({
444	    start: start0 + i * bucketMs,
445	    end: start0 + (i + 1) * bucketMs,
446	    status: null,
447	    total: 0,
448	  }));
449	  for (const s of samples) {
450	    const t = tsMs(s.ts);
451	    if (t < start0 || t > now) continue;
452	    let idx = Math.floor((t - start0) / bucketMs);
453	    if (idx < 0) idx = 0;
454	    if (idx >= n) idx = n - 1;
455	    const b = buckets[idx];
456	    b.total++;
457	    b.status = b.status === null ? s.status : worstStatus([b.status, s.status]);
458	  }
459	  return buckets;
460	}
