467	/**
468	 * The auto-incident state machine, pure and deterministic.
469	 *
470	 * `recent` is the most-recent-first run of a component's sample statuses (newest
471	 * at index 0). With no open incident, a leading run of >= INCIDENT_OPEN_STREAK
472	 * unhealthy samples opens one (severity = down if the newest is down, else
473	 * degraded). With one open, a leading run of >= INCIDENT_RESOLVE_STREAK healthy
474	 * samples resolves it. Anything else is a no-op — this is called every sweep, so
475	 * it must be idempotent once the streak condition is (un)met.
476	 */
477	export function decideIncident(recent: CompStatus[], hasOpenIncident: boolean): IncidentDecision {
478	  if (recent.length === 0) return { action: "none" };
479	
480	  let unhealthyStreak = 0;
481	  for (const s of recent) {
482	    if (s !== "operational") unhealthyStreak++;
483	    else break;
484	  }
485	  let healthyStreak = 0;
486	  for (const s of recent) {
487	    if (s === "operational") healthyStreak++;
488	    else break;
489	  }
490	
491	  if (!hasOpenIncident) {
492	    if (unhealthyStreak >= INCIDENT_OPEN_STREAK) {
493	      return { action: "open", severity: recent[0] === "down" ? "down" : "degraded" };
494	    }
495	    return { action: "none" };
496	  }
497	  if (healthyStreak >= INCIDENT_RESOLVE_STREAK) return { action: "resolve" };
498	  return { action: "none" };
499	}
