501	/**
502	 * Public-safe copy for an auto-opened incident. Deliberately generic — it names
503	 * the friendly component and the severity, and never embeds the probe's raw
504	 * `detail` (which can carry host:port / upstream error text).
505	 */
506	export function autoIncidentCopy(
507	  component: HealthComponent,
508	  severity: "degraded" | "down"
509	): { title: string; body: string } {
510	  const name = COMPONENT_LABELS[component] ?? component;
511	  const what = severity === "down" ? "a service disruption" : "degraded performance";
512	  return {
513	    title: `${name}: ${SEVERITY_LABEL[severity]}`,
514	    body:
515	      `Our automated monitoring detected ${what} affecting ${name}. Engineers have been ` +
516	      `notified and this incident will update automatically as the component recovers.`,
517	  };
