522	/**
523	 * Persist one HealthSample per component AND advance the auto-incident state
524	 * machine. Called on the worker monitor cadence (see worker/monitor.ts →
525	 * sampleHealthSweep). Cheap and idempotent: 4-row insert, one small read + at
526	 * most one write per component, plus a bounded retention prune.
527	 */
528	export async function sampleHealth(now: Date = new Date()): Promise<void> {
529	  const report = await getHealth();
530	
531	  await db.healthSample.createMany({
532	    data: HEALTH_COMPONENTS.map((c) => ({
533	      component: c,
534	      status: report[c].status,
535	      detail: report[c].detail ? report[c].detail.slice(0, 240) : null,
536	      ts: now,
537	    })),
538	  });
539	
540	  const lookback = Math.max(INCIDENT_OPEN_STREAK, INCIDENT_RESOLVE_STREAK, 1);
541	  for (const c of HEALTH_COMPONENTS) {
542	    const recentRows = await db.healthSample.findMany({
543	      where: { component: c },
544	      orderBy: { ts: "desc" },
545	      take: lookback,
546	      select: { status: true },
547	    });
548	    const recent = recentRows.map((r) => r.status as CompStatus);
549	    const open = await db.statusIncident.findFirst({
550	      where: { component: c, resolvedAt: null, auto: true },
551	      orderBy: { startedAt: "desc" },
552	    });
553	    const decision = decideIncident(recent, !!open);
554	    if (decision.action === "open" && !open) {
555	      const copy = autoIncidentCopy(c, decision.severity);
556	      const incident = await db.statusIncident.create({
557	        data: { component: c, severity: decision.severity, title: copy.title, body: copy.body, auto: true, startedAt: now },
558	      });
559	      await alertIncidentOpened(incident);
560	    } else if (decision.action === "resolve" && open) {
561	      await db.statusIncident.update({ where: { id: open.id }, data: { resolvedAt: now } });
562	      await alertIncidentResolved(open);
563	    }
564	  }
565	
566	  // Retention prune — best-effort, never blocks a sample.
567	  try {
568	    const cutoff = new Date(now.getTime() - HEALTH_SAMPLE_RETENTION_DAYS * 24 * 60 * 60_000);
569	    await db.healthSample.deleteMany({ where: { ts: { lt: cutoff } } });
570	  } catch (e) {
571	    console.error("[monitor] health-sample prune error", e);
572	  }
573	}
