697	
698	export type JobStats = {
699	  windowMs: number;
700	  done: number;
701	  failed: number;
702	  /** Currently QUEUED (live depth, not windowed). */
703	  queued: number;
704	  /** Currently RUNNING (live). */
705	  running: number;
706	  /** failed / (done + failed) over the window, or `null` when nothing settled. */
707	  failureRate: number | null;
708	};
709	
710	/** Queue depth + settled job outcomes over the window, straight from the Job table. */
711	export async function jobStats(
712	  windowMs = 24 * 60 * 60_000,
713	  now: number = Date.now()
714	): Promise<JobStats> {
715	  const since = new Date(now - windowMs);
716	  const [done, failed, queued, running] = await Promise.all([
717	    db.job.count({ where: { status: "DONE", updatedAt: { gte: since } } }),
718	    db.job.count({ where: { status: "FAILED", updatedAt: { gte: since } } }),
719	    db.job.count({ where: { status: "QUEUED" } }),
720	    db.job.count({ where: { status: "RUNNING" } }),
721	  ]);
722	  const settled = done + failed;
723	  return { windowMs, done, failed, queued, running, failureRate: settled === 0 ? null : failed / settled };
724	}
