125	/**
126	 * One reconciliation pass over every node's utilization vs the OPEN NodeAlert
127	 * rows. Safe to call every monitor cadence.
128	 */
129	export async function nodeCapacitySweep(): Promise<void> {
130	  if (SANDBOX) return; // no real nodes to size in the sandbox
131	
132	  const t = await nodeThresholds();
133	
134	  let utils: NodeUtil[];
135	  try {
136	    const [proxmox, hosting] = await Promise.all([proxmoxNodeUtil(t), hostingNodeUtil(t)]);
137	    utils = [...proxmox, ...hosting];
138	  } catch (e) {
139	    console.error("[node-capacity] utilization compute error", e);
140	    return;
141	  }
142	
143	  let open: Array<{
144	    id: string;
145	    nodeKind: string;
146	    nodeId: string;
147	    dimension: string;
148	    severity: string;
149	    lastNotifiedAt: Date | null;
150	  }>;
151	  try {
152	    open = await db.nodeAlert.findMany({
153	      where: { status: "OPEN" },
154	      select: { id: true, nodeKind: true, nodeId: true, dimension: true, severity: true, lastNotifiedAt: true },
155	    });
156	  } catch (e) {
157	    console.error("[node-capacity] could not read open alerts", e);
158	    return;
159	  }
160	  const openByKey = new Map(open.map((a) => [`${a.nodeKind}:${a.nodeId}:${a.dimension}`, a]));
161	
162	  const now = new Date();
163	  const cooldownMs = NODE_CAP_COOLDOWN_HOURS * 60 * 60_000;
164	  const floor = resolveFloor(t);
165	  // Every (kind,id,dimension) we actually evaluated this sweep — so a dimension
166	  // that was merely ABSENT (e.g. Proxmox unreachable, so no CPU/DISK reading) is
167	  // never mistaken for "recovered".
168	  const evaluated = new Set<string>();
169	  const nodeIds = new Set(utils.map((u) => `${u.kind}:${u.id}`));
170	
171	  for (const nu of utils) {
172	    for (const d of nu.dims) {
173	      const key = `${nu.kind}:${nu.id}:${d.dimension}`;
174	      evaluated.add(key);
175	      const sev = severityFor(d.pct, t);
176	      const existing = openByKey.get(key);
177	      const roundedPct = Math.round(d.pct);
178	      const metric = {
179	        allocPct: d.allocPct === null ? null : Math.round(d.allocPct),
180	        realPct: d.realPct === null ? null : Math.round(d.realPct),
181	        warnPct: t.warnPct,
182	        critPct: t.critPct,
183	      };
184	
185	      if (sev === "OK") {
186	        // Auto-resolve, but only once we've dropped a hysteresis margin below WARN.
187	        if (existing && d.pct < floor) {
188	          try {
189	            await db.nodeAlert.update({
190	              where: { id: existing.id },
191	              data: { status: "RESOLVED", pct: roundedPct, detail: d.detail, resolvedAt: now },
192	            });
193	            await notifyNodeCapacity(
194	              `Node capacity cleared: ${nu.name} — ${d.dimension}`,
195	              `${nu.kind === "PROXMOX" ? "Compute node" : "Hosting node"} "${nu.name}" ${d.dimension} ` +
196	                `is back to ${roundedPct}% (below the ${t.warnPct}% warn line). Capacity warning resolved.`,
197	            );
198	          } catch (e) {
199	            console.error(`[node-capacity] resolve failed for ${key}`, e);
200	          }
201	        }
202	        // Between the floor and WARN: leave the alert OPEN (hysteresis) — no-op.
203	        continue;
204	      }
205	
206	      // sev is WARN or CRITICAL.
207	      try {
208	        if (!existing) {
209	          // NEW — always notify.
210	          await db.nodeAlert.create({
211	            data: {
212	              nodeKind: nu.kind,
213	              nodeId: nu.id,
214	              nodeName: nu.name,
215	              dimension: d.dimension,
216	              severity: sev,
217	              pct: roundedPct,
218	              detail: d.detail,
219	              metric,
220	              status: "OPEN",
221	              lastNotifiedAt: now,
222	            },
223	          });
224	          await notifyNodeCapacity(
225	            `Node capacity ${sev}: ${nu.name} — ${d.dimension}`,
226	            dimBody(nu, d, sev, t.warnPct, t.critPct),
227	          );
228	        } else if (existing.severity !== sev) {
229	          // STATE CHANGE (escalation/de-escalation between WARN and CRITICAL) —
230	          // always notify.
231	          await db.nodeAlert.update({
232	            where: { id: existing.id },
233	            data: { severity: sev, pct: roundedPct, detail: d.detail, metric, lastNotifiedAt: now },
234	          });
235	          await notifyNodeCapacity(
236	            `Node capacity ${sev}: ${nu.name} — ${d.dimension}`,
237	            dimBody(nu, d, sev, t.warnPct, t.critPct),
238	          );
239	        } else {
240	          // SAME severity persists — refresh the figure silently, re-notify only
241	          // once the cooldown has elapsed.
242	          const due = !existing.lastNotifiedAt || now.getTime() - existing.lastNotifiedAt.getTime() > cooldownMs;
243	          await db.nodeAlert.update({
244	            where: { id: existing.id },
245	            data: { pct: roundedPct, detail: d.detail, metric, ...(due ? { lastNotifiedAt: now } : {}) },
246	          });
247	          if (due) {
248	            await notifyNodeCapacity(
249	              `Node capacity ${sev}: ${nu.name} — ${d.dimension}`,
250	              dimBody(nu, d, sev, t.warnPct, t.critPct),
251	            );
252	          }
253	        }
254	      } catch (e) {
255	        console.error(`[node-capacity] alert upsert failed for ${key}`, e);
256	      }
257	    }
258	  }
259	
260	  // Close out alerts whose NODE no longer exists at all (deleted / de-registered).
261	  // A dimension that was merely absent this sweep (unreachable Proxmox) is left
262	  // untouched above — we only resolve here when the whole node is gone.
263	  for (const [key, a] of openByKey) {
264	    if (evaluated.has(key)) continue;
265	    if (nodeIds.has(`${a.nodeKind}:${a.nodeId}`)) continue; // node still exists, dim just unobserved
266	    try {
267	      await db.nodeAlert.update({
268	        where: { id: a.id },
269	        data: { status: "RESOLVED", resolvedAt: now, detail: "Node removed — capacity alert closed." },
270	      });
271	    } catch (e) {
272	      console.error(`[node-capacity] stale-node resolve failed for ${key}`, e);
273	    }
274	  }
275	}
