388	/**
389	 * Where the last sweep stopped. The sweep is time-bounded, so on a large fleet it
390	 * may not reach every server; resuming from the cursor rather than always
391	 * restarting at the first row is what stops the tail of the list from being
392	 * silently never metered — a server whose usage always reads 0 because nobody
393	 * ever looked at it is precisely the failure this whole change exists to fix.
394	 */
395	let bwCursor = 0;
396	
397	/**
398	 * Sampling runs INLINE in the worker's strictly serial job loop: every second
399	 * spent here is a second no customer job runs, so the sweep is hard-bounded.
400	 * A Proxmox node that hangs must cost one timeout, not the queue.
401	 */
402	const BW_CALL_TIMEOUT_MS = 8_000;
403	const BW_SWEEP_BUDGET_MS = 45_000;
404	/** RRD back-fill is ~10x the payload of a status read, so cap it per sweep. */
405	const BW_MAX_BACKFILLS_PER_SWEEP = 50;
406	/** Below this a gap is not worth an extra API call. */
407	const BW_BACKFILL_MIN_GAP_MS = 2 * 60_000;
408	/** `timeframe=hour` holds 60 x 60s buckets; beyond that the gap is unrecoverable. */
409	const BW_RRD_WINDOW_MS = 60 * 60_000;
