411	/**
412	 * Bound one Proxmox call. Note this abandons the promise rather than cancelling
413	 * the request (lib/proxmox takes no AbortSignal) — the point is that the sweep
414	 * moves on, not that the socket closes.
415	 */
416	function withTimeout<T>(p: Promise<T>, ms: number, what: string): Promise<T> {
417	  return new Promise<T>((resolve, reject) => {
418	    const timer = setTimeout(
419	      () => reject(new Error(`proxmox call timed out after ${ms}ms: ${what}`)),
420	      ms
421	    );
422	    p.then(
423	      (v) => {
424	        clearTimeout(timer);
425	        resolve(v);
426	      },
427	      (e) => {
428	        clearTimeout(timer);
429	        reject(e);
430	      }
431	    );
432	  });
433	}
