481	        id: true,
482	        hostname: true,
483	        vmid: true,
484	        bwWindowStart: true,
485	        node: { select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true } },
486	      },
487	      orderBy: { id: "asc" }, // stable order, so the cursor below means something
488	    });
