539	        })
540	      : pve;
541	    const pnode = s.node?.pveNode ?? defaultNode;
542	
543	    try {
544	      const cur = await withTimeout(
545	        client.get(`/nodes/${pnode}/qemu/${s.vmid}/status/current`),
546	        BW_CALL_TIMEOUT_MS,
547	        `status/current vm ${s.vmid}`
548	      );
549	      // Our DB says RUNNING but Proxmox is authoritative. A stopped VM reports
550	      // netin/netout 0, and treating that as a counter rollback would be noise.
551	      if (String(cur?.status ?? "") !== "running") {
552	        bwBaselines.delete(key);
553	        continue;
554	      }
555	      const netin = Number(cur?.netin);
556	      const netout = Number(cur?.netout);
557	      if (!Number.isFinite(netin) || !Number.isFinite(netout)) {
558	        // Node too old / unexpected payload: no counters, nothing to meter.
559	        continue;
560	      }
561	      const sample: BwSample = {
562	        netin,
563	        netout,
564	        uptimeSec: Number(cur?.uptime) || 0,
565	        pid: Number.isFinite(Number(cur?.pid)) ? Number(cur.pid) : null,
566	        atMs: Date.now(),
567	      };
568	
569	      const prev = bwBaselines.get(key);
570	      bwBaselines.set(key, sample);
571	      sampled++;
572	
573	      let inBytes = 0;
574	      let outBytes = 0;
575	
576	      if (prev) {
577	        const credit = creditFromCounters(prev, sample);
578	        inBytes = credit.inBytes;
579	        outBytes = credit.outBytes;
580	        if (credit.reason !== "delta") {
581	          // Logged, never silent: each of these means the customer's total is
582	          // missing traffic we could not attribute, and an operator chasing a
583	          // suspiciously low figure needs to see it.
584	          console.warn(
585	            `[bandwidth] ${s.hostname} (vm ${s.vmid}) counter ${credit.reason} — ` +
586	              `credited ${inBytes} in / ${outBytes} out (prev ${prev.netin}/${prev.netout} ` +
587	              `pid ${prev.pid} up ${prev.uptimeSec}s → now ${sample.netin}/${sample.netout} ` +
588	              `pid ${sample.pid} up ${sample.uptimeSec}s)`
589	          );
590	        }
591	      } else if (priorSweepMs !== null) {
592	        // Cold start (worker restarted, or this VM just came up). The counter
593	        // baseline is gone, so recover the interval from RRD rate data instead
594	        // of dropping it — without this, every redeploy silently erases up to a
595	        // sweep interval of every customer's usage.
596	        const gapMs = sweepStartMs - priorSweepMs;
597	        if (gapMs > BW_RRD_WINDOW_MS) {
598	          // Longer than RRD's hour window: part of this gap is unrecoverable.
599	          // Recorded so the UI can admit the period under-reports.
600	          gapDetected = true;
601	        }
602	        if (gapMs >= BW_BACKFILL_MIN_GAP_MS && backfills < BW_MAX_BACKFILLS_PER_SWEEP) {
603	          backfills++;
604	          const filled = await backfillGap(client, pnode, s.vmid, priorSweepMs, sample.atMs);
605	          if (filled) {
606	            inBytes = filled.inBytes;
607	            outBytes = filled.outBytes;
608	            backfilled = true;
609	          }
610	        }
611	      }
612	
613	      const roundedIn = Math.max(0, Math.round(inBytes));
614	      const roundedOut = Math.max(0, Math.round(outBytes));
615	
616	      // The period marker predates metering on every row created before this
617	      // sweep existed (it defaults to the row's creation date), so pull it
618	      // forward to the moment measurement actually began. Without this the UI
619	      // would claim these bytes cover months we never watched.
620	      const needsWindowFix = s.bwWindowStart.getTime() < startedAtMs;
621	      const effectiveWindowMs = Math.max(s.bwWindowStart.getTime(), startedAtMs);
622	      const roll = sample.atMs - effectiveWindowMs >= BW_PERIOD_MS;
623	
624	      if (roundedIn === 0 && roundedOut === 0 && !roll && !needsWindowFix) {
625	        continue; // nothing to record — skip the write entirely
626	      }
627	
628	      if (roll) {
629	        // New period: these bytes belong to the period starting now.
630	        await db.server.update({
631	          where: { id: s.id },
632	          data: {
633	            bwInBytes: BigInt(roundedIn),
634	            bwOutBytes: BigInt(roundedOut),
635	            bwWindowStart: new Date(sample.atMs),
636	          },
637	        });
638	      } else {
639	        await db.server.update({
640	          where: { id: s.id },
641	          data: {
642	            bwInBytes: { increment: BigInt(roundedIn) },
643	            bwOutBytes: { increment: BigInt(roundedOut) },
644	            ...(needsWindowFix ? { bwWindowStart: new Date(startedAtMs) } : {}),
645	          },
646	        });
647	      }
648	    } catch (e) {
649	      console.error(`[bandwidth] sample error for ${s.hostname} (vm ${s.vmid})`, e);
650	    }
651	  }
652	
653	  bwCursor = total > 0 ? (startIdx + visited) % total : 0;
654	
655	  // Drop baselines for VMs no longer in the RUNNING set (deleted, stopped,
656	  // suspended, reinstalled onto a new vmid) so the map stays bounded. Servers
657	  // skipped by the time budget ARE in liveKeys, so their baselines survive.
658	  for (const key of [...bwBaselines.keys()]) {
659	    if (!liveKeys.has(key)) bwBaselines.delete(key);
660	  }
661	
662	  try {
663	    await recordBwSweep({
664	      sweepEndMs: Date.now(),
665	      sampled,
666	      candidates: total,
667	      gapDetected,
668	      backfilled,
669	      hadStartedAt: health.startedAt !== null,
670	    });
671	  } catch (e) {
672	    console.error("[bandwidth] could not record sweep markers", e);
673	  }
674	}
