676	/**
677	 * Recover a metering gap for one VM from RRD rate data.
678	 *
679	 * Returns null (rather than 0) when RRD had nothing usable, so the caller does
680	 * not treat "no data" as "no traffic". Bounded by the same per-call timeout as
681	 * the counter read.
682	 */
683	async function backfillGap(
684	  client: BwClient,
685	  pnode: string,
686	  vmid: number,
687	  fromMs: number,
688	  toMs: number
689	): Promise<{ inBytes: number; outBytes: number } | null> {
690	  try {
691	    const rows = await withTimeout(
692	      client.get(`/nodes/${pnode}/qemu/${vmid}/rrddata`, { timeframe: "hour", cf: "AVERAGE" }),
693	      BW_CALL_TIMEOUT_MS,
694	      `rrddata vm ${vmid}`
695	    );
696	    const filled = integrateRrdBytes(
697	      Array.isArray(rows) ? rows : [],
698	      Math.floor(fromMs / 1000),
699	      Math.floor(toMs / 1000)
700	    );
701	    if (!filled) return null;
702	    return { inBytes: filled.inBytes, outBytes: filled.outBytes };
703	  } catch (e) {
704	    console.error(`[bandwidth] rrd back-fill failed for vm ${vmid}`, e);
705	    return null;
706	  }
707	}
