709	export async function monitorSweep(): Promise<void> {
710	  if (SANDBOX) return; // no real nodes/Proxmox to monitor in the sandbox
711	
712	  // 0. Bandwidth metering. Runs FIRST and inside monitorSweep on purpose:
713	  //    worker/index.ts calls monitorSweep() and then abuseSweep() in the same
714	  //    block, so metering this way guarantees the abuse detector reads counters
715	  //    from this sweep rather than the previous one — and needs no change to the
716	  //    worker loop, which other work owns.
717	  try {
718	    await sampleServerBandwidth();
719	  } catch (e) {
720	    console.error("[bandwidth] sweep error", e);
721	  }
722	  // 1. Node disk usage > threshold
723	  try {
724	    const storage = await nodeStorageUsage();
725	    for (const s of storage) {
726	      if (s.reachable && s.total > 0 && s.ratio > DISK_WARN_RATIO) {
727	        const pct = Math.round(s.ratio * 100);
728	        await notifyAdmins(
729	          `Disk capacity warning — ${s.node}/${s.storage} at ${pct}%`,
730	          `Storage "${s.storage}" on node ${s.node} is ${pct}% full ` +
731	            `(${(s.avail / 1024 ** 3).toFixed(0)} GB free). Free space or add capacity to keep provisioning healthy.`
732	        );
733	      }
734	    }
735	  } catch (e) {
736	    console.error("[monitor] disk check error", e);
737	  }
738	
739	  // 2. Node RAM pressure > threshold
740	  try {
741	    const ram = await nodeRamUsage();
742	    for (const r of ram) {
743	      if (r.reachable && r.total > 0 && r.ratio > RAM_WARN_RATIO) {
744	        const pct = Math.round(r.ratio * 100);
745	        await notifyAdmins(
746	          `Memory pressure — ${r.node} at ${pct}%`,
747	          `Node ${r.node} RAM is ${pct}% used. New deploys may be refused until usage drops.`
748	        );
749	      }
750	    }
751	  } catch (e) {
752	    console.error("[monitor] ram check error", e);
753	  }
754	
755	  // 3. Stuck jobs (RUNNING beyond the stuck threshold)
756	  try {
757	    const stuck = await stuckJobs();
758	    if (stuck.length > 0) {
759	      const mins = Math.round(STUCK_JOB_MS / 60_000);
760	      const lines = stuck
761	        .slice(0, 8)
762	        .map(
763	          (j) =>
764	            `• ${j.type}${j.hostname ? ` (${j.hostname})` : ""} — running ${fmtAge(
765	              Date.now() - j.updatedAt.getTime()
766	            )}`
767	        )
768	        .join("\n");
769	      await notifyAdmins(
770	        `Stuck jobs — ${stuck.length} running > ${mins}m`,
771	        `The worker has job(s) stuck in RUNNING:\n${lines}`
772	      );
773	    }
774	  } catch (e) {
775	    console.error("[monitor] stuck-job check error", e);
776	  }
777	
778	  // 4. Worker liveness + pending-job backlog
779	  try {
780	    const wh = await workerHealth();
781	    if (wh.status === "down") {
782	      await notifyAdmins(
783	        "Worker appears stopped",
784	        wh.detail + ". Check the provisioning worker process."
785	      );
786	    }
787	    if (wh.queuedBacklog >= QUEUE_BACKLOG_ALERT) {
788	      await notifyAdmins(
789	        `Job backlog building — ${wh.queuedBacklog} queued`,
790	        `${wh.queuedBacklog} jobs are waiting in the queue. The worker may be overloaded or slow.`
791	      );
792	    }
793	  } catch (e) {
794	    console.error("[monitor] worker check error", e);
795	  }
796	
797	  // 5. Backup freshness (best-effort; skipped if backup storage isn't listable)
798	  try {
799	    const bk = await backupSummary();
800	    if (bk.reachable && bk.count > 0 && bk.newestCtime !== null) {
801	      const ageMs = Date.now() - bk.newestCtime * 1000;
802	      if (ageMs > BACKUP_STALE_MS) {
803	        await notifyAdmins(
804	          `Backups look stale — newest is ${fmtAge(ageMs)} old`,
805	          `The most recent backup on disk is ${fmtAge(ageMs)} old. Verify the backup schedule is running.`
806	        );
807	      }
808	    }
809	  } catch (e) {
810	    console.error("[monitor] backup check error", e);
811	  }
812	
813	  // 6. Node capacity warnings — per-node utilization (allocation + real usage)
814	  //    vs the admin WARN/CRITICAL thresholds, debounced against OPEN NodeAlert
815	  //    rows so a filling node is surfaced before provisioning fails. Kept LAST so
816	  //    a slow multi-node Proxmox poll can't delay the cheaper checks above.
817	  try {
818	    await nodeCapacitySweep();
819	  } catch (e) {
820	    console.error("[node-capacity] sweep error", e);
821	  }
822	}
