2	import { db } from "./db";
3	import type { Prisma } from "@prisma/client";
4	
5	/**
6	 * IPAM — private-IP and SSH-forward-port allocation.
7	 *
8	 * Node-aware: when a `nodeId` is supplied the pool is taken from that Node's
9	 * configured range (`subnetPrefix` / `ipStart` / `ipEnd` / `sshPortStart` /
10	 * `sshPortEnd`). Without a nodeId we fall back to the global env range, which is
11	 * the single-node behaviour this module has always had.
12	 *
13	 * Race safety: `Server.ipAddress` and `Server.sshPort` are UNIQUE columns, so a
14	 * concurrent double-provision must not hand out the same value twice. When the
15	 * caller passes the server it is allocating for, the "find free + claim" pair
16	 * runs inside a single transaction guarded by a Postgres advisory lock, with a
17	 * retry loop on unique-constraint conflicts. Callers that do not pass a server
18	 * id get a best-effort pick plus a short-lived in-process reservation (which
19	 * covers concurrent jobs inside one worker process, the common case).
20	 */
21	
22	const ENV_SUBNET_PREFIX = process.env.NXEON_SUBNET_PREFIX ?? "10.20.0.";
23	const IP_START = Number(process.env.NXEON_IP_START ?? 100);
24	const IP_END = Number(process.env.NXEON_IP_END ?? 250);
25	export const SSH_PORT_START = Number(process.env.NXEON_SSH_PORT_START ?? 20000);
26	export const SSH_PORT_END = Number(process.env.NXEON_SSH_PORT_END ?? 29999);
27	
28	/** Advisory-lock key that serialises IPAM allocation across processes. */
29	const IPAM_LOCK_KEY = 728_144_301;
30	/** How many times we re-pick after losing a unique-constraint race. */
31	const CLAIM_ATTEMPTS = 8;
32	/** How long an unclaimed hand-out is remembered in this process. */
33	const RESERVATION_TTL_MS = 10 * 60_000;
34	
35	export type IpamRange = {
36	  nodeId: string | null;
37	  subnetPrefix: string;
38	  ipStart: number;
39	  ipEnd: number;
40	  sshPortStart: number;
41	  sshPortEnd: number;
42	  bridge: string | null;
43	  natChain: string | null;
44	};
45	
46	const GLOBAL_RANGE: IpamRange = {
47	  nodeId: null,
48	  subnetPrefix: ENV_SUBNET_PREFIX,
49	  ipStart: IP_START,
50	  ipEnd: IP_END,
51	  sshPortStart: SSH_PORT_START,
52	  sshPortEnd: SSH_PORT_END,
53	  bridge: process.env.NXEON_BRIDGE ?? null,
54	  natChain: process.env.NXEON_NAT_CHAIN ?? null,
55	};
56	
57	const num = (v: unknown, fallback: number) =>
58	  typeof v === "number" && Number.isFinite(v) ? v : fallback;
59	
60	/**
61	 * Resolve the pool a node allocates from. Unknown/empty node fields fall back to
62	 * the global env values so a half-configured Node row can never produce an
63	 * empty range.
64	 */
65	export async function ipamRange(nodeId?: string | null): Promise<IpamRange> {
66	  if (!nodeId) return { ...GLOBAL_RANGE };
67	  const node = await db.node.findUnique({
68	    where: { id: nodeId },
69	    select: {
70	      id: true,
71	      subnetPrefix: true,
72	      ipStart: true,
73	      ipEnd: true,
74	      sshPortStart: true,
75	      sshPortEnd: true,
76	      bridge: true,
77	      natChain: true,
78	    },
79	  });
80	  if (!node) return { ...GLOBAL_RANGE };
81	  const prefix = node.subnetPrefix?.trim() || GLOBAL_RANGE.subnetPrefix;
82	  return {
83	    nodeId: node.id,
84	    subnetPrefix: prefix.endsWith(".") ? prefix : `${prefix}.`,
85	    ipStart: num(node.ipStart, GLOBAL_RANGE.ipStart),
86	    ipEnd: num(node.ipEnd, GLOBAL_RANGE.ipEnd),
87	    sshPortStart: num(node.sshPortStart, GLOBAL_RANGE.sshPortStart),
88	    sshPortEnd: num(node.sshPortEnd, GLOBAL_RANGE.sshPortEnd),
89	    bridge: node.bridge ?? GLOBAL_RANGE.bridge,
90	    natChain: node.natChain ?? GLOBAL_RANGE.natChain,
91	  };
92	}
