94	// ---------- in-process reservations ----------
95	
96	const reservations = new Map<string, number>();
97	
98	function isReserved(key: string): boolean {
99	  const until = reservations.get(key);
100	  if (until === undefined) return false;
101	  if (until <= Date.now()) {
102	    reservations.delete(key);
103	    return false;
104	  }
105	  return true;
106	}
107	
108	function reserve(key: string): void {
109	  if (reservations.size > 5000) {
110	    const now = Date.now();
111	    for (const [k, until] of reservations) if (until <= now) reservations.delete(k);
112	  }
113	  reservations.set(key, Date.now() + RESERVATION_TTL_MS);
114	}
115	
116	function isUniqueConflict(e: any): boolean {
117	  return e?.code === "P2002";
118	}
119	
120	type Tx = Prisma.TransactionClient;
121	
122	/**
123	 * Serialise allocators across processes with a transaction-scoped advisory lock
124	 * (auto-released on commit/rollback). Support is probed once OUTSIDE a
125	 * transaction — a failing statement inside an open Postgres transaction would
126	 * abort it, so we never speculatively try it in the hot path.
127	 */
128	let advisoryLocks: boolean | null = null;
129	// Two workarounds baked in:
130	//  - the key is a literal, not a bound parameter: a bound JS number can reach
131	//    Postgres as `numeric` and fail to resolve the ...(bigint) overload;
132	//  - pg_advisory_xact_lock() returns `void`, which Prisma's $queryRaw cannot
133	//    deserialize, so it is wrapped in a subselect that yields an int column.
134	const LOCK_SQL = `SELECT 1 AS locked FROM (SELECT pg_advisory_xact_lock(${IPAM_LOCK_KEY})) _lock`;
135	
136	async function lockIpam(tx: Tx): Promise<void> {
137	  if (advisoryLocks === false) return;
138	  await tx.$queryRawUnsafe(LOCK_SQL);
139	}
140	
141	async function probeAdvisoryLocks(): Promise<void> {
142	  if (advisoryLocks !== null) return;
143	  try {
144	    // Take and immediately release it (xact locks drop at commit). Done once,
145	    // outside the hot path, because a failing statement inside an open
146	    // transaction would abort that transaction.
147	    await db.$transaction(async (tx) => {
148	      await tx.$queryRawUnsafe(LOCK_SQL);
149	    });
150	    advisoryLocks = true;
151	  } catch {
152	    // Not Postgres, or the role lacks permission: the unique-conflict retry
153	    // loop plus in-process reservations remain as the safety net.
154	    advisoryLocks = false;
155	  }
156	}
