158	// ---------- IP allocation ----------
159	
160	/**
161	 * Candidate IPs are all `<prefix><n>`, so only servers already sitting in the
162	 * same subnet prefix can conflict — servers on other nodes (different prefix)
163	 * are naturally excluded. We still read the column globally because
164	 * `Server.ipAddress` is globally UNIQUE: skipping a value that another node
165	 * happens to hold is what keeps the insert from blowing up.
166	 */
167	async function pickFreeIp(tx: Tx, range: IpamRange): Promise<string> {
168	  const rows = await tx.server.findMany({
169	    where: { ipAddress: { startsWith: range.subnetPrefix } },
170	    select: { ipAddress: true },
171	  });
172	  const used = new Set(rows.map((r) => r.ipAddress!).filter(Boolean));
173	  for (let i = range.ipStart; i <= range.ipEnd; i++) {
174	    const ip = `${range.subnetPrefix}${i}`;
175	    if (used.has(ip)) continue;
176	    if (isReserved(`ip:${ip}`)) continue;
177	    return ip;
178	  }
179	  throw new Error(
180	    range.nodeId
181	      ? `IP pool exhausted for node ${range.nodeId} (${range.subnetPrefix}${range.ipStart}-${range.ipEnd})`
182	      : "IP pool exhausted"
183	  );
184	}
