186	/**
187	 * Allocate a private IP.
188	 *
189	 * @param nodeId          allocate from this Node's configured subnet/range.
190	 * @param claimForServerId when given, the IP is written onto that Server row in
191	 *                         the same transaction, making the allocation atomic.
192	 */
193	export async function allocateIp(
194	  nodeId?: string | null,
195	  claimForServerId?: string | null
196	): Promise<string> {
197	  const range = await ipamRange(nodeId);
198	  await probeAdvisoryLocks();
199	
200	  if (!claimForServerId) {
201	    // No row to claim against: pick + reserve in-process so concurrent jobs in
202	    // this worker cannot be handed the same address.
203	    const ip = await db.$transaction(async (tx) => {
204	      await lockIpam(tx);
205	      return pickFreeIp(tx, range);
206	    });
207	    reserve(`ip:${ip}`);
208	    return ip;
209	  }
210	
211	  let lastErr: unknown;
212	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
213	    let ip = "";
214	    try {
215	      ip = await db.$transaction(async (tx) => {
216	        await lockIpam(tx);
217	        const candidate = await pickFreeIp(tx, range);
218	        await tx.server.update({
219	          where: { id: claimForServerId },
220	          data: { ipAddress: candidate },
221	        });
222	        return candidate;
223	      });
224	    } catch (e) {
225	      lastErr = e;
226	      if (isUniqueConflict(e)) {
227	        // Someone beat us to it between pick and claim — skip it and retry.
228	        continue;
229	      }
230	      throw e;
231	    }
232	    reserve(`ip:${ip}`);
233	    return ip;
234	  }
235	  throw new Error(
236	    `IP allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
237	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
238	  );
239	}
