241	// ---------- SSH forward-port allocation ----------
242	
243	/**
244	 * `Server.sshPort` and `PortForward.publicPort` are both globally UNIQUE, so the
245	 * taken-set is read globally even though the *range* we scan is per-node.
246	 * Node-awareness therefore comes from the range: give each node a disjoint
247	 * sshPortStart/sshPortEnd window and two nodes can never collide.
248	 */
249	async function pickFreePort(tx: Tx, range: IpamRange): Promise<number> {
250	  const [servers, forwards] = await Promise.all([
251	    tx.server.findMany({
252	      where: { sshPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
253	      select: { sshPort: true },
254	    }),
255	    tx.portForward.findMany({
256	      where: { publicPort: { gte: range.sshPortStart, lte: range.sshPortEnd } },
257	      select: { publicPort: true },
258	    }),
259	  ]);
260	  const used = new Set<number>([
261	    ...servers.map((s) => s.sshPort!).filter((p) => p != null),
262	    ...forwards.map((f) => f.publicPort),
263	  ]);
264	  for (let p = range.sshPortStart; p <= range.sshPortEnd; p++) {
265	    if (used.has(p)) continue;
266	    if (isReserved(`port:${p}`)) continue;
267	    return p;
268	  }
269	  throw new Error(
270	    range.nodeId
271	      ? `SSH port pool exhausted for node ${range.nodeId} (${range.sshPortStart}-${range.sshPortEnd})`
272	      : "SSH port pool exhausted"
273	  );
274	}
