276	/**
277	 * Allocate an SSH forward port.
278	 *
279	 * @param nodeId          allocate from this Node's configured port range.
280	 * @param claimForServerId when given, the port is written onto that Server row
281	 *                         in the same transaction, making it atomic.
282	 */
