299	  let lastErr: unknown;
300	  for (let attempt = 0; attempt < CLAIM_ATTEMPTS; attempt++) {
301	    let port = 0;
302	    try {
303	      port = await db.$transaction(async (tx) => {
304	        await lockIpam(tx);
305	        const candidate = await pickFreePort(tx, range);
306	        await tx.server.update({
307	          where: { id: claimForServerId },
