313	      lastErr = e;
314	      if (isUniqueConflict(e)) continue;
315	      throw e;
316	    }
317	    reserve(`port:${port}`);
318	    return port;
319	  }
320	  throw new Error(
321	    `SSH port allocation contended — gave up after ${CLAIM_ATTEMPTS} attempts` +
322	      (lastErr ? `: ${String((lastErr as any)?.message ?? lastErr).slice(0, 160)}` : "")
323	  );
