390	##### lib/nat-rules.ts
391	/**
392	 * Port-forward (DNAT) rule planning, reconciliation and PROOF.
393	 *
394	 * INCIDENT (customer-journey rehearsal 2026-07-26, finding H5): `syncPortForwards`
395	 * opened with an unconditional `iptables -t nat -F NXEON_FWD` and then rebuilt the
396	 * whole chain in a loop with no try/catch, no rollback and no read-back. `exec`
397	 * there is `promisify(execFile)`, so ONE failed `-A` rejected and aborted the
398	 * loop — every server after that point was left with no DNAT rule at all. The job
399	 * still went DONE, because DONE meant "the last `iptables -A` exited 0". The
400	 * result was a fleet-wide SSH blackhole with no notification and a dashboard
401	 * still showing everyone's port. Worse, `remove()` calls the sync AFTER deleting
402	 * the server row, so the throw re-queued DELETE, which then died on "Server not
403	 * found" and never retried the sync.
404	 *
405	 * WHAT MID-FLUSH LOOKS LIKE, and why this module does not flush:
406	 *
407	 *   A flush is an instant, total outage for every customer on the box. Everything
408	 *   between the `-F` and the last successful `-A` is a window in which live SSH
409	 *   sessions keep working (conntrack) but every NEW connection is dropped. If the
410	 *   rebuild dies halfway — a malformed IP, an ENOENT on the iptables binary, the
411	 *   worker being restarted, the DB query returning a partial fleet — the window
412	 *   never closes and nothing notices.
413	 *
414	 *   So there is no flush. We READ the chain, DIFF it against what the database
415	 *   says should be there, and apply only the difference. A rule that is already
416	 *   correct is never removed, so no failure anywhere in this module can take down
417	 *   a customer who was working before it ran. Then we read the chain BACK and
418	 *   compare it to the intent; anything missing is raised loudly with the exact
419	 *   command an operator can run. "The last iptables call exited 0" is not proof
420	 *   that the ruleset is right, and is no longer accepted as such.
421	 *
422	 * Everything here is pure except `reconcileNatChain`, which is driven through the
423	 * `NatHost` seam so test/nat-sync.test.ts can exercise it against an in-memory
424	 * fake chain with no iptables, no root and no network.
425	 */
426	
427	export type NatRule = {
428	  /** "tcp" | "udp" */
429	  proto: string;
430	  /** Public port on the host. */
431	  dport: number;
432	  /** Guest IP the packet is rewritten to. */
433	  destIp: string;
434	  /** Guest port the packet is rewritten to. */
435	  destPort: number;
436	};
437	
438	/** One server's forwarding requirements, as read from the database. */
439	export type ForwardSource = {
440	  serverId: string;
441	  hostname: string;
442	  ipAddress: string | null;
443	  sshPort: number | null;
444	  portForwards: { protocol: string; publicPort: number; guestPort: number }[];
445	};
446	
447	export type NatConflict = { proto: string; dport: number; winner: string; losers: string[] };
448	export type NatRejection = { hostname: string; reason: string };
449	
450	export type NatIntent = {
451	  /** Exactly what the chain should contain, in a stable order. */
452	  rules: NatRule[];
453	  /** Two servers claiming the same public port. The loser's rule is NOT installed. */
454	  conflicts: NatConflict[];
455	  /** Rows we refused to turn into a rule because a field was not a valid IP/port/protocol. */
456	  rejected: NatRejection[];
457	};
458	
459	const IPV4 = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
460	
461	function validPort(n: unknown): n is number {
462	  return typeof n === "number" && Number.isInteger(n) && n >= 1 && n <= 65535;
463	}
464	
465	/**
466	 * Turn the fleet into the exact DNAT ruleset the chain should hold.
467	 *
468	 * Two things this refuses to do quietly:
469	 *
470	 *  1. Install a rule built from a field that is not a valid IPv4 address, port or
471	 *     protocol. `execFile` with an argv array is already injection-safe, but a
472	 *     malformed value produces an iptables error mid-run, which under the old
473	 *     flush-and-rebuild is what aborted the loop and blackholed everyone after
474	 *     it. Rejected rows are reported, not silently skipped.
475	 *  2. Install two rules claiming the same protocol/public port. iptables is
476	 *     first-match, so a duplicate silently sends one customer's traffic to
477	 *     another customer's VM. The first claimant (stable order) wins and the
478	 *     collision is reported so somebody can fix the allocation.
479	 */
480	export function planNatRules(servers: readonly ForwardSource[]): NatIntent {
481	  const rules: NatRule[] = [];
482	  const conflicts: NatConflict[] = [];
483	  const rejected: NatRejection[] = [];
484	  const claimed = new Map<string, { hostname: string; index: number }>();
485	
486	  const claim = (r: NatRule, hostname: string) => {
487	    const key = `${r.proto}/${r.dport}`;
488	    const prior = claimed.get(key);
489	    if (prior) {
490	      const c = conflicts.find((x) => x.proto === r.proto && x.dport === r.dport);
491	      if (c) c.losers.push(hostname);
492	      else conflicts.push({ proto: r.proto, dport: r.dport, winner: prior.hostname, losers: [hostname] });
493	      return;
494	    }
495	    claimed.set(key, { hostname, index: rules.length });
496	    rules.push(r);
497	  };
498	
499	  // Stable order: sorted by hostname, then by public port. iptables is
500	  // first-match on distinct ports so order does not affect behaviour, but a
501	  // deterministic order makes the diff, the logs and the tests readable.
502	  const ordered = [...servers].sort((a, b) => a.hostname.localeCompare(b.hostname));
503	
504	  for (const s of ordered) {
505	    if (!s.ipAddress || !IPV4.test(s.ipAddress)) {
506	      rejected.push({ hostname: s.hostname, reason: `private IP ${JSON.stringify(s.ipAddress)} is not a valid IPv4 address` });
507	      continue;
508	    }
509	    if (!validPort(s.sshPort)) {
510	      rejected.push({ hostname: s.hostname, reason: `SSH port ${JSON.stringify(s.sshPort)} is not a valid port` });
511	    } else {
512	      claim({ proto: "tcp", dport: s.sshPort, destIp: s.ipAddress, destPort: 22 }, s.hostname);
513	    }
514	
515	    for (const f of [...s.portForwards].sort((a, b) => a.publicPort - b.publicPort)) {
516	      const proto = String(f.protocol ?? "").toLowerCase();
517	      if (proto !== "tcp" && proto !== "udp") {
518	        rejected.push({ hostname: s.hostname, reason: `port forward protocol ${JSON.stringify(f.protocol)} is not tcp or udp` });
519	        continue;
520	      }
521	      if (!validPort(f.publicPort) || !validPort(f.guestPort)) {
522	        rejected.push({
523	          hostname: s.hostname,
524	          reason: `port forward ${JSON.stringify(f.publicPort)}->${JSON.stringify(f.guestPort)} has an out-of-range port`,
525	        });
526	        continue;
527	      }
528	      claim({ proto, dport: f.publicPort, destIp: s.ipAddress, destPort: f.guestPort }, s.hostname);
529	    }
530	  }
531	
532	  return { rules, conflicts, rejected };
533	}
534	
535	/** The identity of a rule for set operations — everything that makes it distinct. */
536	export function ruleKey(r: NatRule): string {
537	  return `${r.proto}/${r.dport}->${r.destIp}:${r.destPort}`;
538	}
539	
540	/** Human-readable, and close enough to the real command to paste after `iptables -t nat -A NXEON_FWD`. */
541	export function ruleText(r: NatRule): string {
542	  return `-p ${r.proto} --dport ${r.dport} -j DNAT --to-destination ${r.destIp}:${r.destPort}`;
543	}
544	
545	/** The argv fragment shared by -A, -D and -C. */
546	export function ruleSpec(r: NatRule): string[] {
547	  return [
548	    "-p", r.proto,
549	    "--dport", String(r.dport),
550	    "-j", "DNAT",
551	    "--to-destination", `${r.destIp}:${r.destPort}`,
552	  ];
553	}
554	
555	/**
556	 * Parse `iptables -t nat -S <chain>` back into rules.
557	 *
558	 * iptables normalises what it prints (it inserts `-m tcp`, and reorders some
559	 * options), so the output is NOT byte-comparable to what we passed to `-A`. It is
560	 * parsed rather than string-matched for exactly that reason.
561	 *
562	 * Anything in our chain we cannot parse is returned in `unparsed` and never
563	 * touched. Deleting a rule we do not understand is how you turn "a stray rule
564	 * exists" into "somebody's forwarding is gone", and we do not know enough to be
565	 * making that trade silently.
566	 */
567	export function parseChainRules(chain: string, sOutput: string): { rules: NatRule[]; unparsed: string[] } {
568	  const rules: NatRule[] = [];
569	  const unparsed: string[] = [];
570	  for (const raw of String(sOutput ?? "").split("\n")) {
571	    const line = raw.trim();
572	    if (!line) continue;
573	    if (!line.startsWith(`-A ${chain} `)) continue; // -N, and jumps in other chains
574	    const body = line.slice(`-A ${chain} `.length);
575	    const proto = /(?:^|\s)-p\s+(tcp|udp)(?:\s|$)/.exec(body)?.[1];
576	    const dport = /(?:^|\s)--dport\s+(\d{1,5})(?:\s|$)/.exec(body)?.[1];
577	    const dest = /(?:^|\s)--to-destination\s+(\d{1,3}(?:\.\d{1,3}){3}):(\d{1,5})(?:\s|$)/.exec(body);
578	    const isDnat = /(?:^|\s)-j\s+DNAT(?:\s|$)/.test(body);
579	    if (!proto || !dport || !dest || !isDnat) {
580	      unparsed.push(line);
581	      continue;
582	    }
583	    const r: NatRule = { proto, dport: Number(dport), destIp: dest[1], destPort: Number(dest[2]) };
584	    if (!validPort(r.dport) || !validPort(r.destPort) || !IPV4.test(r.destIp)) {
585	      unparsed.push(line);
586	      continue;
587	    }
588	    rules.push(r);
589	  }
590	  return { rules, unparsed };
591	}
592	
593	export type NatPlan = { toAdd: NatRule[]; toDelete: NatRule[] };
594	
595	/**
596	 * What has to change to turn `actual` into `intended`.
597	 *
598	 * This is the whole point of the rewrite: a rule that is already correct appears
599	 * in neither list, so it is never removed and never re-added. There is no moment
600	 * at which a working customer's forwarding is absent from the kernel.
601	 */
602	export function natReconcilePlan(intended: readonly NatRule[], actual: readonly NatRule[]): NatPlan {
603	  const want = new Map(intended.map((r) => [ruleKey(r), r]));
604	  const have = new Map(actual.map((r) => [ruleKey(r), r]));
605	  const toAdd = [...want.entries()].filter(([k]) => !have.has(k)).map(([, r]) => r);
606	  const toDelete = [...have.entries()].filter(([k]) => !want.has(k)).map(([, r]) => r);
607	  return { toAdd, toDelete };
608	}
609	
610	export type NatVerdict = { ok: boolean; missing: NatRule[]; extra: NatRule[] };
611	
612	/**
613	 * Did the chain end up holding what we intended? Read back from the kernel, not
614	 * inferred from exit codes.
615	 */
616	export function verifyNatChain(intended: readonly NatRule[], actual: readonly NatRule[]): NatVerdict {
617	  const { toAdd: missing, toDelete: extra } = natReconcilePlan(intended, actual);
618	  return { ok: missing.length === 0 && extra.length === 0, missing, extra };
619	}
620	
621	/**
622	 * The failure sentence. Named, exported and tested because the whole defect class
623	 * is "a surface reported an outcome it did not verify" — the remedy is only worth
624	 * anything if what it says is specific enough to act on.
625	 */
626	export function natFailureMessage(opts: {
627	  chain: string;
628	  missing: readonly NatRule[];
629	  extra: readonly NatRule[];
630	  errors: readonly string[];
631	}): string {
632	  const parts: string[] = [];
633	  if (opts.missing.length) {
634	    parts.push(
635	      `${opts.missing.length} port-forward rule(s) are NOT in the ${opts.chain} chain after the sync, ` +
636	        `so that traffic is being dropped: ${opts.missing.slice(0, 8).map(ruleText).join("; ")}` +
637	        (opts.missing.length > 8 ? ` (+${opts.missing.length - 8} more)` : "")
638	    );
639	  }
640	  if (opts.extra.length) {
641	    parts.push(
642	      `${opts.extra.length} rule(s) that should have been removed are still present: ` +
643	        opts.extra.slice(0, 8).map(ruleText).join("; ")
644	    );
645	  }
646	  if (opts.errors.length) parts.push(`iptables reported: ${opts.errors.slice(0, 8).join(" | ")}`);
647	  parts.push(`Inspect the live chain with: iptables -t nat -S ${opts.chain}`);
648	  return parts.join(". ");
649	}
