652	// The seam
653	// ---------------------------------------------------------------------------
654	
655	/**
656	 * Everything `reconcileNatChain` needs from the host, as an interface rather than
657	 * a bare `execFile`.
658	 *
659	 * WHY: this function edits the live NAT table of a production box carrying paying
660	 * customers. Its decision ladder — what to delete, what to add, what counts as
661	 * proof afterwards, what to say when it does not hold — must be exercised
662	 * without touching a kernel, so the only implementation production ever uses
663	 * (`iptablesHost` in worker/network.ts) is matched by an in-memory fake in
664	 * test/nat-sync.test.ts.
665	 */
666	export type NatHost = {
667	  /** Create the chain and the PREROUTING jump if absent. Must be idempotent. */
668	  ensureChain: () => Promise<void>;
669	  /** Raw `iptables -t nat -S <chain>` output. */
670	  listChain: () => Promise<string>;
671	  addRule: (r: NatRule) => Promise<void>;
672	  deleteRule: (r: NatRule) => Promise<void>;
673	};
674	
675	export type NatSyncResult = {
676	  added: number;
677	  deleted: number;
678	  /** Rules the chain is proven to hold. */
679	  verified: number;
680	  conflicts: NatConflict[];
681	  rejected: NatRejection[];
682	  /** Lines in our chain we could not parse; left alone, reported here. */
683	  unparsed: string[];
684	};
685	
686	/**
687	 * Reconcile the chain to `intent` and PROVE the result, or throw saying exactly
688	 * what is broken.
689	 *
690	 * Failure handling is deliberately two-phase. Individual `-A`/`-D` errors are
691	 * COLLECTED rather than thrown, so one bad rule can no longer abandon every
692	 * server after it in the list — that was the H5 blackhole. Then the chain is read
693	 * back and compared to the intent, and only that comparison decides success. A
694	 * rule that failed to add but turns out to be present anyway (a concurrent sync)
695	 * is not an error; a rule that "added fine" but is not in the chain is.
696	 */
697	export async function reconcileNatChain(
698	  host: NatHost,
699	  chain: string,
700	  intent: NatIntent
701	): Promise<NatSyncResult> {
702	  await host.ensureChain();
703	
704	  const current = parseChainRules(chain, await host.listChain());
705	  const plan = natReconcilePlan(intent.rules, current.rules);
706	  const errors: string[] = [];
707	
708	  // Delete first: frees a public port that is being reassigned to another guest
709	  // in the same pass, which would otherwise be an unresolvable conflict.
710	  let deleted = 0;
711	  for (const r of plan.toDelete) {
712	    try {
713	      await host.deleteRule(r);
714	      deleted++;
715	    } catch (e: any) {
716	      errors.push(`delete ${ruleText(r)}: ${String(e?.message ?? e).slice(0, 160)}`);
717	    }
718	  }
719	
720	  let added = 0;
721	  for (const r of plan.toAdd) {
722	    try {
723	      await host.addRule(r);
724	      added++;
725	    } catch (e: any) {
726	      errors.push(`add ${ruleText(r)}: ${String(e?.message ?? e).slice(0, 160)}`);
727	    }
728	  }
729	
730	  // The proof. Not "every call exited 0" — what the kernel actually holds now.
731	  const final = parseChainRules(chain, await host.listChain());
732	  const verdict = verifyNatChain(intent.rules, final.rules);
733	  if (!verdict.ok) {
734	    throw new Error(
735	      natFailureMessage({ chain, missing: verdict.missing, extra: verdict.extra, errors })
736	    );
737	  }
738	  if (errors.length) {
739	    // Every intended rule is present and no stray remains, so forwarding is
740	    // correct — but something errored on the way and that is not nothing.
741	    console.warn(`[nat] ${chain} reconciled, but iptables errored on the way: ${errors.join(" | ")}`);
742	  }
743	
744	  return {
745	    added,
746	    deleted,
747	    verified: final.rules.length,
748	    conflicts: intent.conflicts,
749	    rejected: intent.rejected,
750	    unparsed: final.unparsed,
751	  };
752	}
