754	/**
755	 * Bandwidth metering — the one place that decides (a) how Proxmox's per-VM
756	 * network counters become `Server.bwInBytes` / `bwOutBytes`, and (b) how much
757	 * confidence a usage figure is allowed to project at the customer.
758	 *
759	 * Background: both columns shipped with `@default(0)` and NOTHING ever wrote
760	 * them. Every plan sells a bandwidth allowance, the billing panel was titled
761	 * "Transfer used this cycle … versus plan allowance", and it read a permanent
762	 * `0 B / 20 TB · 0%`. Downstream, `worker/abuse.ts` computed its outbound rate
763	 * from `bwOutBytes` deltas, so `deltaBytes` was always 0 and BANDWIDTH_SPIKE
764	 * could never fire: the platform shipped an abuse detector that could not
765	 * detect anything. This module is the missing signal.
766	 *
767	 * Two hard rules, both of which exist because a *confidently wrong* number is
768	 * worse here than a visibly incomplete one:
769	 *
770	 *  1. Never invent traffic. Proxmox `netin`/`netout` are cumulative per QEMU
771	 *     PROCESS, not per VM lifetime — a stop/start, a hard reset, a reinstall or
772	 *     a live migration replaces the process and the counters restart at 0. A
773	 *     naive `cur - prev` then goes hugely negative, and (when the fresh boot has
774	 *     already pushed more than the stale baseline held) it can just as easily go
775	 *     hugely positive. Either way the delta is fiction, and fiction that feeds
776	 *     an abuse detector can suspend a paying customer. `creditFromCounters`
777	 *     detects the restart and credits only bytes it can prove happened inside
778	 *     the interval.
779	 *  2. Never present a partial period as authoritative. The meter can only know
780	 *     traffic from the moment it started sampling. `bwUsageView` reports the
781	 *     period it actually covers, and refuses to render a percentage at all when
782	 *     no sample has ever been taken — a "0 B / 20 TB · 0%" that means "we never
783	 *     looked" is exactly the defect class this codebase keeps repeating.
784	 *
785	 * Plain module (no "use server"): imported by the worker sweep
786	 * (worker/monitor.ts), by worker/abuse.ts and by the customer billing page.
787	 */
788	
789	import { getSetting, setSetting } from "./settings";
790	
791	// ---------------------------------------------------------------------------
792	// Metering-run markers
793	// ---------------------------------------------------------------------------
794	// These live in the `Setting` KV rather than on Server rows because
795	// prisma/schema.prisma is frozen — and because they are genuinely global: one
796	// sweep meters every VM at once. They are what lets the UI say "measured since"
797	// and "last updated" instead of implying the number is complete.
798	
799	/** First sweep that successfully sampled at least one VM. Null = never metered. */
800	export const BW_STARTED_AT_KEY = "bw_meter_started_at";
801	/**
802	 * END of the most recent sweep that sampled at least one VM.
803	 *
804	 * The end, not the start, and that matters: this timestamp is where an RRD
805	 * back-fill after a worker restart begins counting. Anchored to the sweep start
806	 * it would re-count the traffic of every server the previous sweep sampled after
807	 * that instant — inventing traffic, which is the one thing metering must never
808	 * do. Anchored to the end it can only ever lose a few seconds.
809	 */
810	export const BW_LAST_AT_KEY = "bw_meter_last_at";
811	/** Last time the meter was down longer than it can back-fill (traffic was lost). */
812	export const BW_GAP_AT_KEY = "bw_meter_gap_at";
813	/**
814	 * Last time the meter back-filled a restart gap from RRD. Back-filled bytes land
815	 * in one write but describe up to an hour of traffic, so any rate computed over
816	 * that window is inflated. worker/abuse.ts reads this and sits out the affected
817	 * window rather than raising a spike alert on an accounting artefact.
818	 */
819	export const BW_BACKFILL_AT_KEY = "bw_meter_backfill_at";
820	
821	/**
822	 * Length of a metering period. Plans sell "N TB / month", so the counters roll
823	 * on a 30-day cadence: without a roll the totals grow forever and every server
824	 * eventually renders a bogus "over allowance — overage may apply" warning.
825	 * This is a metering period, NOT the invoice cycle (renewal dates vary per
826	 * server and per term length) — which is why the UI names the actual start date
827	 * instead of the words "this cycle".
828	 */
829	export const BW_PERIOD_DAYS = 30;
830	export const BW_PERIOD_MS = BW_PERIOD_DAYS * 24 * 60 * 60_000;
831	
832	/**
833	 * A sample older than this means the meter is not currently reporting. Generous
834	 * on purpose: sweeps run inline in the worker's strictly serial loop, so a long
835	 * backup or restore can legitimately delay one by tens of minutes. Crossing it
836	 * only changes the wording shown to the customer ("last updated Xh ago"), never
837	 * the number.
838	 */
839	export const BW_STALE_MS = 60 * 60_000;
840	
841	/**
842	 * Absurdity ceiling for a credited delta, in bytes/sec (~20 Gbit/s — well above
843	 * anything this hardware can actually push). Anything faster is a counter
844	 * artefact (process replaced, PVE restarted, vmid reused), not traffic. Set high
845	 * so real abuse is never filtered out: a 200 Mbit/s spammer is 100x under it.
846	 */
847	export const BW_MAX_PLAUSIBLE_BYTES_PER_SEC = 2_500_000_000;
848	
849	/**
850	 * Tolerance when comparing guest uptime against the sample interval. Proxmox
851	 * reports whole seconds and the interval is measured on our clock, so a couple
852	 * of seconds of skew is normal; 90s keeps a slow sweep from being mistaken for
853	 * a VM restart.
854	 */
855	export const BW_UPTIME_SLACK_SEC = 90;
856	
857	// ---------------------------------------------------------------------------
858	// Counter sampling
859	// ---------------------------------------------------------------------------
860	
861	/** The fields we read from `GET /nodes/<node>/qemu/<vmid>/status/current`. */
862	export type BwCounters = {
863	  /** Cumulative inbound bytes for the current QEMU process. */
864	  netin: number;
865	  /** Cumulative outbound bytes for the current QEMU process. */
866	  netout: number;
867	  /** Guest uptime in seconds (0 when not running). */
868	  uptimeSec: number;
869	  /** QEMU pid — changes iff the process was replaced, i.e. the counters reset. */
870	  pid: number | null;
871	};
872	
873	export type BwSample = BwCounters & { atMs: number };
874	
875	export type BwCreditReason =
876	  | "delta" // clean monotonic delta, fully inside the interval
877	  | "vm-restarted" // counters reset mid-interval; credited only post-restart bytes
878	  | "counter-rollback" // counters moved backwards with no restart to explain it
879	  | "implausible"; // delta faster than any real link — counter artefact
880	
881	export type BwCredit = {
882	  inBytes: number;
883	  outBytes: number;
884	  reason: BwCreditReason;
885	};
886	
887	/**
888	 * Bytes to add to a server's cumulative totals, given the previous sample and
889	 * the current one. Pure and total — never throws, never returns a negative.
890	 *
891	 * The whole point of this function is the reset case. A VM stop/start, hard
892	 * reset, reinstall or live migration gives the guest a new QEMU process whose
893	 * `netin`/`netout` start again at 0 (a soft reboot inside the guest does NOT —
894	 * the process survives and the counters keep climbing, which is why `pid` and
895	 * `uptime`, not "did the guest reboot", are the signals used here):
896	 *
897	 *   - `pid` changed, or uptime went backwards, or uptime is shorter than the
898	 *     interval → the reset happened INSIDE this interval, so every byte on the
899	 *     new counter was transferred during the interval. Credit the raw counter.
900	 *     Traffic from before the reset is lost; that under-counts, which is the
901	 *     safe direction. Crediting `cur - prev` here would have been the "hugely
902	 *     positive" fiction.
903	 *   - counters moved backwards but uptime/pid say the process was NOT replaced →
904	 *     our baseline does not describe this VM (vmid reuse, a PVE-side counter
905	 *     reset). Credit nothing and re-baseline; guessing would fabricate traffic.
906	 *   - delta implies a rate no link can carry → counter artefact. Credit nothing.
907	 */
908	export function creditFromCounters(prev: BwSample, cur: BwSample): BwCredit {
909	  const intervalSec = Math.max(0, (cur.atMs - prev.atMs) / 1000);
910	  const zero = { inBytes: 0, outBytes: 0 };
911	
912	  const sane = (v: number) => (Number.isFinite(v) && v >= 0 ? v : 0);
913	  const curIn = sane(cur.netin);
914	  const curOut = sane(cur.netout);
915	  const prevIn = sane(prev.netin);
916	  const prevOut = sane(prev.netout);
917	
918	  const pidChanged =
919	    prev.pid != null && cur.pid != null && prev.pid !== cur.pid;
920	  const uptimeWentBack = cur.uptimeSec > 0 && cur.uptimeSec < prev.uptimeSec;
921	  // Uptime shorter than the gap we are accounting for → it booted inside it.
922	  const bootedInsideInterval =
923	    cur.uptimeSec > 0 && cur.uptimeSec + BW_UPTIME_SLACK_SEC < intervalSec;
924	  const restarted = pidChanged || uptimeWentBack || bootedInsideInterval;
925	  const wentBackwards = curIn < prevIn || curOut < prevOut;
926	
927	  // Physical ceiling for this interval. Applied to every branch: a credit is
928	  // only ever allowed to shrink here, never grow.
929	  const ceiling =
930	    intervalSec > 0 ? intervalSec * BW_MAX_PLAUSIBLE_BYTES_PER_SEC : 0;
931	
932	  if (restarted) {
933	    // Everything on the fresh counter happened inside this interval.
934	    if (ceiling > 0 && (curIn > ceiling || curOut > ceiling)) {
935	      return { ...zero, reason: "implausible" };
936	    }
937	    return { inBytes: curIn, outBytes: curOut, reason: "vm-restarted" };
938	  }
939	
940	  if (wentBackwards) {
941	    return { ...zero, reason: "counter-rollback" };
942	  }
943	
944	  const inBytes = curIn - prevIn;
945	  const outBytes = curOut - prevOut;
946	  if (ceiling > 0 && (inBytes > ceiling || outBytes > ceiling)) {
947	    return { ...zero, reason: "implausible" };
948	  }
949	  return { inBytes, outBytes, reason: "delta" };
950	}
951	
952	/**
953	 * Integrate a Proxmox RRD series into bytes over `(fromSec, toSec]`.
954	 *
955	 * Used only to back-fill the gap left by a worker restart: the counter baseline
956	 * lives in worker memory, so without this every restart silently drops up to a
957	 * full sweep interval of traffic for every server — on a platform that redeploys
958	 * several times a day that is a systematic multi-percent under-count of a figure
959	 * customers are held to.
960	 *
961	 * `netin`/`netout` in rrddata are AVERAGE BYTES PER SECOND for each bucket, so
962	 * bytes = rate x bucket length. Only buckets that closed inside the window are
963	 * counted: the newest bucket is still filling, and counting it would double-count
964	 * against the counter delta the next sweep takes. Returns null when no bucket
965	 * qualified, so callers can tell "no data" from "genuinely zero".
966	 */
967	export function integrateRrdBytes(
968	  rows: Array<Record<string, unknown>>,
969	  fromSec: number,
970	  toSec: number
971	): { inBytes: number; outBytes: number; buckets: number } | null {
972	  if (!Array.isArray(rows) || rows.length === 0) return null;
973	  const times = rows.map((r) => Number(r?.time));
974	  let inBytes = 0;
975	  let outBytes = 0;
976	  let buckets = 0;
977	
978	  for (let i = 0; i < rows.length; i++) {
979	    const t = times[i];
980	    if (!Number.isFinite(t)) continue;
981	    const next = times[i + 1];
982	    // Bucket length from the series itself; the API's step can change with the
983	    // timeframe, so never hard-code 60s.
984	    const step = Number.isFinite(next) && next > t ? next - t : 60;
985	    if (step <= 0 || step > 3600) continue;
986	    if (t < fromSec) continue; // before the gap we are filling
987	    if (t + step > toSec) continue; // still filling, or past the gap
988	
989	    const ri = Number(rows[i]?.netin);
990	    const ro = Number(rows[i]?.netout);
991	    // RRD emits null/undefined for steps it has no data for (including the step
992	    // a counter reset landed in). Skipping them under-counts; inventing a value
993	    // would not.
994	    if (Number.isFinite(ri) && ri >= 0) inBytes += ri * step;
995	    if (Number.isFinite(ro) && ro >= 0) outBytes += ro * step;
996	    buckets++;
997	  }
998	
999	  if (buckets === 0) return null;
1000	  return { inBytes, outBytes, buckets };
1001	}
