1003	// ---------------------------------------------------------------------------
1004	// Meter health (read by the worker and by the customer UI)
1005	// ---------------------------------------------------------------------------
1006	
1007	export type BwMeterHealth = {
1008	  /** When metering first ran. Null = never — show no usage figure at all. */
1009	  startedAt: Date | null;
1010	  /** Start of the most recent sweep. */
1011	  lastAt: Date | null;
1012	  /** Last unrecoverable metering outage (traffic in that gap is uncounted). */
1013	  gapAt: Date | null;
1014	  /** Last RRD back-fill — rates spanning it are inflated, see the key's doc. */
1015	  backfillAt: Date | null;
1016	  /** A sample landed within BW_STALE_MS. */
1017	  live: boolean;
1018	  /** Age of `lastAt`, or null if never metered. */
1019	  ageMs: number | null;
1020	};
1021	
1022	function parseDate(raw: string): Date | null {
1023	  if (!raw) return null;
1024	  const d = new Date(raw);
1025	  return Number.isNaN(d.getTime()) ? null : d;
1026	}
1027	
1028	/** Read the metering markers. One query per key; all four are tiny strings. */
1029	export async function readBwMeterHealth(now = Date.now()): Promise<BwMeterHealth> {
1030	  const [started, last, gap, backfill] = await Promise.all([
1031	    getSetting(BW_STARTED_AT_KEY, ""),
1032	    getSetting(BW_LAST_AT_KEY, ""),
1033	    getSetting(BW_GAP_AT_KEY, ""),
1034	    getSetting(BW_BACKFILL_AT_KEY, ""),
1035	  ]);
1036	  const startedAt = parseDate(started);
1037	  const lastAt = parseDate(last);
1038	  const ageMs = lastAt ? Math.max(0, now - lastAt.getTime()) : null;
1039	  return {
1040	    startedAt,
1041	    lastAt,
1042	    gapAt: parseDate(gap),
1043	    backfillAt: parseDate(backfill),
1044	    live: ageMs !== null && ageMs <= BW_STALE_MS,
1045	    ageMs,
1046	  };
1047	}
1048	
1049	/**
1050	 * Record that a sweep ran. `startedAt` is written once, on the first sweep that
1051	 * actually sampled something — it is the honest lower bound on "we have been
1052	 * measuring since", because traffic before the first baseline was never seen.
1053	 */
1054	export async function recordBwSweep(opts: {
1055	  /** When sampling FINISHED — see BW_LAST_AT_KEY for why the end and not the start. */
1056	  sweepEndMs: number;
1057	  /** VMs successfully sampled. */
1058	  sampled: number;
1059	  /** RUNNING VMs the sweep tried to sample. */
1060	  candidates: number;
1061	  gapDetected: boolean;
1062	  backfilled: boolean;
1063	  hadStartedAt: boolean;
1064	}): Promise<void> {
1065	  // Tried and got nothing (every node unreachable) → do NOT advance the markers.
1066	  // The customer is then told the meter is behind, which is the truth. Nothing to
1067	  // sample at all (no running VMs) still counts as a healthy sweep.
1068	  if (opts.sampled === 0 && opts.candidates > 0) return;
1069	  const at = new Date(opts.sweepEndMs).toISOString();
1070	  if (!opts.hadStartedAt) await setSetting(BW_STARTED_AT_KEY, at);
1071	  await setSetting(BW_LAST_AT_KEY, at);
1072	  if (opts.gapDetected) await setSetting(BW_GAP_AT_KEY, at);
1073	  if (opts.backfilled) await setSetting(BW_BACKFILL_AT_KEY, at);
1074	}
1075	
1076	// ---------------------------------------------------------------------------
1077	// Customer-facing view
1078	// ---------------------------------------------------------------------------
1079	
1080	/** Just enough of a Server row to describe its metered usage. */
1081	export type BwServerRow = {
1082	  status: string;
1083	  bwInBytes: bigint | number;
1084	  bwOutBytes: bigint | number;
1085	  bwWindowStart: Date;
1086	};
1087	
1088	export type BwUsageView = {
1089	  /**
1090	   * False = we have never metered this server, so there is no figure to show.
1091	   * Callers MUST render an explicit "not measured yet" state rather than the
1092	   * zero — that zero is what made the panel read "0 B / 20 TB · 0%" forever.
1093	   */
1094	  measured: boolean;
1095	  usedBytes: number;
1096	  allowanceBytes: number;
1097	  /** Percent of allowance, or null when `measured` is false. */
1098	  pct: number | null;
1099	  /** Start of the span these bytes actually cover. */
1100	  measuredFrom: Date | null;
1101	  coveredMs: number;
1102	  /** Covered span is shorter than a full period — the total WILL grow. */
1103	  partial: boolean;
1104	  /** Fraction of a full period covered (0..1). */
1105	  coverage: number;
1106	  /** The meter was down long enough inside this window to have lost traffic. */
1107	  hasGap: boolean;
1108	  /** Nothing accrues right now (VM not running / metering stale). */
1109	  accruing: boolean;
1110	};
1111	
1112	/**
1113	 * Turn a Server row plus meter health into something honest to render.
1114	 *
1115	 * `measuredFrom` is `max(bwWindowStart, meter startedAt)`: rows that existed
1116	 * before metering did have `bwWindowStart` defaulted to their creation date, and
1117	 * presenting their counters as covering that whole span would claim months of
1118	 * measurement we never performed.
1119	 */
1120	export function bwUsageView(
1121	  server: BwServerRow,
1122	  allowanceBytes: number,
1123	  health: BwMeterHealth,
1124	  now = new Date()
1125	): BwUsageView {
1126	  const usedBytes = Number(server.bwInBytes) + Number(server.bwOutBytes);
1127	  const measured = health.startedAt !== null;
1128	
1129	  const windowStart = server.bwWindowStart;
1130	  const measuredFrom = !measured
1131	    ? null
1132	    : windowStart.getTime() > health.startedAt!.getTime()
1133	      ? windowStart
1134	      : health.startedAt!;
1135	
1136	  const coveredMs = measuredFrom
1137	    ? Math.max(0, now.getTime() - measuredFrom.getTime())
1138	    : 0;
1139	  const coverage = Math.min(1, coveredMs / BW_PERIOD_MS);
1140	
1141	  return {
1142	    measured,
1143	    usedBytes: measured ? usedBytes : 0,
1144	    allowanceBytes,
1145	    pct:
1146	      measured && allowanceBytes > 0 ? (usedBytes / allowanceBytes) * 100 : null,
1147	    measuredFrom,
1148	    coveredMs,
1149	    // 99% counts as complete: the roll happens on the next sweep after the
1150	    // period ends, so demanding an exact 30 days would flag every full period
1151	    // as partial for the few minutes before it rolls.
1152	    partial: coverage < 0.99,
1153	    coverage,
1154	    hasGap:
1155	      measured &&
1156	      health.gapAt !== null &&
1157	      measuredFrom !== null &&
1158	      health.gapAt.getTime() >= measuredFrom.getTime(),
1159	    accruing: server.status === "RUNNING" && health.live,
1160	  };
1161	}
1162	
1163	/** "Jul 26, 2026" — the period start, stated instead of implied. */
1164	export function fmtBwDate(d: Date): string {
1165	  return d.toLocaleDateString("en-US", {
1166	    month: "short",
1167	    day: "numeric",
1168	    year: "numeric",
1169	  });
1170	}
1171	
1172	/** Compact span for "measured since X (2d 4h of 30 days)". */
1173	export function fmtBwSpan(ms: number): string {
1174	  const m = Math.floor(Math.max(0, ms) / 60_000);
1175	  if (m < 60) return `${m}m`;
1176	  const h = Math.floor(m / 60);
1177	  if (h < 48) return `${h}h`;
1178	  const d = Math.floor(h / 24);
1179	  return `${d}d ${h % 24}h`;
1180	}
