170	/** A server's EFFECTIVE root disk in GB — plan allowance plus purchased extra. */
171	export function effectiveDiskGB(planDiskGB: number, extraDiskGB: number | null | undefined): number {
172	  return Math.max(0, Math.round(planDiskGB)) + Math.max(0, Math.round(extraDiskGB ?? 0));
173	}
