185	/**
186	 * The one-off charge for `monthlyCents` of extra disk over the months still left
187	 * on the current paid term. THE single definition, shared by the server
188	 * (lib/disk-expand.ts diskExpandQuote) and the control that DISPLAYS the figure
189	 * before the customer agrees to it (components/customer/AddStorage.tsx).
190	 *
191	 * It lives in this pure module for exactly the reason `walletSplit` does: the
192	 * client has to be able to import it, so what is shown is byte-for-byte what is
193	 * charged. Until 2026-07-27 the server computed
194	 * `Math.max(0, Math.round(monthlyCents * remainingMonths))` and AddStorage computed
195	 * the same expression over its OWN private copy of `MS_PER_AVG_MONTH` — the two
196	 * places agreeing by convention that this codebase has been bitten by repeatedly
197	 * (the wizard's promo line, the "+30 days" renew button, the resize picker before
198	 * it was moved onto lib/proration.ts). Pass `remainingMonths(expiresAt, now)` from
199	 * lib/proration.ts as the second argument; do not re-derive it.
200	 *
201	 * Clamped at both ends: an expired term (negative months) prorates to zero rather
202	 * than crediting, and a negative price can never come out as a negative charge.
203	 */
204	export function extraDiskProrateCents(monthlyCents: number, monthsRemaining: number): number {
205	  const monthly = Math.max(0, monthlyCents);
206	  const months = Math.max(0, monthsRemaining);
207	  if (!Number.isFinite(monthly) || !Number.isFinite(months)) return 0;
208	  return Math.max(0, Math.round(monthly * months));
209	}
