211	/** Is `gb` a purchasable amount (a positive multiple of the step, within range)? */
212	export function isValidExtraDiskAddGB(gb: number): boolean {
213	  return (
214	    Number.isInteger(gb) &&
215	    gb >= EXTRA_DISK_MIN_GB &&
216	    gb <= EXTRA_DISK_MAX_ADD_GB &&
217	    gb % EXTRA_DISK_STEP_GB === 0
218	  );
219	}
