221	/**
222	 * Coerce arbitrary input to a purchasable amount: rounded DOWN to the step and
223	 * clamped to [0, EXTRA_DISK_MAX_ADD_GB]. Rounding DOWN (never up) means a
224	 * malformed value can only ever cost the customer less, never more. Returns 0
225	 * for "no extra disk", which every caller treats as a no-op.
226	 */
227	export function normalizeExtraDiskGB(gb: unknown): number {
228	  const n = Number(gb);
229	  if (!Number.isFinite(n) || n <= 0) return 0;
230	  const stepped = Math.floor(n / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB;
231	  if (stepped < EXTRA_DISK_MIN_GB) return 0;
232	  return Math.min(EXTRA_DISK_MAX_ADD_GB, stepped);
233	}
