235	/** Selectable amounts for the wizard/server-page controls: 10…500 GB by 10. */
236	export function extraDiskOptions(): number[] {
237	  const out: number[] = [];
238	  for (let g = EXTRA_DISK_MIN_GB; g <= EXTRA_DISK_MAX_ADD_GB; g += EXTRA_DISK_STEP_GB) out.push(g);
239	  return out;
240	}
