242	/**
243	 * The largest amount a server can still add without breaching the effective-disk
244	 * ceiling, rounded DOWN to the step. 0 means "already at the ceiling".
245	 */
246	export function maxAddableExtraDiskGB(planDiskGB: number, extraDiskGB: number): number {
247	  const headroom = EXTRA_DISK_MAX_TOTAL_GB - effectiveDiskGB(planDiskGB, extraDiskGB);
248	  if (headroom < EXTRA_DISK_MIN_GB) return 0;
249	  return Math.min(EXTRA_DISK_MAX_ADD_GB, Math.floor(headroom / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB);
250	}
251	
252	/** Human label for an extra-disk line item / notification. */
253	export function extraDiskLabel(gb: number): string {
254	  return `${Math.max(0, Math.round(gb))} GB extra disk storage`;
255	}
