257	/**
258	 * Clamp a raw "extra GB to add" input to a valid, on-step, in-range amount (0
259	 * allowed) — the SHARED-HOSTING order form's own normalizer. Rounds to the
260	 * NEAREST step (unlike `normalizeExtraDiskGB` above, which rounds DOWN for the
261	 * VPS disk-expand slider's "never cost more than shown" guarantee); hosting's
262	 * extra disk is chosen from a fixed set of stepped options, not typed free-form,
263	 * so nearest-step is the correct behaviour here and has always been.
264	 *
265	 * Lives in this plain module (not lib/actions-hosting.ts, which is a `"use
266	 * server"` file) so it can be imported by lib/actions-payment-providers.ts
267	 * (PayPal/Coinbase hosting-order creation) WITHOUT becoming a second
268	 * network-callable export of a Server Actions module — see
269	 * test/auth-lockouts.test.ts's "HAZARD" suite, which exists precisely to catch
270	 * a pure helper being exported from a `"use server"` file for no reason.
271	 */
272	export function normalizeExtraDiskAddGB(raw: unknown): number {
273	  const n = Math.round((Number(raw) || 0) / EXTRA_DISK_STEP_GB) * EXTRA_DISK_STEP_GB;
274	  return Math.max(0, Math.min(EXTRA_DISK_MAX_ADD_GB, n));
275	}
