343	type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
344	
345	function loadServer(serverId: string) {
346	  return db.server.findUnique({ where: { id: serverId }, include: { plan: true } });
347	}
348	
349	export type DiskExpandQuote = {
350	  server: QuotedServer;
351	  /** GB being added in THIS purchase. */
352	  addGB: number;
353	  /** `extraDiskGB` the server will hold once the worker finishes. */
354	  targetExtraDiskGB: number;
355	  /** Effective disk (plan + extra) after the expansion. */
356	  newTotalDiskGB: number;
357	  perGbCents: number;
358	  /** Recurring monthly cost of the newly-added GB (billed every renewal). */
359	  monthlyCents: number;
360	  /** One-off charge for the remainder of the CURRENT paid term. */
361	  prorateCents: number;
362	};
363	
364	/**
365	 * Validate an expansion and compute the prorated charge over the ACTUAL
366	 * remaining duration — identical maths to `resizeQuote` (monthly cost × every
367	 * remaining month; null expiresAt on free/admin servers => 0). Throws
368	 * DiskExpandError with a user-facing message on any guard failure. Does NOT
369	 * check ownership — callers must do that.
370	 */
371	export async function diskExpandQuote(serverId: string, addGB: number): Promise<DiskExpandQuote> {
372	  const server = await loadServer(serverId);
373	  if (!server) throw new DiskExpandError("Not found");
374	  if (!isValidExtraDiskAddGB(addGB)) {
375	    throw new DiskExpandError(
376	      `Choose between ${EXTRA_DISK_MIN_GB} and 500 GB, in ${EXTRA_DISK_STEP_GB} GB steps.`,
377	    );
378	  }
379	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
380	    throw new DiskExpandError("Server is busy — wait for the current operation to finish.");
381	  }
382	  if (!server.vmid) throw new DiskExpandError("This server hasn't finished provisioning yet.");
383	
384	  const targetExtraDiskGB = server.extraDiskGB + addGB;
385	  const newTotalDiskGB = effectiveDiskGB(server.plan.diskGB, targetExtraDiskGB);
386	  if (newTotalDiskGB > EXTRA_DISK_MAX_TOTAL_GB) {
387	    throw new DiskExpandError(
388	      `A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB — this would take it to ${newTotalDiskGB} GB. Contact support for larger volumes.`,
389	    );
390	  }
391	
392	  // Don't sell space the node can't physically back.
393	  const cap = await diskCapacityCheck(server.nodeId, addGB);
394	  if (!cap.ok) throw new DiskExpandError(cap.reason ?? "Not enough storage available right now.");
395	
396	  const perGbCents = await extraDiskPerGbCents();
397	  const monthlyCents = extraDiskCentsAt(addGB, perGbCents);
398	
399	  // The remaining-term maths comes from the two SHARED functions the "Add storage"
400	  // control also calls, so the figure the customer agreed to and the figure debited
401	  // here cannot be two different derivations of the same idea. This block used to
402	  // inline both — its own `remainingMonths` expression over a second copy of
403	  // `MS_PER_AVG_MONTH` re-exported from lib/resize.ts.
404	  let prorateCents = 0;
405	  if (!server.isFree && server.expiresAt) {
406	    prorateCents = extraDiskProrateCents(monthlyCents, remainingMonths(server.expiresAt, Date.now()));
407	  }
408	  return { server, addGB, targetExtraDiskGB, newTotalDiskGB, perGbCents, monthlyCents, prorateCents };
409	}
