411	/**
412	 * Apply the expansion: (optionally) debit the wallet for the prorated charge,
413	 * record the wallet transaction + PAID invoice, and queue the DISK_EXPAND job the
414	 * worker performs on Proxmox + inside the guest. Re-validates every guard (size,
415	 * ceiling, steady state, one in-flight job) so it is safe to call from the
416	 * unauthenticated confirm route. Throws DiskExpandError on any guard failure.
417	 *
418	 * `chargeCents` overrides the recomputed proration — the paid path passes the
419	 * exact amount the customer paid into their wallet at checkout so the debit here
420	 * nets to zero against that credit (mirrors lib/resize.ts applyResize).
421	 *
422	 * NOTE: `Server.extraDiskGB` is deliberately NOT advanced here. The worker sets it
423	 * only after the disk really grew, so a failed job is refunded (see
424	 * reconcileFailedJob) and no renewal ever bills for space that wasn't delivered.
425	 */
426	export async function applyDiskExpand(opts: {
427	  serverId: string;
428	  addGB: number;
429	  actorUserId: string;
430	  chargeCents?: number;
431	}): Promise<void> {
432	  const quote = await diskExpandQuote(opts.serverId, opts.addGB);
433	  const { server, addGB, targetExtraDiskGB, newTotalDiskGB, monthlyCents } = quote;
434	  const prorateCents = opts.chargeCents ?? quote.prorateCents;
435	
436	  const pending = await db.job.count({
437	    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
438	  });
439	  if (pending > 0) throw new DiskExpandError("Another operation is already in progress on this server.");
440	
441	  const label = extraDiskLabel(addGB);
442	  try {
443	    await db.$transaction(async (tx) => {
444	      if (prorateCents > 0) {
445	        await debitWallet(tx, server.userId, prorateCents);
446	        await tx.walletTransaction.create({
447	          data: {
448	            userId: server.userId,
449	            amountCents: -prorateCents,
450	            description: `${label} (prorated) — ${server.hostname}`,
451	          },
452	        });
453	        // PAID invoice for the proration. The line item spells out BOTH the
454	        // permanence and the recurring monthly cost, so the billing document
455	        // itself carries the one-way warning.
456	        await tx.invoice.create({
457	          data: invoiceCreateData({
458	            userId: server.userId,
459	            description: `${label} (prorated) — ${server.hostname}`,
460	            status: "PAID",
461	            lineItems: [
462	              {
463	                description:
464	                  `${label} — prorated for remaining term (${server.hostname}). ` +
465	                  `Disk grows to ${newTotalDiskGB} GB permanently; renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
466	                qty: 1,
467	                unitCents: prorateCents,
468	                amountCents: prorateCents,
469	              },
470	            ],
471	          }),
472	        });
473	      }
474	      // Record the amount charged AND the target on the job so the worker can
475	      // (a) know how far to grow and (b) REVERSE the charge if the expansion
476	      // terminally fails — money is committed here, before the job runs.
477	      await tx.job.create({
478	        data: {
479	          type: "DISK_EXPAND",
480	          serverId: server.id,
481	          payload: { addGB, targetExtraDiskGB, prorateCents, monthlyCents } as any,
482	        },
483	      });
484	      await tx.auditLog.create({
485	        data: {
486	          userId: opts.actorUserId,
487	          action: "server.disk_expand",
488	          detail: `${server.id} +${addGB}GB -> extra=${targetExtraDiskGB} total=${newTotalDiskGB} prorate=${prorateCents}`,
489	        },
490	      });
491	    });
492	  } catch (e) {
493	    if (e instanceof InsufficientBalanceError) {
494	      throw new DiskExpandError("Insufficient balance — top up your wallet first.");
495	    }
496	    throw e;
497	  }
498	}
