500	/**
501	 * What a VM's Proxmox config must be put back to after a backup restore.
502	 *
503	 * ── THE INCIDENT ─────────────────────────────────────────────────────────────
504	 *
505	 * `worker/restore.ts` restores a customer's vzdump archive over their live VMID
506	 * with `qmrestore --force`. That does not restore *disks into* an existing VM —
507	 * it replaces the VM, config and all. Whatever `net0`, `ipconfig0`, `cores` and
508	 * `memory` the archive recorded become the VM's identity again, silently, and
509	 * the handler then started it.
510	 *
511	 * Two independent consequences, both invisible to the customer and to us:
512	 *
513	 * 1. NETWORK IDENTITY — the serious one. Addresses are not permanent. Suspending
514	 *    a server releases its dedicated IP back to the pool (`releaseDedicatedIp`)
515	 *    and `lib/ipam.ts` hands released NAT addresses back out to new servers. So
516	 *    an archive taken before a suspend, a plan move or an IP change carries an
517	 *    address that may now belong to a DIFFERENT CUSTOMER. Restoring it booted a
518	 *    second guest onto that address on the shared bridge: two machines, one IP,
519	 *    on a segment they do not share a tenant with. Whose traffic arrives where is
520	 *    decided by ARP.
521	 *
522	 * 2. SIZE vs. BILLING — `cores`/`memory` came back at whatever plan the archive
523	 *    was taken under. A customer who upgraded after that backup was restored to
524	 *    the smaller plan while the `Server` row, the invoice and the renewal price
525	 *    all still said the larger one. Nothing reconciled the two.
526	 *
527	 * ── THE RULE ─────────────────────────────────────────────────────────────────
528	 *
529	 * The `Server` row is the authority on identity, never the archive. After a
530	 * restore the platform-owned keys are written back from that row and then READ
531	 * BACK and verified; if they did not take, the VM must not be started. A restore
532	 * that leaves a machine stopped is an inconvenience — one that boots on someone
533	 * else's address is an incident.
534	 *
535	 * This module is pure on purpose: no Prisma, no Proxmox, no clock, no env. It is
536	 * driven directly by test/restore-identity.test.ts, which is the only way the
537	 * "two customers, one IP" case can be exercised without a real restore.
538	 */
539	
540	/** The sizing fields the platform owns, from `Server.plan`. */
541	export type RestorePlan = { cpuCores: number; ramMB: number };
542	
543	/** A dedicated (public, OVH failover) address currently held by this server. */
544	export type RestoreDedicatedIp = {
545	  address: string;
546	  virtualMac: string | null;
547	  /** OVH failover gateway — `ovhGateway()` in lib/dedicated-ip.ts. */
548	  gateway: string;
549	};
550	
551	/**
552	 * Everything needed to rebuild a VM's identity, read from the `Server` row and
553	 * its node at restore time — never from the archive.
554	 */
555	export type RestoreIdentityInput = {
556	  plan: RestorePlan;
557	  /** `Server.ipAddress` — the NAT address, when the server is not on a dedicated IP. */
558	  natIp: string | null;
559	  /** `gatewayIp(node.subnetPrefix)`. */
560	  natGateway: string;
561	  /** `node.bridge`, e.g. `vmbr1`. */
562	  natBridge: string;
563	  /** The row from `DedicatedIp`, or null for a NAT server. */
564	  dedicated: RestoreDedicatedIp | null;
565	};
566	
567	/** Proxmox `POST /nodes/{node}/qemu/{vmid}/config` body. */
568	export type VmIdentityConfig = {
569	  cores: number;
570	  memory: number;
571	  onboot: number;
572	  net0: string;
573	  ipconfig0: string;
574	};
575	
576	/**
577	 * Raised when the `Server` row cannot describe a network the VM may legally boot
578	 * on. The caller must fail the restore job rather than start the VM: leaving the
579	 * archive's stale address in place is precisely the outcome being prevented.
580	 */
581	export class RestoreIdentityError extends Error {
