588	/**
589	 * The config a restored VM must be given, derived from the `Server` row.
590	 *
591	 * Mirrors what PROVISION writes in worker/index.ts (and what unsuspend rewrites)
592	 * so a restored machine is configured identically to a freshly provisioned one.
593	 */
594	export function restoreIdentityConfig(input: RestoreIdentityInput): VmIdentityConfig {
595	  const cores = Math.trunc(Number(input.plan?.cpuCores));
596	  const memory = Math.trunc(Number(input.plan?.ramMB));
597	  if (!Number.isFinite(cores) || cores < 1 || !Number.isFinite(memory) || memory < 1) {
598	    throw new RestoreIdentityError(
599	      "the server's plan has no usable cpuCores/ramMB, so the restored VM's size cannot be reasserted",
600	    );
601	  }
602	
603	  const base = { cores, memory, onboot: 1 };
604	
605	  if (input.dedicated) {
606	    // Public bridge + OVH Virtual MAC; failover IP as a /32 with the host gateway.
607	    // Without the vMAC the address does not route, and inventing one would put an
608	    // unbound MAC on the PUBLIC bridge — refuse instead.
609	    const mac = (input.dedicated.virtualMac ?? "").trim();
610	    if (!mac) {
611	      throw new RestoreIdentityError(
612	        `dedicated IP ${input.dedicated.address} has no Virtual MAC bound, so the restored VM has no valid public network config`,
613	      );
614	    }
615	    if (!input.dedicated.gateway?.trim()) {
616	      throw new RestoreIdentityError(
617	        `dedicated IP ${input.dedicated.address} has no gateway, so the restored VM has no valid public network config`,
618	      );
619	    }
620	    return {
621	      ...base,
622	      net0: `virtio=${mac},bridge=vmbr0`,
623	      ipconfig0: `ip=${input.dedicated.address}/32,gw=${input.dedicated.gateway.trim()}`,
624	    };
625	  }
626	
627	  const ip = (input.natIp ?? "").trim();
628	  if (!ip) {
629	    throw new RestoreIdentityError(
630	      "the server row holds no IP address, so there is no address the restored VM may boot on",
631	    );
632	  }
633	  const gw = (input.natGateway ?? "").trim();
634	  if (!gw) {
635	    throw new RestoreIdentityError("no NAT gateway is configured for this server's node");
636	  }
637	  const bridge = (input.natBridge ?? "").trim();
638	  if (!bridge) {
639	    throw new RestoreIdentityError("no bridge is configured for this server's node");
640	  }
641	  return {
642	    ...base,
643	    net0: `virtio,bridge=${bridge}`,
644	    ipconfig0: `ip=${ip}/24,gw=${gw}`,
645	  };
646	}
