656	/**
657	 * Which of the requested keys did NOT take, comparing the config we asked for
658	 * against the config Proxmox reports.
659	 *
660	 * `net0`/`ipconfig0` are compared component-wise: PVE normalises and may ADD
661	 * fields (`firewall=1`, a `link_down` flag, a `,type=` it filled in). Requiring
662	 * a byte-exact match would fail a correct apply, and a test that fails on
663	 * correct behaviour gets deleted. Requiring every component we ASKED FOR to be
664	 * present is the property that actually matters — in particular that `ip=` is
665	 * the address the `Server` row holds and not the archive's.
666	 *
667	 * Returns human-readable mismatch descriptions; empty means the apply is proven.
668	 */
669	export function restoreIdentityMismatches(
670	  desired: VmIdentityConfig,
671	  actual: Record<string, unknown> | null | undefined,
672	): string[] {
673	  const out: string[] = [];
674	  if (!actual || typeof actual !== "object") {
675	    return ["Proxmox returned no config for the restored VM, so nothing could be verified"];
676	  }
677	
678	  for (const key of ["cores", "memory", "onboot"] as const) {
679	    const want = Number(desired[key]);
680	    const got = Number((actual as Record<string, unknown>)[key]);
681	    if (!Number.isFinite(got) || got !== want) {
682	      out.push(`${key}: expected ${want}, VM reports ${String((actual as Record<string, unknown>)[key] ?? "unset")}`);
683	    }
684	  }
685	
686	  for (const key of ["net0", "ipconfig0"] as const) {
687	    const want = parts(desired[key]);
688	    const got = new Set(parts((actual as Record<string, unknown>)[key]));
689	    const missing = want.filter((p) => !got.has(p));
690	    if (missing.length > 0) {
691	      out.push(
692	        `${key}: expected ${missing.join(", ")}, VM reports "${String(
693	          (actual as Record<string, unknown>)[key] ?? "unset",
694	        )}"`,
695	      );
696	    }
697	  }
698	
699	  return out;
700	}
