859	export async function createCustomPlan(spec: CustomPlanSpec): Promise<CreatedCustomPlan> {
860	  const quote = await customPlanQuote(spec);
861	  if (!quote.ok) throw new CustomPlanError(quote.reason);
862	  const cap = await customPlanCapacityCheck(spec);
863	  if (!cap.ok) throw new CustomPlanError(cap.reason ?? "Not enough room for that configuration right now.");
864	
865	  let lastErr: unknown;
866	  for (let attempt = 0; attempt < 3; attempt++) {
867	    try {
868	      const plan = await db.plan.create({
869	        data: {
870	          slug: customPlanSlug(spec, randSuffix()),
871	          name: customPlanName(spec),
872	          cpuCores: spec.cpuCores,
873	          ramMB: spec.ramMB,
874	          diskGB: spec.diskGB,
875	          bandwidthTB: quote.floor.bandwidthTB,
876	          priceCents: quote.priceCents,
877	          storageTier: "nvme",
878	          active: false,
879	          sortOrder: CUSTOM_PLAN_SORT_ORDER,
880	        },
881	      });
882	      return {
883	        id: plan.id,
884	        name: plan.name,
885	        cpuCores: plan.cpuCores,
886	        ramMB: plan.ramMB,
887	        diskGB: plan.diskGB,
888	        bandwidthTB: plan.bandwidthTB,
889	        priceCents: plan.priceCents,
890	        storageTier: plan.storageTier,
891	      };
892	    } catch (e) {
893	      lastErr = e; // near-impossible slug collision (6-char random suffix) — retry once or twice
894	    }
895	  }
896	  throw lastErr instanceof Error ? lastErr : new CustomPlanError("Could not create the custom plan — please try again.");
897	}
