1031	export type CustomPlanSpec = { cpuCores: number; ramMB: number; diskGB: number };
1032	
1033	/** The floor a custom spec must clear on every dimension — today, the live "Max"
1034	 *  plan's specs (see lib/custom-plan.ts customPlanFloor, which reads it from the
1035	 *  DB rather than hardcoding it, so a future catalog change is picked up live). */
1036	export type CustomPlanFloor = {
1037	  cpuCores: number;
1038	  ramMB: number;
1039	  diskGB: number;
1040	  priceCents: number;
1041	  bandwidthTB: number;
1042	};
1043	
1044	export type CustomPlanCeiling = { maxCpuCores: number; maxRamMB: number; maxDiskGB: number };
1045	
1046	export type CustomPlanRates = { perVcpuCents: number; perRamGbCents: number; perDiskGbCents: number };
1047	
1048	/**
1049	 * The custom-plan price: Max's price plus the per-unit rate for whatever exceeds
1050	 * Max on each dimension. Only the EXCESS over the floor is charged for — a spec
1051	 * that matches Max on RAM/disk but asks for double the CPU pays only for the
1052	 * extra CPU, not a second copy of Max's whole price.
1053	 *
1054	 * Defensively clamped to STRICTLY more than the floor's price: a valid spec
1055	 * (per validateCustomPlanSpec) always exceeds the floor on at least one
1056	 * dimension, so with positive rates this clamp is a no-op — but if an admin ever
1057	 * zeroes a rate (e.g. sets `extra_disk_gb_price_cents` to "0"), a disk-only
1058	 * custom spec must still never price at-or-below Max, which would silently
1059	 * undercut the catalog (the exact class of bug lib/resize.ts's price-monotonic
1060	 * guard exists to prevent one level up, at resize time).
1061	 */
1062	export function computeCustomPlanPriceCents(
1063	  spec: CustomPlanSpec,
1064	  floor: CustomPlanFloor,
1065	  rates: CustomPlanRates,
1066	): number {
1067	  const extraCpu = Math.max(0, spec.cpuCores - floor.cpuCores);
1068	  const extraRamGB = Math.max(0, (spec.ramMB - floor.ramMB) / 1024);
1069	  const extraDiskGB = Math.max(0, spec.diskGB - floor.diskGB);
1070	  const raw =
1071	    floor.priceCents +
1072	    extraCpu * rates.perVcpuCents +
1073	    extraRamGB * rates.perRamGbCents +
1074	    extraDiskGB * rates.perDiskGbCents;
1075	  return Math.max(Math.round(raw), floor.priceCents + 1);
1076	}
1077	
1078	/**
1079	 * Guardrails: every dimension must be at or above the floor (never a way to buy
1080	 * something Max-sized or smaller under a different name) and at or below the
1081	 * admin-configured ceiling. A spec that matches the floor EXACTLY on all three
1082	 * dimensions is rejected too — that's just Max, not a custom order.
1083	 */
1084	export function validateCustomPlanSpec(
1085	  spec: CustomPlanSpec,
1086	  floor: CustomPlanFloor,
1087	  ceiling: CustomPlanCeiling,
1088	): { ok: true } | { ok: false; reason: string } {
1089	  if (!Number.isFinite(spec.cpuCores) || !Number.isFinite(spec.ramMB) || !Number.isFinite(spec.diskGB)) {
1090	    return { ok: false, reason: "Invalid configuration." };
1091	  }
1092	  if (spec.cpuCores < floor.cpuCores || spec.ramMB < floor.ramMB || spec.diskGB < floor.diskGB) {
1093	    return {
1094	      ok: false,
1095	      reason:
1096	        `A custom server can't go below ${floor.cpuCores} vCPU / ${floor.ramMB / 1024} GB RAM / ${floor.diskGB} GB disk ` +
1097	        `on any dimension — for anything smaller, pick a plan above instead.`,
1098	    };
1099	  }
1100	  if (spec.cpuCores > ceiling.maxCpuCores || spec.ramMB > ceiling.maxRamMB || spec.diskGB > ceiling.maxDiskGB) {
1101	    return {
1102	      ok: false,
1103	      reason:
1104	        `Custom servers top out at ${ceiling.maxCpuCores} vCPU / ${ceiling.maxRamMB / 1024} GB RAM / ` +
1105	        `${ceiling.maxDiskGB} GB disk — contact support for anything larger.`,
1106	    };
1107	  }
1108	  if (spec.cpuCores === floor.cpuCores && spec.ramMB === floor.ramMB && spec.diskGB === floor.diskGB) {
1109	    return { ok: false, reason: "That's exactly the Max plan — choose Max above instead of building custom." };
1110	  }
1111	  return { ok: true };
1112	}
