1114	/** Clamp an arbitrary (e.g. slider-dragged, or player-count-derived) spec into the
1115	 *  floor..ceiling range, rounding to whole units. Used by the UI so a slider or a
1116	 *  recommendation can never even VISUALLY suggest an invalid spec. */
1117	export function clampCustomPlanSpec(
1118	  spec: CustomPlanSpec,
1119	  floor: CustomPlanFloor,
1120	  ceiling: CustomPlanCeiling,
1121	): CustomPlanSpec {
1122	  return {
1123	    cpuCores: Math.min(ceiling.maxCpuCores, Math.max(floor.cpuCores, Math.round(spec.cpuCores))),
1124	    ramMB: Math.min(ceiling.maxRamMB, Math.max(floor.ramMB, Math.round(spec.ramMB))),
1125	    diskGB: Math.min(ceiling.maxDiskGB, Math.max(floor.diskGB, Math.round(spec.diskGB))),
1126	  };
1127	}
