2	/**
3	 * Live-telemetry ingestion + read-back for the nxeon-shipper agent feature.
4	 *
5	 * WHAT THIS IS: a short rolling window (TELEMETRY_RETENTION_HOURS) of raw
6	 * connection/auth events shipped by nxeon-shipper — SSH logins/logouts/failed
7	 * attempts, visitor HTTP hits, and mail auth attempts — fanned into the same
8	 * /admin/monitor page the existing Live Ops feed (lib/monitor-feed.ts) drives.
9	 *
10	 * ARCHITECTURE CALL (documented per the task's "make the reasonable call"
11	 * instruction): this is DB-backed (a `TelemetryEvent` row per event), read by
12	 * the existing 8s poll in LiveMonitorTerminal, NOT a new SSE/WebSocket
13	 * channel. Reasons:
14	 *   1. Single-node deployment (see docs/DOCUMENTATION.md) — there is exactly
15	 *      one Next.js process and one worker process; a push channel would only
16	 *      be saving the latency of one indexed, limit-50 query every 8s, which
17	 *      is not meaningfully "not live" for an ops console (SSH events show up
18	 *      within one poll tick, i.e. worst-case ~8s, typically 2-5s given the
19	 *      shipper's own 3s batch interval).
20	 *   2. The existing monitor page is ALREADY a poll loop end to end (route +
21	 *      component); adding a second transport (SSE) alongside it for only
22	 *      SOME event types would fragment the one console into two update
23	 *      cadences for no operator-visible benefit, and every other admin
24	 *      surface in this codebase (Jobs, HostingTask, node stats) is polled
25	 *      the same way.
26	 *   3. Postgres growth is bounded by retention (below) + the worker sweep
27	 *      (worker/telemetry.ts telemetrySweep), so "DB as ring buffer" carries
28	 *      none of the unbounded-growth risk that would make this a bad idea.
29	 * If a future phase needs sub-second delivery (e.g. a live "who's SSH'd in
30	 * right now" indicator), promote just that slice to SSE — terminal-server's
31	 * `ws` dependency is already in the tree as prior art for a push channel.
32	 */
33	import { db } from "./db";
34	import { resolveTelemetryPrincipal } from "./telemetry-token";
35	
36	export const TELEMETRY_RETENTION_HOURS = 48;
37	/** Hard cap on events accepted per batch POST — matches the shipper's own
38	 *  batchMaxEvents (50) with headroom, so a misbehaving/compromised agent
39	 *  can't smuggle an oversized payload through one request. */
40	const MAX_EVENTS_PER_BATCH = 200;
41	const VALID_TYPES = new Set(["SSH_LOGIN", "SSH_LOGOUT", "SSH_FAILED", "VISITOR", "MAIL_AUTH"]);
42	const VALID_NODE_KINDS = new Set(["VPS", "GAME", "HOSTING", "MAIL"]);
43	
44	export type EventIn = {
45	  type: string;
46	  ts: string;
47	  ip?: string;
48	  user?: string;
49	  path?: string;
50	  status?: string;
51	  meta?: string;
52	  site?: string;
53	};
54	
55	export type BatchIn = {
56	  server_id?: string;
57	  node_kind?: string;
58	  label?: string;
59	  events?: EventIn[];
60	};
61	
62	export function clip(s: string | undefined | null, max: number): string | undefined {
63	  if (!s) return undefined;
64	  return s.length > max ? s.slice(0, max) : s;
65	}
66	
67	/**
68	 * Pure batch → row-shape transform, split out from ingestTelemetryBatch so it
69	 * can be unit-tested without a database (see test/telemetry.test.ts) — same
70	 * "extract the pure function" pattern worker/provision-health.ts's
71	 * attemptsFor/retryCheck use. Clamps batch size, drops malformed/unknown
72	 * event types, and clips every free-form string field so one hostile/buggy
73	 * shipper can't smuggle an oversized row into Postgres.
74	 */
75	export function buildTelemetryRows(principal: import("./telemetry-token").TelemetryPrincipal, body: BatchIn) {
76	  const events = Array.isArray(body.events) ? body.events.slice(0, MAX_EVENTS_PER_BATCH) : [];
77	  const label = clip(body.label, 200) ?? null;
78	  return events
79	    .filter((e) => e && typeof e.type === "string" && VALID_TYPES.has(e.type))
80	    .map((e) => {
81	      let ts = new Date(e.ts);
82	      if (Number.isNaN(ts.getTime())) ts = new Date();
83	      return {
84	        serverId: principal.kind === "VPS" || principal.kind === "GAME" ? principal.serverId : null,
85	        nodeId: principal.kind === "HOSTING" ? principal.nodeId : principal.kind === "MAIL" ? "mail" : null,
86	        nodeKind: principal.kind,
87	        type: e.type,
88	        ts,
89	        ip: clip(e.ip, 64) ?? null,
90	        user: clip(e.user, 128) ?? null,
91	        path: clip(e.path, 512) ?? null,
92	        site: clip(e.site, 200) ?? null,
93	        status: clip(e.status, 32) ?? null,
94	        meta: clip(e.meta, 256) ?? null,
95	        label,
96	      };
97	    });
98	}
99	
100	/**
101	 * Validate the bearer token against Server/HostingNode/mail-secret, validate
102	 * + clamp the batch shape, and insert. Returns the count actually stored (0
103	 * if the token was invalid or the batch was empty/malformed — callers should
104	 * still answer 401 for a bad token, this function only owns the DB write).
105	 */
106	export async function ingestTelemetryBatch(
107	  token: string,
108	  body: BatchIn
109	): Promise<{ ok: true; stored: number } | { ok: false; reason: string }> {
110	  const nodeKind = body.node_kind && VALID_NODE_KINDS.has(body.node_kind) ? body.node_kind : "VPS";
111	  const principal = await resolveTelemetryPrincipal(token, nodeKind);
112	  if (!principal) return { ok: false, reason: "invalid token" };
113	
114	  const rows = buildTelemetryRows(principal, body);
115	  if (rows.length === 0) return { ok: true, stored: 0 };
116	
117	  await db.telemetryEvent.createMany({ data: rows });
118	  return { ok: true, stored: rows.length };
119	}
120	
121	export type TelemetryEventView = {
122	  id: string;
123	  serverId: string | null;
124	  nodeId: string | null;
125	  nodeKind: string;
126	  type: string;
127	  ts: string;
128	  ip: string | null;
129	  user: string | null;
130	  path: string | null;
131	  site: string | null;
132	  status: string | null;
133	  meta: string | null;
134	  label: string | null;
135	};
136	
137	/**
138	 * Recent events for the admin monitor feed. Capped at `limit` (the monitor
139	 * UI only ever shows a scrolling tail, same as the existing Job/HostingTask
140	 * action log), ordered newest-first.
141	 */
142	export async function getRecentTelemetry(limit = 80): Promise<TelemetryEventView[]> {
143	  const rows = await db.telemetryEvent.findMany({
144	    orderBy: { createdAt: "desc" },
145	    take: limit,
146	  });
147	  return rows.map((r) => ({
148	    id: r.id,
149	    serverId: r.serverId,
150	    nodeId: r.nodeId,
151	    nodeKind: r.nodeKind,
152	    type: r.type,
153	    ts: r.ts.toISOString(),
154	    ip: r.ip,
155	    user: r.user,
156	    path: r.path,
157	    site: r.site,
158	    status: r.status,
159	    meta: r.meta,
160	    label: r.label,
161	  }));
162	}
163	
164	/**
165	 * Prune rows past the retention window. Called first (before anything that
166	 * could throw) by worker/telemetry.ts's sweep, same "prune, then act" order
167	 * as worker/monitor.ts sampleServerDisks — a prune failure must never block
168	 * the rest of the sweep, and the rest of the sweep must never leave stale
169	 * rows to expire only when a LATER sweep happens to succeed.
170	 */
171	export async function pruneTelemetry(): Promise<number> {
172	  const cutoff = new Date(Date.now() - TELEMETRY_RETENTION_HOURS * 60 * 60_000);
173	  const { count } = await db.telemetryEvent.deleteMany({ where: { createdAt: { lt: cutoff } } });
174	  return count;
175	}
176	##### lib/telemetry-token.ts
177	/**
178	 * Per-server / per-node bearer tokens for the nxeon-shipper live-telemetry
179	 * agent (see agent/nxeon-shipper). Unlike lib/terminal-token.ts (a 60s JWE
180	 * minted per browser session), a shipper token is a PERSISTENT machine
181	 * credential baked into cloud-init / a node's shipper config at provision
182	 * time and used indefinitely from then on — so it follows the same
183	 * hash-at-rest convention as password-reset tokens and the deploy-hook
184	 * secrets in lib/actions-account.ts, NOT the ephemeral-JWE convention:
185	 *
186	 *   - mint(): random 32-byte token, return the raw value ONCE, store only
187	 *     its SHA-256 hash (`Server.telemetryTokenHash` / `HostingNode.telemetryTokenHash`).
188	 *   - lookupByToken(): hash the presented token and look the owner up by the
189	 *     unique hash column — the same shape as PasswordResetToken lookups.
190	 *
191	 * There's no rotation UI yet (Phase 2): re-provisioning a server mints a
192	 * fresh token and overwrites the old hash, which is all we need since a
193	 * leaked shipper token only grants "post low-value connection-event rows
194	 * for this one server," not read/write access to anything else.
195	 */
196	import { randomBytes, createHash } from "node:crypto";
197	import { db } from "./db";
198	
199	export function mintTelemetryToken(): { token: string; hash: string } {
200	  const token = randomBytes(32).toString("base64url");
201	  const hash = createHash("sha256").update(token).digest("hex");
202	  return { token, hash };
203	}
204	
205	export function hashTelemetryToken(token: string): string {
206	  return createHash("sha256").update(token).digest("hex");
207	}
208	
209	/**
210	 * Mint a fresh telemetry token for a server, persist its hash, and return
211	 * the raw token to embed in that server's cloud-init config. Call this once
212	 * per (re)provision, right before buildCloudInit() so the config file the
213	 * agent boots with matches the hash we just stored.
214	 */
215	export async function mintServerTelemetryToken(serverId: string): Promise<string> {
216	  const { token, hash } = mintTelemetryToken();
217	  await db.server.update({ where: { id: serverId }, data: { telemetryTokenHash: hash } });
218	  return token;
219	}
220	
221	export async function mintHostingNodeTelemetryToken(nodeId: string): Promise<string> {
222	  const { token, hash } = mintTelemetryToken();
223	  await db.hostingNode.update({ where: { id: nodeId }, data: { telemetryTokenHash: hash } });
224	  return token;
225	}
226	
227	export type TelemetryPrincipal =
228	  | { kind: "VPS" | "GAME"; serverId: string }
229	  | { kind: "HOSTING"; nodeId: string }
230	  | { kind: "MAIL" };
231	
232	/**
233	 * Resolve a presented bearer token to the server/node it belongs to. Checked
234	 * in order: Server (VPS/GAME — nodeKind carried by the shipper's own config,
235	 * not re-derived here since a game server and a VPS look identical at this
236	 * layer), then HostingNode, then the single static MAIL_TELEMETRY_TOKEN env
237	 * secret (the mail box has no Prisma row to hang a hash off today — see
238	 * commit message for why a static shared secret is an acceptable stopgap for
239	 * one fixed, admin-controlled centralized node).
240	 */
241	export async function resolveTelemetryPrincipal(token: string, claimedNodeKind: string): Promise<TelemetryPrincipal | null> {
242	  if (!token) return null;
243	  const hash = hashTelemetryToken(token);
244	
245	  if (claimedNodeKind === "MAIL") {
246	    const secret = process.env.MAIL_TELEMETRY_TOKEN;
247	    if (secret && hash === hashTelemetryToken(secret)) return { kind: "MAIL" };
248	    return null;
249	  }
250	
251	  if (claimedNodeKind === "HOSTING") {
252	    const node = await db.hostingNode.findUnique({ where: { telemetryTokenHash: hash }, select: { id: true } });
253	    return node ? { kind: "HOSTING", nodeId: node.id } : null;
254	  }
255	
256	  const server = await db.server.findUnique({
257	    where: { telemetryTokenHash: hash },
258	    select: { id: true, gameVariant: true },
259	  });
260	  if (!server) return null;
261	  return { kind: server.gameVariant ? "GAME" : "VPS", serverId: server.id };
262	}
263	##### lib/platform-backups.ts
264	/**
265	 * Whole-system ("platform") backup visibility for /admin/backups.
266	 *
267	 * WHY THIS EXISTS
268	 * ---------------
269	 * The fleet Backups page (app/admin/backups) reads backups LIVE from Proxmox —
270	 * it enumerates each node's `backup` storage via /storage/backup/content. That
271	 * is the right source for *customer* on-demand backups, but it is structurally
272	 * blind to the platform's own disaster-recovery backups.
273	 *
274	 * On 2026-07-26 the whole-system backup (scripts/backup-vms.sh) was deliberately
275	 * moved OUT of the Proxmox `backup` storage and into a `--dumpdir`
276	 * (/tank/backup/platform), so that a customer clicking "Create backup" — whose
277	 * retention prunes by vmid inside the `backup` storage — could no longer delete
278	 * the platform's DR copy of that same VM. The trade-off: Proxmox only indexes
279	 * `<storage>/dump`, so those archives have no volid and NEVER appear in the
280	 * content listing the admin page reads. Result: the daily whole-system backup
281	 * runs and succeeds, but /admin/backups shows "no recent backup" for everything,
282	 * which reads as "backups are broken" when they are in fact healthy.
283	 *
284	 * This module closes that blind spot WITHOUT touching backup execution: it reads
285	 * the status JSON the backup units already write (/tank/backup/status/*.json) and
286	 * lists the dumpdir archives (/tank/backup/platform), so the panel can tell the
287	 * truth about the whole-system backup subsystem. Read-only; no deletion, no
288	 * scheduling, no Proxmox calls.
289	 *
290	 * The web app runs as the unprivileged `nxeon` user; the status files are 0644 in
291	 * a 0755 dir and the dumpdir is world-listable, so this read is exactly the
292	 * channel scripts/backup-offsite.sh documents as "the only way the portal can
293	 * tell the owner the truth about off-site state".
294	 */
295	
296	import { promises as fs } from "fs";
297	import path from "path";
298	
299	const STATUS_DIR = process.env.NXEON_BACKUP_STATUS_DIR ?? "/tank/backup/status";
300	const PLATFORM_DIR = process.env.NXEON_PLATFORM_BACKUP_DIR ?? "/tank/backup/platform";
301	
302	/** Health of one whole-system backup subsystem (a status JSON file). */
303	export type SubsystemStatus = {
304	  key: "vm" | "host-config" | "offsite" | "verify-restore";
305	  label: string;
306	  /** null = status file missing/unreadable (we have no evidence either way). */
307	  ok: boolean | null;
308	  /** ISO timestamp of the last run, or null. */
309	  at: string | null;
310	  /** Age of the last run in ms, or null when unknown. */
311	  ageMs: number | null;
312	  /** One-line human detail (mode/dest/error/etc.), best-effort. */
313	  detail: string;
314	  /** True when the status file could not be read at all. */
315	  missing: boolean;
316	};
317	
318	/** Newest platform DR archive we hold for one guest vmid. */
319	export type PlatformGuest = {
320	  vmid: number;
321	  count: number;
322	  newestAgeMs: number;
323	  newestFile: string;
324	  totalBytes: number;
325	};
326	
327	export type PlatformBackupsView = {
328	  /** False when neither the status dir nor the dumpdir could be read at all. */
329	  available: boolean;
330	  statusDir: string;
331	  platformDir: string;
332	  subsystems: SubsystemStatus[];
333	  guests: PlatformGuest[];
334	  /** vmid -> newest archive age in ms, for cross-referencing the Proxmox view. */
335	  coverageByVmid: Record<number, number>;
336	  totalArchives: number;
337	  totalBytes: number;
338	};
339	
340	async function readStatusFile(name: string): Promise<Record<string, unknown> | null> {
341	  try {
342	    const raw = await fs.readFile(path.join(STATUS_DIR, name), "utf8");
343	    return JSON.parse(raw) as Record<string, unknown>;
344	  } catch {
345	    return null;
346	  }
347	}
348	
349	function ageOf(at: unknown, now: number): number | null {
350	  if (typeof at !== "string") return null;
351	  const t = Date.parse(at);
352	  return Number.isFinite(t) ? Math.max(0, now - t) : null;
353	}
354	
355	function str(v: unknown): string {
356	  return typeof v === "string" ? v : v == null ? "" : String(v);
357	}
358	
359	/**
360	 * Parse a vzdump archive filename into its vmid. Matches only the real archive
361	 * (`.vma`/`.vma.zst`/`.vma.gz`), never the sidecar `.log`.
362	 *   vzdump-qemu-102-2026_08_04-04_40_22.vma.zst -> 102
363	 */
364	function vmidFromArchive(file: string): number | null {
365	  const m = /^vzdump-[a-z]+-(\d+)-.*\.vma(\.(zst|gz|lzo))?$/i.exec(file);
366	  if (!m) return null;
367	  const n = Number(m[1]);
368	  return Number.isInteger(n) ? n : null;
369	}
370	
371	/**
372	 * Read the whole-system backup status + dumpdir contents. Never throws — a
373	 * missing directory or unreadable file degrades to `missing`/`available:false`,
374	 * because the honest answer to "we cannot read the backup state" is to say so,
375	 * not to claim success (the exact failure mode scripts/backup-offsite.sh exists
376	 * to prevent).
377	 */
378	export async function readPlatformBackups(now = Date.now()): Promise<PlatformBackupsView> {
379	  const [vm, host, offsite, verify] = await Promise.all([
380	    readStatusFile("vm-backup.json"),
381	    readStatusFile("host-config.json"),
382	    readStatusFile("offsite.json"),
383	    readStatusFile("verify-restore.json"),
384	  ]);
385	
386	  const subsystems: SubsystemStatus[] = [];
387	
388	  const push = (
389	    key: SubsystemStatus["key"],
390	    label: string,
391	    s: Record<string, unknown> | null,
392	    detail: (s: Record<string, unknown>) => string
393	  ) => {
394	    if (!s) {
395	      subsystems.push({ key, label, ok: null, at: null, ageMs: null, detail: "no status file yet", missing: true });
396	      return;
397	    }
398	    subsystems.push({
399	      key,
400	      label,
401	      ok: typeof s.ok === "boolean" ? (s.ok as boolean) : null,
402	      at: typeof s.at === "string" ? (s.at as string) : null,
403	      ageMs: ageOf(s.at, now),
404	      detail: detail(s),
405	      missing: false,
406	    });
407	  };
408	
409	  push("vm", "Whole-system VM backup", vm, (s) => {
410	    const mode = str(s.mode);
411	    const dest = str(s.dest);
412	    const keep = str(s.keepLast);
413	    if (s.ok === false) return `FAILED — ${str(s.error) || "see journalctl -u nxeon-backup-vms"}`;
414	    return `${mode || "dumpdir"} → ${dest || PLATFORM_DIR}${keep ? ` · keep-last ${keep}` : ""}`;
415	  });
416	  push("host-config", "Host configuration (/etc/pve)", host, (s) => {
417	    if (s.ok === false) return `FAILED — ${str(s.error) || "unknown"}`;
418	    const defs = str(s.vmDefinitions);
419	    return defs ? `${defs} VM definition(s) captured` : "captured";
420	  });
421	  push("offsite", "Off-site replication", offsite, (s) => {
422	    if (s.configured === false) return "NOT CONFIGURED — every backup lives only on this chassis";
423	    if (s.ok === false) return `FAILED — ${str(s.detail) || "replication failed"}`;
424	    const base = str(s.detail) || `replicated via ${str(s.kind) || "remote"}`;
425	    const pruned = typeof s.prunedRemote === "number" ? s.prunedRemote : Number(s.prunedRemote);
426	    // Only rclone/rsync are true mirrors — Mega (megatools' megacopy) is
427	    // upload-only, so this run's mirror-prune count is the only visible
428	    // evidence retention is actually keeping the Mega copy bounded rather than
429	    // growing forever. See lib/offsite-retention.ts.
430	    return Number.isFinite(pruned) && pruned > 0 ? `${base} · pruned ${pruned} stale remote file(s)` : base;
431	  });
432	  push("verify-restore", "Restore verification", verify, (s) => {
433	    if (s.ok === false) return `FAILED — ${str(s.error) || "verification failed"}`;
434	    const arch = str(s.vmArchives);
435	    const warn = str(s.warnings);
436	    return `${arch ? `${arch} VM archive(s) verified` : "verified"}${warn ? ` · ${warn}` : ""}`;
437	  });
438	
439	  // Dumpdir contents → newest archive per guest vmid.
440	  const guestsMap = new Map<number, PlatformGuest>();
441	  let totalArchives = 0;
442	  let totalBytes = 0;
443	  let dirReadable = false;
444	  try {
445	    const files = await fs.readdir(PLATFORM_DIR);
446	    dirReadable = true;
447	    for (const file of files) {
448	      const vmid = vmidFromArchive(file);
449	      if (vmid === null) continue;
450	      let mtimeMs = 0;
451	      let size = 0;
452	      try {
453	        const st = await fs.stat(path.join(PLATFORM_DIR, file));
454	        mtimeMs = st.mtimeMs;
455	        size = st.size;
456	      } catch {
457	        continue;
458	      }
459	      totalArchives++;
460	      totalBytes += size;
461	      const age = Math.max(0, now - mtimeMs);
462	      const cur = guestsMap.get(vmid);
463	      if (!cur) {
464	        guestsMap.set(vmid, { vmid, count: 1, newestAgeMs: age, newestFile: file, totalBytes: size });
465	      } else {
466	        cur.count++;
467	        cur.totalBytes += size;
468	        if (age < cur.newestAgeMs) {
469	          cur.newestAgeMs = age;
470	          cur.newestFile = file;
471	        }
472	      }
473	    }
474	  } catch {
475	    dirReadable = false;
476	  }
477	
478	  const guests = [...guestsMap.values()].sort((a, b) => a.vmid - b.vmid);
479	  const coverageByVmid: Record<number, number> = {};
480	  for (const g of guests) coverageByVmid[g.vmid] = g.newestAgeMs;
481	
482	  const anyStatus = Boolean(vm || host || offsite || verify);
483	  return {
484	    available: anyStatus || dirReadable,
485	    statusDir: STATUS_DIR,
486	    platformDir: PLATFORM_DIR,
487	    subsystems,
488	    guests,
489	    coverageByVmid,
490	    totalArchives,
491	    totalBytes,
492	  };
493	}
494	##### lib/offsite-retention.ts
495	/**
496	 * Off-site (Mega) retention — pure decision logic for what to prune from the
497	 * Mega copy of the platform's backups.
498	 *
499	 * WHY THIS EXISTS
500	 * ----------------
501	 * `scripts/backup-offsite.sh` mirrors `/tank/backup/{db,platform}` to a Mega
502	 * account via `megatools megacopy`. megacopy's own contract (see its manpage)
503	 * is explicit: "no files are ever overwritten or removed" — it is upload-only.
504	 * That is the right default for a tool that also does one-way *downloads*, but
505	 * it means Mega storage grows forever unless something else prunes it, even
506	 * though the LOCAL copies these files came from already rotate out on a
507	 * schedule (`scripts/backup-db.sh` deletes dumps past `NXEON_DB_RETENTION_DAYS`
508	 * (14d default); `scripts/backup-vms.sh` / `backup-pve-config.sh` keep only the
509	 * newest `NXEON_*_BACKUP_KEEP` archives (3 by default)).
510	 *
511	 * The two rclone/rsync targets `backup-offsite.sh` already supports don't have
512	 * this problem: `rclone sync` and `rsync --delete` both mirror the destination
513	 * to exactly match the source, so a file pruned locally is pruned remotely on
514	 * the very next run for free. Mega is the odd one out, so it needs an explicit
515	 * prune step — this module IS that step's decision logic, kept dependency-free
516	 * (no fs, no child_process, no clock — `now` is always passed in) so it can be
517	 * unit tested without a Mega account, a filesystem, or `megatools` installed.
518	 *
519	 * TWO RULES, applied together:
520	 *
521	 *  1. MIRROR: delete any remote file whose name is no longer present in the
522	 *     local source directory. This is the primary mechanism — it makes the
523	 *     Mega copy track whatever the LOCAL retention policy already decided,
524	 *     exactly like the rclone/rsync paths do implicitly. No day-count guessing
525	 *     needed; it just follows local truth.
526	 *  2. AGE CAP: delete any remote file older than `maxAgeDays`, regardless of
527	 *     local state. This is a defence-in-depth backstop for the case the mirror
528	 *     rule can't reach — e.g. `OFFSITE_INCLUDE_VMS` was flipped off after
529	 *     having been on for a while, so the VM archives it already shipped are no
530	 *     longer represented by anything in the local source directory the next
531	 *     run even looks at, and would otherwise never be revisited.
532	 *
533	 * `scripts/backup-offsite.sh` currently wires up rule 1 only (it has no
534	 * reliable way to get parsed per-file timestamps out of `megals` without a live
535	 * account to verify the exact output format against — see the script's MEGA
536	 * section comment). Rule 2 is implemented and tested here so the policy is
537	 * defined precisely and ready to wire in once that's verified live.
538	 */
539	
540	/** One file as it exists in Mega right now. */
541	export type RemoteFile = {
542	  name: string;
543	  /** Last-modified time, epoch ms. */
544	  mtimeMs: number;
545	};
546	
547	/**
548	 * Default retention window for the Mega copy, in days.
549	 *
550	 * ASSUMPTION (flagged — could not be verified without real Mega credentials):
551	 * chosen to match the local PREMIUM backup tier's "keep a month" precedent
552	 * (see `lib/backup-tiers.ts` PREMIUM = keep 30 daily archives), which is also
553	 * comfortably inside Mega's smallest paid tier (Mega Pro Lite, 2TB as of this
554	 * writing) for this platform's current backup volume (~183GB in
555	 * /tank/backup at time of writing per `df -h /tank/backup`). If the Mega
556	 * account in use is a free 20GB account, or the platform's backup volume grows
557	 * materially, this default should be revisited — it is a policy knob, not a
558	 * hard limit enforced anywhere else.
559	 */
560	export const MEGA_OFFSITE_RETENTION_DAYS = 30;
561	
562	export type MegaRetentionPlan = {
563	  /** Remote names to keep (present locally and inside the age cap). */
564	  keep: string[];
565	  /** Remote names to delete because no local file of that name exists. */
566	  deleteOrphaned: string[];
567	  /** Remote names to delete because they exceeded the age cap (rule 2). */
568	  deleteExpired: string[];
569	};
570	
571	/**
572	 * Compute what should be deleted from the Mega copy of ONE label directory
573	 * (e.g. "db", "host-config", "vms" — see backup-offsite.sh's `sync_one`).
574	 *
575	 * `localNames` is every file basename currently in the local source dir for
576	 * this label (what megacopy would upload from, right now). `remoteFiles` is
577	 * everything megatools reports it holds for this label. A name that is both
578	 * local and inside the age cap is kept; everything else is deleted, orphaned
579	 * names taking priority in the return shape (a name can only match one rule —
580	 * dedup below picks orphaned first since "no longer wanted locally" is the
581	 * stronger signal than "old but still the current file").
582	 */
583	export function megaRetentionPlan(opts: {
584	  localNames: readonly string[];
585	  remoteFiles: readonly RemoteFile[];
586	  now: number;
587	  maxAgeDays?: number;
588	}): MegaRetentionPlan {
589	  const maxAgeDays = opts.maxAgeDays ?? MEGA_OFFSITE_RETENTION_DAYS;
590	  const maxAgeMs = Math.max(0, maxAgeDays) * 24 * 60 * 60 * 1000;
591	  const localSet = new Set(opts.localNames);
592	
593	  const keep: string[] = [];
594	  const deleteOrphaned: string[] = [];
595	  const deleteExpired: string[] = [];
596	
597	  for (const f of opts.remoteFiles) {
598	    if (!localSet.has(f.name)) {
599	      deleteOrphaned.push(f.name);
600	      continue;
601	    }
602	    const ageMs = opts.now - f.mtimeMs;
603	    if (ageMs > maxAgeMs) {
604	      deleteExpired.push(f.name);
605	      continue;
606	    }
607	    keep.push(f.name);
608	  }
609	
610	  return { keep, deleteOrphaned, deleteExpired };
611	}
612	
613	/** Convenience: every name a plan says to delete, orphaned first. */
614	export function namesToDelete(plan: MegaRetentionPlan): string[] {
615	  return [...plan.deleteOrphaned, ...plan.deleteExpired];
616	}
617	##### lib/backup-upgrade.ts
618	/**
619	 * Mid-term BACKUP TIER upgrade — the money path for raising ONE server's backup
620	 * RETENTION tier (FREE keep 2 -> PLUS keep 7) without touching its plan.
621	 *
622	 * Deliberately mirrors lib/disk-expand.ts line-for-line so the two paid-upgrade
623	 * money paths cannot drift apart:
624	 *   - `backupUpgradeQuote` is the ONLY place the prorated amount is computed, and
625	 *     both the display (server page card) and the charge (applyBackupUpgrade) call
626	 *     it, so the figure shown === the figure debited.
627	 *   - `applyBackupUpgrade` debits the wallet and applies the tier inside ONE
628	 *     $transaction: a rolled-back debit leaves the tier unchanged, and a tier that
629	 *     was applied was always paid for. It re-checks the current tier INSIDE the tx
630	 *     before debiting, so a double-submit can never double-charge.
631	 *
632	 * Two deliberate differences from disk-expand:
633	 *   1. WALLET-ONLY in the MVP (no Stripe mid-term checkout route — deferred to the
634	 *      full build). A customer with no balance can still buy Plus on card at ORDER
635	 *      time through lib/order.ts.
636	 *   2. NO worker job. Unlike growing a disk, retention is just a column the next
637	 *      scheduled prune reads (worker/index.ts backupCreate), so the tier is applied
638	 *      inline and takes effect on the next backup — nothing to reconcile.
639	 *
640	 * UPGRADE-ONLY: there is no downgrade path (baseline FREE is never taken away and no
641	 * refund logic exists here). Game servers are REJECTED — renewalCharge prices a game
642	 * plan as flat all-in with NO add-on lines, so granting one a paid tier would sell a
643	 * tier the renewal engine never bills (the "never grant a paid tier without payment"
644	 * invariant, in reverse).
645	 */
646	import { db } from "./db";
647	import { debitWallet, InsufficientBalanceError } from "./wallet";
648	import { invoiceCreateData } from "./invoices";
649	import { getSettingInt } from "./settings";
650	import { remainingMonths } from "./proration";
651	import {
652	  type BackupTier,
653	  BACKUP_PLUS_DEFAULT_PRICE_CENTS,
654	  backupTierMonthlyCents,
655	  backupTierSpec,
656	} from "./backup-tiers";
657	
658	export class BackupUpgradeError extends Error {}
659	
660	/**
661	 * The Plus monthly price actually charged, from the admin setting
662	 * (`backup_plus_price_cents`, default 299 = $2.99/mo). Single source of truth for
663	 * the order-time upsell, this mid-term upgrade and every renewal, so they cannot
664	 * disagree.
665	 */
666	export async function backupPlusMonthlyCents(): Promise<number> {
667	  const v = await getSettingInt("backup_plus_price_cents", BACKUP_PLUS_DEFAULT_PRICE_CENTS);
668	  return Math.max(0, Math.round(v));
669	}
670	
671	function loadServer(serverId: string) {
672	  return db.server.findUnique({ where: { id: serverId } });
673	}
674	type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
675	
676	export type BackupUpgradeQuote = {
677	  server: QuotedServer;
678	  targetTier: BackupTier;
679	  /** Resolved retention the tier grants. */
680	  keep: number;
681	  /** Recurring monthly cost of the tier (billed every renewal). */
682	  monthlyCents: number;
683	  /** One-off charge for the remainder of the CURRENT paid term (0 for free/admin). */
684	  prorateCents: number;
685	};
686	
687	/**
688	 * Validate an upgrade and compute the prorated charge over the ACTUAL remaining
689	 * term — identical maths to diskExpandQuote (monthly cost x every remaining month;
690	 * null expiresAt on free/admin servers => 0). Throws BackupUpgradeError on any guard
691	 * failure. Does NOT check ownership — callers must.
692	 */
693	export async function backupUpgradeQuote(
694	  serverId: string,
695	  targetTier: BackupTier,
696	): Promise<BackupUpgradeQuote> {
697	  const server = await loadServer(serverId);
698	  if (!server) throw new BackupUpgradeError("Not found");
699	  if (server.gamePlanId) {
700	    throw new BackupUpgradeError("Backup tiers aren't available for game servers yet.");
701	  }
702	  if (targetTier !== "PLUS") throw new BackupUpgradeError("That backup tier isn't available.");
703	  if (server.backupTier === targetTier) {
704	    throw new BackupUpgradeError("This server is already on that backup tier.");
705	  }
706	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
707	    throw new BackupUpgradeError("Server is busy — wait for the current operation to finish.");
708	  }
709	
710	  const spec = backupTierSpec(targetTier);
711	  const monthlyCents = backupTierMonthlyCents(targetTier, await backupPlusMonthlyCents());
712	  // Remaining-term maths from the SHARED lib/proration.ts helper (same as
713	  // extraDiskProrateCents) so the card's figure and this debit are one derivation.
714	  let prorateCents = 0;
715	  if (!server.isFree && server.expiresAt) {
716	    prorateCents = Math.max(0, Math.round(monthlyCents * remainingMonths(server.expiresAt, Date.now())));
717	  }
718	  return { server, targetTier, keep: spec.keep, monthlyCents, prorateCents };
719	}
720	
721	/**
722	 * Apply the upgrade: (optionally) debit the wallet for the prorated charge, record
723	 * the wallet transaction + PAID invoice, and stamp the tier + resolved retention on
724	 * the server — all in ONE $transaction. `chargeCents` overrides the recomputed
725	 * proration for a caller that already collected an exact amount (parity with
726	 * applyDiskExpand, unused in the wallet-only MVP). Throws BackupUpgradeError on any
727	 * guard failure or insufficient balance.
728	 */
729	export async function applyBackupUpgrade(opts: {
730	  serverId: string;
731	  targetTier: BackupTier;
732	  actorUserId: string;
733	  chargeCents?: number;
734	}): Promise<void> {
735	  const quote = await backupUpgradeQuote(opts.serverId, opts.targetTier);
736	  const { server, targetTier, keep, monthlyCents } = quote;
737	  const prorateCents = opts.chargeCents ?? quote.prorateCents;
738	  const spec = backupTierSpec(targetTier);
739	  const label = `${spec.label} backups (keep ${keep})`;
740	
741	  try {
742	    await db.$transaction(async (tx) => {
743	      // Re-read the tier INSIDE the tx before any money moves: two concurrent
744	      // upgrades (a double-click) both quote FREE, but only the first commits PLUS;
745	      // the second sees PLUS here and aborts before debiting — no double charge.
746	      const fresh = await tx.server.findUnique({
747	        where: { id: server.id },
748	        select: { backupTier: true, status: true },
749	      });
750	      if (!fresh) throw new BackupUpgradeError("Not found");
751	      if (fresh.backupTier === targetTier) {
752	        throw new BackupUpgradeError("This server is already on that backup tier.");
753	      }
754	      if (!["RUNNING", "STOPPED"].includes(fresh.status)) {
755	        throw new BackupUpgradeError("Server is busy — wait for the current operation to finish.");
756	      }
757	
758	      if (prorateCents > 0) {
759	        await debitWallet(tx, server.userId, prorateCents);
760	        await tx.walletTransaction.create({
761	          data: {
762	            userId: server.userId,
763	            amountCents: -prorateCents,
764	            description: `${label} (prorated) — ${server.hostname}`,
765	          },
766	        });
767	        await tx.invoice.create({
768	          data: invoiceCreateData({
769	            userId: server.userId,
770	            description: `${label} (prorated) — ${server.hostname}`,
771	            status: "PAID",
772	            lineItems: [
773	              {
774	                description:
775	                  `${label} — prorated for remaining term (${server.hostname}). ` +
776	                  `Renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
777	                qty: 1,
778	                unitCents: prorateCents,
779	                amountCents: prorateCents,
780	              },
781	            ],
782	          }),
783	        });
784	      }
785	      // Apply the tier + resolved retention, and make sure backups actually RUN —
786	      // retention is meaningless without a schedule, so bridge to the columns the
787	      // scheduler (worker/backup-schedule.ts) reads, exactly as the order path does.
788	      await tx.server.update({
789	        where: { id: server.id },
790	        data: {
791	          backupTier: targetTier,
792	          backupKeep: keep,
793	          autoBackup: true,
794	          backupIntervalHours: spec.intervalHours,
795	        },
796	      });
797	      await tx.auditLog.create({
798	        data: {
799	          userId: opts.actorUserId,
800	          action: "server.backup_upgrade",
801	          detail: `${server.id} -> ${targetTier} keep=${keep} prorate=${prorateCents}`,
802	        },
803	      });
804	    });
805	  } catch (e) {
806	    if (e instanceof InsufficientBalanceError) {
807	      throw new BackupUpgradeError("Insufficient balance — top up your wallet first.");
808	    }
809	    throw e;
810	  }
811	}
812	##### lib/backup-verify.ts
813	/**
814	 * Backup PROOF rules — the pure decision logic that stands between "the vzdump
815	 * task returned" and telling a customer they have a restore point.
816	 *
817	 * INCIDENT (customer-journey rehearsal 2026-07-26, finding H4): `lastAutoBackup`
818	 * was stamped at the moment the BACKUP_CREATE job row was ENQUEUED, and written
819	 * nowhere else. So "Last automatic backup: 2026-07-26 04:00 UTC" only ever meant
820	 * *a row was created*. vzdump could have failed every night for a month with no
821	 * alert, no failure notification, and the schedule marked satisfied — so the
822	 * retry was a full interval away and the customer found out at restore time, the
823	 * one moment it cannot be fixed. The deploy wizard SELLS this at the point of
824	 * sale ("Daily auto-backups · Nightly snapshots to separate storage for easy
825	 * restore").
826	 *
827	 * The rules now:
828	 *
829	 *   - `Server.lastAutoBackup` is a PROOF timestamp. It is written in exactly one
830	 *     place — `backupCreate` in worker/index.ts — after a storage-content read
831	 *     shows an archive for this VMID that was NOT there before the run and has
832	 *     size > 0. An exit code from the vzdump task is not evidence.
833	 *   - The sweep's anti-pile-up anchor is the last ATTEMPT, read from the Job
834	 *     table. That is a fact we can observe without claiming anything about the
835	 *     outcome.
836	 *   - Absence is rendered, not hidden: `backupScheduleHealth` is the single
837	 *     source of the sentence the customer reads under "Scheduled backups".
838	 *
839	 * Deterministic and dependency-free on purpose: no Prisma, no Proxmox, no clock
840	 * (every entry point takes `now`). Covered by test/backup-proof.test.ts.
841	 */
842	
843	// ---------------------------------------------------------------------------
844	// Proof
845	// ---------------------------------------------------------------------------
846	
847	/** The subset of a Proxmox storage-content row this module reasons about. */
848	export type BackupArchive = {
849	  volid?: string;
850	  vmid?: number;
851	  size?: number;
852	  ctime?: number;
853	};
854	
855	export type BackupProof =
856	  | { proven: true; volid: string; sizeBytes: number }
857	  | { proven: false; reason: string };
858	
859	/** Human-sized bytes for notification/log copy. */
860	export function humanBytes(n: number): string {
861	  if (!Number.isFinite(n) || n < 0) return "unknown size";
862	  const units = ["B", "KB", "MB", "GB", "TB"];
863	  let v = n;
864	  let i = 0;
865	  while (v >= 1024 && i < units.length - 1) {
866	    v /= 1024;
867	    i++;
868	  }
869	  return `${i === 0 ? v : v.toFixed(1)} ${units[i]}`;
870	}
871	
872	/**
873	 * Did THIS run demonstrably write a backup?
874	 *
875	 * Evidence is a volid present in `after` that was absent from `before`, carrying
876	 * a non-zero size. Set membership rather than a timestamp comparison on purpose:
877	 * `ctime` comes off the hypervisor and any window we computed would come off the
878	 * worker's clock, and skew between the two is exactly the kind of thing that
879	 * turns a proof back into a guess. A volid that was not there and now is cannot
880	 * be explained away by a clock.
881	 *
882	 * Every failure returns the reason AND the command an operator can run, because
883	 * "backup failed" with no next step is barely better than the silence it
884	 * replaced.
885	 */
886	export function freshBackupProof(opts: {
887	  vmid: number;
888	  before: readonly BackupArchive[];
889	  after: readonly BackupArchive[];
890	}): BackupProof {
891	  const { vmid } = opts;
892	  const check = `Check it yourself with: pvesm list backup --vmid ${vmid}`;
893	  const seen = new Set<string>();
894	  for (const b of opts.before) {
895	    if (b.vmid === vmid && typeof b.volid === "string") seen.add(b.volid);
896	  }
897	
898	  const fresh = opts.after.filter(
899	    (b) => b.vmid === vmid && typeof b.volid === "string" && !seen.has(b.volid)
900	  );
901	
902	  if (fresh.length === 0) {
903	    return {
904	      proven: false,
905	      reason:
906	        `the vzdump task finished but no new archive for VMID ${vmid} appeared in the ` +
907	        `"backup" storage, so nothing was written and there is no restore point from this run. ` +
908	        check,
909	    };
910	  }
911	
912	  // Prefer the largest new archive: if a run somehow left a truncated stub beside
913	  // a good one, the good one is the honest answer.
914	  const sized = fresh
915	    .filter((b) => typeof b.size === "number" && Number.isFinite(b.size))
916	    .sort((a, b) => (b.size ?? 0) - (a.size ?? 0));
917	
918	  if (sized.length === 0) {
919	    return {
920	      proven: false,
921	      reason:
922	        `a new archive for VMID ${vmid} appeared (${fresh[0].volid}) but the storage listing ` +
923	        `reported no size for it, so we cannot confirm it contains anything. ` +
924	        `Not recording a backup we cannot prove. ` +
925	        check,
926	    };
927	  }
928	
929	  const best = sized[0];
930	  if ((best.size ?? 0) <= 0) {
931	    return {
932	      proven: false,
933	      reason:
934	        `a new archive for VMID ${vmid} appeared (${best.volid}) but it is 0 bytes — ` +
935	        `an empty file is not a backup and would fail at restore time. ` +
936	        check,
937	    };
938	  }
939	
940	  return { proven: true, volid: best.volid!, sizeBytes: best.size! };
941	}
