943	// ---------------------------------------------------------------------------
944	// Scheduling
945	// ---------------------------------------------------------------------------
946	
947	/**
948	 * Is another automatic backup due?
949	 *
950	 * Anchored on the last ATTEMPT, never on the last SUCCESS. Anchoring on success
951	 * looks more correct and is a trap: a server whose backups always fail has no
952	 * success to anchor to, so it would be "due" on every 15-minute sweep pass
953	 * forever — hammering a sick VM and burying the rest of the fleet's queue behind
954	 * it. The attempt is a fact; the outcome is what we refuse to assume.
955	 */
956	export function isAutoBackupDue(opts: {
957	  now: number;
958	  intervalHours: number | null;
959	  lastAttemptAt: Date | null;
960	}): boolean {
961	  const hours = opts.intervalHours ?? 0;
962	  if (!(hours > 0)) return false;
963	  if (!opts.lastAttemptAt) return true;
964	  return opts.now >= opts.lastAttemptAt.getTime() + hours * 60 * 60_000;
965	}
966	
967	export type BackupHealthState = "off" | "ok" | "pending" | "never" | "stale" | "failing";
968	export type BackupHealth = { state: BackupHealthState; detail: string };
969	
970	/** How many intervals may elapse with no verified backup before we call it stale. */
971	export const STALE_INTERVAL_MULTIPLE = 2;
972	
973	function stamp(d: Date): string {
974	  return d.toISOString().slice(0, 16).replace("T", " ") + " UTC";
975	}
976	
977	/**
978	 * The one sentence the customer reads under "Scheduled backups", and the same
979	 * one the sweep logs for the operator. It must never imply a restore point that
980	 * was not proved.
981	 *
982	 * `lastVerifiedAt` is `Server.lastAutoBackup`, which since H4 means "an archive
983	 * was observed in storage at this time" — not "a job was queued at this time".
984	 */
985	export function backupScheduleHealth(opts: {
986	  now: number;
987	  autoBackup: boolean;
988	  intervalHours: number | null;
989	  lastVerifiedAt: Date | null;
990	  lastAttempt: { at: Date; status: string } | null;
991	}): BackupHealth {
992	  const hours = opts.intervalHours ?? 0;
993	  if (!opts.autoBackup || !(hours > 0)) {
994	    return { state: "off", detail: "Scheduled backups are off for this server." };
995	  }
996	
997	  const verified = opts.lastVerifiedAt;
998	  const verifiedLine = verified
999	    ? `The most recent backup we can prove exists is from ${stamp(verified)}.`
1000	    : "No automatic backup has ever been verified for this server, so the schedule has produced no restore point.";
1001	
1002	  // Ordered by what the customer stands to lose, not by tidiness: a failing
1003	  // schedule outranks a stale one, which outranks "we have never seen one".
1004	  if (opts.lastAttempt?.status === "FAILED") {
1005	    return {
1006	      state: "failing",
1007	      detail:
1008	        `The last automatic backup attempt (${stamp(opts.lastAttempt.at)}) FAILED. ` +
1009	        `${verifiedLine} Open a ticket if this repeats — do not assume tonight's run will fix it.`,
1010	    };
1011	  }
1012	
1013	  if (!verified) {
1014	    if (!opts.lastAttempt) {
1015	      return {
1016	        state: "pending",
1017	        detail: "No automatic backup has run yet — the first one is queued by the next sweep.",
1018	      };
1019	    }
1020	    return {
1021	      state: "never",
1022	      detail:
1023	        `Automatic backups have been attempted since ${stamp(opts.lastAttempt.at)}, but none has ` +
1024	        "been verified to exist in storage. Do not rely on having a restore point.",
1025	    };
1026	  }
1027	
1028	  const overdueAfter = verified.getTime() + hours * 60 * 60_000 * STALE_INTERVAL_MULTIPLE;
1029	  if (opts.now > overdueAfter) {
1030	    return {
1031	      state: "stale",
1032	      detail:
1033	        `${verifiedLine} That is more than ${STALE_INTERVAL_MULTIPLE} backup intervals ago, so the ` +
1034	        "schedule is not keeping up. Treat anything newer than that as unprotected.",
1035	    };
1036	  }
1037	
1038	  return { state: "ok", detail: `Last verified backup: ${stamp(verified)} (confirmed present in storage).` };
1039	}
