1047	/**
1048	 * Deployment-confirmation email helper.
1049	 *
1050	 * Sends the "your server is ready" email once a server is provisioned and
1051	 * reachable, from BOTH the provision success path (worker) and the admin
1052	 * "reconcile from Proxmox" recovery. It is deliberately:
1053	 *
1054	 *  - TRANSACTIONAL: sent with the CRITICAL `provision_ready` kind so a customer
1055	 *    preference can never suppress it (see lib/prefs.ts).
1056	 *  - DEDUPED via `EmailLog`: `EmailLog` has no `serverId` column and we add no
1057	 *    schema, so the dedupe keys on the template tag + the customer + the
1058	 *    server-unique dashboard path that the rendered HTML always contains. Only
1059	 *    a prior SENT row blocks a resend, so a failed attempt can still be retried
1060	 *    on the next reconcile/provision.
1061	 *  - BEST-EFFORT: it runs on the provision money-path, so it swallows every
1062	 *    error and NEVER throws into the caller.
1063	 */
1064	
1065	const DEPLOY_TEMPLATE = "server_deployed";
1066	
1067	type DeployedServer = {
1068	  id: string;
1069	  hostname: string;
1070	  sshPort: number | null;
1071	  userId: string;
1072	  gamePlanId?: string | null;
1073	  plan?: { name?: string | null } | null;
1074	  node?: { publicIp?: string | null } | null;
1075	  osTemplate?: { family?: string | null } | null;
1076	  portForwards?: { publicPort: number; guestPort: number }[];
1077	  dedicatedIp?: { address: string } | null;
1078	};
1079	
1080	type DeployedUser = { email?: string | null } | null | undefined;
1081	
1082	export async function sendServerDeployedEmail(
1083	  server: DeployedServer,
1084	  user: DeployedUser
1085	): Promise<void> {
1086	  try {
1087	    const email = user?.email;
1088	    if (!email) return;
1089	
1090	    const dashboardUrl = `${appUrl()}/dashboard/servers/${server.id}`;
1091	
1092	    // Per-server dedupe (see file header). The dashboard path is server-unique
1093	    // and survives EmailLog redaction (only secret query params are stripped).
1094	    const already = await db.emailLog.findFirst({
1095	      where: {
1096	        template: DEPLOY_TEMPLATE,
1097	        userId: server.userId,
1098	        status: "SENT",
1099	        html: { contains: `/dashboard/servers/${server.id}` },
1100	      },
1101	      select: { id: true },
1102	    });
1103	    if (already) return;
1104	
1105	    // ALWAYS the node's public IP + forwarded ssh port — never the internal
1106	    // 10.20.x.x address, which is unreachable from outside the host.
1107	    const host = server.node?.publicIp ?? process.env.PUBLIC_IP ?? "";
1108	    const sshEndpoint = server.sshPort ? `${host}:${server.sshPort}` : host;
1109	
1110	    const isGame = !!server.gamePlanId;
1111	    const family = server.osTemplate?.family as GameFamily | undefined;
1112	    const gameEntry = family && family in GAME_DISPLAY ? GAME_DISPLAY[family] : null;
1113	    const gamePort = family && (GAME_PORT as Record<string, { port: number }>)[family];
1114	
1115	    let gameConnect: string | undefined;
1116	    if (isGame && gamePort) {
1117	      const dedIp = server.dedicatedIp ?? await db.dedicatedIp.findFirst({ where: { serverId: server.id }, select: { address: true } });
1118	      if (dedIp) {
1119	        gameConnect = `${dedIp.address}:${gamePort.port}`;
1120	      } else {
1121	        const fwds = server.portForwards ?? await db.portForward.findMany({ where: { serverId: server.id }, select: { publicPort: true, guestPort: true } });
1122	        const fwd = fwds.find((f) => f.guestPort === gamePort.port);
1123	        if (fwd) gameConnect = `${host}:${fwd.publicPort}`;
1124	      }
1125	    }
1126	
1127	    const tpl = emails.serverDeployed({
1128	      hostname: server.hostname,
1129	      planName: server.plan?.name ?? "Nxeon",
1130	      sshEndpoint,
1131	      dashboardUrl,
1132	      gameLabel: isGame && gameEntry ? gameEntry.name : undefined,
1133	      gameConnect,
1134	    });
1135	
1136	    await sendMail({
1137	      to: email,
1138	      subject: tpl.subject,
1139	      html: tpl.html,
1140	      // Records EmailLog.template = "server_deployed" — the dedupe key above.
1141	      template: tpl.template,
1142	      userId: server.userId,
1143	      // CRITICAL kind → non-suppressible transactional delivery.
1144	      kind: "provision_ready",
1145	    });
