1204	export async function recordAudit(userId: string | null, action: string, detail?: string): Promise<void> {
1205	  // Attribute to the real admin when an admin is impersonating, so customer-scoped
1206	  // actions taken during impersonation aren't logged as if the customer did them.
1207	  const imp = await impersonating();
1208	  const actor = imp ? `actingAdmin=${imp.admin.id}` : "";
1209	  const fullDetail = detail && actor ? `${detail} ${actor}` : detail || actor || undefined;
1210	  await db.auditLog.create({ data: { userId, action, detail: fullDetail } });
1211	}
