2	/**
3	 * Inline (non-worker) quick reads for the control panel: service status and a
4	 * live process/resource snapshot. These are cheap, read-only SSH commands with a
5	 * short timeout, so they run inline from the server actions rather than via a
6	 * queued job (mirrors how lib/sftp.ts serves file listings inline).
7	 *
8	 * SANDBOX: on staging NO real SSH is ever opened — every read returns realistic,
9	 * deterministic synthetic data so the whole panel UX works end to end without a
10	 * live VM. Plain server module (no "use server"): imported by lib/actions-cron.ts.
11	 */
12	import { SANDBOX } from "./sandbox";
13	import { withServerSsh, exec, assertService, shellQuote, QUICK_TIMEOUT_MS } from "./ssh-exec";
14	import { COMMON_SERVICES, type ServiceStatus, type ProcessSnapshot } from "./cpanel-types";
15	import type { SftpServer } from "./sftp";
16	
17	/** Deterministic pseudo-random in [0,1) from a string seed (sandbox realism). */
18	function seeded(seed: string): number {
19	  let h = 2166136261;
20	  for (let i = 0; i < seed.length; i++) {
21	    h ^= seed.charCodeAt(i);
22	    h = Math.imul(h, 16777619);
23	  }
24	  return ((h >>> 0) % 10000) / 10000;
25	}
26	
27	// ---------------------------------------------------------------------------
28	// Service status
29	// ---------------------------------------------------------------------------
30	
31	/**
32	 * Status of the common services. In sandbox, nginx/ssh look running, php-fpm/
33	 * mysql installed-and-running, the rest a deterministic mix. On prod we ask
34	 * systemd for each unit in one round-trip.
35	 */
36	export async function readServiceStatuses(server: SftpServer): Promise<ServiceStatus[]> {
37	  if (SANDBOX) {
38	    return COMMON_SERVICES.map((s) => {
39	      let state: ServiceStatus["state"];
40	      if (s.unit === "nginx" || s.unit === "ssh") state = "running";
41	      else if (s.unit === "php-fpm" || s.unit === "mysql") state = "running";
42	      else state = seeded(server.id + s.unit) > 0.5 ? "running" : "not-installed";
43	      return { unit: s.unit, label: s.label, state };
44	    });
45	  }
46	
47	  return withServerSsh(server, async (conn) => {
48	    const out: ServiceStatus[] = [];
49	    for (const s of COMMON_SERVICES) {
50	      assertService(s.unit);
51	      const q = shellQuote(s.unit);
52	      // is-active prints active/inactive/failed/unknown; if the unit doesn't
53	      // exist at all, `systemctl list-unit-files` finds nothing → not-installed.
54	      const r = await exec(
55	        conn,
56	        `if systemctl list-unit-files ${q}.service >/dev/null 2>&1 || systemctl status ${q} >/dev/null 2>&1; then ` +
57	          `systemctl is-active ${q} 2>/dev/null || echo inactive; else echo missing; fi`,
58	        QUICK_TIMEOUT_MS
59	      );
60	      const v = r.stdout.trim();
61	      let state: ServiceStatus["state"];
62	      if (v === "active") state = "running";
63	      else if (v === "missing") state = "not-installed";
64	      else if (v === "inactive" || v === "failed") state = "stopped";
65	      else state = "unknown";
66	      out.push({ unit: s.unit, label: s.label, state });
67	    }
68	    return out;
69	  });
70	}
71	
72	// ---------------------------------------------------------------------------
73	// Process / resource snapshot
74	// ---------------------------------------------------------------------------
75	
76	const SANDBOX_COMMANDS = [
77	  "nginx: worker process",
78	  "php-fpm: pool www",
79	  "mysqld",
80	  "node /var/www/app/server.js",
81	  "redis-server *:6379",
82	  "systemd --user",
83	  "sshd: root@pts/0",
84	];
85	
86	export async function readProcessSnapshot(server: SftpServer): Promise<ProcessSnapshot> {
87	  if (SANDBOX) {
88	    const base = seeded(server.id);
89	    const cpuPct = Math.round((15 + base * 55) * 10) / 10;
90	    const memTotalMB = 4096;
91	    const memUsedMB = Math.round(memTotalMB * (0.35 + base * 0.4));
92	    const diskTotalGB = 80;
93	    const diskUsedGB = Math.round(diskTotalGB * (0.2 + base * 0.5) * 10) / 10;
94	    const top = SANDBOX_COMMANDS.map((command, i) => ({
95	      pid: 400 + i * 137 + Math.floor(seeded(server.id + i) * 90),
96	      user: i % 3 === 0 ? "root" : "www-data",
97	      cpu: Math.round(seeded(server.id + "c" + i) * 40 * 10) / 10,
98	      mem: Math.round(seeded(server.id + "m" + i) * 12 * 10) / 10,
99	      command,
100	    }))
101	      .sort((a, b) => b.cpu - a.cpu)
102	      .slice(0, 6);
103	    return {
104	      cpuPct,
105	      memUsedMB,
106	      memTotalMB,
107	      diskUsedGB,
108	      diskTotalGB,
109	      loadAvg: [
110	        Math.round(base * 2 * 100) / 100,
111	        Math.round(base * 1.6 * 100) / 100,
112	        Math.round(base * 1.2 * 100) / 100,
113	      ],
114	      uptimeSec: Math.floor(3600 * 24 * (2 + base * 20)),
115	      top,
116	    };
117	  }
118	
119	  return withServerSsh(server, async (conn) => {
120	    // One fixed command bundle — no user input anywhere. Emits labelled lines we
121	    // parse below; robust to missing tools (best-effort fields).
122	    const script =
123	      "echo '#LOAD'; cat /proc/loadavg 2>/dev/null; " +
124	      "echo '#UP'; cat /proc/uptime 2>/dev/null; " +
125	      "echo '#MEM'; free -m 2>/dev/null | awk '/^Mem:/{print $2, $3}'; " +
126	      "echo '#DISK'; df -BG / 2>/dev/null | awk 'NR==2{gsub(/G/,\"\"); print $2, $3}'; " +
127	      "echo '#CPU'; awk '/^cpu /{u=$2+$4; t=$2+$4+$5; print u, t}' /proc/stat 2>/dev/null; " +
128	      "echo '#TOP'; ps -eo pid,user,pcpu,pmem,comm --sort=-pcpu 2>/dev/null | head -n 8";
129	    const r = await exec(conn, script, QUICK_TIMEOUT_MS);
130	    return parseSnapshot(r.stdout);
131	  });
132	}
133	
134	/** Parse the labelled snapshot output into a ProcessSnapshot (best-effort). */
135	function parseSnapshot(out: string): ProcessSnapshot {
136	  const sections: Record<string, string[]> = {};
137	  let cur = "";
138	  for (const raw of out.split("\n")) {
139	    const line = raw.trimEnd();
140	    if (line.startsWith("#")) {
141	      cur = line.slice(1);
142	      sections[cur] = [];
143	    } else if (cur && line.trim().length) {
144	      sections[cur].push(line);
145	    }
146	  }
147	  const num = (s: string | undefined, d = 0) => {
148	    const n = Number(s);
149	    return Number.isFinite(n) ? n : d;
150	  };
151	
152	  const load = (sections.LOAD?.[0] ?? "").split(/\s+/);
153	  const loadAvg: [number, number, number] = [num(load[0]), num(load[1]), num(load[2])];
154	  const uptimeSec = Math.floor(num((sections.UP?.[0] ?? "").split(/\s+/)[0]));
155	  const mem = (sections.MEM?.[0] ?? "").split(/\s+/);
156	  const memTotalMB = num(mem[0], 1);
157	  const memUsedMB = num(mem[1]);
158	  const disk = (sections.DISK?.[0] ?? "").split(/\s+/);
159	  const diskTotalGB = num(disk[0], 1);
160	  const diskUsedGB = num(disk[1]);
161	  const cpu = (sections.CPU?.[0] ?? "").split(/\s+/);
162	  const cpuBusy = num(cpu[0]);
163	  const cpuTotal = num(cpu[1], 1);
164	  const cpuPct = Math.round(Math.min(100, (cpuBusy / cpuTotal) * 100) * 10) / 10;
165	
166	  const top = (sections.TOP ?? [])
167	    .filter((l) => !/^\s*PID\b/i.test(l))
168	    .map((l) => {
169	      const p = l.trim().split(/\s+/);
170	      return {
171	        pid: num(p[0]),
172	        user: p[1] ?? "?",
173	        cpu: num(p[2]),
174	        mem: num(p[3]),
175	        command: p.slice(4).join(" ") || "?",
176	      };
177	    })
178	    .slice(0, 6);
179	
180	  return { cpuPct, memUsedMB, memTotalMB, diskUsedGB, diskTotalGB, loadAvg, uptimeSec, top };
181	}
