368	// Single source of truth for how Claude Code (the Anthropic CLI) is installed on
369	// a Nxeon guest VM. Both paths use these SAME steps:
370	//   1. new servers  — worker/index.ts bakes them into cloud-init (buildCloudInit)
371	//   2. old servers  — lib/claude-backfill.ts runs them over SSH (task #73)
372	// so a change to the install logic can never drift between the two.
373	//
374	// The steps are idempotent: re-running them on a box that already has `claude`
375	// is a no-op that simply re-confirms the binary and re-writes the marker file.
376	
377	/** The install steps as individual shell lines (no shebang). */
378	export const CLAUDE_CLI_INSTALL_STEPS: string[] = [
379	  "# --- Nxeon: install Claude Code (Anthropic CLI) ---",
380	  "(apt-get install -y git curl ca-certificates || dnf install -y git curl ca-certificates || true)",
381	  // 1) Official native installer first — no Node needed, lands in ~/.local/bin.
382	  "curl -fsSL https://claude.ai/install.sh | bash || true",
383	  // 2) npm fallback only if the native install didn't produce a binary.
384	  "if ! command -v claude >/dev/null 2>&1 && [ ! -x /root/.local/bin/claude ]; then " +
385	    "if ! command -v node >/dev/null 2>&1; then " +
386	    "(curl -fsSL https://deb.nodesource.com/setup_20.x | bash - && apt-get install -y nodejs) || " +
387	    "(curl -fsSL https://rpm.nodesource.com/setup_20.x | bash - && dnf install -y nodejs) || " +
388	    "(apt-get install -y nodejs npm || true); fi; " +
389	    "npm install -g @anthropic-ai/claude-code || true; fi",
390	  // 3) Put it on the interactive PATH wherever it landed, so `claude` just works.
391	  "for p in /root/.local/bin/claude /usr/local/bin/claude /usr/bin/claude \"$(command -v claude 2>/dev/null)\"; do " +
392	    "[ -n \"$p\" ] && [ -x \"$p\" ] && ln -sf \"$p\" /usr/local/bin/claude && break; done",
393	  // 4) Record the TRUE outcome — the MOTD reads this so it never claims an install
394	  //    that did not happen (a failed install must not read as success).
395	  "if command -v claude >/dev/null 2>&1 || [ -x /usr/local/bin/claude ]; then " +
396	    "echo 'ok' > /root/.nxeon-claude-installed; else " +
397	    "echo 'failed' > /root/.nxeon-claude-installed; fi",
398	];
