400	/** A single runnable bash script for the backfill path (SSH `exec`). */
401	export function claudeInstallScript(): string {
402	  return ["#!/bin/bash", "set -x", ...CLAUDE_CLI_INSTALL_STEPS].join("\n");
403	}
