409	/**
410	 * Pure, dependency-free model for the Claude Code `--output-format stream-json`
411	 * event stream, plus the `--input-format stream-json` encoder.
412	 *
413	 * This is how the Matrix "chat" console drives `claude` on a customer's own
414	 * server WITHOUT a raw terminal: the CLI runs headless in stream-json mode, emits
415	 * newline-delimited JSON events on stdout, and reads newline-delimited user
416	 * messages on stdin. This module turns those raw events into a small, stable UI
417	 * event model the React renderer consumes, and encodes user turns for stdin.
418	 *
419	 * It has NO side effects and NO I/O, so every branch is unit-tested directly
420	 * (test/claude-stream.test.ts). The websocket bridge (terminal-server) stays
421	 * dumb — it forwards raw NDJSON lines — and all parsing happens here, on the
422	 * client, against these shapes.
423	 *
424	 * Wire format reference (Claude Code CLI, current): system/init, assistant,
425	 * user (tool_result), stream_event (partial deltas), result, system/api_retry,
426	 * and error events. Shapes are read defensively — unknown fields are ignored and
427	 * unknown event types yield nothing rather than throwing.
428	 */
429	
430	/** A raw parsed stream-json line: any object with a string `type`. */
431	export type RawStreamEvent = { type: string; [k: string]: unknown };
432	
433	/** Parse one NDJSON line into a raw event, or null if blank / not an event. */
434	export function parseStreamLine(line: string): RawStreamEvent | null {
435	  const trimmed = line.trim();
436	  if (!trimmed) return null;
437	  let obj: unknown;
438	  try {
439	    obj = JSON.parse(trimmed);
440	  } catch {
441	    return null;
442	  }
443	  if (obj && typeof obj === "object" && typeof (obj as { type?: unknown }).type === "string") {
444	    return obj as RawStreamEvent;
445	  }
446	  return null;
447	}
448	
449	/* -------------------------------------------------------------------------- */
450	/* UI event model — the small, stable shape the renderer consumes.            */
451	/* -------------------------------------------------------------------------- */
452	
453	export type AgentUiEvent =
454	  /** Session started — carries the session id + model + available tool names. */
455	  | { kind: "session"; sessionId: string; model: string | null; tools: string[] }
456	  /** A complete assistant text block (authoritative; supersedes any partial). */
457	  | { kind: "assistant_text"; text: string }
458	  /** Claude decided to use a tool. */
459	  | { kind: "tool_use"; id: string; name: string; input: unknown }
460	  /** The result of a tool call, matched back to its tool_use by id. */
461	  | { kind: "tool_result"; toolUseId: string; content: string; isError: boolean }
462	  /** A streaming token delta (only with --include-partial-messages). */
463	  | { kind: "text_delta"; text: string }
464	  /** The turn finished. */
465	  | {
466	      kind: "result";
467	      isError: boolean;
468	      text: string | null;
469	      costUsd: number | null;
470	      durationMs: number | null;
471	      numTurns: number | null;
472	    }
473	  /** A transient, non-fatal notice (e.g. an API retry). */
474	  | { kind: "notice"; text: string }
475	  /** A fatal/error event from the stream. */
476	  | { kind: "error"; message: string };
477	
478	type ContentBlock = {
479	  type?: string;
480	  text?: unknown;
481	  id?: unknown;
482	  name?: unknown;
483	  input?: unknown;
484	  tool_use_id?: unknown;
485	  content?: unknown;
486	  is_error?: unknown;
487	};
488	
489	/** Pull a content-block array from an event, tolerating the nested `message` shape. */
490	function contentBlocks(ev: RawStreamEvent): ContentBlock[] {
491	  const direct = ev.content;
492	  const nested = (ev.message as { content?: unknown } | undefined)?.content;
493	  const arr = Array.isArray(direct) ? direct : Array.isArray(nested) ? nested : null;
494	  return arr ? (arr as ContentBlock[]) : [];
495	}
496	
497	/** Tool results can be a bare string or an array of text/… blocks — flatten to text. */
498	function toolResultText(content: unknown): string {
499	  if (typeof content === "string") return content;
500	  if (Array.isArray(content)) {
501	    return content
502	      .map((b) => {
503	        if (typeof b === "string") return b;
504	        if (b && typeof b === "object" && typeof (b as { text?: unknown }).text === "string") {
505	          return (b as { text: string }).text;
506	        }
507	        return "";
508	      })
509	      .join("");
510	  }
511	  return "";
512	}
513	
514	function toolNames(tools: unknown): string[] {
515	  if (!Array.isArray(tools)) return [];
516	  return tools
517	    .map((t) => {
518	      if (typeof t === "string") return t;
519	      if (t && typeof t === "object" && typeof (t as { name?: unknown }).name === "string") {
520	        return (t as { name: string }).name;
521	      }
522	      return "";
523	    })
524	    .filter(Boolean);
525	}
526	
527	function numberOrNull(v: unknown): number | null {
528	  return typeof v === "number" && Number.isFinite(v) ? v : null;
529	}
530	
531	/**
532	 * Normalize a raw stream event into 0+ UI events. One raw event can yield
533	 * several (an assistant turn with text + two tool calls → three UI events).
534	 * Unknown event types return [] — the UI simply doesn't render them.
535	 */
536	export function normalizeStreamEvent(ev: RawStreamEvent): AgentUiEvent[] {
537	  switch (ev.type) {
538	    case "system": {
539	      if (ev.subtype === "init") {
540	        return [
541	          {
542	            kind: "session",
543	            sessionId: typeof ev.session_id === "string" ? ev.session_id : "",
544	            model: typeof ev.model === "string" ? ev.model : null,
545	            tools: toolNames(ev.tools),
546	          },
547	        ];
548	      }
549	      if (ev.subtype === "api_retry") {
550	        const attempt = numberOrNull(ev.attempt);
551	        const max = numberOrNull(ev.max_retries);
552	        const suffix = attempt && max ? ` (attempt ${attempt}/${max})` : "";
553	        return [{ kind: "notice", text: `Retrying after an API error${suffix}…` }];
554	      }
555	      return [];
556	    }
557	
558	    case "assistant": {
559	      const out: AgentUiEvent[] = [];
560	      for (const b of contentBlocks(ev)) {
561	        if (b.type === "text" && typeof b.text === "string" && b.text.length > 0) {
562	          out.push({ kind: "assistant_text", text: b.text });
563	        } else if (b.type === "tool_use") {
564	          out.push({
565	            kind: "tool_use",
566	            id: typeof b.id === "string" ? b.id : "",
567	            name: typeof b.name === "string" ? b.name : "tool",
568	            input: b.input,
569	          });
570	        }
571	      }
572	      return out;
573	    }
574	
575	    case "user": {
576	      const out: AgentUiEvent[] = [];
577	      for (const b of contentBlocks(ev)) {
578	        if (b.type === "tool_result") {
579	          out.push({
580	            kind: "tool_result",
581	            toolUseId: typeof b.tool_use_id === "string" ? b.tool_use_id : "",
582	            content: toolResultText(b.content),
583	            isError: Boolean(b.is_error),
584	          });
585	        }
586	      }
587	      return out;
588	    }
589	
590	    case "stream_event": {
591	      const inner = ev.event as
592	        | { type?: string; delta?: { type?: string; text?: unknown } }
593	        | undefined;
594	      if (
595	        inner?.type === "content_block_delta" &&
596	        inner.delta?.type === "text_delta" &&
597	        typeof inner.delta.text === "string" &&
598	        inner.delta.text.length > 0
599	      ) {
600	        return [{ kind: "text_delta", text: inner.delta.text }];
601	      }
602	      return [];
603	    }
604	
605	    case "result": {
606	      const cost = ev.cost as { total_cost_usd?: unknown } | undefined;
607	      return [
608	        {
609	          kind: "result",
610	          isError: Boolean(ev.is_error),
611	          text: typeof ev.result === "string" ? ev.result : null,
612	          costUsd: numberOrNull(cost?.total_cost_usd),
613	          durationMs: numberOrNull(ev.duration_ms),
614	          numTurns: numberOrNull(ev.num_turns),
615	        },
616	      ];
617	    }
618	
619	    case "error": {
620	      return [
621	        {
622	          kind: "error",
623	          message: typeof ev.error === "string" ? ev.error : "Claude reported an error.",
624	        },
625	      ];
626	    }
627	
628	    default:
629	      return [];
630	  }
631	}
632	
633	/** Convenience: parse a raw NDJSON line straight to UI events (or [] if unusable). */
634	export function streamLineToUiEvents(line: string): AgentUiEvent[] {
635	  const ev = parseStreamLine(line);
636	  return ev ? normalizeStreamEvent(ev) : [];
637	}
638	
639	/**
640	 * Encode a user turn for `--input-format stream-json` (written to the CLI's
641	 * stdin as a single NDJSON line — the caller appends the newline). Uses the
642	 * full `{type:"user",message:{role,content}}` envelope the CLI expects.
643	 */
644	export function encodeUserMessage(text: string): string {
645	  return JSON.stringify({ type: "user", message: { role: "user", content: text } });
646	}
647	
648	/** A short one-line summary of a tool call's input, for the tool card header. */
649	export function summarizeToolInput(name: string, input: unknown): string {
650	  if (!input || typeof input !== "object") return "";
651	  const o = input as Record<string, unknown>;
652	  const pick = (k: string): string => (typeof o[k] === "string" ? (o[k] as string) : "");
653	  // Show the most useful field per common tool; fall back to the first string.
654	  const candidate =
655	    pick("command") ||
656	    pick("file_path") ||
657	    pick("path") ||
658	    pick("pattern") ||
659	    pick("url") ||
660	    pick("description") ||
661	    "";
662	  if (candidate) return candidate.length > 160 ? candidate.slice(0, 157) + "…" : candidate;
663	  return "";
664	}
665	##### lib/claude-console-core.ts
666	// Pure, dependency-free logic for the Matrix multi-console workspace.
667	//
668	// This module has NO "use server" directive and NO side effects, so its pure
669	// helpers can be unit-tested directly and imported by both the server action
670	// (lib/actions-claude-console.ts) and the client UI. Anything that touches the
671	// database, the Anthropic API, or SSH lives in the action, not here.
672	//
673	// What lives here:
674	//   - the console state machine (build status -> a coarse UI phase)
675	//   - the mirror-mode fan-out (one prompt -> N independent build requests)
676	//   - multimodal image-part assembly (pasted data URLs -> Anthropic image blocks)
677	// Each is covered by test/build-studio.test.ts.
678	
679	/** How many AI build consoles a workspace may hold at once. */
680	export const MAX_CONSOLES = 6;
681	
682	/** Mirror mode fans a single prompt across this many consoles (inclusive). */
683	export const MIRROR_MIN = 2;
684	export const MIRROR_MAX = 6;
685	
686	/** Media types the multimodal planner will accept for a pasted image. */
687	export const ALLOWED_IMAGE_MEDIA_TYPES = [
688	  "image/png",
689	  "image/jpeg",
690	  "image/gif",
691	  "image/webp",
692	] as const;
693	export type ImageMediaType = (typeof ALLOWED_IMAGE_MEDIA_TYPES)[number];
694	
695	/** At most this many images per prompt, and this many base64 bytes each (~4MB). */
696	export const MAX_IMAGES_PER_PROMPT = 6;
697	export const MAX_IMAGE_BASE64_CHARS = 4_000_000;
698	
699	export type ConsoleImage = { mediaType: ImageMediaType; dataBase64: string };
700	
701	export type PlanStep = { cmd: string; intent: string };
702	
703	/**
704	 * A coarse phase the console UI renders, derived ONLY from the build's real
705	 * status. The workspace never invents a phase the backend does not report — a
706	 * console that shows "running" is a console whose ClaudeBuild row says RUNNING.
707	 */
708	export type ConsolePhase =
709	  | "idle" // no build yet
710	  | "planning" // Claude is drafting / plan queued
711	  | "awaiting" // plan ready, waiting for the owner to approve
712	  | "running" // approved plan executing over SSH
713	  | "done"
714	  | "failed";
715	
716	/** Statuses that mean the build has finished (terminal). */
717	export const TERMINAL_STATUSES = ["DONE", "FAILED"] as const;
718	
719	/** Map a raw ClaudeBuild.status to the coarse console phase. Null status = idle. */
720	export function consolePhase(status: string | null | undefined): ConsolePhase {
721	  switch (status) {
722	    case "QUEUED":
723	    case "PLANNING":
724	      return "planning";
725	    case "AWAITING_APPROVAL":
726	      return "awaiting";
727	    case "RUNNING":
728	      return "running";
729	    case "DONE":
730	      return "done";
731	    case "FAILED":
732	      return "failed";
733	    default:
734	      return "idle";
735	  }
736	}
737	
738	/** True while a build is neither idle nor terminal (i.e. work is in flight). */
739	export function isBuildActive(status: string | null | undefined): boolean {
740	  const phase = consolePhase(status);
741	  return phase === "planning" || phase === "awaiting" || phase === "running";
742	}
