744	/* -------------------------------------------------------------------------- */
745	/* Mirror-mode fan-out                                                         */
746	/* -------------------------------------------------------------------------- */
747	
748	export type MirrorBuildRequest = {
749	  serverId: string;
750	  prompt: string;
751	  mirrorGroupId: string;
752	  title: string;
753	};
754	
755	/**
756	 * Expand one mirror instruction into N independent build requests that share
757	 * the initial prompt and a common mirrorGroupId. `serverIds` is one entry per
758	 * console — the SAME server id may repeat (mirror on one box) or differ (mirror
759	 * across several boxes). Each request is otherwise independent: they plan and
760	 * run separately, and each still requires its own approval.
761	 *
762	 * Throws on an out-of-range fan-out so the caller reports it rather than
763	 * silently launching the wrong number of builds.
764	 */
765	export function mirrorFanout(
766	  prompt: string,
767	  serverIds: string[],
768	  mirrorGroupId: string
769	): MirrorBuildRequest[] {
770	  const clean = (prompt ?? "").trim();
771	  if (!clean) throw new Error("Mirror mode needs a prompt to share across the consoles.");
772	  if (!mirrorGroupId) throw new Error("Mirror mode needs a group id.");
773	  if (serverIds.length < MIRROR_MIN || serverIds.length > MIRROR_MAX) {
774	    throw new Error(`Mirror mode spans ${MIRROR_MIN}-${MIRROR_MAX} consoles.`);
775	  }
776	  return serverIds.map((serverId, i) => {
777	    if (!serverId) throw new Error("Every mirror console needs a target server.");
778	    return {
779	      serverId,
780	      prompt: clean,
781	      mirrorGroupId,
782	      // A, B, C … so the relationship is legible in the UI and audit log.
783	      title: `Variation ${String.fromCharCode(65 + i)}`,
784	    };
785	  });
786	}
787	
788	/* -------------------------------------------------------------------------- */
789	/* Multimodal image-part assembly                                             */
790	/* -------------------------------------------------------------------------- */
791	
792	/**
793	 * Parse a browser `data:` URL (as produced by a paste / FileReader) into a
794	 * validated {mediaType, dataBase64}. Returns null for anything that is not a
795	 * supported base64 image data URL — the caller drops it rather than forwarding
796	 * an unknown blob to the model.
797	 */
798	export function parseImageDataUrl(dataUrl: string): ConsoleImage | null {
799	  if (typeof dataUrl !== "string") return null;
800	  const m = /^data:([a-z0-9.+/-]+);base64,([A-Za-z0-9+/=\s]+)$/i.exec(dataUrl.trim());
801	  if (!m) return null;
802	  const mediaType = m[1].toLowerCase();
803	  if (!(ALLOWED_IMAGE_MEDIA_TYPES as readonly string[]).includes(mediaType)) return null;
804	  const dataBase64 = m[2].replace(/\s+/g, "");
805	  if (!dataBase64) return null;
806	  return { mediaType: mediaType as ImageMediaType, dataBase64 };
807	}
808	
809	/** Reject images that are too many or too large before they reach the API. */
810	export function validateImages(images: ConsoleImage[]): { ok: true } | { ok: false; error: string } {
811	  if (images.length > MAX_IMAGES_PER_PROMPT) {
812	    return { ok: false, error: `Attach at most ${MAX_IMAGES_PER_PROMPT} images per message.` };
813	  }
814	  for (const img of images) {
815	    if (!(ALLOWED_IMAGE_MEDIA_TYPES as readonly string[]).includes(img.mediaType)) {
816	      return { ok: false, error: `Unsupported image type: ${img.mediaType}` };
817	    }
818	    if (!img.dataBase64 || img.dataBase64.length > MAX_IMAGE_BASE64_CHARS) {
819	      return { ok: false, error: "One of the images is too large (max ~4MB each)." };
820	    }
821	  }
822	  return { ok: true };
823	}
