825	/**
826	 * An Anthropic Messages-API user-content block: a text block, or a base64 image
827	 * block. Shape matches the multimodal Messages API exactly (image blocks carry
828	 * `source: { type: "base64", media_type, data }`).
829	 */
830	export type AnthropicTextBlock = { type: "text"; text: string };
831	export type AnthropicImageBlock = {
832	  type: "image";
833	  source: { type: "base64"; media_type: ImageMediaType; data: string };
834	};
835	export type AnthropicContentBlock = AnthropicTextBlock | AnthropicImageBlock;
