837	/**
838	 * Assemble the user-turn content for a plan request: the pasted images first
839	 * (so the model has the visual context before the instruction), then the text
840	 * prompt. When there are no images this is a single text block, byte-identical
841	 * to the plain-text planner path.
842	 */
843	export function buildUserContent(prompt: string, images: ConsoleImage[]): AnthropicContentBlock[] {
844	  const blocks: AnthropicContentBlock[] = [];
845	  for (const img of images) {
846	    blocks.push({
847	      type: "image",
848	      source: { type: "base64", media_type: img.mediaType, data: img.dataBase64 },
849	    });
850	  }
851	  blocks.push({ type: "text", text: prompt });
