856	/* Plan parsing (shared shape with the worker's plan phase)                    */
857	/* -------------------------------------------------------------------------- */
858	
859	/**
860	 * Parse Claude's plan reply into a validated list of {cmd,intent} steps, or
861	 * null. Mirrors the worker's parser so a plan produced in-action executes the
862	 * same way the worker's own plans do. Tolerates prose around the JSON array.
863	 */
864	export function parsePlanReply(reply: string): PlanStep[] | null {
865	  if (typeof reply !== "string") return null;
866	  const start = reply.indexOf("[");
867	  const end = reply.lastIndexOf("]");
868	  if (start === -1 || end === -1 || end < start) return null;
869	  let raw: unknown;
870	  try {
871	    raw = JSON.parse(reply.slice(start, end + 1));
872	  } catch {
873	    return null;
874	  }
875	  if (!Array.isArray(raw)) return null;
876	  const steps: PlanStep[] = [];
877	  for (const item of raw) {
878	    if (typeof item === "string") {
879	      const cmd = item.trim();
880	      if (cmd) steps.push({ cmd, intent: "" });
881	    } else if (item && typeof item === "object") {
882	      const anyItem = item as Record<string, unknown>;
883	      const cmd = String(anyItem.cmd ?? anyItem.command ?? "").trim();
884	      const intent = String(anyItem.intent ?? anyItem.description ?? "").trim();
885	      if (cmd) steps.push({ cmd, intent });
886	    }
887	  }
888	  return steps.length ? steps : null;
889	}
