128	/**
129	 * The expiry a renewal should advance to.
130	 *
131	 * The base is `max(currentExpiry, now)`, so an item that has been expired for
132	 * months is brought forward to one full term from *today* with a single charge
133	 * rather than being back-billed for every missed period. This also guarantees
134	 * the new expiry is always strictly in the future, which is what makes the
135	 * sweep idempotent (the "due" query only selects `expiresAt < now`).
136	 */
137	export function nextExpiry(
138	  currentExpiry: Date | null | undefined,
139	  now: Date,
140	  months: number
141	): Date {
142	  const base = new Date(
143	    Math.max(currentExpiry ? currentExpiry.getTime() : now.getTime(), now.getTime())
144	  );
145	  return addMonths(base, Math.max(1, Math.round(months)));
146	}
147	
148	/** Instant the grace period ends for an item that expired at `expiresAt`. */
149	export function graceEndsAt(expiresAt: Date, graceDays: number = PRODUCT_GRACE_DAYS): Date {
150	  return new Date(expiresAt.getTime() + graceDays * DAY_MS);
151	}
152	
153	/** True once the grace period after `expiresAt` has fully elapsed. */
154	export function isPastGrace(
155	  expiresAt: Date,
156	  now: Date,
157	  graceDays: number = PRODUCT_GRACE_DAYS
158	): boolean {
159	  return now.getTime() > graceEndsAt(expiresAt, graceDays).getTime();
160	}
161	
162	/** Date after which an unpaid volume may be reclaimed (messaging only). */
163	export function reclaimAt(
164	  expiresAt: Date,
165	  graceDays: number = PRODUCT_GRACE_DAYS,
166	  reclaimDays: number = PRODUCT_RECLAIM_DAYS
167	): Date {
168	  return new Date(expiresAt.getTime() + (graceDays + reclaimDays) * DAY_MS);
169	}
170	
171	/** Lower bound for "have we already sent this notification recently?" lookups. */
172	export function dedupeSince(now: Date, days: number = NOTIFY_DEDUPE_DAYS): Date {
173	  return new Date(now.getTime() - days * DAY_MS);
174	}
175	
176	/** True when the item has passed its paid-through date and owes a renewal. */
177	export function isDueForRenewal(expiresAt: Date | null | undefined, now: Date): boolean {
178	  return !!expiresAt && expiresAt.getTime() < now.getTime();
179	}
180	
181	/** True when the item expires inside the pre-expiry warning window. */
182	export function isRenewingSoon(
183	  expiresAt: Date | null | undefined,
184	  now: Date,
185	  warnDays: number = PRODUCT_WARN_DAYS
186	): boolean {
187	  if (!expiresAt) return false;
188	  const t = expiresAt.getTime();
189	  return t > now.getTime() && t < now.getTime() + warnDays * DAY_MS;
190	}
191	
192	/** Whether the wallet covers a renewal (free items always "afford" themselves). */
193	export function canAfford(balanceCents: number, priceCents: number): boolean {
194	  return priceCents <= 0 || balanceCents >= priceCents;
195	}
196	
197	/**
198	 * What the sweep should do with an item that is past its expiry date.
199	 *  - `renew`   charge the wallet and push `expiresAt` forward
200	 *  - `grace`   still inside the grace window: leave it running, nag the owner
201	 *  - `enforce` grace elapsed and unpaid: suspend (email) / detach (volume)
202	 */
203	export type RenewalAction = "renew" | "grace" | "enforce";
204	
205	export function renewalDecision(opts: {
206	  expiresAt: Date;
207	  now: Date;
208	  autoRenew: boolean;
209	  balanceCents: number;
210	  priceCents: number;
211	  graceDays?: number;
212	}): RenewalAction {
213	  const { expiresAt, now, autoRenew, balanceCents, priceCents } = opts;
214	  if (autoRenew && canAfford(balanceCents, priceCents)) return "renew";
215	  if (isPastGrace(expiresAt, now, opts.graceDays)) return "enforce";
216	  return "grace";
217	}
218	
219	/**
220	 * Whether a pre-expiry warning is warranted: only bother the customer when the
221	 * renewal would actually fail today (auto-renew off, or wallet too low).
222	 */
223	export function needsUpcomingWarning(opts: {
224	  autoRenew: boolean;
225	  balanceCents: number;
226	  priceCents: number;
227	}): boolean {
228	  return !(opts.autoRenew && canAfford(opts.balanceCents, opts.priceCents));
229	}
