231	import { vpsTerm, vpsTermPriceCents, termPriceCents } from "./billing-terms";
232	import { extraDiskCentsAt } from "./extra-disk";
233	import { type BackupTier, backupTierMonthlyCents } from "./backup-tiers";
234	
235	/**
236	 * What one renewal costs — the SINGLE definition, used by every path that quotes
237	 * or charges one: the automatic sweep in worker/billing.ts, the saved-card path,
238	 * the "Renew now" button, the server page and the deploy wizard's term cards.
239	 *
240	 * WHY IT LIVES IN ITS OWN FILE. It used to sit in lib/stripe-cards.ts, which
241	 * imports the Stripe SDK and (transitively) nodemailer. The moment a CLIENT
242	 * component — the deploy wizard — needed the renewal price, that import chain
243	 * dragged `nodemailer/lib/dkim` into the browser bundle and the build failed with
244	 * "Can't resolve 'fs'". The pricing rule is pure arithmetic and has no business
245	 * carrying a mail transport with it, so it lives here with only the two tiny
246	 * modules it genuinely needs. lib/stripe-cards.ts re-exports it, so no server-side
247	 * caller had to change.
248	 *
249	 * The rule this file exists to enforce: there is ONE renewal formula. Two
250	 * incidents in one day came from a second copy — first a button that hardcoded
251	 * "+30 days" and the monthly price while the action charged a full term ($8.99
252	 * shown, $97.09 taken), then the shared quote written to fix it, which computed
253	 * from `plan.priceCents` and so ignored `gamePlan` and would have billed a $4.99
254	 * game server at its $8.99 base plan. Do not add a second formula.
255	 */
256	export type RenewalCharge = {
257	  months: number;
258	  /**
259	   * The amount to CHARGE / display — tax-INCLUSIVE (net + tax). When no
260	   * `taxRatePercent` is supplied (the default), tax is 0 and this equals `netCents`,
261	   * so every existing caller is unchanged. Because display and charge both read this
262	   * one field, `displayed === charged === renewed` holds by construction.
263	   */
264	  totalCents: number;
265	  /** The pre-tax subtotal (plan + IP + disk + backup). Invoice line items sum to this. */
266	  netCents: number;
267	  /** The VAT/GST added on top of `netCents` (Finding 1); 0 when no rate was passed. */
268	  taxCents: number;
269	  /** The rate (%) `taxCents` was computed at, recorded on the invoice. */
270	  taxRatePercent: number;
271	  /** The extra-root-disk portion, which gets its own invoice line. */
272	  extraDiskCents: number;
273	  extraDiskMonthlyCents: number;
274	  /** The paid backup-tier portion (Plus retention), which gets its own invoice line. */
275	  backupCents: number;
276	  backupMonthlyCents: number;
277	  /** Human label for the invoice / receipt ("Nebula VPS" or the game plan name). */
278	  label: string;
279	};
280	
281	export type PricedServer = {
282	  termMonths: number;
283	  extraDiskGB: number;
284	  plan: { name: string; priceCents: number };
285	  gamePlan: { name: string; priceCents: number; termMonths: number } | null;
286	  dedicatedIp: unknown | null;
287	  /** Paid backup retention tier. A full Server row supplies it; synthetic callers must pass it. */
288	  backupTier: BackupTier;
289	  /**
290	   * The ANNUAL discount FROZEN on this server at sale (`Server.annualDiscountPct`),
291	   * or null on a legacy/monthly/flat row. OPTIONAL so the many synthetic
292	   * `PricedServer` display/quote objects keep compiling; a full Server row supplies
293	   * it automatically. When present it WINS over the live `prices.annualDiscountPct`,
294	   * so an annual VPS / NxCloud / game server renews at exactly the rate it was
295	   * SOLD at even if the admin retunes the setting afterwards; null falls back to
296	   * the live rate, which for every non-annual term is identical maths.
297	   */
298	  annualDiscountPct?: number | null;
299	};
300	
301	/**
302	 * The admin-priced inputs a renewal is charged against. Every field is REQUIRED
303	 * deliberately, mirroring how the codebase guards renewal pricing everywhere else
304	 * (`termPromoPercent` is likewise required in lib/proration.ts): a call site that
305	 * builds this object cannot silently forget one and fall back to a stale default.
306	 */
307	export type RenewalPrices = {
308	  ipMonthlyCents: number;
309	  extraDiskPerGbCents: number;
310	  backupPlusCents: number;
311	  /**
312	   * The admin-configured ANNUAL discount (percent), resolved from the
313	   * `annual_discount_percent` setting via `annualDiscountPct()`.
314	   *
315	   * REQUIRED — not optional. A 12-month server renews at
316	   * `vpsTermPriceCents(price, 12, annualDiscountPct)`; if a call site could OMIT
317	   * this it would silently price annual at the shipped default (10%) while the
318	   * owner had set, say, 20% — the rate the customer was shown and charged at order.
319	   * Required turns that into a compile error at every one of the ~8 places that
320	   * build this object, so the annual setting cannot be forgotten on any renewal
321	   * path and `displayed === charged === renewed` holds.
322	   */
323	  annualDiscountPct: number;
324	  /**
325	   * OPTIONAL destination VAT/GST rate (percent) for the customer who owns this
326	   * server, resolved from their billing country (lib/tax.ts taxContextForUser).
327	   * Omitted / 0 => no tax added and `totalCents === netCents`, so every call site
328	   * that does not opt in is byte-for-byte unchanged. A charge site passes the
329	   * OWNER's rate so the wallet debit, the card leg and the invoice all agree; a
330	   * display of the owner's own renewal passes the SAME rate so the figure shown
331	   * equals the figure taken.
332	   */
333	  taxRatePercent?: number;
334	};
335	
336	export function renewalCharge(
337	  server: PricedServer,
338	  prices: RenewalPrices,
339	): RenewalCharge {
340	  const isGame = !!server.gamePlan;
341	  // The term to renew — the customer's chosen `Server.termMonths` (1 = monthly,
342	  // 12 = annual). A game term is now a per-order choice (Monthly / Annual) just like
343	  // a VPS, so it rides the Server row, not the plan.
344	  //
345	  // VPS/NxCloud terms are always one of the 4 standard `VPS_TERMS`, so we normalise
346	  // through `vpsTerm`. A GAME server, however, may historically carry ANY term the
347	  // plan was configured with (a pre-existing game server was created with
348	  // `termMonths = gamePlan.termMonths`, which the admin can set 1..36). We therefore
349	  // read the game term back RAW (clamped >= 1) rather than through `vpsTerm`, whose
350	  // fallback would collapse a non-standard legacy value (say 3) to monthly and
351	  // change that server's renewal cadence. For the seeded games (all `termMonths: 1`)
352	  // and any new Monthly/Annual order this is identical to the standard path.
353	  const months = isGame ? Math.max(1, Math.round(server.termMonths)) : vpsTerm(server.termMonths).months;
354	  // The annual discount to price the term at: the rate FROZEN on the server at sale,
355	  // falling back to the live setting for legacy/monthly rows. Both halves resolve
356	  // the same number, so an annual sub renews at the sold rate.
357	  const annualPct = server.annualDiscountPct ?? prices.annualDiscountPct;
358	  // Extra root disk is billed EVERY cycle at the current per-GB price. Game plans
359	  // are a flat all-in price and never carry the add-on lines.
360	  const extraDiskMonthlyCents = isGame ? 0 : extraDiskCentsAt(server.extraDiskGB, prices.extraDiskPerGbCents);
361	  const extraDiskCents = extraDiskMonthlyCents * months;
362	  // Paid backup retention (Plus) rides alongside extra disk: billed every cycle at
363	  // the current admin price, and — like every add-on line — NOT carried by a game
364	  // plan (renewalCharge's game branch is flat all-in, so game servers are never
365	  // sold a paid backup tier; see lib/backup-upgrade.ts's game guard).
366	  const backupMonthlyCents = isGame ? 0 : backupTierMonthlyCents(server.backupTier, prices.backupPlusCents);
367	  const backupCents = backupMonthlyCents * months;
368	  // A game plan's `priceCents` is its MONTHLY base (every seed is `termMonths: 1`).
369	  // Divide by the plan's own term so an admin plan configured as, say, a 3-month
370	  // bundle still yields a per-month rate; then price the customer's chosen term
371	  // through the SAME formula VPS uses. For a monthly game server this is exactly
372	  // `priceCents`; an ANNUAL game server renews at 12× that, less the annual discount.
373	  const gameMonthlyCents = isGame
374	    ? Math.round(server.gamePlan!.priceCents / Math.max(1, server.gamePlan!.termMonths))
375	    : 0;
376	  // LEGACY GUARD. Game servers sold BEFORE terms existed carry no frozen annual rate
377	  // (`annualDiscountPct == null`) and always renewed at the plan's FLAT `priceCents`,
378	  // with no term discount ever applied. Preserve that exactly so no pre-existing game
379	  // server's renewal moves — only servers sold through the new term-aware flow (which
380	  // always stamps a frozen `annualDiscountPct`) are priced with `termPriceCents`.
381	  //
382	  // GUARD ON isGame FIRST. This value is only USED in the isGame branch below, but a
383	  // bare ternary evaluates it for EVERY server — and a VPS `PricedServer` (e.g. the one
384	  // the deploy wizard builds, `gamePlan: null`, no `annualDiscountPct`) then hits the
385	  // `annualDiscountPct == null` arm and dereferences `server.gamePlan!.priceCents` on a
386	  // null, crashing the whole deploy page with "Cannot read properties of null". Compute
387	  // 0 for non-game so the null is never touched.
388	  const gameTotalCents = !isGame
389	    ? 0
390	    : server.annualDiscountPct == null
391	      ? server.gamePlan!.priceCents
392	      : termPriceCents(gameMonthlyCents, months, annualPct);
393	  const netCents = isGame
394	    ? gameTotalCents +
395	      (server.dedicatedIp ? prices.ipMonthlyCents * months : 0)
396	    : vpsTermPriceCents(server.plan.priceCents, months, annualPct) +
397	      // Bill the IP surcharge only when the server ACTUALLY holds a dedicated IP,
