488	// Pure, dependency-free proration maths shared by the server actions (resize,
489	// disk expansion, downgrade) and the client pickers that DISPLAY the number.
490	// No server-only imports, exactly like lib/wallet-split.ts — so the figure the
491	// customer sees is byte-for-byte the figure that gets charged or credited.
492	//
493	// NOTHING IN HERE READS THE CLOCK FOR A PRICE. Every input is passed in. Until
494	// 2026-07-26 the rate basis defaulted to `currentPromo(new Date())`, which meant
495	// the customer set the price of a resize by choosing the day they clicked — see
496	// `resolveTermPromoPercent`. This module must never import `currentPromo` again.
497	
498	import { vpsEffectiveMonthly } from "./billing-terms";
499	import { deepestPromoPercent, discountedCents } from "./promotions";
500	
501	/** Average calendar month in ms (365.25/12 ≈ 30.44d). */
502	export const MS_PER_AVG_MONTH = 30.44 * 86400_000;
503	
504	/**
505	 * Months of paid term left at `now` — 0 when there is no expiry (free/admin
506	 * servers) and clamped at zero so an already-expired term never prorates
507	 * negatively.
508	 *
509	 * There is deliberately NO cap parameter, and re-adding one would reopen a money
510	 * bug. `expiresAt` only ever moves forward in exchange for payment: the initial
511	 * order term (lib/order.ts, lib/actions.ts placeOrder), `renewNow`
512	 * (lib/actions.ts) and the auto-renew sweep (worker/billing.ts) each advance it by
513	 * exactly `termMonths` and charge `vpsTermPriceCents` for those months. So every
514	 * month between `now` and `expiresAt` is a month the customer has actually bought,
515	 * however many terms of "Renew now" are stacked up in there, and the honest
516	 * prorated figure covers all of them.
517	 *
518	 * This used to take `capMonths`, and that optional knob is precisely how the two
519	 * directions drifted apart: the upgrade path (lib/resize.ts) passed no cap while
520	 * the downgrade path (lib/actions-server-lifecycle.ts) passed `server.termMonths`.
521	 * A customer who had stacked "Renew now" out to 36 months on a 12-month term was
522	 * charged $544.32 to move Starter -> Max and credited only $181.44 to move
523	 * straight back — the platform kept $362.88 it never earned. Four call sites
524	 * (two servers, two pickers) had to agree on that argument by convention, and they
525	 * did not. With the knob gone every caller gets the same number from the same
526	 * one-argument call, so the round-trip invariant is structural instead of a
527	 * comment someone has to honour.
528	 *
529	 * A cap was never what protected the credit side either. The credit is
530	 * `(effective(from) - effective(to)) x months` priced through `prorateDeltaCents`
531	 * at the term-discounted AND promo-reduced rate, while the renewal paths charge
532	 * the term price with no promo applied — so the credit for a given month is
533	 * strictly less than what that month cost. What made the old credit a money
534	 * printer was the RAW LIST-price delta it used before 2026-07-25, not the number
535	 * of months it spanned.
536	 */
537	export function remainingMonths(expiresAt: Date | null, now: number): number {
538	  if (!expiresAt) return 0;
539	  return Math.max(0, (expiresAt.getTime() - now) / MS_PER_AVG_MONTH);
540	}
541	
542	/**
543	 * The rate basis for a proration, resolved from what the server row records.
544	 *
545	 * `Server.termPromoPercent` is the percent off the term-discounted monthly rate
546	 * that the months currently left on `expiresAt` were ACTUALLY sold at. NULL means
547	 * the row predates that column and the rate is unknown.
548	 *
549	 * ─── WHY NULL MUST NOT FALL THROUGH TO `currentPromo(now)` ──────────────────
550	 * That was the bug, fixed 2026-07-26. `prorateDeltaCents` used to default its rate
551	 * basis to the seasonal promo running at the instant of the call. Promos rotate by
552	 * calendar date from a 15% Launch Sale up to 45% for Cyber Monday (lib/promotions.ts),
553	 * so both halves of a round trip were priced off a number the CUSTOMER got to choose
554	 * by picking the date. Upgrade on Cyber Monday: the delta is charged at 55% of the
555	 * honest rate. Downgrade back in mid-January: the same delta is credited at 85%.
556	 * The 30-point spread x plan delta x every remaining month falls straight into the
557	 * wallet, repeatable every promo cycle, with the platform's own marketing calendar
558	 * published as the timetable. On the pinned catalogue (Starter 899 -> Max 3299, a
559	 * 36-month term) that is $207.36 of minted cash per cycle for zero net change.
560	 *
561	 * It was also simply the wrong rate. lib/promotions.ts states in its opening line
562	 * that a promo discounts a customer's FIRST TERM only and that renewals never get
563	 * it — yet this priced a mid-term plan change, on months that may well have been
564	 * bought at a renewal's full price, off a promo the customer was never sold.
565	 *
566	 * ─── THE FALLBACK, AND WHY IT IS THE DEEPEST DISCOUNT AND NOT FULL PRICE ────
567	 * The obvious conservative guess is "assume they paid full list" (percent 0). It is
568	 * the wrong direction and it MINTS MONEY. A credit is monotonically INCREASING in
569	 * the rate basis, so percent 0 produces the LARGEST credit this function can emit.
570	 * A customer who really bought Max on a 36-month term during Cyber Monday paid
571	 * 0.55 x 2639 = 1451c per month-equivalent; a downgrade to Starter priced at
572	 * percent 0 credits (2639 - 719) = 1920c per month — 469c/month MORE than they ever
573	 * paid, so 36 months hands back $168.84 of cash they never spent AND leaves them a
574	 * running Starter VPS for three years.
575	 *
576	 * So the fallback goes the other way: assume the LEAST the platform has ever
577	 * charged (`deepestPromoPercent()`, currently the 45% Cyber Monday). Under that
578	 * basis the credit is bounded below the real cash for every rate the customer could
579	 * actually have been sold. The price of being wrong in this direction is a cheaper
580	 * upgrade for an unknown-rate server — a pricing concession, not a printer: it can
581	 * only ever reduce revenue collected, never push cash OUT, and because BOTH
582	 * directions read this same resolved number a round trip still nets to exactly
583	 * zero. Given the choice between under-charging and over-refunding, this file's
584	 * entire incident history says take the under-charge.
585	 *
586	 * (After scripts/backfill-term-promo-percent.ts this branch is unreachable on live
587	 * data — every row carries a rate derived from what it was actually invoiced.)
588	 */
589	export function resolveTermPromoPercent(termPromoPercent: number | null | undefined): number {
590	  if (termPromoPercent === null || termPromoPercent === undefined) return deepestPromoPercent();
591	  // A stored value outside 0-100 would invert or amplify the delta; clamp rather
592	  // than trust, since this number is a direct multiplier on money.
593	  return Math.min(100, Math.max(0, termPromoPercent));
594	}
595	
596	/**
597	 * The value-weighted blend of the rate the remaining months are already on and the
598	 * rate a freshly-added block of months is being sold at.
599	 *
600	 * `termPromoPercent` is ONE scalar covering every month left on `expiresAt`, but
601	 * months get added to that window at different rates: an intro-discounted first
602	 * term, then renewals at full price, and occasionally an admin gift at no price at
603	 * all. Overwriting the scalar on each addition would silently reprice the months
604	 * already in there — and in the profitable direction. Concretely: buy a 36-month
605	 * term at 45% off, click "Renew now" once (which honestly charges full price for 36
606	 * more months), and a plain overwrite would re-rate the original 36 discounted
607	 * months to full price too, restoring the exact same spread this field exists to
608	 * kill. Blending keeps the total cash value of the remaining window invariant:
609	 * added months contribute their own rate and nothing reprices what came before.
610	 *
611	 * The result is deliberately NOT rounded to a whole percent, which is why the
612	 * column is a Float: 36 months at 45% off plus 36 renewed months at full price is
613	 * exactly 22.5% off, and rounding that to 23 shaves $7.20 off the $1,071.36 credit
614	 * those 72 months are worth. Rounding here would also compound over a server's
615	 * lifetime, once per renewal. (It could never break the round-trip invariant —
616	 * both directions read the same stored scalar whatever it holds — but "symmetric"
617	 * and "correct" are different properties and this file owes the customer both.)
618	 */
619	export function prorateBlendPercent(opts: {
620	  /** Rate the months already on the clock were sold at (already resolved). */
621	  currentPercent: number;
622	  /** How many months are already on the clock. */
623	  currentMonths: number;
624	  /** Rate the newly-added months are being sold at. 0 = full price, 100 = gifted. */
625	  addedPercent: number;
626	  /** How many months are being added. Non-positive => nothing to blend. */
627	  addedMonths: number;
628	}): number {
629	  const cur = Math.min(100, Math.max(0, opts.currentPercent));
630	  const add = Math.min(100, Math.max(0, opts.addedPercent));
631	  const curMonths = Math.max(0, opts.currentMonths);
632	  const addMonths = Math.max(0, opts.addedMonths);
633	  const total = curMonths + addMonths;
634	  // Nothing on the clock and nothing added: keep the incoming rate rather than
635	  // divide by zero. (Also the honest answer for "term shortened, none added" —
636	  // fewer months at the same rate, which is exactly what the caller wants.)
637	  if (total <= 0) return cur;
638	  const value = curMonths * (1 - cur / 100) + addMonths * (1 - add / 100);
639	  const pct = 100 * (1 - value / total);
640	  // Snap off binary-float noise only: 36mo at 45% blended with 36mo at 0% is
641	  // exactly 22.5 but computes as 22.500000000000007, and blending a rate with
642	  // itself must be an exact no-op rather than drifting a hair on every renewal.
643	  // Six decimal places is a millionth of a percentage point — far below a cent on
644	  // any conceivable term — while leaving every genuine fraction intact.
645	  return Math.min(100, Math.max(0, Math.round(pct * 1e6) / 1e6));
646	}
647	
648	/**
649	 * The prorated difference between two monthly plan prices over the remaining
650	 * term, priced against THE RATE THIS SERVER'S TERM WAS ACTUALLY SOLD AT.
651	 *
652	 * Why the rate is a required argument (2026-07-26): it used to default to
653	 * `currentPromo(now)`, which handed the customer the pricing basis for both halves
654	 * of a round trip — see `resolveTermPromoPercent` for the full arbitrage. Making it
655	 * required means a call site cannot forget it; there is no basis to fall back TO.
656	 *
657	 * Why this exists at all (2026-07-25): proration used the raw list monthly delta
658	 * while the original purchase applied BOTH the term discount (lib/order.ts) and the
659	 * seasonal promo. Upgrading therefore cost far more than buying the target plan
660	 * outright for the same end date — on a 36-month term with a 30% promo running,
661	 * $1,044.45 to upgrade versus $665.08 fresh: the customer overpaid $379.37. The
662	 * mirror image was worse in kind: the downgrade CREDIT used the same undiscounted
663	 * delta, so it refunded more than was ever paid.
664	 *
665	 * Both directions price off the SAME function and the SAME persisted scalar, so
666	 * they cannot drift apart:
667	 *   effective monthly (term discount) → term's sold rate → × months left.
668	 */
669	export function prorateDeltaCents(opts: {
670	  fromMonthlyCents: number;
671	  toMonthlyCents: number;
672	  termMonths: number;
673	  monthsRemaining: number;
674	  /**
675	   * `Server.termPromoPercent` — percent off that THIS server's remaining months
676	   * were sold at. Pass the row value straight through, null and all; it is
677	   * resolved here so every call site resolves it identically.
678	   */
679	  termPromoPercent: number | null;
680	  /**
681	   * The admin-configured ANNUAL discount (percent) from `annualDiscountPct()`.
682	   *
683	   * OPTIONAL — unlike the renewal-pricing field in lib/renewal-charge.ts, which is
684	   * required. Two reasons it is safe optional here: it only bites a 12-month server
685	   * (every other `termMonths` ignores it via `termDiscountPct`), and when omitted it
686	   * falls back to the shipped default — the same number the annual term shipped at.
687	   * Server-side resize paths (lib/resize.ts, lib/actions-server-lifecycle.ts) and
688	   * the resize UIs DO pass the live value, so an annual server's mid-term upgrade
689	   * and downgrade credit price against the SAME rate its order and renewals use;
690	   * left off, the maths is unchanged for every non-annual term and matches the
691	   * default for annual.
692	   */
693	  annualDiscountPct?: number;
694	}): number {
695	  const pct = resolveTermPromoPercent(opts.termPromoPercent);
696	  const eff = (monthly: number) =>
697	    discountedCents(vpsEffectiveMonthly(monthly, opts.termMonths, opts.annualDiscountPct), pct);
698	  const delta = eff(opts.toMonthlyCents) - eff(opts.fromMonthlyCents);
699	  return Math.round(delta * Math.max(0, opts.monthsRemaining));
700	}
