707	/** Downgrade credit — never negative; caller passes from=old, to=new. */
708	export function prorateDowngradeCreditCents(
709	  opts: Parameters<typeof prorateDeltaCents>[0]
710	): number {
711	  return Math.max(0, -prorateDeltaCents(opts));
712	}
