714	/**
715	 * The prorated refund owed for the UNUSED portion of a paid term on IMMEDIATE
716	 * cancellation (Finding 2), in cents — the value of every remaining month priced at
717	 * the SAME effective rate the term was sold at, computed as a downgrade all the way
718	 * to a $0 plan (so it reuses `prorateDowngradeCreditCents`).
719	 *
720	 * NEVER OVER-REFUNDS: the per-month credit is the term-discounted, promo-reduced rate,
721	 * while every month on the clock was collected at AT LEAST that (renewals charge the
722	 * full term price with no promo), and `expiresAt` only advances in exchange for
723	 * payment — so the credit is strictly ≤ what was actually paid for the unused time.
724	 * Game servers return 0 (they are sold at a flat game-plan price, not the base VPS
725	 * `planMonthlyCents` this values against, so any non-zero figure could over-refund).
726	 *
727	 * `annualDiscountPct` must be pre-resolved by the caller to
728	 * `frozenAnnualDiscountPct(server) ?? liveRate`, mirroring the resize/downgrade paths.
729	 */
730	export function terminationRefundCents(opts: {
731	  isFree: boolean;
732	  expiresAt: Date | null;
733	  isGame: boolean;
734	  planMonthlyCents: number;
735	  termMonths: number;
736	  termPromoPercent: number | null;
737	  annualDiscountPct: number;
738	  /**
739	   * The plan-portion cash actually collected for this term (net of promo AND coupon,
740	   * add-ons excluded), from `Server.refundableTermCents`. When present it is the
741	   * AUTHORITATIVE basis — the refund is this figure prorated over the unused months,
742	   * which is exact, coupon-aware and provably ≤ paid. Only when it is null (legacy
743	   * rows predating the column) do we fall back to the `termPromoPercent` formula,
744	   * which never over-refunds but reads $0 for the 100-stamped common case.
745	   */
746	  refundableTermCents?: number | null;
747	  now?: number;
748	}): number {
749	  if (opts.isFree || !opts.expiresAt || opts.isGame) return 0;
750	  const rem = remainingMonths(opts.expiresAt, opts.now ?? Date.now());
751	  // AUTHORITATIVE PATH: prorate the real cash collected. `rem` is clamped ≥ 0 and can
752	  // reach at most `termMonths` (expiresAt only advances one term per payment), so the
753	  // ratio is ≤ 1 and the refund is ≤ the cash collected — never an over-refund. The
754	  // final clamp is belt-and-braces against a stale/renewed expiresAt drift.
755	  if (opts.refundableTermCents != null && opts.termMonths > 0) {
756	    const basis = Math.max(0, opts.refundableTermCents);
757	    const refund = Math.round((basis * Math.min(rem, opts.termMonths)) / opts.termMonths);
758	    return Math.max(0, Math.min(refund, basis));
759	  }
760	  // LEGACY FALLBACK: value each unused month at the term-discounted, promo-reduced rate.
761	  return prorateDowngradeCreditCents({
762	    fromMonthlyCents: opts.planMonthlyCents,
763	    toMonthlyCents: 0,
764	    termMonths: opts.termMonths,
765	    termPromoPercent: opts.termPromoPercent,
766	    annualDiscountPct: opts.annualDiscountPct,
767	    monthsRemaining: rem,
768	  });
769	}
