973	// Server-side resolver for the visitor's DISPLAY currency + the active FX rates.
974	//
975	// This is the glue between the pure layers (lib/geo-currency.ts, the FX helpers in
976	// lib/tax.ts) and Next's request context (`headers()` / `cookies()`). Import it
977	// from server components / layouts only — it reads the Setting store (db).
978	//
979	// DISPLAY vs CHARGE: everything here decides only how prices are SHOWN. The charge
980	// currency is USD and is untouched. See the boundary note in lib/tax.ts.
981	
982	import "server-only";
983	import { cookies, headers } from "next/headers";
984	import {
985	  CURRENCIES,
986	  CURRENCY_COOKIE,
987	  DEFAULT_CURRENCY,
988	  parseRatesOverride,
989	  rateFor,
990	} from "./currency";
991	import { getSetting } from "./settings";
992	import { countryFromHeaders, currencyForCountry } from "./geo-currency";
993	import { countryFromRequestIp } from "./geo-ip";
994	
995	export { CURRENCY_COOKIE };
996	
997	/** How the display currency was chosen — surfaced for debugging / the switcher UI. */
998	export type CurrencySource = "cookie" | "geo" | "default";
999	
1000	export type ResolvedCurrency = {
1001	  /** The chosen DISPLAY currency code (always a key of CURRENCIES). */
1002	  currency: string;
1003	  /** Where the choice came from. */
1004	  source: CurrencySource;
1005	  /** Full rates table (target units per USD), admin-override merged over defaults. */
1006	  rates: Record<string, number>;
1007	  /** The chosen currency's rate — `rates[currency]`, guaranteed > 0. */
1008	  rate: number;
1009	};
1010	
1011	/** Validate a code against the currencies we can actually render. */
1012	function validCurrency(code: string | null | undefined): string | null {
1013	  const c = (code ?? "").trim().toUpperCase();
1014	  return c && CURRENCIES[c] ? c : null;
1015	}
1016	
1017	/** The active FX rates: the admin `currency_rates` override merged over defaults. */
1018	export async function getCurrencyRates(): Promise<Record<string, number>> {
1019	  return parseRatesOverride(await getSetting("currency_rates"));
1020	}
1021	
1022	/**
1023	 * Resolve the visitor's display currency for the current request.
1024	 *
1025	 * Precedence:
1026	 *   1. `nx_currency` cookie — an explicit manual choice from the switcher wins.
1027	 *   2. CDN/proxy country header (Cloudflare `cf-ipcountry` etc.) → mapped currency.
1028	 *   3. IP → country via the bundled geoip-lite dataset (works with no CDN in
1029	 *      front; the header path in step 2 wins whenever a CDN is added later).
1030	 *   4. The operator's configured default `currency` Setting (USD out of the box).
1031	 *
1032	 * Anything unrecognised at each step falls through to the next, and the final
1033	 * fallback is always a currency we can render. Never throws.
1034	 */
1035	export async function resolveDisplayCurrency(): Promise<ResolvedCurrency> {
1036	  const [jar, hdrs, rates, configuredDefault] = await Promise.all([
1037	    cookies(),
1038	    headers(),
1039	    getCurrencyRates(),
1040	    getSetting("currency"),
1041	  ]);
1042	
1043	  const fallback = validCurrency(configuredDefault) ?? DEFAULT_CURRENCY;
1044	
1045	  let currency = fallback;
1046	  let source: CurrencySource = "default";
1047	
1048	  const cookieChoice = validCurrency(jar.get(CURRENCY_COOKIE)?.value);
1049	  if (cookieChoice) {
1050	    currency = cookieChoice;
1051	    source = "cookie";
1052	  } else {
1053	    // CDN/proxy header first; else resolve the country from the client IP with
1054	    // the local geoip-lite dataset (no CDN required). NB: countryFromHeaders
1055	    // returns "" (not null) when absent, so use || — not ?? — to fall through.
1056	    const country = countryFromHeaders(hdrs) || countryFromRequestIp(hdrs);
1057	    if (country) {
1058	      const geoCurrency = validCurrency(currencyForCountry(country));
1059	      // Only treat geo as decisive when it actually places the visitor somewhere
1060	      // with a non-default currency; otherwise keep the operator default.
1061	      if (geoCurrency && geoCurrency !== fallback) {
1062	        currency = geoCurrency;
1063	        source = "geo";
1064	      } else if (geoCurrency) {
1065	        source = "geo";
1066	      }
1067	    }
1068	  }
1069	
1070	  return { currency, source, rates, rate: rateFor(rates, currency) };
1071	}
