16	/**
17	 * Per-server DISK EXPANSION handler (JobType.DISK_EXPAND).
18	 *
19	 * Grows ONE server's own root disk by N GB — the plan's CPU/RAM are untouched.
20	 * Payment already happened at enqueue time (lib/disk-expand.ts applyDiskExpand),
21	 * so this handler trusts `payload.addGB` / `payload.targetExtraDiskGB` and is
22	 * responsible only for delivering the space.
23	 *
24	 * `worker/index.ts` owns the job loop and its `handlers` map; wire this in there
25	 * as `DISK_EXPAND: diskExpand`. It must NOT be listed in VM_STATE_FAILURE_JOBS:
26	 * growing a disk never changes the VM's run state, so a failure must not strand
27	 * the server in ERROR (see the note in worker/index.ts).
28	 *
29	 * ─── SEQUENCE ───────────────────────────────────────────────────────────────
30	 *   1. read the VM config, work out the CURRENT scsi0 size
31	 *   2. if it is already >= the target, SKIP Proxmox entirely (idempotent retry)
32	 *      otherwise PUT .../resize with size=+<delta>G  (Proxmox only ever grows)
33	 *   3. online-grow the guest: rescan the device, growpart the root partition,
34	 *      then resize2fs / xfs_growfs / btrfs resize depending on the fs type
35	 *   4. persist Server.extraDiskGB and notify
36	 *
37	 * ─── RETRY SAFETY ───────────────────────────────────────────────────────────
38	 * Every step is idempotent. A retry after a crash mid-way re-reads the real disk
39	 * size from Proxmox, skips work already done, and re-runs the guest grow (which
40	 * is a no-op — growpart reports NOCHANGE and resize2fs "nothing to do").
41	 *
42	 * ─── GROWTH IS ONE-WAY ──────────────────────────────────────────────────────
43	 * Proxmox refuses to shrink a disk and so do we: the delta is always positive and
44	 * `Server.extraDiskGB` is only ever raised.
45	 *
46	 * ─── THE CUSTOMER NEVER PAYS FOR INVISIBLE SPACE ────────────────────────────
47	 * If the guest grow can't be done online (server stopped, unreachable, LVM/exotic
48	 * layout, missing tools) the disk is STILL bigger — so this is NOT treated as a
49	 * failure. The job completes and the notification spells out the exact commands
50	 * to run, rather than leaving the customer paying for space they can't see.
51	 */
52	
53	/** Root device paths are the only thing we ever interpolate — keep them inert. */
54	const DEV_PATH_RE = /^\/dev\/[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$/;
55	/** A bare kernel block-device name, e.g. "sda", "vda", "nvme0n1". */
56	const DEV_NAME_RE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,31}$/;
57	/** A partition number, 1–99. */
58	const PARTNUM_RE = /^[1-9][0-9]?$/;
59	/** Filesystems we know how to grow online. */
60	const GROWABLE_FS = new Set(["ext2", "ext3", "ext4", "xfs", "btrfs"]);
61	
