100	/**
101	 * Parse the size out of a Proxmox disk config string, e.g.
102	 * "vmdata:vm-101-disk-0,size=50G" / ",size=32768M" / ",size=1T".
103	 * Returns GB (floor), or null when the string carries no size.
104	 */
105	export function parseDiskSizeGB(spec: string | undefined | null): number | null {
106	  if (typeof spec !== "string") return null;
107	  const m = /(?:^|,)size=(\d+(?:\.\d+)?)([KMGT]?)/i.exec(spec);
108	  if (!m) return null;
109	  const n = Number(m[1]);
110	  if (!Number.isFinite(n)) return null;
111	  switch ((m[2] || "").toUpperCase()) {
112	    case "T": return Math.floor(n * 1024);
113	    case "G": return Math.floor(n);
114	    case "M": return Math.floor(n / 1024);
115	    case "K": return Math.floor(n / 1024 / 1024);
116	    default:  return Math.floor(n / 1024 ** 3); // bare bytes
117	  }
118	}
