120	type GuestLayout = {
121	  rootDevice: string;   // /dev/sda1
122	  fsType: string;       // ext4 | xfs | …
123	  parentName: string;   // sda
124	  partNum: string;      // 1
125	};
126	
127	/**
128	 * Read the guest's root-filesystem layout with a single READ-ONLY command
129	 * (fixed string — nothing is interpolated), then validate every field against a
130	 * shell-inert allowlist before it is ever used in a mutating command. We reject
131	 * rather than sanitize, exactly like lib/ssh-exec.ts.
132	 */
133	async function detectLayout(conn: Client): Promise<GuestLayout | { error: string }> {
134	  const probe = [
135	    'ROOT="$(findmnt -nro SOURCE / 2>/dev/null | head -n1)"',
136	    'FSTYPE="$(findmnt -nro FSTYPE / 2>/dev/null | head -n1)"',
137	    'BASE="$(basename "$ROOT" 2>/dev/null)"',
138	    'PARENT="$(lsblk -nro PKNAME "$ROOT" 2>/dev/null | head -n1)"',
139	    'PARTNUM="$(cat "/sys/class/block/$BASE/partition" 2>/dev/null || echo "")"',
140	    'echo "ROOT=$ROOT"; echo "FSTYPE=$FSTYPE"; echo "PARENT=$PARENT"; echo "PARTNUM=$PARTNUM"',
141	  ].join("; ");
142	  const res = await exec(conn, probe, QUICK_TIMEOUT_MS);
143	  const get = (k: string) =>
144	    (new RegExp(`^${k}=(.*)$`, "m").exec(res.stdout)?.[1] ?? "").trim();
145	
146	  const rootDevice = get("ROOT");
147	  const fsType = get("FSTYPE").toLowerCase();
148	  const parentName = get("PARENT");
149	  const partNum = get("PARTNUM");
150	
151	  if (!DEV_PATH_RE.test(rootDevice)) {
152	    return { error: `could not identify the root device (got "${rootDevice.slice(0, 40)}")` };
153	  }
154	  if (!GROWABLE_FS.has(fsType)) {
155	    return { error: `unsupported root filesystem "${fsType.slice(0, 20) || "unknown"}"` };
156	  }
157	  // LVM / device-mapper roots need pvresize + lvextend, which we will not
158	  // attempt unattended on live customer data — hand over exact instructions.
159	  if (rootDevice.startsWith("/dev/mapper/") || /^dm-\d+$/.test(parentName)) {
160	    return { error: "the root filesystem is on LVM" };
161	  }
162	  if (!DEV_NAME_RE.test(parentName)) {
163	    return { error: `could not identify the parent disk of ${rootDevice}` };
164	  }
165	  if (!PARTNUM_RE.test(partNum)) {
166	    return { error: `could not identify the partition number of ${rootDevice}` };
167	  }
168	  return { rootDevice, fsType, parentName, partNum };
169	}
