171	/** The exact commands a customer (or support) can run to finish the job by hand. */
172	function manualCommands(layout: GuestLayout | null): string {
173	  if (layout) {
174	    return [
175	      `growpart /dev/${layout.parentName} ${layout.partNum}`,
176	      layout.fsType === "xfs"
177	        ? "xfs_growfs /"
178	        : layout.fsType === "btrfs"
179	          ? "btrfs filesystem resize max /"
180	          : `resize2fs ${layout.rootDevice}`,
181	    ].join(" && ");
182	  }
183	  return (
184	    "ROOT=$(findmnt -nro SOURCE /); PARENT=/dev/$(lsblk -nro PKNAME \"$ROOT\"); " +
185	    "PART=$(cat /sys/class/block/$(basename \"$ROOT\")/partition); " +
186	    "growpart \"$PARENT\" \"$PART\" && (resize2fs \"$ROOT\" || xfs_growfs /)"
187	  );
188	}
