190	/**
191	 * Grow the guest filesystem online. Returns null on success, or a human-readable
192	 * reason plus the exact remediation commands when it could not be done.
193	 */
194	async function growGuestFilesystem(
195	  server: any,
196	  onStep: (pct: number, step: string) => Promise<void>,
197	): Promise<{ reason: string; commands: string } | null> {
198	  let layout: GuestLayout | null = null;
199	  try {
200	    return await withServerSsh(server, async (conn) => {
201	      await onStep(62, "Detecting the root filesystem");
202	      const detected = await detectLayout(conn);
203	      if ("error" in detected) {
204	        return { reason: detected.error, commands: manualCommands(null) };
205	      }
206	      layout = detected;
207	      const parentPath = `/dev/${layout.parentName}`;
208	      if (!DEV_PATH_RE.test(parentPath)) {
209	        return { reason: "could not identify the parent disk", commands: manualCommands(null) };
210	      }
211	
212	      // growpart ships in cloud-guest-utils (Debian/Ubuntu) or cloud-utils-growpart
213	      // (RHEL family). Fixed string — no interpolation.
214	      await onStep(70, "Preparing the guest tools");
215	      const ensure = await exec(
216	        conn,
217	        "if ! command -v growpart >/dev/null 2>&1; then " +
218	          "(DEBIAN_FRONTEND=noninteractive apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y cloud-guest-utils) || " +
219	          "dnf install -y cloud-utils-growpart || yum install -y cloud-utils-growpart || true; fi; " +
220	          "command -v growpart >/dev/null 2>&1 && echo OK || echo MISSING",
221	        SETUP_TIMEOUT_MS * 5,
222	      );
223	      if (!/\bOK\b/.test(ensure.stdout)) {
224	        return {
225	          reason: "growpart could not be installed on the server",
226	          commands: `apt-get install -y cloud-guest-utils || dnf install -y cloud-utils-growpart; ${manualCommands(layout)}`,
227	        };
228	      }
229	
230	      // Make the kernel notice the larger block device before growing anything.
231	      // Every interpolated value passed the allowlist above and is quoted anyway.
232	      await onStep(78, "Rescanning the virtual disk");
233	      await exec(
234	        conn,
235	        `echo 1 > /sys/class/block/${shellQuote(layout.parentName)}/device/rescan 2>/dev/null; ` +
236	          `partprobe ${shellQuote(parentPath)} >/dev/null 2>&1; ` +
237	          `udevadm settle >/dev/null 2>&1; true`,
238	        QUICK_TIMEOUT_MS,
239	      );
240	
241	      // growpart exits 1 with "NOCHANGE" when the partition is already maximal —
242	      // that is the idempotent-retry case, not a failure.
243	      await onStep(85, "Growing the root partition");
244	      const grow = await exec(
245	        conn,
246	        `growpart ${shellQuote(parentPath)} ${shellQuote(layout.partNum)} 2>&1`,
247	        SETUP_TIMEOUT_MS,
248	      );
249	      const growOut = `${grow.stdout}${grow.stderr}`;
250	      if (grow.code !== 0 && !/NOCHANGE/i.test(growOut)) {
251	        return {
252	          reason: `growpart failed: ${growOut.trim().slice(0, 200)}`,
253	          commands: manualCommands(layout),
254	        };
255	      }
256	
257	      await onStep(92, "Growing the filesystem");
258	      const fsCmd =
259	        layout.fsType === "xfs"
260	          ? "xfs_growfs / 2>&1"
261	          : layout.fsType === "btrfs"
262	            ? "btrfs filesystem resize max / 2>&1"
263	            : `resize2fs ${shellQuote(layout.rootDevice)} 2>&1`;
264	      const fs = await exec(conn, fsCmd, SETUP_TIMEOUT_MS * 3);
265	      const fsOut = `${fs.stdout}${fs.stderr}`;
266	      // "Nothing to do" / "already N blocks long" are the no-op retry cases.
267	      if (fs.code !== 0 && !/nothing to do|already .* long|no change/i.test(fsOut)) {
268	        return {
269	          reason: `${layout.fsType} grow failed: ${fsOut.trim().slice(0, 200)}`,
270	          commands: manualCommands(layout),
271	        };
272	      }
273	      return null;
274	    });
275	  } catch (e: any) {
276	    // Unreachable / no credentials / timeout — the disk is still bigger.
277	    return {
278	      reason: String(e?.message ?? e).slice(0, 200),
279	      commands: manualCommands(layout),
280	    };
281	  }
282	}
