284	export async function diskExpand(job: Job): Promise<void> {
285	  const payload = (job.payload ?? {}) as { addGB?: number; targetExtraDiskGB?: number };
286	  const addGB = Math.round(Number(payload.addGB ?? 0));
287	  if (!Number.isInteger(addGB) || addGB <= 0) throw new Error("disk expand: invalid addGB");
288	
289	  const server = await db.server.findUnique({
290	    where: { id: job.serverId! },
291	    include: { plan: true, node: true, dedicatedIp: true },
292	  });
293	  if (!server) throw new Error(`Server ${job.serverId} not found`);
294	
295	  // Target is recorded on the job at purchase time so a concurrent write can't
296	  // move the goalposts; fall back to "current + addGB" for older payloads.
297	  const targetExtraDiskGB = Math.max(
298	    server.extraDiskGB,
299	    Math.round(Number(payload.targetExtraDiskGB ?? server.extraDiskGB + addGB)),
300	  );
301	  const targetTotalGB = effectiveDiskGB(server.plan.diskGB, targetExtraDiskGB);
302	  const link = `/dashboard/servers/${server.id}`;
303	  const step = (pct: number, s: string) => reportJobProgress(job.id, pct, s);
304	
305	  if (SANDBOX) {
306	    // Simulate the whole sequence — no Proxmox call, no SSH — but exercise the
307	    // real progress bar and persist the purchased storage so billing is exact.
308	    for (const s of [
309	      { pct: 8, step: "Checking current disk size" },
310	      { pct: 30, step: `Growing the virtual disk to ${targetTotalGB} GB` },
311	      { pct: 60, step: "Connecting to the server" },
312	      { pct: 85, step: "Growing the root partition" },
313	      { pct: 95, step: "Growing the filesystem" },
314	    ]) {
315	      await step(s.pct, s.step);
316	      await new Promise((r) => setTimeout(r, 400));
317	    }
318	    await db.server.update({ where: { id: server.id }, data: { extraDiskGB: targetExtraDiskGB } });
319	    await step(100, "Storage expanded");
320	    await notify(
321	      server.userId,
322	      `${server.hostname}: storage expanded to ${targetTotalGB} GB`,
323	      `Sandbox expansion of +${addGB} GB completed (no real VM was touched). Added storage is permanent.`,
324	      link,
325	    );
326	    return;
327	  }
328	
329	  if (!server.vmid) throw new Error("disk expand: server has no VM yet");
330	  const { conn } = await nodeFor(server);
331	
332	  // 1. What size is the disk RIGHT NOW? (Authoritative — survives retries.)
333	  await step(5, "Checking current disk size");
334	  const cfg = await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`);
335	  const currentGB = parseDiskSizeGB(cfg?.scsi0);
336	  if (currentGB == null) throw new Error("disk expand: could not read the current scsi0 disk size");
337	
338	  // 2. Grow on the hypervisor — ONLY when it isn't already big enough. A retry
339	  //    after a crash lands here with the disk already grown and skips straight
340	  //    to the guest-side grow (idempotent, never shrinks).
341	  const deltaGB = targetTotalGB - currentGB;
342	  if (deltaGB > 0) {
343	    await step(15, `Growing the virtual disk to ${targetTotalGB} GB`);
344	    // Proxmox accepts only a POSITIVE delta here ("+NG") and refuses to shrink.
345	    const upid = await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
346	      disk: "scsi0",
347	      size: `+${deltaGB}G`,
348	    });
349	    if (typeof upid === "string" && upid.startsWith("UPID")) {
350	      await step(30, "Waiting for the hypervisor");
351	      await conn.waitForTask(upid, 600_000);
352	    }
353	  } else {
354	    console.log(`[disk-expand] vmid ${server.vmid} already ${currentGB}G >= ${targetTotalGB}G — skipping Proxmox resize`);
355	  }
356	
357	  // 3. Grow the guest filesystem ONLINE. A failure here is NOT a job failure —
358	  //    the space is already paid for and already attached.
359	  let warn: { reason: string; commands: string } | null = null;
360	  if (server.status !== "RUNNING") {
361	    warn = {
362	      reason: "the server is powered off",
363	      commands: manualCommands(null),
364	    };
365	  } else {
366	    await step(55, "Connecting to the server");
367	    warn = await growGuestFilesystem(server, step);
368	  }
369	
370	  // 4. Persist the purchased storage. Done AFTER the disk really grew, so a
371	  //    terminal failure before this point is refunded by the worker's reconcile
372	  //    pass and never renews.
373	  await db.server.update({ where: { id: server.id }, data: { extraDiskGB: targetExtraDiskGB } });
374	
375	  if (warn) {
376	    await step(100, `Disk grown to ${targetTotalGB} GB — filesystem needs a manual grow`);
377	    await notify(
378	      server.userId,
379	      `${server.hostname}: disk grown to ${targetTotalGB} GB — one step left`,
380	      `We added ${addGB} GB and your virtual disk is now ${targetTotalGB} GB, but we couldn't expand the filesystem automatically because ${warn.reason}. ` +
381	        (server.status !== "RUNNING"
382	          ? "Most images grow the filesystem by themselves on the next boot — just start the server. If it doesn't, "
383	          : "") +
384	        `SSH in as root and run:\n\n    ${warn.commands}\n\nThen \`df -h /\` will show the full ${targetTotalGB} GB. Added storage is permanent for this server's lifetime.`,
385	      link,
386	    );
387	    console.warn(`[disk-expand] ${server.hostname}: online grow skipped — ${warn.reason}`);
388	    return;
389	  }
390	
391	  await step(100, `Storage expanded to ${targetTotalGB} GB`);
392	  await notify(
393	    server.userId,
394	    `${server.hostname}: storage expanded to ${targetTotalGB} GB`,
395	    `We added ${addGB} GB to this server's disk and grew the filesystem — \`df -h /\` shows it now. Added storage is permanent for this server's lifetime and renews with the server.`,
396	    link,
397	  );
398	}
