400	// "Build with Claude AI" worker handler — SAFE, plan-then-approve.
401	//
402	// Two phases, driven by ClaudeBuild.approved:
403	//   1. PLAN  (approved=false): ask Claude — with the OWNER'S effective key — for
404	//      an ordered JSON array of non-destructive shell commands. Store it to
405	//      ClaudeBuild.plan and set AWAITING_APPROVAL. NOTHING is executed.
406	//   2. EXECUTE (approved=true): run each approved command over SSH, enforcing a
407	//      denylist, a per-command timeout, and a hard command cap. Append output to
408	//      ClaudeBuild.log, then set DONE (or FAILED on error). Never runs a command
409	//      that was not part of the approved plan.
410	//
411	// This handler is wired into worker/index.ts's `handlers` map by the
412	// orchestrator (see INTEGRATION NEEDED in the final report):
413	//   import { claudeBuild } from "./claude";
414	//   CLAUDE_BUILD: claudeBuild,
415	
416	import { execFile } from "node:child_process";
417	import { promisify } from "node:util";
418	import { db } from "../lib/db";
419	import { askClaude, effectiveKeyFor, type ClaudeMessage } from "../lib/anthropic";
420	import { SANDBOX } from "../lib/sandbox";
421	import { serverRootPassword } from "../lib/sftp";
422	import type { Job } from "@prisma/client";
423	
424	const execFileAsync = promisify(execFile);
425	
426	/** Hard cap on the number of commands executed for a single build. */
427	export const CLAUDE_MAX_COMMANDS = 20;
428	
429	/** Per-command SSH execution timeout. */
430	const CMD_TIMEOUT_MS = 120_000;
431	/** Cap on captured output per command (chars) to keep the log bounded. */
432	const MAX_OUTPUT_CHARS = 4000;
433	/** Cap on total stored log size. */
434	const MAX_LOG_CHARS = 60_000;
435	
436	type PlanStep = { cmd: string; intent: string };
437	
438	const PLAN_SYSTEM_PROMPT = `You are an expert Linux server administrator. You are given a goal for a SINGLE Debian/Ubuntu server that you operate on over SSH as root. Produce a PLAN — do NOT run anything.
439	
440	Output ONLY a JSON array of steps and NOTHING else (no markdown, no backticks, no prose before or after). Each step is an object:
441	{"cmd": "<one non-interactive shell command>", "intent": "<short plain-English explanation of what it does and why>"}
442	
443	Rules for the plan:
444	- Operate ONLY on this one server. Never touch other hosts, networks, or cloud APIs.
445	- Commands must be non-interactive: use flags like -y and DEBIAN_FRONTEND=noninteractive; never launch editors, pagers, REPLs, or anything that waits for input.
446	- NON-DESTRUCTIVE ONLY. Absolutely no whole-disk or whole-system operations: no rm -rf /, no mkfs/fdisk/dd on disks, no wiping /etc, no reboot/shutdown/poweroff/halt, no user/password changes, no disabling SSH.
447	- Keep each command self-contained and idempotent where possible.
448	- Prefer standard packages and services (apt, systemctl, nginx, ufw, etc.).
449	- At most ${CLAUDE_MAX_COMMANDS} steps. If the goal cannot be met safely, return an empty array [].`;
450	
451	/** Escape a string for safe single-quoted inclusion in a bash -c argument. */
452	function shSingleQuote(s: string): string {
453	  return `'${s.replace(/'/g, `'\\''`)}'`;
454	}
455	
456	/** Reject catastrophic commands as a defense-in-depth backstop (denylist). */
457	function isForbidden(cmd: string): boolean {
458	  const c = cmd.toLowerCase();
459	  const patterns = [
460	    /rm\s+(-[a-z]*\s+)*(-[a-z]*r[a-z]*f|-[a-z]*f[a-z]*r)\s+\/(\s|$)/, // rm -rf /
461	    /\bmkfs\b/,
462	    /\bfdisk\b/,
463	    /\bparted\b/,
464	    /\bdd\b[^|]*of=\/dev\//, // dd of=/dev/*
465	    /\b(reboot|shutdown|poweroff|halt|init\s+0|init\s+6)\b/,
466	    /\bshred\b/,
467	    /\bpasswd\b/,
468	    /:\(\)\s*\{.*\};:/, // fork bomb :(){ :|:& };:
469	    />\s*\/dev\/sd[a-z]/,
470	    /\bsystemctl\s+(stop|disable|mask)\s+(ssh|sshd)\b/,
471	  ];
472	  return patterns.some((p) => p.test(c));
473	}
