475	/** Run one command on the server over SSH via sshpass. Never throws. */
476	async function sshExec(
477	  server: { ipAddress: string | null; rootPassword: string | null; rootPasswordEnc?: string | null },
478	  command: string
479	): Promise<{ output: string; failed: boolean }> {
480	  const password = serverRootPassword(server);
481	  if (!server.ipAddress || !password) {
482	    return { output: "[nxeon] server has no reachable IP or root password", failed: true };
483	  }
484	  // The worker reaches VMs directly on the private bridge (10.20.0.0/24), so we
485	  // connect to the private IP on port 22.
486	  const args = [
487	    "-p",
488	    password,
489	    "ssh",
490	    "-o",
491	    "StrictHostKeyChecking=no",
492	    "-o",
493	    "UserKnownHostsFile=/dev/null",
494	    "-o",
495	    "ConnectTimeout=10",
496	    "-o",
497	    "BatchMode=no",
498	    `root@${server.ipAddress}`,
499	    // Wrap in bash -c with a single-quoted payload so complex commands survive intact.
500	    `bash -c ${shSingleQuote(command)}`,
501	  ];
502	  try {
503	    const { stdout, stderr } = await execFileAsync("sshpass", args, {
504	      timeout: CMD_TIMEOUT_MS,
505	      maxBuffer: 8 * 1024 * 1024,
506	      env: { ...process.env, DEBIAN_FRONTEND: "noninteractive" },
507	    });
508	    const out = `${stdout}${stderr ? `\n${stderr}` : ""}`.trim();
509	    return { output: out || "[no output]", failed: false };
510	  } catch (e: any) {
511	    // execFile rejects on non-zero exit or timeout; capture whatever we got.
512	    const out = `${e?.stdout ?? ""}${e?.stderr ? `\n${e.stderr}` : ""}`.trim();
513	    const reason = e?.killed
514	      ? `[nxeon] command timed out after ${CMD_TIMEOUT_MS / 1000}s`
515	      : `[nxeon] command exited with code ${e?.code ?? "?"}`;
516	    return { output: `${out ? out + "\n" : ""}${reason}`, failed: true };
517	  }
518	}
