524	/** Parse Claude's plan reply into a validated list of steps, or null. */
525	function parsePlan(reply: string): PlanStep[] | null {
526	  const start = reply.indexOf("[");
527	  const end = reply.lastIndexOf("]");
528	  if (start === -1 || end === -1 || end < start) return null;
529	  let raw: unknown;
530	  try {
531	    raw = JSON.parse(reply.slice(start, end + 1));
532	  } catch {
533	    return null;
534	  }
535	  if (!Array.isArray(raw)) return null;
536	  const steps: PlanStep[] = [];
537	  for (const item of raw) {
538	    if (typeof item === "string") {
539	      const cmd = item.trim();
540	      if (cmd) steps.push({ cmd, intent: "" });
541	    } else if (item && typeof item === "object") {
542	      const anyItem = item as Record<string, unknown>;
543	      const cmd = String(anyItem.cmd ?? anyItem.command ?? "").trim();
544	      const intent = String(anyItem.intent ?? anyItem.description ?? "").trim();
545	      if (cmd) steps.push({ cmd, intent });
546	    }
547	  }
548	  return steps.length ? steps : null;
549	}
