558	export async function claudeBuild(job: Job): Promise<void> {
559	  const payload = (job.payload ?? {}) as { buildId?: string };
560	  const buildId = payload.buildId;
561	  if (!buildId) throw new Error("claudeBuild: missing buildId in job payload");
562	
563	  const build = await db.claudeBuild.findUnique({ where: { id: buildId }, include: { server: true } });
564	  if (!build) throw new Error(`claudeBuild: build ${buildId} not found`);
565	  const server = build.server;
566	
567	  // Terminal builds are never re-processed by a stray/duplicate job.
568	  if (build.status === "DONE" || build.status === "FAILED") return;
569	
570	  if (SANDBOX) {
571	    // Simulate the plan-then-approve flow with no Anthropic call and no SSH.
572	    if (!build.approved) {
573	      await db.claudeBuild.update({
574	        where: { id: buildId },
575	        data: {
576	          status: "AWAITING_APPROVAL",
577	          plan: JSON.stringify([{ cmd: "echo sandbox build", intent: "Sandbox simulated step" }]),
578	        },
579	      });
580	    } else {
581	      await db.claudeBuild.update({
582	        where: { id: buildId },
583	        data: {
584	          status: "DONE",
585	          steps: 1,
586	          log: truncate((build.log ?? "") + "\n[sandbox] simulated build completed\n", MAX_LOG_CHARS),
587	        },
588	      });
589	      await db.notification
590	        .create({
591	          data: {
592	            userId: build.userId,
593	            title: `Claude finished building on ${server?.hostname ?? "your server"}`,
594	            body: build.prompt.slice(0, 140),
595	            href: `/dashboard/build`,
596	          },
597	        })
598	        .catch(() => {});
599	    }
600	    return;
601	  }
602	
603	  // Everything is gated on an effective owner key + a reachable RUNNING server.
604	  const owner = await db.user.findUnique({
605	    where: { id: build.userId },
606	    select: { anthropicKeyEnc: true },
607	  });
608	  const apiKey = effectiveKeyFor(owner);
609	  if (!apiKey) {
610	    await failBuild(buildId, build.log ?? "", "No Anthropic API key available for the owner.");
611	    return;
612	  }
613	  if (!server || server.status !== "RUNNING") {
614	    await failBuild(buildId, build.log ?? "", "The server is not running.");
615	    return;
616	  }
617	  if (!server.ipAddress || !serverRootPassword(server)) {
618	    await failBuild(buildId, build.log ?? "", "The server is not reachable (no IP or root password).");
