620	  }
621	
622	  if (!build.approved) {
623	    await planPhase(buildId, build.status, build.prompt, build.log ?? "", apiKey);
624	  } else {
625	    await executePhase(buildId, build.prompt, build.plan, build.log ?? "", server);
626	  }
627	}
