629	/** Phase 1: ask Claude for a plan, store it, and await owner approval. */
630	async function planPhase(
631	  buildId: string,
632	  status: string,
633	  prompt: string,
634	  priorLog: string,
635	  apiKey: string
636	): Promise<void> {
637	  // Only plan for a not-yet-planned build; ignore duplicate jobs otherwise.
638	  if (status !== "QUEUED" && status !== "PLANNING") return;
639	
640	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "PLANNING" } });
641	
642	  const messages: ClaudeMessage[] = [
643	    { role: "user", content: `Goal: ${prompt}\n\nProduce the plan now as a JSON array of {"cmd","intent"} steps.` },
644	  ];
645	
646	  let reply: string;
647	  try {
648	    reply = await askClaude(apiKey, messages, PLAN_SYSTEM_PROMPT, { maxTokens: 4096, timeoutMs: 90_000 });
649	  } catch (e: any) {
650	    await failBuild(buildId, priorLog, `Planning failed: ${e?.message ?? e}`);
651	    return;
652	  }
653	
654	  const plan = parsePlan(reply);
655	  if (!plan) {
656	    await failBuild(buildId, priorLog, "Claude did not return a usable plan for this goal.");
657	    return;
658	  }
659	
660	  const capped = plan.slice(0, CLAUDE_MAX_COMMANDS);
661	  await db.claudeBuild.update({
662	    where: { id: buildId },
663	    data: { status: "AWAITING_APPROVAL", plan: JSON.stringify(capped) },
664	  });
665	}
