667	/** Phase 2: execute the OWNER-APPROVED plan over SSH. */
668	async function executePhase(
669	  buildId: string,
670	  prompt: string,
671	  planJson: string | null,
672	  priorLog: string,
673	  server: { ipAddress: string | null; rootPassword: string | null; rootPasswordEnc?: string | null; hostname: string | null }
674	): Promise<void> {
675	  let plan: PlanStep[] = [];
676	  try {
677	    const parsed = JSON.parse(planJson ?? "[]");
678	    if (Array.isArray(parsed)) {
679	      plan = parsed
680	        .map((s: any) => ({ cmd: String(s?.cmd ?? s ?? "").trim(), intent: String(s?.intent ?? "") }))
681	        .filter((s: PlanStep) => s.cmd);
682	    }
683	  } catch {
684	    plan = [];
685	  }
686	
687	  if (plan.length === 0) {
688	    await failBuild(buildId, priorLog, "No approved plan to execute.");
689	    return;
690	  }
691	
692	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "RUNNING" } });
693	
694	  const commands = plan.slice(0, CLAUDE_MAX_COMMANDS);
695	  let log = priorLog;
696	  const append = async (chunk: string, steps: number) => {
697	    log = truncate(log + chunk, MAX_LOG_CHARS);
698	    await db.claudeBuild.update({ where: { id: buildId }, data: { log, steps } });
699	  };
700	
701	  await append(`# Goal: ${prompt}\n# Executing approved plan (${commands.length} command(s))\n\n`, 0);
702	
703	  let steps = 0;
704	  let finalStatus: "DONE" | "FAILED" = "DONE";
705	
706	  try {
707	    for (const step of commands) {
708	      const command = step.cmd;
709	
710	      // Defense-in-depth: even an approved plan is re-checked against the denylist.
711	      if (isForbidden(command)) {
712	        await append(`\n$ ${command}\n[nxeon] Skipped — blocked by the safety denylist.\n`, steps);
713	        continue;
714	      }
715	
716	      steps += 1;
717	      const { output, failed } = await sshExec(server, command);
718	      const shown = truncate(output, MAX_OUTPUT_CHARS);
719	      await append(`\n$ ${command}\n${shown}\n`, steps);
720	
721	      if (failed) {
722	        await append(`\n[nxeon] Command failed — stopping execution.\n`, steps);
723	        finalStatus = "FAILED";
724	        break;
725	      }
726	    }
727	  } catch (e: any) {
728	    await append(`\n[nxeon] Build error: ${e?.message ?? e}\n`, steps);
729	    finalStatus = "FAILED";
730	  }
731	
732	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: finalStatus, steps } });
733	
734	  try {
735	    await db.notification.create({
736	      data: {
737	        userId: (await db.claudeBuild.findUnique({ where: { id: buildId }, select: { userId: true } }))!.userId,
738	        title:
739	          finalStatus === "DONE"
740	            ? `Claude finished building on ${server.hostname}`
741	            : `Claude build failed on ${server.hostname}`,
742	        body: prompt.slice(0, 140),
743	        href: `/dashboard/build`,
744	      },
745	    });
746	  } catch {
747	    /* notification is best-effort */
748	  }
749	}
