27	 *
28	 * A volume's underlying Proxmox disk only exists once it has been attached at
29	 * least once. `Volume.diskName` stores the STABLE Proxmox volume id of that disk
30	 * (e.g. "vmdata:vm-101-disk-1") — not a slot — because the slot/unused index
31	 * changes across detach/re-attach; we always re-scan the VM config to find the
32	 * disk's current key (scsiN while attached, unusedN while detached).
33	 *
34	 * ─── THREE THINGS THIS FILE IS RESPONSIBLE FOR ──────────────────────────────
35	 *
36	 * 1. PORTABILITY (a volume is sold as a portable disk, not a welded one).
37	 *    A Proxmox disk is OWNED by a vmid (`vm-<vmid>-disk-N`), so moving a volume
38	 *    to another server is not a DB edit — the disk has to be reassigned to the
39	 *    other VM (`move_disk` + `target-vmid`, which RENAMES the volume). See
40	 *    `reassignDiskToServer`. PVE requires both VMs on the same node, so a
41	 *    cross-node move is refused up front instead of half-done.
42	 *
43	 * 2. GUEST PREPARATION (format on first use, mount on every use).
44	 *    Nothing used to format or mount a volume: attach hot-plugged a raw disk and
45	 *    the notification told the customer to do it themselves. That is also why
46	 *    `Volume.inUse` was never knowable. `prepareGuestVolume` now does it — and is
47	 *    written to REFUSE on any ambiguity rather than risk a customer's bytes.
48	 *
49	 * 3. SAFE DETACH (never hot-unplug a live filesystem).
50	 *    A detach used to be an unconditional SCSI unplug with no sync and no
51	 *    unmount: a volume mounted at /var/lib/mysql lost its device mid-write →
52	 *    journal abort / InnoDB corruption. `releaseGuestVolume` unmounts first and
53	 *    REFUSES when the filesystem is still in use, unless the customer has given
54	 *    an explicit informed override (`payload.ackInUse`).
55	 *
56	 * ─── PROXMOX CONFIG WRITES ARE ASYNCHRONOUS ─────────────────────────────────
57	 * A config POST returns before the config file reflects it, so an immediate GET
58	 * can hand back the pre-write view. Every read-after-write in this file goes
59	 * through `waitForConfig` — that race is exactly how volumes ended up with a
60	 * null `diskName` in production.
61	 */
62	
63	async function loadVolume(job: Job) {
64	  const payload = (job.payload ?? {}) as { volumeId?: string };
65	  if (!payload.volumeId) throw new Error("volume job: missing volumeId");
66	  const volume = await db.volume.findUnique({
67	    where: { id: payload.volumeId },
68	    // `dedicatedIp` is needed to open an SSH session to the guest (lib/sftp
69	    // connectionTarget: dedicated IP:22, else PUBLIC_IP:sshPort).
70	    include: { server: { include: { node: true, dedicatedIp: true } } },
71	  });
72	  if (!volume) throw new Error(`Volume ${payload.volumeId} not found`);
73	  return volume;
74	}
75	
76	/** The server a VOLUME_ATTACH should land on. */
77	async function loadAttachTarget(job: Job, volume: Awaited<ReturnType<typeof loadVolume>>) {
78	  const payload = (job.payload ?? {}) as { targetServerId?: string };
79	  // `targetServerId` is authoritative: the enqueueing action deliberately does
80	  // NOT re-point `Volume.serverId` when a volume moves between servers, because
81	  // that pin is what stops a reinstall/restore on the server that still
82	  // physically holds the disk from purging it (worker/index.ts). Fall back to
83	  // `job.serverId` / `volume.serverId` so jobs queued by the older action (which
84	  // carried no targetServerId) still resolve correctly.
85	  const id = payload.targetServerId ?? job.serverId ?? volume.serverId;
86	  if (!id) return null;
87	  return db.server.findUnique({
88	    where: { id },
89	    include: { node: true, dedicatedIp: true },
90	  });
91	}
