128	/** Strip Proxmox disk options: "vmdata:vm-101-disk-1,size=10G" -> "vmdata:vm-101-disk-1". */
129	function volidOf(configValue: unknown): string {
130	  return String(configValue ?? "").split(",")[0].trim();
131	}
132	
133	/**
134	 * True for a real Proxmox disk volid such as "vmdata:vm-102-disk-1" (or a
135	 * file/dir volid like "vmdata:102/vm-102-disk-1.raw"). Used to reject empty/
136	 * garbage read-backs so `Volume.diskName` is never persisted as a non-volid.
137	 */
138	function isRealVolid(v: unknown): v is string {
139	  return typeof v === "string" && /^[^,\s:]+:\S*vm-\d+-disk-\d+/.test(v.trim());
140	}
141	
142	/** The vmid that OWNS a volid ("vmdata:vm-102-disk-1" -> 102), or null. */
143	function vmidOfVolid(volid: unknown): number | null {
144	  const m = /vm-(\d+)-disk-\d+/.exec(String(volid ?? ""));
145	  if (!m) return null;
146	  const n = Number(m[1]);
147	  return Number.isInteger(n) && n > 0 ? n : null;
148	}
149	
150	/** All disk volids currently referenced by a VM config (scsi/virtio/ide/sata/unused). */
151	function diskVolids(config: Record<string, any>): string[] {
152	  const out: string[] = [];
153	  for (const [k, v] of Object.entries(config)) {
154	    if (typeof v !== "string") continue;
155	    if (!/^(scsi|virtio|ide|sata|unused)\d+$/.test(k)) continue;
156	    const id = volidOf(v);
157	    if (isRealVolid(id)) out.push(id);
158	  }
159	  return out;
160	}
161	
162	/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
163	function freeScsiSlot(config: Record<string, any>): string {
164	  for (let i = 1; i <= 30; i++) {
165	    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
166	  }
167	  throw new Error("no free scsi slot available on this VM");
168	}
169	
170	/** Find the config key (scsiN / unusedN / …) that currently references `volid`. */
171	function keyForVolid(config: Record<string, any>, volid: string): string | null {
172	  for (const [k, v] of Object.entries(config)) {
173	    if (typeof v === "string" && volidOf(v) === volid) return k;
174	  }
175	  return null;
176	}
