178	/**
179	 * Read a VM config, polling until `ready(config)` is satisfied.
180	 *
181	 * Proxmox applies a config POST ASYNCHRONOUSLY: the call returns before the
182	 * config file is rewritten, so an immediate GET can still return the pre-write
183	 * view. Every read-after-write here uses this — the un-polled version is how
184	 * ATTACHED volumes ended up with `diskName === null`, which then made a
185	 * re-attach hand back a brand-new empty disk and orphan the real one.
186	 */
187	async function waitForConfig(
188	  conn: any,
189	  vmid: number,
190	  ready: (config: Record<string, any>) => boolean,
191	  tries = 10,
192	  delayMs = 1000
193	): Promise<Record<string, any>> {
194	  let config = (await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`)) as Record<string, any>;
195	  for (let i = 0; i < tries && !ready(config); i++) {
196	    await new Promise((r) => setTimeout(r, delayMs));
197	    config = (await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`)) as Record<string, any>;
198	  }
199	  return config;
200	}
