202	/**
203	 * Is the VM actually running right now?
204	 *
205	 * `Server.status` is NOT good enough for this decision: a row can say STOPPED or
206	 * ERROR while the VM is up (and vice versa), and getting it wrong here means
207	 * hot-unplugging a mounted filesystem. Proxmox is the ground truth; "unknown" is
208	 * reported honestly so the caller can refuse instead of assuming.
209	 */
210	async function vmRunState(conn: any, vmid: number): Promise<"running" | "stopped" | "unknown"> {
211	  try {
212	    const s = await conn.vmStatus(vmid);
213	    const st = String(s?.status ?? "");
214	    if (st === "running") return "running";
215	    if (st) return "stopped";
216	  } catch (e) {
217	    console.error(`[volumes] could not read run state of VM ${vmid}`, e);
218	  }
219	  return "unknown";
220	}
221	
222	// ===========================================================================
223	// GUEST SIDE — detect / format / mount / unmount
224	// ===========================================================================
225	/**
226	 * Everything below runs inside the customer's VM over SSH, and every command is
227	 * built the way lib/ssh-exec.ts demands: values are validated against a
228	 * shell-inert allowlist FIRST (we reject, never sanitize) and quoted second.
229	 *
230	 * The formatting decision is the most dangerous operation in this file, so it is
231	 * deliberately gated by five INDEPENDENT layers, and any one of them failing (or
232	 * being merely unclear) means we mount nothing and format nothing:
233	 *
234	 *   1. IDENTITY — the device must be one that appeared in the guest between a
235	 *      snapshot taken BEFORE the hot-plug and a poll taken after it, and exactly
236	 *      one such device may appear. We never guess "probably /dev/sdb".
237	 *   2. SIZE — that device's size must match the volume's nominal size.
238	 *   3. HISTORY — the Volume row must never have carried a filesystem
239	 *      (`fsType`/`mountPath`/`inUse` all unset). If the row says it was
240	 *      formatted but the disk looks blank, that contradiction means we may be
241	 *      looking at the wrong device: refuse and report, touch nothing.
242	 *   4. SIGNATURES — `blkid`, `wipefs -n`, children, holders and mountpoints must
243	 *      all come back empty, AND three separate 1–4 MiB windows (start, middle,
244	 *      end) must read as pure zeros. Every filesystem/partition table/LVM/LUKS/
245	 *      md-raid layout writes a header inside those windows, so "no signature and
246	 *      zeros at both ends" is as close to proof-of-blank as a disk allows.
247	 *   5. mke2fs ITSELF — `mkfs.ext4` is invoked with a SINGLE `-F`. That waives
248	 *      only the "this is a whole device, not a partition" objection; a single
249	 *      `-F` still makes mke2fs refuse a device that is mounted or otherwise in
250	 *      use by the kernel (two are required to override that), so the kernel gets
251	 *      the last veto after all our own checks.
252	 */
253	
254	const GiB = 1024 ** 3;
255	/** A bare kernel block-device name we are willing to interpolate: "sdb", "vdc". */
256	const DEV_NAME_RE = /^[a-z][a-z0-9]{1,31}$/;
257	const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
258	/** Absolute mount path we either generate or read back from the guest. */
259	const MOUNT_PATH_RE = /^\/[A-Za-z0-9._/-]{1,120}$/;
260	/** Filesystems we are willing to mount unattended. */
261	const MOUNTABLE_FS = new Set(["ext2", "ext3", "ext4", "xfs", "btrfs"]);
262	/** What a blank volume gets formatted with. */
263	const VOLUME_FS = "ext4";
264	
265	/** Strip control characters and clamp — everything read back from the guest. */
266	function clean(s: unknown, max: number): string {
267	  return String(s ?? "")
268	    .replace(/[\x00-\x1f\x7f]/g, " ")
269	    .trim()
270	    .slice(0, max);
271	}
272	
273	/**
274	 * Run one guest command, turning transport failures into an empty result instead
275	 * of an exception: every caller treats "no output" as "unclear → do not touch",
276	 * so a timeout can never be mistaken for a green light (nor fail an attach that
277	 * has already been paid for and hot-plugged).
278	 */
279	async function sh(
280	  conn: Client,
281	  cmd: string,
282	  timeoutMs: number = QUICK_TIMEOUT_MS
283	): Promise<{ code: number | null; stdout: string; stderr: string }> {
284	  try {
285	    return await exec(conn, cmd, timeoutMs);
286	  } catch (e: any) {
287	    return { code: null, stdout: "", stderr: String(e?.message ?? e) };
288	  }
289	}
290	
291	/** Pull `KEY=value` out of a probe's stdout. */
292	function kv(out: string, key: string): string {
293	  return clean(new RegExp(`^${key}=(.*)$`, "m").exec(out ?? "")?.[1] ?? "", 255);
294	}
295	
296	type GuestDisk = { name: string; type: string; sizeBytes: number; fstype: string; mount: string; pkname: string };
297	
298	function parseLsblk(out: string): GuestDisk[] {
299	  const rows: GuestDisk[] = [];
300	  for (const line of (out ?? "").split("\n")) {
301	    if (!line.trim()) continue;
302	    const map: Record<string, string> = {};
303	    for (const m of line.matchAll(/([A-Z]+)="([^"]*)"/g)) map[m[1]] = m[2];
304	    if (!map.NAME) continue;
305	    rows.push({
306	      name: clean(map.NAME, 64),
307	      type: clean(map.TYPE ?? "", 32),
308	      sizeBytes: Number(map.SIZE) || 0,
309	      fstype: clean(map.FSTYPE ?? "", 32),
310	      mount: clean(map.MOUNTPOINT ?? "", 200),
311	      pkname: clean(map.PKNAME ?? "", 64),
312	    });
313	  }
314	  return rows;
315	}
316	
317	/** Every block device the guest can see right now, or null if it could not be read. */
318	async function guestBlockDevices(conn: Client): Promise<GuestDisk[] | null> {
319	  const r = await sh(conn, `lsblk -b -P -o NAME,TYPE,SIZE,FSTYPE,MOUNTPOINT,PKNAME 2>/dev/null`);
320	  const rows = parseLsblk(r.stdout);
321	  return rows.length ? rows : null;
322	}
323	
324	/**
325	 * Names of the whole disks that carry (or stack under) the root filesystem.
326	 * Nothing in that tree is ever a candidate, however it is stacked (partition,
327	 * LVM, dm-crypt) — walking PKNAME keeps an LVM root from ever looking "blank".
328	 */
329	async function rootDiskNames(conn: Client, rows: GuestDisk[]): Promise<Set<string>> {
330	  const byName = new Map(rows.map((r) => [r.name, r]));
331	  const topOf = (name: string): string => {
332	    let cur = name;
333	    for (let i = 0; i < 8; i++) {
334	      const row = byName.get(cur);
335	      if (!row?.pkname || row.pkname === cur) break;
336	      cur = row.pkname;
337	    }
338	    return cur;
339	  };
340	  const out = new Set<string>();
341	  const r = await sh(conn, `findmnt -nro SOURCE / 2>/dev/null | head -n1`);
342	  const src = clean(r.stdout, 128);
343	  if (src.startsWith("/dev/")) {
344	    out.add(topOf(src.slice(src.lastIndexOf("/") + 1)));
345	    const pk = await sh(conn, `lsblk -no PKNAME ${shellQuote(src)} 2>/dev/null | head -n1`);
346	    const parent = clean(pk.stdout, 64);
347	    if (parent) out.add(topOf(parent));
348	  }
349	  return out;
350	}
351	
352	/** Whole-disk names visible in the guest (excluding the root disk's tree). */
353	async function guestDiskNames(conn: Client): Promise<Set<string> | null> {
354	  const rows = await guestBlockDevices(conn);
355	  if (!rows) return null;
356	  const roots = await rootDiskNames(conn, rows);
357	  return new Set(rows.filter((d) => d.type === "disk" && !roots.has(d.name)).map((d) => d.name));
358	}
359	
360	type DeviceProbe = {
361	  ok: boolean;
362	  sizeBytes: number;
363	  fsType: string;
364	  ptType: string;
365	  uuid: string;
366	  mount: string;
367	  /** True only when EVERY blankness test came back negative. */
368	  blank: boolean;
369	  /** Human-readable list of the signs of data we found (empty when blank). */
370	  evidence: string[];
371	};
372	
373	/**
374	 * READ-ONLY interrogation of one whole disk, in a single round trip.
375	 *
376	 * `blkid -p` probes the device itself rather than the (possibly stale) cache, and
377	 * the three `dd` windows catch layouts libblkid does not know: a filesystem, a
378	 * partition table, an LVM PV label, a LUKS header, an md-raid superblock (1.0
379	 * lives at the END of the device — hence the tail window) or a swap area all put
380	 * bytes inside them. Reading is the only thing this function does.
381	 */
382	async function probeDevice(conn: Client, name: string): Promise<DeviceProbe> {
383	  const fail: DeviceProbe = { ok: false, sizeBytes: 0, fsType: "", ptType: "", uuid: "", mount: "", blank: false, evidence: ["the disk could not be interrogated"] };
384	  if (!DEV_NAME_RE.test(name)) return fail;
385	  const dev = `/dev/${name}`;
386	  const q = shellQuote(dev);
387	  const probe = [
388	    `SZ=$(blockdev --getsize64 ${q} 2>/dev/null || echo 0)`,
389	    `echo "SIZE=$SZ"`,
390	    `echo "FSTYPE=$(blkid -p -s TYPE -o value ${q} 2>/dev/null)"`,
391	    `echo "PTTYPE=$(blkid -p -s PTTYPE -o value ${q} 2>/dev/null)"`,
392	    `echo "USAGE=$(blkid -p -s USAGE -o value ${q} 2>/dev/null)"`,
393	    `echo "UUID=$(blkid -s UUID -o value ${q} 2>/dev/null)"`,
394	    `echo "MOUNT=$(findmnt -nro TARGET -S ${q} 2>/dev/null | head -n1)"`,
395	    `echo "HOLDERS=$(ls -A /sys/block/${name}/holders 2>/dev/null | tr '\\n' ' ')"`,
396	    `echo "CHILDREN=$(lsblk -no NAME ${q} 2>/dev/null | tail -n +2 | tr -d ' ' | tr '\\n' ' ')"`,
397	    `if command -v wipefs >/dev/null 2>&1; then echo "WIPEFS=$(wipefs -n ${q} 2>/dev/null | wc -l)"; else echo "WIPEFS=na"; fi`,
398	    // Three zero-windows: first 4 MiB, 1 MiB at the midpoint, last 1 MiB.
399	    `nz() { dd if=${q} bs=1048576 skip="$1" count="$2" iflag=skip_bytes,count_bytes 2>/dev/null | tr -d '\\000' | wc -c; }`,
400	    `[ "$SZ" -gt 8388608 ] 2>/dev/null && { echo "ZHEAD=$(nz 0 4194304)"; echo "ZMID=$(nz $((SZ/2)) 1048576)"; echo "ZTAIL=$(nz $((SZ-1048576)) 1048576)"; }`,
401	    `echo "PROBE=OK"`,
402	  ].join("; ");
403	
404	  const r = await sh(conn, probe, SETUP_TIMEOUT_MS);
405	  if (kv(r.stdout, "PROBE") !== "OK") return fail;
406	
407	  const sizeBytes = Number(kv(r.stdout, "SIZE")) || 0;
408	  const fsType = kv(r.stdout, "FSTYPE").toLowerCase();
409	  const ptType = kv(r.stdout, "PTTYPE").toLowerCase();
410	  const usage = kv(r.stdout, "USAGE").toLowerCase();
411	  const uuid = kv(r.stdout, "UUID");
412	  const mount = kv(r.stdout, "MOUNT");
413	  const holders = kv(r.stdout, "HOLDERS");
414	  const children = kv(r.stdout, "CHILDREN");
415	  const wipefs = kv(r.stdout, "WIPEFS");
416	  const zhead = kv(r.stdout, "ZHEAD");
417	  const zmid = kv(r.stdout, "ZMID");
418	  const ztail = kv(r.stdout, "ZTAIL");
419	
420	  const evidence: string[] = [];
421	  if (fsType) evidence.push(`a ${fsType} filesystem`);
422	  if (ptType) evidence.push(`a ${ptType} partition table`);
423	  if (usage && !fsType && !ptType) evidence.push(`a ${usage} signature`);
424	  if (uuid) evidence.push(`filesystem UUID ${uuid}`);
425	  if (mount) evidence.push(`it is mounted at ${mount}`);
426	  if (holders) evidence.push(`kernel holders (${holders})`);
427	  if (children) evidence.push(`child devices (${children})`);
428	  // `wipefs -n` prints nothing at all when it finds no magic; any line is a hit.
429	  if (wipefs !== "na" && Number(wipefs) > 0) evidence.push("on-disk signatures reported by wipefs");
430	  // A missing/short size, or zero-windows we could not read, is ambiguity — and
431	  // ambiguity is treated exactly like data.
432	  if (sizeBytes <= 8 * 1024 * 1024) evidence.push("its size could not be read");
433	  else if (zhead !== "0" || zmid !== "0" || ztail !== "0") {
434	    evidence.push(
435	      zhead === "" || zmid === "" || ztail === ""
436	        ? "the raw start/middle/end of the disk could not be read back"
437	        : "non-zero bytes at the start, middle or end of the disk"
438	    );
439	  }
440	
441	  return { ok: true, sizeBytes, fsType, ptType, uuid, mount, blank: evidence.length === 0, evidence };
442	}
443	
444	/** Does `sizeBytes` plausibly belong to a `sizeGB` volume? */
445	function sizeMatches(sizeBytes: number, sizeGB: number): boolean {
446	  const expected = Math.max(1, Math.round(sizeGB)) * GiB;
447	  // Storage back-ends round up to an extent / volblocksize, so allow a little
448	  // slack — but not enough to confuse a volume with a differently-sized disk.
449	  const slack = Math.max(64 * 1024 * 1024, expected * 0.03);
450	  return sizeBytes >= expected - slack && sizeBytes <= expected + slack;
451	}
452	
453	/** The default, stable mount point for a volume. Stable across re-attaches. */
454	function defaultMountPath(volumeId: string): string | null {
455	  const slug = String(volumeId ?? "").toLowerCase().replace(/[^a-z0-9]/g, "");
456	  if (slug.length < 8) return null;
457	  const path = `/mnt/nxeon-vol-${slug}`;
458	  return MOUNT_PATH_RE.test(path) ? path : null;
459	}
460	
461	/**
462	 * Give the guest a chance to notice a freshly hot-plugged SCSI disk, then return
463	 * the ONE device that appeared since `before`.
464	 *
465	 * Identity by set-difference (not by name, size or slot arithmetic) is what makes
466	 * the rest of this safe: the device we go on to touch is, by construction, the one
467	 * that appeared when we plugged this volume in. Zero or several new devices means
468	 * we cannot say which disk is the customer's — so we say so and stop.
469	 */
470	async function findAttachedDevice(
471	  conn: Client,
472	  before: Set<string>,
473	  sizeGB: number
474	): Promise<{ name: string } | { error: string }> {
475	  // Writing "- - -" to a SCSI host's scan node only asks the kernel to re-probe.
476	  await sh(conn, `for h in /sys/class/scsi_host/host*/scan; do echo '- - -' > "$h" 2>/dev/null; done; udevadm settle 2>/dev/null; true`);
477	
478	  let appeared: GuestDisk[] = [];
479	  for (let i = 0; i < 12; i++) {
480	    const rows = await guestBlockDevices(conn);
481	    if (rows) {
482	      const roots = await rootDiskNames(conn, rows);
483	      appeared = rows.filter((d) => d.type === "disk" && !roots.has(d.name) && !before.has(d.name));
484	      if (appeared.length) break;
485	    }
486	    await new Promise((r) => setTimeout(r, 2500));
487	  }
488	
489	  if (appeared.length === 0) {
490	    return { error: "the server did not report a new disk after the attach (a reboot usually makes it appear)" };
491	  }
492	  if (appeared.length > 1) {
493	    return { error: `${appeared.length} new disks appeared at once, so we cannot tell which one is this volume` };
494	  }
495	  const dev = appeared[0];
496	  if (!DEV_NAME_RE.test(dev.name)) {
497	    return { error: `the new disk has an unexpected device name (${dev.name.slice(0, 20)})` };
498	  }
499	  if (!sizeMatches(dev.sizeBytes, sizeGB)) {
500	    return {
501	      error:
502	        `the new disk is ${Math.round(dev.sizeBytes / GiB)} GB but this volume is ${sizeGB} GB — ` +
503	        `refusing to touch a disk we cannot positively identify`,
504	    };
505	  }
506	  return { name: dev.name };
507	}
