509	/**
510	 * Persist an ALREADY-FORMATTED filesystem: an /etc/fstab entry BY UUID (never by
511	 * /dev/sdX — a volume can come back as a different letter, and then fstab mounts
512	 * the wrong disk) with `nofail`, then mount it.
513	 *
514	 * `nofail` is not optional. A volume can be detached, moved to another server or
515	 * simply fail to appear; without `nofail` systemd holds local-fs.target and the
516	 * customer's server does not finish booting. An unmounted disk is a support
517	 * ticket, a server that will not boot is an outage.
518	 *
519	 * Idempotent: the grep guard and the `mountpoint -q` short-circuit make a re-run
520	 * a no-op. NEVER formats — that decision belongs to the caller alone.
521	 */
522	async function mountVolumeFs(
523	  conn: Client,
524	  devName: string,
525	  mountPath: string,
526	  fsType: string
527	): Promise<{ ok: true; uuid: string } | { ok: false; error: string }> {
528	  if (!DEV_NAME_RE.test(devName)) return { ok: false, error: "device name failed validation" };
529	  if (!MOUNT_PATH_RE.test(mountPath) || mountPath.includes("..") || mountPath.includes("//")) {
530	    return { ok: false, error: `unsupported mount path ${mountPath.slice(0, 40)}` };
531	  }
532	  if (!MOUNTABLE_FS.has(fsType)) return { ok: false, error: `unsupported filesystem ${fsType.slice(0, 20)}` };
533	
534	  const dev = shellQuote(`/dev/${devName}`);
535	  const path = shellQuote(mountPath);
536	
537	  // udev may still be settling right after a mkfs; give the UUID two chances.
538	  let uuid = "";
539	  for (let i = 0; i < 2 && !UUID_RE.test(uuid); i++) {
540	    if (i) await sh(conn, `udevadm settle 2>/dev/null; true`);
541	    uuid = clean((await sh(conn, `blkid -s UUID -o value ${dev} 2>/dev/null`)).stdout, 64);
542	  }
543	  if (!UUID_RE.test(uuid)) return { ok: false, error: "could not read a filesystem UUID back" };
544	
545	  // Refuse to stack our mount on top of somebody else's filesystem.
546	  const occupied = await sh(conn, `findmnt -nro SOURCE --mountpoint ${path} 2>/dev/null | head -n1`);
547	  const occupiedBy = clean(occupied.stdout, 128);
548	  if (occupiedBy && occupiedBy !== `/dev/${devName}`) {
549	    return { ok: false, error: `${mountPath} is already in use by ${occupiedBy}` };
550	  }
551	
552	  await sh(conn, `mkdir -p ${path}`);
553	  await sh(
554	    conn,
555	    `grep -q "UUID=${uuid} " /etc/fstab || printf 'UUID=%s %s %s defaults,nofail 0 2\\n' '${uuid}' ${path} ${shellQuote(fsType)} >> /etc/fstab`
556	  );
557	  await sh(conn, `mountpoint -q ${path} || mount ${path} 2>&1 || mount ${dev} ${path} 2>&1`, SETUP_TIMEOUT_MS);
558	  const live = await sh(conn, `mountpoint -q ${path} && echo MOUNTED`);
559	  if (!clean(live.stdout, 32).includes("MOUNTED")) {
560	    return { ok: false, error: `mounting ${mountPath} failed` };
561	  }
562	  return { ok: true, uuid };
563	}
