565	/** Where should this volume be mounted? Never invents a path over an existing layout. */
566	async function resolveMountPath(
567	  conn: Client,
568	  volume: { id: string; mountPath: string | null },
569	  uuid: string
570	): Promise<string | null> {
571	  // 1) An fstab entry for THIS filesystem wins: it is where the guest already
572	  //    expects the disk, and the migration engine bind-mounts Docker's stores out
573	  //    of that directory. Mounting somewhere else would leave those binds dangling.
574	  if (UUID_RE.test(uuid)) {
575	    const r = await sh(conn, `awk -v u="UUID=${uuid}" '$1==u {print $2; exit}' /etc/fstab 2>/dev/null`);
576	    const fromFstab = clean(r.stdout, 200);
577	    if (MOUNT_PATH_RE.test(fromFstab)) return fromFstab;
578	  }
579	  // 2) Then the path we recorded last time (kept across a detach for the same reason).
580	  if (volume.mountPath && MOUNT_PATH_RE.test(volume.mountPath)) return volume.mountPath;
581	  // 3) Otherwise our own stable path.
582	  return defaultMountPath(volume.id);
583	}
