589	/**
590	 * Make an attached volume usable: format it if (and ONLY if) it is provably
591	 * blank, mount it either way, and record enough to make a later detach safe.
592	 *
593	 * `formatAllowed` is the DB-side half of the format gate: the Volume row must
594	 * never have carried a filesystem. It is deliberately separate from the
595	 * disk-side evidence so that the two have to agree.
596	 */
597	async function prepareGuestVolume(
598	  server: any,
599	  volume: { id: string; sizeGB: number; mountPath: string | null; fsType: string | null; inUse: boolean },
600	  before: Set<string>
601	): Promise<PrepareResult> {
602	  const formatAllowed = !volume.fsType && !volume.mountPath && !volume.inUse;
603	  try {
604	    return await withServerSsh(server, async (conn) => {
605	      const found = await findAttachedDevice(conn, before, volume.sizeGB);
606	      if ("error" in found) return { prepared: false, detail: found.error };
607	
608	      const probe = await probeDevice(conn, found.name);
609	      if (!probe.ok) {
610	        return { prepared: false, detail: `/dev/${found.name} could not be interrogated, so it was left untouched` };
611	      }
612	
613	      // ── Already mounted: adopt it, change nothing about the data. ──────────
614	      if (probe.mount) {
615	        const fsType = probe.fsType || "unknown";
616	        if (!MOUNT_PATH_RE.test(probe.mount)) {
617	          return { prepared: false, detail: `it is already mounted at an unsupported path (${probe.mount.slice(0, 40)})`, fsType: probe.fsType || undefined };
618	        }
619	        // Make sure that mount survives a reboot, without touching the contents.
620	        if (MOUNTABLE_FS.has(fsType) && UUID_RE.test(probe.uuid)) {
621	          await sh(
622	            conn,
623	            `grep -q "UUID=${probe.uuid} " /etc/fstab || printf 'UUID=%s %s %s defaults,nofail 0 2\\n' '${probe.uuid}' ${shellQuote(probe.mount)} ${shellQuote(fsType)} >> /etc/fstab`
624	          );
625	        }
626	        return {
627	          prepared: true,
628	          fsType,
629	          mountPath: probe.mount,
630	          detail: `already mounted at ${probe.mount} (${fsType}) — its contents were not touched`,
631	        };
632	      }
633	
634	      // ── Carries data: mount a filesystem we understand, never reformat. ────
635	      if (probe.fsType || probe.ptType) {
636	        if (probe.ptType || !MOUNTABLE_FS.has(probe.fsType)) {
637	          // A partition table (or an fs we do not mount unattended) means the
638	          // layout is the customer's business; guessing which partition to mount
639	          // is how you mount the wrong thing.
640	          return {
641	            prepared: false,
642	            fsType: probe.fsType || probe.ptType,
643	            detail:
644	              `/dev/${found.name} already contains ${probe.evidence[0] ?? "existing data"}. ` +
645	              `It was attached but NOT formatted or mounted — mount it yourself so nothing is guessed.`,
646	          };
647	        }
648	        const path = await resolveMountPath(conn, volume, probe.uuid);
649	        if (!path) return { prepared: false, fsType: probe.fsType, detail: "could not derive a mount point" };
650	        const m = await mountVolumeFs(conn, found.name, path, probe.fsType);
651	        if (!m.ok) return { prepared: false, fsType: probe.fsType, detail: m.error };
652	        return {
653	          prepared: true,
654	          fsType: probe.fsType,
655	          mountPath: path,
656	          detail: `existing ${probe.fsType} filesystem mounted at ${path} — nothing was reformatted`,
657	        };
658	      }
659	
660	      // ── Nothing detected on the disk. Format ONLY if history agrees. ───────
661	      if (!formatAllowed) {
662	        // The row says this volume carries a filesystem but the disk shows no
663	        // trace of one. That is a contradiction, and the likeliest explanations
664	        // (wrong device, a disk that was recreated empty) both end with somebody
665	        // formatting data. Stop and hand it to a human.
666	        return {
667	          prepared: false,
668	          detail:
669	            `refusing to touch /dev/${found.name}: this volume is recorded as ${volume.fsType ?? "formatted"}` +
670	            `${volume.mountPath ? ` mounted at ${volume.mountPath}` : ""}, but the disk reports no filesystem at all. ` +
671	            `Nothing was formatted or mounted — please contact support before writing to it.`,
672	        };
673	      }
674	      if (!probe.blank) {
675	        return {
676	          prepared: false,
677	          detail: `refusing to format /dev/${found.name}: ${probe.evidence.join("; ")}`,
678	        };
679	      }
680	
681	      // Single `-F`: waives only the "whole device, not a partition" objection.
682	      // mke2fs still refuses a device it believes is mounted or in use, which is
683	      // the last independent veto after our own five checks.
684	      const mk = await sh(
685	        conn,
686	        `mkfs.${VOLUME_FS} -F -m 0 -L nxeon-vol ${shellQuote(`/dev/${found.name}`)} 2>&1`,
687	        INSTALL_TIMEOUT_MS
688	      );
689	      if (mk.code !== 0) {
690	        return { prepared: false, detail: `mkfs.${VOLUME_FS} refused /dev/${found.name}: ${clean(mk.stdout || mk.stderr, 200)}` };
691	      }
692	      const path = (await resolveMountPath(conn, volume, "")) ?? defaultMountPath(volume.id);
693	      if (!path) return { prepared: false, detail: "could not derive a mount point" };
694	      const m = await mountVolumeFs(conn, found.name, path, VOLUME_FS);
695	      if (!m.ok) return { prepared: false, fsType: VOLUME_FS, detail: m.error };
696	      return {
697	        prepared: true,
698	        fsType: VOLUME_FS,
699	        mountPath: path,
700	        detail: `formatted ${VOLUME_FS} and mounted at ${path} (fstab UUID entry with nofail)`,
701	      };
702	    });
703	  } catch (e: any) {
704	    return { prepared: false, detail: `the server could not be reached to prepare the disk (${clean(e?.message ?? e, 120)})` };
705	  }
706	}
