708	/** What the customer can run by hand when we deliberately did not prepare the disk. */
709	function manualPrepareHint(volumeId: string): string {
710	  const path = defaultMountPath(volumeId) ?? "/mnt/data";
711	  return (
712	    `lsblk   # find the new disk, e.g. /dev/sdb\n` +
713	    `mkfs.ext4 /dev/sdb && mkdir -p ${path} && mount /dev/sdb ${path}\n` +
714	    `echo "UUID=$(blkid -s UUID -o value /dev/sdb) ${path} ext4 defaults,nofail 0 2" >> /etc/fstab`
715	  );
716	}
