718	type ReleaseResult =
719	  /** The filesystem is not (or no longer) mounted — the disk can be unplugged. */
720	  | { released: true; detail: string }
721	  /** Something still depends on it. Refuse unless the customer overrode it. */
722	  | { released: false; dependents: string[]; detail: string };
723	
724	/**
725	 * Take the volume's filesystem out of service BEFORE the disk is unplugged.
726	 *
727	 * The old detach was a bare SCSI unplug: no sync, no unmount, no guest-agent
728	 * involvement. A volume mounted at /var/lib/mysql simply lost its device mid
729	 * write — journal abort, InnoDB corruption — while the UI promised "Data is
730	 * preserved.". And the same primitive fires with no human present from billing
731	 * (worker/product-renewals.ts queues VOLUME_DETACH on an overdue volume attached
732	 * to a RUNNING VM), which is why the refusal lives here and not only in the UI.
733	 *
734	 * Nothing is mutated before the decision: `sync` and the probes are harmless, the
735	 * fstab edit happens only once we know the unmount is going ahead. If the worker
736	 * dies between the unmount and the fstab edit the entry is stale — which is
737	 * survivable only because every entry we write carries `nofail`.
738	 */
739	async function releaseGuestVolume(
740	  server: any,
741	  volume: { id: string; sizeGB: number; mountPath: string | null; fsType: string | null; inUse: boolean },
742	  ackInUse: boolean
743	): Promise<ReleaseResult> {
744	  const knownFs = !!(volume.inUse || volume.mountPath || volume.fsType);
745	  try {
746	    return await withServerSsh(server, async (conn) => {
747	      // Which device is ours? The recorded mount point is the reliable link (it
748	      // is unique to this volume); otherwise fall back to a size match, and treat
749	      // "several disks could be it" as in-use rather than guessing.
750	      let devName = "";
751	      let mountPath = "";
752	      if (volume.mountPath && MOUNT_PATH_RE.test(volume.mountPath)) {
753	        const r = await sh(conn, `findmnt -nro SOURCE --mountpoint ${shellQuote(volume.mountPath)} 2>/dev/null | head -n1`);
754	        const src = clean(r.stdout, 128);
755	        if (src.startsWith("/dev/")) {
756	          devName = src.slice(5);
757	          mountPath = volume.mountPath;
758	        }
759	      }
760	      if (!devName) {
761	        const rows = await guestBlockDevices(conn);
762	        if (!rows) {
763	          return knownFs
764	            ? { released: false, dependents: [], detail: "the server's disks could not be listed, so we cannot confirm the filesystem is idle" }
765	            : { released: true, detail: "no filesystem is recorded for this volume and the guest could not be probed" };
766	        }
767	        const roots = await rootDiskNames(conn, rows);
768	        const candidates = rows.filter(
769	          (d) => d.type === "disk" && !roots.has(d.name) && sizeMatches(d.sizeBytes, volume.sizeGB)
770	        );
771	        const mounted = candidates.filter((d) => d.mount || rows.some((o) => o.pkname === d.name && o.mount));
772	        if (mounted.length === 0) {
773	          return { released: true, detail: "the volume's filesystem is not mounted" };
774	        }
775	        if (mounted.length > 1) {
776	          return {
777	            released: false,
778	            dependents: mounted.map((d) => `/dev/${d.name} mounted at ${d.mount || "a partition mount point"}`),
779	            detail: `${mounted.length} mounted disks match this volume's size, so we cannot tell which one to unmount`,
780	          };
781	        }
782	        devName = mounted[0].name;
783	        mountPath = mounted[0].mount;
784	      }
785	      if (!DEV_NAME_RE.test(devName) || !MOUNT_PATH_RE.test(mountPath)) {
786	        return { released: true, detail: "the volume's filesystem is not mounted" };
787	      }
788	
789	      const path = shellQuote(mountPath);
790	      const uuid = clean((await sh(conn, `blkid -s UUID -o value ${shellQuote(`/dev/${devName}`)} 2>/dev/null`)).stdout, 64);
791	
792	      // Flush before anything else — cheap, and the one thing the old code never did.
793	      await sh(conn, `sync`, SETUP_TIMEOUT_MS);
794	
795	      const plain = await sh(conn, `umount ${path} 2>&1`, SETUP_TIMEOUT_MS);
796	      const stillMounted = clean((await sh(conn, `mountpoint -q ${path} && echo BUSY`)).stdout, 32).includes("BUSY");
797	
798	      if (stillMounted) {
799	        const dependents = await mountDependents(conn, mountPath);
800	        if (!ackInUse) {
801	          return {
802	            released: false,
803	            dependents,
804	            detail: `${mountPath} could not be unmounted: ${clean(plain.stdout || plain.stderr, 160) || "the filesystem is in use"}`,
805	          };
806	        }
807	        // Informed override: the customer accepted that whatever is using this
808	        // filesystem will break. A lazy unmount detaches the tree now and lets
809	        // the kernel release it when the last reference goes, which is still far
810	        // better than yanking the device out from under an open file.
811	        await removeFstabEntry(conn, uuid);
812	        await sh(conn, `umount -l ${path} 2>&1`, SETUP_TIMEOUT_MS);
813	        await sh(conn, `sync`, SETUP_TIMEOUT_MS);
814	        return {
815	          released: true,
816	          detail: `${mountPath} was still in use (${dependents.join(", ") || "unknown holders"}) and was force-unmounted on your instruction`,
817	        };
818	      }
819	
820	      await removeFstabEntry(conn, uuid);
821	      return { released: true, detail: `${mountPath} was unmounted cleanly` };
822	    });
823	  } catch (e: any) {
824	    // Cannot reach the guest. If we know it carries a mounted filesystem we
825	    // refuse: an unverified hot-unplug is exactly the corruption we are here to
826	    // prevent. If no filesystem was ever recorded there is nothing to corrupt.
827	    const why = clean(e?.message ?? e, 120);
828	    return knownFs
829	      ? { released: false, dependents: [], detail: `the server could not be reached to unmount the volume first (${why})` }
830	      : { released: true, detail: `no filesystem is recorded for this volume and the server is unreachable (${why})` };
831	  }
832	}
