834	/**
835	 * Drop the fstab line we own (matched on the filesystem UUID, so nothing else can
836	 * match it). Deliberately leaves any bind-mount lines the migration engine wrote
837	 * alone: those are its configuration, not ours, and every entry it writes also
838	 * carries `nofail`, so a missing source directory cannot break the boot.
839	 */
840	async function removeFstabEntry(conn: Client, uuid: string): Promise<void> {
841	  if (!UUID_RE.test(uuid)) return;
842	  await sh(conn, `sed -i "\\|^UUID=${uuid}[[:space:]]|d" /etc/fstab 2>/dev/null; true`);
843	}
