845	/** Name what is holding a mount point open, for an honest refusal message. */
846	async function mountDependents(conn: Client, mountPath: string): Promise<string[]> {
847	  if (!MOUNT_PATH_RE.test(mountPath)) return [];
848	  const q = shellQuote(mountPath);
849	  const r = await sh(
850	    conn,
851	    // Bind mounts sourced from inside this filesystem (how Docker's stores are
852	    // relocated onto a volume), then the processes with files open under it.
853	    `findmnt -rno TARGET,SOURCE 2>/dev/null | awk -v p=${q} '{ if (index($2, p"/")==1 || index($1, p"/")==1) print "bind " $1 }' | sort -u | head -n 8; ` +
854	      `P=$(fuser -Mm ${q} 2>/dev/null | tr -cd '0-9 \\n'); ` +
855	      `[ -n "$P" ] && ps -o comm= -p $P 2>/dev/null | sort -u | head -n 8 | sed 's/^/proc /'; true`
856	  );
857	  const out: string[] = [];
858	  for (const line of clean(r.stdout, 2000).split("\n")) {
859	    const t = line.trim();
860	    if (t.startsWith("bind ")) out.push(`${t.slice(5)} (bind-mounted out of this volume)`);
861	    else if (t.startsWith("proc ")) out.push(`${t.slice(5)} (running process)`);
862	  }
863	  return out.slice(0, 10);
864	}
