875	export async function volumeCreate(job: Job): Promise<void> {
876	  const volume = await loadVolume(job);
877	  if (volume.status === "PENDING") {
878	    await db.volume.update({ where: { id: volume.id }, data: { status: "DETACHED" } });
879	  }
880	  await notify(
881	    volume.userId,
882	    `Volume "${volume.name}" is ready`,
883	    `${volume.sizeGB} GB block storage is available to attach to a server.`,
884	    "/dashboard/volumes"
