888	/**
889	 * Move an existing disk from the VM that currently owns it to `target`.
890	 *
891	 * A Proxmox disk is named after its owner (`vm-<vmid>-disk-N`), so "the same
892	 * volume on a different server" is a reassignment, not a config copy:
893	 * POST .../move_disk with `target-vmid` renames the volume on the storage and
894	 * moves the config entry across in one locked operation. PVE refuses to do it
895	 * across nodes, so the caller checks that first.
896	 *
897	 * Returns the slot it landed in and its NEW volid — the old `Volume.diskName` is
898	 * dead the moment the rename succeeds.
899	 */
900	async function reassignDiskToServer(
901	  conn: any,
902	  volume: { diskName: string | null; name: string },
903	  sourceVmid: number,
904	  sourceRunning: boolean,
905	  target: { vmid: number; hostname: string }
906	): Promise<{ slot: string; volid: string }> {
907	  const volid = String(volume.diskName);
908	  let sourceConfig = (await conn.get(`/nodes/${conn.node}/qemu/${sourceVmid}/config`)) as Record<string, any>;
909	  let key = keyForVolid(sourceConfig, volid);
910	  if (!key) {
911	    // The disk is not on the VM that is supposed to own it. Creating a fresh one
912	    // would silently hand the customer an empty disk and orphan the real data,
913	    // so stop instead.
914	    throw new Error(
915	      `volume "${volume.name}" is recorded as ${volid} on VM ${sourceVmid}, but that disk is not in the VM's config. ` +
916	        `Refusing to guess — nothing was changed.`
917	    );
918	  }
919	  if (key.startsWith("scsi")) {
920	    // The DB says detached but the disk is still plugged in (a detach that never
921	    // finished). Unplugging a live disk from a RUNNING VM is the corruption we
922	    // refuse elsewhere, so refuse it here too.
923	    if (sourceRunning) {
924	      throw new Error(
925	        `volume "${volume.name}" is still plugged into VM ${sourceVmid} as ${key}. Detach it from that server first.`
926	      );
927	    }
928	    await conn.post(`/nodes/${conn.node}/qemu/${sourceVmid}/config`, { delete: key });
929	    sourceConfig = await waitForConfig(conn, sourceVmid, (c) => {
930	      const k = keyForVolid(c, volid);
931	      return !!k && k.startsWith("unused");
932	    });
933	    key = keyForVolid(sourceConfig, volid);
934	    if (!key || key.startsWith("scsi")) {
935	      throw new Error(`could not detach ${volid} from VM ${sourceVmid} before moving it`);
936	    }
937	  }
938	
939	  const targetConfig = (await conn.get(`/nodes/${conn.node}/qemu/${target.vmid}/config`)) as Record<string, any>;
940	  const slot = freeScsiSlot(targetConfig);
941	
942	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${sourceVmid}/move_disk`, {
943	    disk: key,
944	    "target-vmid": target.vmid,
945	    "target-disk": slot,
946	  });
947	  if (typeof upid === "string" && upid.startsWith("UPID")) await conn.waitForTask(upid);
948	
949	  // The volume was RENAMED to vm-<target>-disk-N, so read the new volid back —
950	  // polling, because the config write lands after the API call returns.
951	  const after = await waitForConfig(conn, target.vmid, (c) => isRealVolid(volidOf(c[slot])));
952	  const newVolid = volidOf(after[slot]);
953	  if (!isRealVolid(newVolid)) {
954	    throw new Error(
955	      `the disk move to ${target.hostname} did not show up in the VM config; not recording a guess. ` +
956	        `Check VM ${target.vmid} on the hypervisor before retrying.`
957	    );
958	  }
959	  return { slot, volid: newVolid };
960	}
