201	async function resolveTlsInputs(userId: string): Promise<MigrationTlsInputs> {
202	  let cloudflareToken: string | null = null;
203	  let acmeEmail: string | null = null;
204	  const knownDomains: string[] = [];
205	  const notes: string[] = [];
206	
