372	// ---- Abandoned migrations: the credential promise, kept on the crash path ---
373	/**
374	 * How long a migration may sit unfinished with NO live job before it is declared
375	 * abandoned. Generous: a real lift-and-shift of a large box legitimately runs for
376	 * a long time, and while it does its job row is QUEUED or RUNNING, which exempts
377	 * it from this entirely.
378	 */
379	export const MIGRATION_ABANDON_MS = 3 * 60 * 60_000;
380	
381	export type AbandonedMigrationInput = {
382	  status: string;
383	  finishedAt: Date | null;
384	  createdAt: Date;
385	  /** Is there a MIGRATE job for this migration still QUEUED or RUNNING? */
386	  hasLiveJob: boolean;
387	  now: number;
388	  maxAgeMs?: number;
389	};
390	
391	/**
392	 * Is this migration abandoned — unfinished, with nothing left that could ever
393	 * finish it?
394	 *
395	 * WHY THIS EXISTS. Two documents promise the same thing in the same words:
396	 * `lib/actions-migrate.ts` ("They are CLEARED by the worker the moment the
397	 * migration finishes — success or failure — so a completed Migration row never
398	 * retains usable credentials") and this file's own header. Both are true for
399	 * every path that reaches `runMigration`'s try/catch. Neither is true for the
400	 * path where the worker never reaches it:
401	 *
402	 *   worker crash / restart  →  `reapStuckJobs` (worker/index.ts) re-QUEUEs the
403	 *   MIGRATE job  →  it crashes again  →  `attempts >= MAX_ATTEMPTS`  →  the job
404	 *   is marked FAILED and handed to `reconcileFailedJob`, which handles RESIZE and
405	 *   DISK_EXPAND and returns immediately for everything else.
406	 *
407	 * Nothing then touches the Migration row again. It keeps `status: "RUNNING"`
408	 * forever — the customer's wizard polls a progress bar that will never move — and
409	 * it keeps `sourcePasswordEnc`, which is the ROOT SSH PASSWORD OF ANOTHER
410	 * PROVIDER'S LIVE SERVER, encrypted at rest but retained indefinitely for a run
411	 * that ended hours ago. "Cleared when the run ends, success or failure" has to
412	 * include the failure mode where nothing was there to clear it.
413	 *
414	 * Pure so the rule is testable without a database, a worker or a clock.
415	 */
416	export function isAbandonedMigration(m: AbandonedMigrationInput): boolean {
417	  if (m.finishedAt) return false;
418	  if (m.status !== "PENDING" && m.status !== "RUNNING") return false;
419	  // Something can still finish it — leave it alone however long it takes.
420	  if (m.hasLiveJob) return false;
421	  return m.now - m.createdAt.getTime() >= (m.maxAgeMs ?? MIGRATION_ABANDON_MS);
422	}
