429	/**
430	 * Settle every abandoned migration: mark it FAILED and CLEAR its stored source
431	 * credentials. See `isAbandonedMigration` for the crash path this closes.
432	 *
433	 * Returns how many it settled, so the caller can log a number it actually
434	 * counted rather than an assurance.
435	 */
436	export async function reapAbandonedMigrations(): Promise<number> {
437	  const rows = await db.migration.findMany({
438	    where: { finishedAt: null, status: { in: ["PENDING", "RUNNING"] } },
439	    select: { id: true, userId: true, status: true, createdAt: true, finishedAt: true, items: true, log: true },
440	    orderBy: { createdAt: "asc" },
441	    take: 100,
442	  });
443	  if (!rows.length) return 0;
444	
445	  const now = Date.now();
446	  let reaped = 0;
447	  for (const m of rows) {
448	    const live = await db.job.findFirst({
449	      where: {
450	        type: "MIGRATE",
451	        status: { in: ["QUEUED", "RUNNING"] },
452	        payload: { path: ["migrationId"], equals: m.id },
453	      },
454	      select: { id: true },
455	    });
456	    if (!isAbandonedMigration({ status: m.status, finishedAt: m.finishedAt, createdAt: m.createdAt, hasLiveJob: !!live, now })) {
457	      continue;
458	    }
459	    const items = (m.items ?? {}) as MigrationItems;
460	    try {
461	      await db.migration.update({
462	        where: { id: m.id },
463	        data: {
464	          status: "FAILED",
465	          step: "Stopped before finishing",
466	          lastError: ABANDONED_MIGRATION_ERROR,
467	          finishedAt: new Date(),
468	          log: appendLog(m.log, `ERROR: ${ABANDONED_MIGRATION_ERROR}`),
469	        },
470	      });
471	      // The whole point of the sweep. Runs even if the status write above threw,
472	      // because retaining the credential is the worse of the two failures.
473	    } finally {
474	      await clearSecrets(m.id, items).catch((e) =>
475	        console.error(`[migrate] could not clear secrets for abandoned migration ${m.id}:`, e)
476	      );
477	    }
478	    reaped++;
479	    await notify(
480	      m.userId,
481	      "Migration stopped before it finished",
482	      ABANDONED_MIGRATION_ERROR,
483	      "/dashboard/migrate"
484	    );
485	  }
486	  if (reaped) console.log(`[migrate] settled ${reaped} abandoned migration(s) and cleared their stored source credentials`);
487	  return reaped;
488	}
