490	/** How long after a migration finishes we keep watching for the DNS cutover. */
491	const TLS_WATCH_DAYS = 14;
492	/** Minimum gap between certificate attempts for one migration. */
493	const TLS_RETRY_MS = 6 * 60 * 60_000;
494	/**
495	 * The longest one certificate pass may occupy the serial worker. Generous enough
496	 * for SSH plus certbot on a slow box, short enough that an unreachable target
497	 * cannot hold up provisioning.
498	 */
499	const TLS_PASS_TIMEOUT_MS = 4 * 60_000;
500	
501	/**
502	 * Enqueue the post-cutover certificate pass for migrations whose DNS may have
503	 * moved since they finished.
504	 *
505	 * WHY THIS EXISTS. `runPostCutoverTls` was written for exactly this job and had
506	 * exactly one enqueue line — **inside a comment**. So it was dead code, and a
507	 * customer who migrated, then pointed their DNS a day later, never got the
508	 * certificate that could not be issued during the run: their first HTTPS visit
509	 * was a browser warning, forever.
510	 *
511	 * That was bad on its own. It became worse on 2026-07-26, when the migration
512	 * report's cutover instructions were rewritten to tell the customer, in plain
513	 * words, that "Nxeon issues the certificate automatically within about 30 minutes
514	 * of the change, and nothing else is needed." That sentence was false the moment
515	 * it shipped. `sslSweep` does NOT cover this case — it walks `db.sslCertificate`
516	 * rows, and a migration never writes one. A promise the product does not keep is
517	 * the same defect as a success this engine did not verify, so the promise is made
518	 * true here rather than walked back in the copy.
519	 *
520	 * Safe to run repeatedly by construction: the pass copies nothing, never touches
521	 * the source server, never rewrites `Migration.status`, and certbot's
522	 * `--keep-until-expiring` makes an already-certified domain a no-op.
523	 */
524	export async function postCutoverTlsSweep(): Promise<void> {
525	  // Settled here rather than in its own registered sweep because this function is
526	  // the migration subsystem's ONLY periodic entry point (worker/index.ts calls it
527	  // every 30 minutes) and an unfinished migration holding a source root password
528	  // must not wait for a new registration to be plumbed in. It is wrapped so a
529	  // failure here can never stop the certificate pass that follows.
530	  await reapAbandonedMigrations().catch((e) => console.error("[migrate] abandoned-migration sweep failed:", e));
531	
532	  const since = new Date(Date.now() - TLS_WATCH_DAYS * 86_400_000);
533	  const runningServerIds = (
534	    await db.server.findMany({ where: { status: "RUNNING" }, select: { id: true } })
535	  ).map((s) => s.id);
536	  if (!runningServerIds.length) return;
537	
538	  const candidates = await db.migration.findMany({
539	    where: {
540	      status: { in: ["DONE", "COMPLETED_WITH_ISSUES"] },
541	      finishedAt: { gte: since },
542	      // SSH is the first thing this pass does. A server that is not running
543	      // cannot answer, and the attempt would occupy the strictly-serial worker
544	      // until the connection times out. `Migration.serverId` is a bare column
545	      // with no Prisma relation, so the running set is resolved separately.
546	      serverId: { in: runningServerIds },
547	    },
548	    select: { id: true, items: true, serverId: true },
549	    orderBy: { finishedAt: "desc" },
550	    take: 50,
551	  });
552	
553	  // ONE pass per target server, not per migration. A customer who retried a
554	  // migration three times has three rows pointing at the same box; certifying it
555	  // once certifies it for all of them, and the first live run queued four
556	  // redundant SSH sessions for a single server. Newest first, since that run's
557	  // published site config is the one on disk.
558	  const seenServers = new Set<string>();
559	
560	  for (const m of candidates) {
561	    // Already fully certified — a previous pass found nothing outstanding.
562	    if ((m.items as { tlsSettled?: boolean } | null)?.tlsSettled) continue;
563	    if (seenServers.has(m.serverId)) continue;
564	    seenServers.add(m.serverId);
565	
566	    // Don't stack attempts. A job still queued, or one tried recently, means the
567	    // answer is already on its way; certbot rate limits are real and shared.
568	    const recent = await db.job.findFirst({
569	      where: {
570	        type: "MIGRATE",
571	        createdAt: { gte: new Date(Date.now() - TLS_RETRY_MS) },
572	        payload: { path: ["migrationId"], equals: m.id },
573	      },
574	      select: { id: true },
575	    });
576	    if (recent) continue;
577	
578	    await db.job
579	      .create({ data: { type: "MIGRATE", payload: { migrationId: m.id, phase: "tls" } } })
580	      .catch((e) => console.error(`[migrate] could not enqueue TLS pass for ${m.id}:`, e));
581	  }
582	}
