952	/**
953	 * Validate a proposed node's ranges/uniqueness against all other nodes.
954	 * `selfId` excludes the row being edited. Returns an error string or null.
955	 */
956	async function validateAgainstExisting(data: NodeInput, selfId?: string): Promise<string | null> {
957	  if (data.ipEnd < data.ipStart) return "Guest IP range invalid: ipEnd must be ≥ ipStart.";
958	  if (data.sshPortEnd < data.sshPortStart) return "SSH port range invalid: end must be ≥ start.";
959	
960	  const others = await db.node.findMany({
961	    where: selfId ? { id: { not: selfId } } : {},
962	    select: {
963	      name: true,
964	      publicIp: true,
965	      subnetPrefix: true,
966	      ipStart: true,
967	      ipEnd: true,
968	      sshPortStart: true,
969	      sshPortEnd: true,
970	      natChain: true,
971	      isPrimary: true,
972	    },
973	  });
974	
975	  for (const o of others) {
976	    if (o.natChain === data.natChain) {
977	      const next = data.natChain === "NXEON_FWD" ? "NXEON_FWD_N2" : `${data.natChain}_X`;
978	      return `NAT chain "${data.natChain}" is already used by node "${o.name}". Each node needs a globally unique chain (e.g. ${next}).`;
979	    }
980	    // IP ranges only collide inside the same /24 subnet.
981	    if (o.subnetPrefix === data.subnetPrefix && rangesOverlap(data.ipStart, data.ipEnd, o.ipStart, o.ipEnd)) {
982	      return `Guest IP range ${data.subnetPrefix}${data.ipStart}-${data.ipEnd} overlaps node "${o.name}" (${o.subnetPrefix}${o.ipStart}-${o.ipEnd}). Give this node its own /24, e.g. bump subnetPrefix to 10.20.N.`;
983	    }
984	    // SSH ports only collide when two nodes share the same public host.
985	    if (
986	      o.publicIp === data.publicIp &&
987	      rangesOverlap(data.sshPortStart, data.sshPortEnd, o.sshPortStart, o.sshPortEnd)
988	    ) {
989	      return `SSH port range ${data.sshPortStart}-${data.sshPortEnd} overlaps node "${o.name}" on the same host ${data.publicIp}. Use a distinct port range for co-hosted nodes.`;
990	    }
991	    if (data.isPrimary && o.isPrimary) {
992	      return `Node "${o.name}" is already the primary. Only one node can be primary.`;
993	    }
994	  }
995	  return null;
996	}
