1258	/**
1259	 * VOLUME_DELETE — detach (if attached) then permanently destroy the underlying
1260	 * disk, and remove the Volume row.
1261	 */
1262	export async function volumeDelete(job: Job): Promise<void> {
1263	  const volume = await loadVolume(job);
1264	  const server = volume.server;
1265	
1266	  if (SANDBOX) {
1267	    await db.volume.delete({ where: { id: volume.id } });
1268	    await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
1269	    return;
1270	  }
1271	
1272	  // The customer has accepted losing this volume's data, so a busy filesystem is
1273	  // NOT a reason to refuse here — but unmounting first still matters: yanking the
1274	  // device from under an open file wedges the processes using it and can take
1275	  // unrelated services on the same server down with it. Best effort only.
1276	  if (server?.vmid && server.status === "RUNNING" && (volume.inUse || volume.mountPath)) {
1277	    await releaseGuestVolume(server, volume, true).catch(() => undefined);
1278	  }
1279	
1280	  if (server?.vmid && volume.diskName) {
1281	    const { conn } = await nodeFor(server);
1282	    try {
1283	      let config = (await conn.get(`/nodes/${conn.node}/qemu/${server.vmid}/config`)) as Record<string, any>;
1284	      let key = keyForVolid(config, volume.diskName);
1285	
1286	      // If still mounted, detach to an "unused" entry first.
1287	      if (key && key.startsWith("scsi")) {
1288	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
1289	        config = await waitForConfig(conn, server.vmid, (c) => {
1290	          const k = keyForVolid(c, String(volume.diskName));
1291	          return !k || !k.startsWith("scsi");
1292	        });
1293	        key = keyForVolid(config, volume.diskName);
1294	      }
1295	      // Deleting an "unused" entry destroys the underlying disk.
1296	      if (key) {
1297	        await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, { delete: key });
1298	      }
1299	    } catch (e: any) {
1300	      const msg = String(e?.body ?? e?.message ?? e);
1301	      if (!msg.includes("does not exist")) throw e;
1302	    }
1303	  }
1304	
1305	  await db.volume.delete({ where: { id: volume.id } });
1306	  await notify(volume.userId, `Volume "${volume.name}" deleted`, undefined, "/dashboard/volumes");
