} from "@/lib/actions";

export function RenewalCard({
  serverId,
  autoRenew,
  expiresAt,
  priceCents,
  extraDiskMonthlyCents = 0,
  extraDiskGB = 0,
  suspendedUnpaid,
  renewTotalCents,
  renewDurationLabel,
}: {
  serverId: string;
  autoRenew: boolean;
  expiresAt: string | null;
  priceCents: number;
  /**
   * What "Renew now" ACTUALLY charges, and the term it actually buys — computed
   * server-side by the same `renewalQuote()` the action charges through.
   *
   * Real incident, 2026-07-26 QA: this card rendered the literal string
   * "+30 days" beside the plan's MONTHLY price, while `renewNow` has always
   * charged a full term. "Renew now (+30 days, $8.99)" took **$97.09** and moved
   * the expiry twelve months — 10.8× on Starter/12mo, 28.8× on Max/36mo, with no
   * confirmation between the click and the debit. Never re-derive these two
   * numbers in this component; they belong to the action, and a second
   * derivation is exactly how they drifted.
   */
  renewTotalCents: number;
  renewDurationLabel: string;
  /**
   * Monthly surcharge for permanently-added disk. Billed on TOP of the plan every
   * cycle (worker/billing.ts + renewNow), so the card must show the real total —
   * otherwise the quoted renewal price would be lower than the charge.
   */
  extraDiskMonthlyCents?: number;
  extraDiskGB?: number;
  suspendedUnpaid: boolean;
}) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  const totalMonthlyCents = priceCents + extraDiskMonthlyCents;

  return (
    <div className="card">
      <h2 className="mb-3 font-semibold">Subscription</h2>
      {error && (
        <div className="mb-3 rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {error}
        </div>
      )}
      <dl className="space-y-2 text-sm">
        <div className="flex justify-between">
          <dt className="text-slate-400">Price</dt>
          <dd>${(totalMonthlyCents / 100).toFixed(2)}/mo</dd>
        </div>
        {extraDiskMonthlyCents > 0 && (
          <div className="flex justify-between text-xs text-slate-500">
            <dt>
              incl. {extraDiskGB} GB added storage <span className="text-slate-600">(permanent)</span>
            </dt>
            <dd>${(extraDiskMonthlyCents / 100).toFixed(2)}/mo</dd>
          </div>
        )}
        <div className="flex justify-between">
          <dt className="text-slate-400">Paid until</dt>
          <dd>{expiresAt ? expiresAt.slice(0, 10) : "—"}</dd>
        </div>
        <div className="flex items-center justify-between">
          <dt className="text-slate-400">Auto-renew</dt>
          <dd>
            <button
              className={autoRenew ? "btn-secondary py-1" : "btn-primary py-1"}
              disabled={pending}
              onClick={() => start(() => toggleAutoRenew(serverId))}
            >
              {autoRenew ? "On — turn off" : "Off — turn on"}
            </button>
          </dd>
        </div>
      </dl>
      <button
        className="btn-primary mt-4 w-full"
        disabled={pending}
        onClick={() => {
          // An irreversible wallet debit gets one confirmation stating the real
          // amount and the real duration. There was none, and the label was
          // wrong by an order of magnitude — see the prop docs above.
          const ok = window.confirm(
            suspendedUnpaid
              ? `Pay $${(renewTotalCents / 100).toFixed(2)} now to restore this server and extend it by ${renewDurationLabel}?`
              : `Renew this server for ${renewDurationLabel}?\n\n$${(renewTotalCents / 100).toFixed(2)} will be taken from your wallet now.`
          );
          if (!ok) return;
          start(async () => {
            setError(null);
            const res = await renewNow(serverId);
            if (res?.error) setError(res.error);
          });
        }}
      >
        {pending
          ? "Working…"
          : suspendedUnpaid
            ? `Pay $${(renewTotalCents / 100).toFixed(2)} & restore server`
            : `Renew now (+${renewDurationLabel}, $${(renewTotalCents / 100).toFixed(2)})`}
      </button>
    </div>
  );
}

