import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { ClaudeCodeHub } from "@/components/customer/claude-code/ClaudeCodeHub";

export const dynamic = "force-dynamic";
export const metadata = { title: "Build with AI" };

export default async function ClaudeCodePage() {
  const user = await requireUser();

  const servers = await db.server.findMany({
    where: { userId: user.id, status: "RUNNING" },
    select: {
      id: true,
      hostname: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
    orderBy: { createdAt: "desc" },
  });

  const publicIp = process.env.PUBLIC_IP || "YOUR_SERVER_IP";
  const list = servers.map((s) => {
    const ip = s.dedicatedIp?.address;
    const connect = ip ? `ssh root@${ip}` : `ssh -p ${s.sshPort ?? 22} root@${publicIp}`;
    return { id: s.id, hostname: s.hostname, connect };
  });

  return <ClaudeCodeHub servers={list} />;
}
