15	 * Virtual MAC at all, so the MAC-based check above cannot see it. A real
16	 * incident: this exact IP was one query away from being handed to a game
17	 * server because "no Virtual MAC bound" was mistaken for "free" — it was
18	 * actively carrying production hosting traffic via `iptables -t nat`. Treat
19	 * any address with a live DNAT target as claimed, unconditionally.
20	 */
21	async function hasLiveDnatRule(address: string): Promise<boolean> {
22	  try {
23	    const { stdout } = await execFileP("iptables", ["-t", "nat", "-S", "PREROUTING"]);
24	    return stdout.split("\n").some((line) => line.includes(`-d ${address}/32`) && line.includes("-j DNAT"));
25	  } catch {
26	    // iptables unreadable (permissions, not present, sandboxed test env) — fail
27	    // closed is wrong here (it would make every sync a no-op); fail to "not
28	    // claimed by this specific check" and rely on the Virtual MAC check plus
29	    // the existing DB row remaining authoritative for anything already tracked.
30	    return false;
31	  }
32	}
