80	/**
81	 * Pull additional/failover IPv4 addresses routed to our server from OVH and
82	 * upsert them into the pool. The host's own primary IP is never poolable.
83	 */
84	export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
85	  if (SANDBOX) return { imported: 0, total: 0 };
86	  if (!ovhConfigured()) return { imported: 0, total: 0 };
87	  const primary = process.env.PUBLIC_IP;
88	  const blocks: string[] = await ovhApi.ips();
89	  let imported = 0;
90	  for (const block of blocks) {
91	    if (block.includes(":")) continue; // IPv6 handled separately
92	    let info: any;
93	    try {
94	      info = await ovhApi.ipInfo(block);
95	    } catch {
96	      continue;
97	    }
98	    if (info?.routedTo?.serviceName !== SERVER) continue;
99	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
100	    // A /32 block is a single usable IP == the block minus the mask.
101	    const address = block.split("/")[0];
102	    if (address === primary) continue;
103	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
104	    if (!existing) {
105	      // An IP that already has a Virtual MAC bound to it on OVH's side is already
106	      // in active use by SOME VM — possibly one this app never created a Server
107	      // row for (e.g. internal infrastructure provisioned directly via the OVH
108	      // API, like the cold-email relay). A genuinely free IP has no bound MAC
109	      // yet. Importing it as FREE anyway let a real customer server collide with
110	      // an unrelated VM's network identity — never assign an IP that's already
111	      // claimed at the network layer, regardless of whether our DB knows about it.
112	      if (await findVirtualMacForIp(address)) continue;
113	      if (await hasLiveDnatRule(address)) continue;
114	      // Every IP this function imports is, by construction, a spare address
115	      // OVH says is routed to us and not yet claimed at the network layer — the
116	      // pool customer orders draw from. Internal-use IPs (the cold-email relay,
117	      // an owner-operated site, the shared-hosting node) are rare, hand-provisioned
118	      // one-offs marked INTERNAL by an admin after the fact; this sync has no way
119	      // to tell them apart from a genuinely free customer IP and must not try —
120	      // it always imports as CUSTOMER (the schema default, stated here for clarity).
121	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE", purpose: "CUSTOMER" } });
122	      imported++;
123	    }
124	  }
125	  const total = await db.dedicatedIp.count();
126	  return { imported, total };
127	}
