147	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
148	async function findVirtualMacForIp(address: string): Promise<string | null> {
149	  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
150	  for (const m of macs) {
151	    const ips: string[] = await ovh(
152	      "GET",
153	      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
154	    ).catch(() => []);
155	    if (ips.includes(address)) return m;
156	  }
157	  return null;
158	}
