160	/**
161	 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
162	 * Returns the address + virtualMac + gateway, or null if none available.
163	 */
164	export async function allocateDedicatedIp(
165	  serverId: string,
166	  vmid: number
167	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
168	  if (SANDBOX) {
169	    // Hand out a synthetic dedicated IP without any OVH call or pool mutation.
170	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
171	  }
172	  // Idempotent per server: PROVISION can retry (up to MAX_ATTEMPTS). If this
173	  // server already holds a fully-allocated dedicated IP (ASSIGNED + a bound
174	  // Virtual MAC), return it instead of claiming a second pool IP — re-claiming
175	  // would leak an IP and P2002 on the unique DedicatedIp.serverId.
176	  const mine = await db.dedicatedIp.findUnique({ where: { serverId } });
177	  if (mine && mine.status === "ASSIGNED" && mine.virtualMac) {
178	    return { address: mine.address, virtualMac: mine.virtualMac, gateway: ovhGateway() };
179	  }
180	  if (!ovhConfigured()) return null;
181	  // Atomically claim a FREE ip. Excluding purpose: INTERNAL here is a second,
182	  // independent guard (alongside the sync-time checks above) against ever
183	  // handing an admin-marked internal IP — e.g. the shared-hosting node, which
184	  // can sit with serverId: null and no live-attribute for allocation to see —
185	  // to a customer server.
186	  const claim = await db.$transaction(async (tx) => {
187	    const ip = await tx.dedicatedIp.findFirst({
188	      where: { status: "FREE", purpose: "CUSTOMER" },
189	      orderBy: { createdAt: "asc" },
190	    });
191	    if (!ip) return null;
192	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
193	    return ip;
194	  });
195	  if (!claim) return null;
196	
197	  try {
198	    // Reuse an existing vMAC for this IP if one is already bound; else create one.
199	    let mac = await findVirtualMacForIp(claim.address);
200	    if (!mac) {
201	      // Creation is asynchronous (returns a task) — kick it off then poll.
202	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
203	      for (let i = 0; i < 40 && !mac; i++) {
204	        await new Promise((r) => setTimeout(r, 3000));
205	        mac = await findVirtualMacForIp(claim.address);
206	      }
207	    }
208	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
209	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
210	    return { address: claim.address, virtualMac: mac, gateway: ovhGateway() };
211	  } catch (e) {
212	    // Roll the claim back to FREE on failure
213	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
214	    throw e;
215	  }
216	}
