218	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual MAC). */
219	export async function releaseDedicatedIp(serverId: string): Promise<void> {
220	  if (SANDBOX) return;
221	  const ip = await db.dedicatedIp.findUnique({ where: { serverId } });
222	  if (!ip) return;
223	  if (ovhConfigured() && ip.virtualMac) {
224	    try {
225	      // Remove the IP from the vMAC, then delete the vMAC.
226	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
227	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
228	    } catch {
229	      /* best-effort */
230	    }
231	  }
232	  await db.dedicatedIp.update({
233	    where: { id: ip.id },
234	    data: { status: "FREE", serverId: null, virtualMac: null },
235	  });
236	}
