245	/**
246	 * Shared per-server DEDICATED IP purchase core — the money path for adding a
247	 * dedicated public IPv4 to a server that does NOT already have one.
248	 *
249	 * Mirrors lib/disk-expand.ts (which itself mirrors lib/resize.ts) line-for-line
250	 * in shape: a pure `*Quote` function re-validated by `apply*`, used by both the
251	 * wallet flow (lib/actions-dedicated-ip.ts) and the Stripe confirm route so a
252	 * paid checkout can apply the purchase immediately. Plain server module (NOT
253	 * "use server").
254	 *
255	 * ─── WHY THIS CANNOT DOUBLE-CHARGE ──────────────────────────────────────────
256	 * Identical argument to lib/disk-expand.ts: one quote function, one wallet debit
257	 * inside the same transaction that creates the job, and the card path credits
258	 * only the card remainder before debiting the full proration on confirm.
259	 *
260	 * ─── ROLLBACK SAFETY (real infra, real money) ───────────────────────────────
261	 * The actual IP claim + OVH Virtual MAC creation + Proxmox network reconfig all
262	 * happen in the WORKER (`ASSIGN_DEDICATED_IP`, worker/index.ts), never here —
263	 * exactly like DISK_EXPAND never touches Proxmox synchronously inside the
264	 * action. That keeps "charge" and "allocate" as two separate steps that can
265	 * each fail independently without corrupting the other:
266	 *   - If nothing is charged, no job is ever created (both happen in one
267	 *     `$transaction`), so nothing is ever allocated.
268	 *   - If the job's `allocateDedicatedIp` call can't claim a pool IP (or OVH
269	 *     errors), it throws BEFORE touching the DB (see lib/dedicated-ip.ts's own
270	 *     rollback-on-failure) and the job fails/retries; a terminal failure is
271	 *     refunded by `reconcileFailedJob` in worker/index.ts, mirroring RESIZE.
272	 */
273	import { db } from "./db";
274	import { debitWallet, InsufficientBalanceError } from "./wallet";
275	import { invoiceCreateData } from "./invoices";
276	import { remainingMonths } from "./proration";
277	import { extraDiskProrateCents } from "./extra-disk";
278	import { dedicatedIpMonthlyCents, freeCount } from "./dedicated-ip";
279	
280	export class DedicatedIpPurchaseError extends Error {}
281	
282	function loadServer(serverId: string) {
283	  return db.server.findUnique({ where: { id: serverId }, include: { dedicatedIp: true } });
284	}
285	
286	type QuotedServer = NonNullable<Awaited<ReturnType<typeof loadServer>>>;
287	
288	export type DedicatedIpQuote = {
289	  server: QuotedServer;
290	  monthlyCents: number;
291	  /** One-off charge for the remainder of the CURRENT paid term. */
292	  prorateCents: number;
293	};
294	
295	/**
296	 * Validate a dedicated-IP purchase and compute the prorated charge over the
297	 * ACTUAL remaining duration — identical maths to `diskExpandQuote` (a flat
298	 * monthly add-on × every remaining month; null expiresAt on free/admin servers
299	 * => 0). Throws DedicatedIpPurchaseError with a user-facing message on any
300	 * guard failure. Does NOT check ownership — callers must do that.
301	 */
302	export async function dedicatedIpPurchaseQuote(serverId: string): Promise<DedicatedIpQuote> {
303	  const server = await loadServer(serverId);
304	  if (!server) throw new DedicatedIpPurchaseError("Not found");
305	  if (server.dedicatedIp) {
306	    throw new DedicatedIpPurchaseError("This server already has a dedicated IP.");
307	  }
308	  if (!["RUNNING", "STOPPED"].includes(server.status)) {
309	    throw new DedicatedIpPurchaseError("Server is busy — wait for the current operation to finish.");
310	  }
311	  if (!server.vmid) throw new DedicatedIpPurchaseError("This server hasn't finished provisioning yet.");
312	
313	  // A DB-level check only — the authoritative claim happens atomically in the
314	  // worker (allocateDedicatedIp). This just avoids charging a customer for a
315	  // pool we already know is empty.
316	  const available = await freeCount();
317	  if (available <= 0) {
318	    throw new DedicatedIpPurchaseError(
319	      "No dedicated IPs are available in the pool right now — please contact support and we'll get one allocated.",
320	    );
321	  }
322	
323	  const monthlyCents = await dedicatedIpMonthlyCents();
324	  let prorateCents = 0;
325	  if (!server.isFree && server.expiresAt) {
326	    // Reuses the generic "flat monthly amount × remaining months" prorate
327	    // formula lib/extra-disk.ts already owns for the disk add-on — it is not
328	    // disk-specific despite the name (`Math.max(0, Math.round(monthly * months))`),
329	    // and this is exactly the shape of a flat monthly surcharge like the
330	    // dedicated-IP price, so it is reused rather than redefined a third time.
331	    prorateCents = extraDiskProrateCents(monthlyCents, remainingMonths(server.expiresAt, Date.now()));
332	  }
333	  return { server, monthlyCents, prorateCents };
334	}
335	
336	/**
337	 * Apply the purchase: (optionally) debit the wallet for the prorated charge,
338	 * record the wallet transaction + PAID invoice, and queue the
339	 * ASSIGN_DEDICATED_IP job the worker performs against Proxmox/OVH. Re-validates
340	 * every guard so it is safe to call from the unauthenticated confirm route.
341	 * Throws DedicatedIpPurchaseError on any guard failure.
342	 *
343	 * `chargeCents` overrides the recomputed proration — the paid path passes the
344	 * exact amount the customer paid into their wallet at checkout so the debit
345	 * here nets to zero against that credit (mirrors lib/disk-expand.ts).
346	 */
347	export async function applyDedicatedIpPurchase(opts: {
348	  serverId: string;
349	  actorUserId: string;
350	  chargeCents?: number;
351	}): Promise<void> {
352	  const quote = await dedicatedIpPurchaseQuote(opts.serverId);
353	  const { server, monthlyCents } = quote;
354	  const prorateCents = opts.chargeCents ?? quote.prorateCents;
355	
356	  const pending = await db.job.count({
357	    where: { serverId: server.id, status: { in: ["QUEUED", "RUNNING"] } },
358	  });
359	  if (pending > 0) throw new DedicatedIpPurchaseError("Another operation is already in progress on this server.");
360	
361	  try {
362	    await db.$transaction(async (tx) => {
363	      if (prorateCents > 0) {
364	        await debitWallet(tx, server.userId, prorateCents);
365	        await tx.walletTransaction.create({
366	          data: {
367	            userId: server.userId,
368	            amountCents: -prorateCents,
369	            description: `Dedicated IP add-on (prorated) — ${server.hostname}`,
370	          },
371	        });
372	        await tx.invoice.create({
373	          data: invoiceCreateData({
374	            userId: server.userId,
375	            description: `Dedicated IP add-on (prorated) — ${server.hostname}`,
376	            status: "PAID",
377	            lineItems: [
378	              {
379	                description:
380	                  `Dedicated IP — prorated for remaining term (${server.hostname}). ` +
381	                  `Renews at $${(monthlyCents / 100).toFixed(2)}/mo.`,
382	                qty: 1,
383	                unitCents: prorateCents,
384	                amountCents: prorateCents,
385	              },
386	            ],
387	          }),
388	        });
389	      }
390	      // Record the amount charged AND the monthly rate on the job so the worker
391	      // can deliver it, and so a terminal failure can be REVERSED (refund the
392	      // charge, release any IP it managed to claim) — money is committed here,
393	      // before the job runs.
394	      await tx.job.create({
395	        data: {
396	          type: "ASSIGN_DEDICATED_IP",
397	          serverId: server.id,
398	          payload: { prorateCents, monthlyCents } as any,
399	        },
400	      });
401	      await tx.auditLog.create({
402	        data: {
403	          userId: opts.actorUserId,
404	          action: "server.dedicated_ip_purchase",
405	          detail: `${server.id} prorate=${prorateCents} monthly=${monthlyCents}`,
406	        },
407	      });
408	    });
409	  } catch (e) {
410	    if (e instanceof InsufficientBalanceError) {
411	      throw new DedicatedIpPurchaseError("Insufficient balance — top up your wallet first.");
412	    }
413	    throw e;
414	  }
415	}
416	##### lib/wallet-split.ts
417	// Pure, dependency-free wallet/card split math shared by the client wizards
418	// (DeployWizard, ResizePicker) and the server actions (payAndDeploy,
419	// resizeServer). Keeping it here — with NO server-only imports — guarantees the
420	// split the customer SEES is byte-for-byte the split that gets CHARGED.
421	
422	/**
423	 * Stripe rejects card charges under ~$0.50. We never send a card amount below
424	 * this; when the natural remainder would fall under it we leave exactly this
425	 * much on the card and apply slightly less wallet credit (see walletSplit).
426	 */
427	export const STRIPE_MIN_CENTS = 50;
428	
429	export type WalletSplit = {
430	  /** Cents taken from the customer's existing wallet balance. */
431	  walletApplied: number;
432	  /** Cents charged to the card (0 = fully paid from wallet, no Stripe). */
433	  cardCents: number;
434	  /** True when we bumped the card up to STRIPE_MIN_CENTS (reducing wallet). */
435	  clampedForStripeMin: boolean;
436	  /**
437	   * True when the WHOLE amount due is under Stripe's floor, so no card leg exists
438	   * at all and `walletApplied` is the entire due (see walletSplit). Distinct from
439	   * `clampedForStripeMin`, which means the opposite thing — that a card leg does
440	   * exist and was raised to the floor. Surfaces must not conflate them: the deploy
441	   * wizard's `clampedForStripeMin` line says "we'll charge {cardCents} to your
442	   * card", which would be a flat lie here, where `cardCents` is 0.
443	   *
444	   * In this state `walletApplied` may EXCEED the customer's balance. That is not a
445	   * claim the balance covers it — it is the amount that must come from the wallet
446	   * because nothing else can settle it. The caller's guarded `debitWallet` decides
447	   * whether it succeeds, and a surface showing this flag should tell the customer
448	   * to top up rather than imply the payment is already funded.
449	   */
450	  belowStripeMin: boolean;
451	};
452	
453	/**
454	 * Split a due amount between the wallet and the card, honoring the customer's
455	 * "apply my balance" toggle and Stripe's minimum-charge floor.
456	 *
457	 * - `useWallet` off  → everything on the card.
458	 * - wallet covers all → cardCents = 0 (caller pays entirely from wallet, no Stripe).
459	 * - partial cover     → walletApplied = min(balance, due), card = the remainder.
460	 * - tiny remainder    → if 0 < card < STRIPE_MIN_CENTS, reduce walletApplied so
461	 *   exactly STRIPE_MIN_CENTS lands on the card (never send Stripe a sub-minimum
462	 *   charge). Integer-cent exact throughout.
463	 * - whole due sub-floor → no card leg is possible at all; the wallet takes it all
464	 *   and `belowStripeMin` is set (see below).
465	 *
466	 * POSTCONDITION, relied on by every caller: `cardCents` is either 0 or at least
467	 * STRIPE_MIN_CENTS. `lib/actions-server.ts` and `lib/actions-disk.ts` hand
468	 * `cardCents` straight to `createResizeCheckout` / `createDiskExpandCheckout`,
469	 * which guard only `cardCents <= 0` — a sub-floor positive amount reached
470	 * `stripe().checkout.sessions.create` and threw out of the server action. That is
471	 * fixed HERE, in the one function that owns the floor, rather than by bolting a
472	 * duplicate guard onto each call site.
473	 */
474	export function walletSplit(opts: {
475	  dueCents: number;
476	  balanceCents: number;
477	  useWallet: boolean;
478	}): WalletSplit {
479	  const dueCents = Math.max(0, Math.round(opts.dueCents));
480	  const balanceCents = Math.max(0, Math.round(opts.balanceCents));
481	  if (dueCents <= 0) {
482	    return { walletApplied: 0, cardCents: 0, clampedForStripeMin: false, belowStripeMin: false };
483	  }
484	
485	  // The whole amount due is under Stripe's floor, so there is no card leg to be
486	  // had: the clamp below works by moving cents from the wallet ONTO the card, and
487	  // here there are not enough cents in the charge to reach the floor no matter how
488	  // they are divided. Previously this fell through and returned whatever sub-floor
489	  // remainder was left (due 30, balance 10 -> cardCents 20), which Stripe rejects.
490	  //
491	  // Two behaviours were available and only one is honest. Inflating the card leg to
492	  // 50c would charge the customer more than they owe. So the card is dropped
493	  // entirely and the wallet takes the whole amount — the only leg that can settle
494	  // a 30c charge — REGARDLESS of `useWallet`, because respecting that preference
495	  // here would mean no payable split exists at all. `belowStripeMin` reports it so
496	  // callers and surfaces state what happened instead of implying a funded card
497	  // payment, and when the balance falls short the caller's guarded `debitWallet`
