export async function renewNow(serverId: string): Promise<{ error?: string } | void> {
  // Spend path: block wallet debits while an admin is impersonating.
  await assertNotImpersonating();
  const { user, server } = await ownedServer(serverId);
  if (server.isFree || !server.expiresAt) return;
  // A MANUAL renewal is a fresh purchase decision, so it is gated. Note this
  // cannot strand an existing customer: every account that owns a server today
  // predates verification and is grandfathered, and the automatic renewal in
  // worker/billing.ts does not pass through here at all — nobody's server lapses
  // because of this check.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };
  const plan = await db.plan.findUnique({ where: { id: server.planId } });
  if (!plan) return;
  // A game server carries BOTH a base `planId` and a `gamePlanId`, and it is sold
  // at the game plan's FLAT price. Reading only `plan.priceCents` here charged a
  // game-server owner the base VPS term price instead — `minecraft-mm8w85` sold at
  // $4.99 on a Starter base plan would have been billed $8.99, an 80% overcharge.
  const gamePlan = server.gamePlanId
    ? await db.gamePlan.findUnique({
        where: { id: server.gamePlanId },
        select: { name: true, priceCents: true, termMonths: true },
      })
    : null;
  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
    where: { serverId }, select: { id: true },
  }));
  // The SERVER OWNER (not necessarily the acting user) determines the VAT/GST rate
  // and the spend cap — resolved up front so `renewalQuote` prices tax-inclusive.
  const owner = await db.user.findUnique({ where: { id: server.userId } });
  if (!owner) return;
  const renewTaxCtx = await taxContextForUser(owner);
  // Priced through `renewalCharge` — the SAME function the automatic renewal sweep
  // in worker/billing.ts and the saved-card path use. Not a second copy of the
  // arithmetic: see lib/renewal-quote.ts for both incidents that produced this
  // rule, the second of which was a fresh duplicate written hours after the first.
  const quote = renewalQuote(
    {
      termMonths: server.termMonths,
      extraDiskGB: server.extraDiskGB,
      plan: { name: plan.name, priceCents: plan.priceCents },
      gamePlan,
      dedicatedIp: hasDedicatedIp ? {} : null,
      backupTier: server.backupTier,
    },
    {
      ipMonthlyCents: hasDedicatedIp ? await dedicatedIpMonthlyCents() : 0,
      extraDiskPerGbCents: await extraDiskPerGbCents(),
      backupPlusCents: await backupPlusMonthlyCents(),
      annualDiscountPct: await annualDiscountPct(),
      // VAT/GST for the owner's country (Finding 1). `renewCents` below is
      // tax-inclusive, so what the customer is shown === what the wallet is debited.
      taxRatePercent: renewTaxCtx.ratePercent,
    },
  );
  const renewCents = quote.totalCents;
  const term = { months: quote.months };
  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
  const extraDiskCents = gamePlan ? 0 : extraDiskMonthly * quote.months;
  if (owner.balanceCents < renewCents) {
    return { error: "Insufficient balance — top up your wallet first." };
  }
  // Hard monthly spend cap (Finding 3): refuse a manual wallet renewal that would
  // push the owner past their cap. No-op unless they enabled one.
  try {
    await assertSpendCap(owner, renewCents);
  } catch (e) {
    if (e instanceof SpendCapError) return { error: e.message };
    throw e;
  }

  // `E` is the expiry we read OUTSIDE the transaction. We advance it with a
  // compare-and-swap on that exact value so two concurrent "Renew now" clicks
  // can't both read E, both debit, and both write E+term (double-charge, one
  // term granted). Only the CAS that matches E wins; the loser is a no-op.
  const E = server.expiresAt;
  const base = new Date(Math.max(E.getTime(), Date.now()));
  const newExpiry = addMonths(base, term.months);

  // `renewCents` above is `vpsTermPriceCents(...)` — the REGULAR price, with no
  // seasonal promo applied. That is exactly what lib/promotions.ts promises: the
  // strikethrough on the marketing page is the real renewal price. So the months
  // being added here are sold at 0% off, and the term's stored rate has to say so.
  //
  // BLENDED, not overwritten. A customer can renew early, stacking a full-price
  // term on top of months still running at an intro discount. Overwriting would
  // silently reprice those earlier months to full list — and that is the profitable
  // direction: buy 36 months at 45% off, renew once at full price, and every one of
  // the original discounted months would suddenly credit at the full rate on a
  // downgrade. Blending keeps the cash value of the window invariant.
  const renewedPercent = prorateBlendPercent({
    currentPercent: resolveTermPromoPercent(server.termPromoPercent),
    currentMonths: remainingMonths(E, Date.now()),
    addedPercent: 0,
    addedMonths: term.months,
  });
  try {
    await db.$transaction(async (tx) => {
      // Compare-and-swap the expiry first; if it no longer equals E another
      // renewal already advanced it — bail without charging (tx rolls back).
      const adv = await tx.server.updateMany({
        where: { id: serverId, expiresAt: E },
        data: {
          expiresAt: newExpiry,
          termPromoPercent: renewedPercent,
          suspendedNote: null,
          suspendReason: null,
        },
      });
      if (adv.count === 0) throw new AlreadyRenewedError();
      // Atomic guarded debit: a concurrent spend can't drive the wallet negative.
      await debitWallet(tx, server.userId, renewCents);
      await tx.walletTransaction.create({
        data: {
          userId: server.userId,
          amountCents: -renewCents,
          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
        },
      });
      // PAID invoice inside the same CAS-guarded tx: a losing concurrent "Renew
      // now" throws AlreadyRenewedError and rolls back, so no duplicate invoice.
      await tx.invoice.create({
        data: invoiceCreateData({
          userId: server.userId,
          description: `Renewal: ${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
          status: "PAID",
          // Tax recorded separately; the line items below sum to the NET (quote.netCents).
          taxCents: quote.taxCents,
          taxRatePercent: quote.taxRatePercent,
          taxCountry: renewTaxCtx.country,
          period: { start: E, end: newExpiry },
          lineItems: [
            {
              description: `${quote.label} (${server.hostname}) — ${quote.durationLabel}`,
              qty: 1,
              unitCents: quote.netCents - extraDiskCents,
              amountCents: quote.netCents - extraDiskCents,
            },
            ...(extraDiskCents > 0
              ? [
                  {
                    description: `${extraDiskLabel(server.extraDiskGB)} — ${server.hostname} (permanent, $${(extraDiskMonthly / 100).toFixed(2)}/mo)`,
                    qty: 1,
                    unitCents: extraDiskCents,
                    amountCents: extraDiskCents,
                  },
                ]
              : []),
          ],
        }),
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance — top up your wallet first." };
    if (e instanceof AlreadyRenewedError) return { error: "This server was just renewed — refresh to see the new expiry." };
    throw e;
  }
  await audit(user.id, "server.renew_now", serverId);
  // Soft monthly-budget alert (Finding 3), best-effort.
  await maybeAlertBudget(server.userId);
  // KOL/Agency partner commission on this renewal charge (idempotent; best-effort).
  await accrueRecentCommissionsForCustomer(server.userId);

  // An UNPAID-suspended server springs back to life once paid — but only that
  // kind. This used to fire for ANY suspended server, so a customer suspended for
  // outbound abuse could click "Renew now", pay, and put themselves straight back
  // on the network, undoing an abuse or admin action with a card. Legacy rows with
  // a null `suspendReason` are not auto-lifted; an admin can clear those by hand.
  if (server.status === "SUSPENDED" && server.suspendReason === "UNPAID") {
    const pending = await db.job.count({
      where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (pending === 0) await db.job.create({ data: { type: "UNSUSPEND", serverId } });
  }
  revalidatePath(`/dashboard/servers/${serverId}`);
}

