"use server";

/**
 * Control panel — Databases.
 *
 * Create/list/delete MySQL/MariaDB & PostgreSQL databases + DB users on the VPS.
 * The generated password is returned to the caller ONCE (shown with a copy
 * button in the UI) and stored only transiently (encrypted, `passwordEnc`) so
 * the worker can apply it; worker/databases.ts clears it after the create. The
 * engine is installed on first use. Sandbox-gated real work lives in the worker.
 */
import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { encryptSecret } from "./crypto-box";
import { IDENT_RE, generateStrongPassword } from "./ssh-exec";
import { DB_ENGINES, type DbEngine, type DatabaseRow } from "./cpanel-types";

type CreateResult =
  | { ok: true; id: string; name: string; dbUser: string; password: string }
  | { ok: false; error: string };
type Result = { ok: true } | { ok: false; error: string };

const EXCLUSIVE_JOBS = [
  "PROVISION",
  "REINSTALL",
  "DELETE",
  "RESIZE",
  "SUSPEND",
  "UNSUSPEND",
  "SNAPSHOT_ROLLBACK",
  "BACKUP_RESTORE",
  // A disk expansion runs growpart/resize2fs over SSH inside the guest; keep the
  // control-panel operations out of the way while the root filesystem is resized.
  "DISK_EXPAND",
] as const;

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, userId: true, status: true, hostname: true },
  });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

async function ownedDatabase(id: string) {
  const user = await requireUser();
  const database = await db.vpsDatabase.findUnique({ where: { id } });
  if (!database) throw new Error("Not found");
  if (database.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, database };
}

function throttle(userId: string, op: string, max: number): string | null {
  const rl = checkRateLimit(`cpanel:db:${op}:${userId}`, { max, windowMs: 60_000 });
  return rl.ok ? null : `Too many requests — retry in ${rl.retryAfterSec}s.`;
}

async function lifecycleBusy(serverId: string): Promise<boolean> {
  const n = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] }, type: { in: EXCLUSIVE_JOBS as any } },
  });
  return n > 0;
}

function safeError(err: unknown): string {
  const msg = err instanceof Error ? err.message : String(err);
  if (msg === "Not found" || msg === "Forbidden") return "Server not found.";
  return msg.slice(0, 300);
}

function rowOut(d: {
  id: string;
  engine: string;
  name: string;
  dbUser: string;
  status: string;
  error: string | null;
  createdAt: Date;
}): DatabaseRow {
  return {
    id: d.id,
    engine: d.engine,
    name: d.name,
    dbUser: d.dbUser,
    status: d.status,
    error: d.error,
    createdAt: d.createdAt.toISOString(),
  };
}

// ---------------------------------------------------------------------------

export async function listDatabases(
  serverId: string
): Promise<{ ok: true; databases: DatabaseRow[] } | { ok: false; error: string }> {
  try {
    const { server } = await ownedServer(serverId);
    const rows = await db.vpsDatabase.findMany({
      where: { serverId: server.id },
      orderBy: { createdAt: "desc" },
    });
    return { ok: true, databases: rows.map(rowOut) };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function createDatabase(
  serverId: string,
  engine: string,
  nameInput: string,
  userInput: string
): Promise<CreateResult> {
  try {
    const { user, server } = await ownedServer(serverId);
    const limited = throttle(user.id, "create", 10);
    if (limited) return { ok: false, error: limited };
    if (server.status !== "RUNNING") return { ok: false, error: "The server must be running to create a database." };
    if (await lifecycleBusy(server.id))
      return { ok: false, error: "Another server operation is in progress — try again shortly." };

    if (!(DB_ENGINES as readonly string[]).includes(engine))
      return { ok: false, error: "Choose a supported database engine." };
    const name = String(nameInput ?? "").trim();
    const dbUser = String(userInput ?? "").trim();
    if (!IDENT_RE.test(name))
      return { ok: false, error: "Database name: 1–32 letters, digits or underscores." };
    if (!IDENT_RE.test(dbUser))
      return { ok: false, error: "User name: 1–32 letters, digits or underscores." };

    const existing = await db.vpsDatabase.findFirst({
      where: { serverId: server.id, engine, name },
    });
    if (existing) return { ok: false, error: `A ${engine} database named "${name}" already exists.` };

    const count = await db.vpsDatabase.count({ where: { serverId: server.id } });
    if (count >= 50) return { ok: false, error: "Database limit reached (50 per server)." };

    const password = generateStrongPassword(20);
    const row = await db.vpsDatabase.create({
      data: {
        userId: user.id,
        serverId: server.id,
        engine: engine as DbEngine,
        name,
        dbUser,
        passwordEnc: encryptSecret(password),
        status: "PENDING",
      },
    });
    await db.job.create({ data: { type: "DB_CREATE", serverId: server.id, payload: { databaseId: row.id } } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.db.create", detail: `${engine}/${name} on ${server.hostname}` },
    });
    revalidatePath(`/dashboard/servers/${serverId}`);
    // Password returned ONCE — never stored in plaintext, never re-shown.
    return { ok: true, id: row.id, name, dbUser, password };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function deleteDatabase(id: string): Promise<Result> {
  try {
    const { user, database } = await ownedDatabase(id);
    const limited = throttle(user.id, "delete", 15);
    if (limited) return { ok: false, error: limited };
    await db.vpsDatabase.update({ where: { id }, data: { status: "DELETING" } });
    await db.job.create({ data: { type: "DB_DELETE", serverId: database.serverId, payload: { databaseId: id } } });
    await db.auditLog.create({
      data: { userId: user.id, action: "cpanel.db.delete", detail: `${database.engine}/${database.name}` },
    });
    revalidatePath(`/dashboard/servers/${database.serverId}`);
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

